const e={id:"mod-01-foundations",number:"01",title:"Foundations",track:"hld",lessons:[{id:"request-lifecycle",title:"How a Request Travels",subtitle:"From typing a URL to rendered pixels: DNS, TCP/TLS 1.3, HTTP/2 & HTTP/3 QUIC, and backend hops.",duration:"9 min",level:"Beginner",companies:["Microsoft","Google","Amazon","Meta"],tags:["dns","tcp","tls","http2","http3","quic","osi","nat","browser"],objectives:["Trace DNS recursive resolution and Anycast edge routing","Understand TCP 3-way handshake + TLS 1.3 RTT cost","Contrast HTTP/1.1, HTTP/2 multiplexing, and HTTP/3 QUIC","Identify where latency hides inside a production request lifecycle"],steps:[{shortLabel:"DNS lookup",stage:"SETUP",title:"Translating a domain name to an IP",body:["Before a single byte of HTTP leaves your browser, it must resolve `api.shop.com` to an IPv4/IPv6 address via **DNS**. The browser checks its own cache, OS cache, ISP recursive resolver, and then walks Root → TLD (`.com`) → Authoritative Nameserver.","Modern systems use **Anycast DNS** and GeoDNS so a user in Mumbai receives an IP belonging to an edge PoP 15 ms away instead of crossing an ocean."],callout:{type:"KEY IDEA",text:"DNS TTL controls the trade-off between lookup speed (long TTL = fewer lookups) and failover agility (short TTL = faster traffic shifting during an outage)."},scene:{hud:[{label:"PHASE",value:"DNS Resolution",status:"info"},{label:"CACHE MISS RTT",value:"20 – 120 ms",status:"warn"},{label:"CACHE HIT",value:"< 1 ms",status:"good"},{label:"PROTOCOL",value:"UDP :53 / DoH",status:"info"}],nodes:[{id:"browser",type:"users",x:130,y:215,label:"Browser",sublabel:"Local Cache",tone:"slate"},{id:"resolver",type:"hex",x:380,y:215,label:"DNS Resolver",sublabel:"ISP / 1.1.1.1",tone:"blue",badge:"recursive",badgeTone:"blue"},{id:"auth",type:"db",x:625,y:145,label:"Authoritative",sublabel:"Route53 / Azure DNS",tone:"purple",callout:"TTL 60s"},{id:"root",type:"db",x:625,y:295,label:"Root & TLD",sublabel:".com NS",tone:"amber"}],edges:[{from:"browser",to:"resolver",label:"A/AAAA query",packetColor:"coral",bidirectional:!0,speed:2.1},{from:"resolver",to:"root",label:"1. root → .com",packetColor:"amber",dashed:!0,speed:2.6},{from:"resolver",to:"auth",label:"2. IP: 203.0.113.42",packetColor:"green",bidirectional:!0,speed:2}],legend:[{label:"DNS query",tone:"coral"},{label:"resolved IP",tone:"green"},{label:"cache miss walk",tone:"amber"}]}},{shortLabel:"TCP & TLS",stage:"PROBLEM",title:"Handshakes cost multiple round trips",body:["Once the browser has an IP, it opens a reliable **TCP connection** (SYN → SYN-ACK → ACK = 1 RTT) and then negotiates **TLS encryption** so traffic cannot be eavesdropped or tampered with.","With legacy TLS 1.2, TCP + TLS requires **3 full round trips** before sending the first HTTP byte. On a 120 ms mobile network, that burns 360 ms doing pure ceremony!"],callout:{type:"WATCH OUT",text:"TLS 1.3 cuts the cryptographic handshake down to 1 RTT (and 0-RTT for resumed sessions), while TCP Keep-Alive avoids repeating handshakes per request."},scene:{hud:[{label:"TCP HANDSHAKE",value:"1 RTT",status:"warn"},{label:"TLS 1.2 / 1.3",value:"2 RTT → 1 RTT",status:"good"},{label:"CONGESTION CTRL",value:"Slow Start",status:"info"},{label:"PORT",value:"HTTPS :443",status:"info"}],nodes:[{id:"client",type:"users",x:165,y:215,label:"Client",sublabel:"NAT + Ephemeral Port",tone:"slate"},{id:"edge",type:"hex",x:560,y:215,label:"TLS Edge",sublabel:"Envoy / Nginx",tone:"blue",badge:"TLS 1.3",badgeTone:"green",load:38}],edges:[{from:"client",to:"edge",label:"1. TCP SYN / SYN-ACK / ACK",packetColor:"coral",curve:-48,speed:2.3},{from:"client",to:"edge",label:"2. TLS 1.3 KeyShare + Cert",packetColor:"purple",curve:0,bidirectional:!0,speed:2.1},{from:"client",to:"edge",label:"3. Encrypted HTTP Request",packetColor:"green",curve:52,bidirectional:!0,speed:1.8}],legend:[{label:"TCP handshake",tone:"coral"},{label:"TLS crypto",tone:"purple"},{label:"HTTP payload",tone:"green"}]}},{shortLabel:"HTTP/2 & 3",stage:"SOLUTION",title:"Multiplexing & QUIC kill head-of-line blocking",body:["**HTTP/1.1** could only serve one request at a time per TCP connection, forcing browsers to open 6 parallel sockets. **HTTP/2** introduced binary framing and **stream multiplexing** over a single TCP connection plus HPACK header compression.","However, a single dropped TCP packet still stalls every HTTP/2 stream (**TCP Head-of-Line blocking**). **HTTP/3 (QUIC)** runs over UDP with built-in TLS 1.3 and independent streams, surviving Wi-Fi ↔ 5G handoffs cleanly via Connection IDs."],callout:{type:"GOOD TO KNOW",text:"gRPC runs on top of HTTP/2 using binary Protocol Buffers, enabling bidirectional streaming and 5–10x smaller payloads than JSON over HTTP/1.1."},changes:["+Multiplexed parallel streams on 1 connection","+QUIC merges transport + TLS 1.3 into 1 RTT","~Eliminates TCP head-of-line stalls on lossy mobile links"],scene:{hud:[{label:"HTTP/1.1",value:"6 TCP Conns",status:"bad"},{label:"HTTP/2",value:"1 TCP · Mux",status:"warn"},{label:"HTTP/3 QUIC",value:"UDP · 0/1-RTT",status:"good"},{label:"MOBILE LOSS",value:"Isolated Streams",status:"good"}],nodes:[{id:"mobile",type:"users",x:130,y:215,label:"Mobile App",sublabel:"5G / Wi-Fi Roam",tone:"slate",badge:"QUIC ConnID",badgeTone:"green"},{id:"gw",type:"hex",x:400,y:215,label:"Edge Gateway",sublabel:"HTTP/3 → HTTP/2",tone:"green",load:34},{id:"api",type:"hex",x:640,y:215,label:"Origin API",sublabel:"gRPC / REST",tone:"blue",load:42}],edges:[{from:"mobile",to:"gw",label:"Stream 1 (JSON)",packetColor:"green",curve:-40,speed:1.7},{from:"mobile",to:"gw",label:"Stream 2 (Image)",packetColor:"blue",curve:0,speed:2},{from:"mobile",to:"gw",label:"Stream 3 (CSS)",packetColor:"purple",curve:40,speed:1.9},{from:"gw",to:"api",label:"Internal gRPC",packetColor:"amber",bidirectional:!0,speed:1.6}],legend:[{label:"independent QUIC streams",tone:"green"},{label:"internal RPC",tone:"amber"}]}},{shortLabel:"Backend hops",stage:"TECHNIQUE",title:"Inside the datacenter: Edge → App → Cache → DB",body:["Once past TLS termination at the **Load Balancer / API Gateway**, the request is authenticated, rate-limited, and routed to a stateless application server.","The app server checks an in-memory **Cache** (Redis, ~0.5 ms) before falling back to the primary **Database** (PostgreSQL, ~5–15 ms), then serializes the response back along the path."],callout:{type:"INTERVIEW SIGNAL",text:"In Microsoft/Google interviews, always distinguish external WAN latency (50–200 ms) from internal datacenter RPC latency (0.5–2 ms)."},scene:{hud:[{label:"GATEWAY HOP",value:"2 ms",status:"good"},{label:"REDIS HIT",value:"0.6 ms",status:"good"},{label:"DB QUERY",value:"8 ms",status:"info"},{label:"TOTAL P95",value:"48 ms",status:"good"}],nodes:[{id:"user",type:"users",x:95,y:215,label:"Client",sublabel:"HTTPS",tone:"slate"},{id:"lb",type:"hex",x:265,y:215,label:"API Gateway",sublabel:"Auth · RL",tone:"green",load:32},{id:"app",type:"hex",x:455,y:215,label:"App Server",sublabel:"Stateless",tone:"blue",load:45},{id:"redis",type:"cache",x:645,y:125,label:"Redis Cache",sublabel:"0.6 ms",tone:"green",badge:"92% hit",badgeTone:"green"},{id:"db",type:"db",x:645,y:295,label:"Postgres DB",sublabel:"8 ms miss",tone:"purple",callout:"users"}],edges:[{from:"user",to:"lb",label:"TLS",packetColor:"coral",bidirectional:!0,speed:2},{from:"lb",to:"app",label:"HTTP/2",packetColor:"blue",bidirectional:!0,speed:1.8},{from:"app",to:"redis",label:"hit",packetColor:"green",bidirectional:!0,speed:1.4},{from:"app",to:"db",label:"miss only",packetColor:"amber",dashed:!0,speed:2.5}],legend:[{label:"client request",tone:"coral"},{label:"cache hit",tone:"green"},{label:"DB fallback",tone:"amber"}]}},{shortLabel:"Recap",stage:"RECAP",title:"End-to-end request lifecycle mental model",body:["1. **DNS** resolves hostname → IP (Anycast puts users on the nearest PoP).","2. **TCP + TLS 1.3** or **HTTP/3 QUIC** establishes an encrypted multiplexed tunnel with minimal RTTs.","3. **API Gateway** enforces AuthN/AuthZ and Rate Limits; **App Servers** read from **Cache** first and **Database** only on miss."],callout:{type:"KEY IDEA",text:"Every millisecond saved on the critical path multiplies across millions of users. Cut RTTs first (CDN, HTTP/3, Keep-Alive), then cut compute and DB round trips."},scene:{hud:[{label:"DNS",value:"Anycast Geo",status:"good"},{label:"TRANSPORT",value:"QUIC / TLS 1.3",status:"good"},{label:"EDGE",value:"Gateway + CDN",status:"good"},{label:"DATA PATH",value:"Cache → DB",status:"good"}],nodes:[{id:"u",type:"users",x:100,y:215,label:"User",sublabel:"Browser/App",tone:"slate"},{id:"dns",type:"hex",x:255,y:120,label:"Anycast DNS",sublabel:"Nearest IP",tone:"amber"},{id:"gw",type:"hex",x:350,y:255,label:"Edge & LB",sublabel:"HTTP/3 + TLS",tone:"green"},{id:"svc",type:"hex",x:525,y:215,label:"Microservice",sublabel:"Business Logic",tone:"blue"},{id:"store",type:"db",x:675,y:215,label:"Cache + DB",sublabel:"Fast + Durable",tone:"purple"}],edges:[{from:"u",to:"dns",label:"resolve",packetColor:"amber",dashed:!0,speed:2.3},{from:"u",to:"gw",label:"QUIC",packetColor:"green",bidirectional:!0,speed:1.9},{from:"gw",to:"svc",label:"gRPC",packetColor:"blue",bidirectional:!0,speed:1.7},{from:"svc",to:"store",label:"query",packetColor:"purple",bidirectional:!0,speed:1.8}],legend:[{label:"DNS lookup",tone:"amber"},{label:"encrypted edge",tone:"green"},{label:"data access",tone:"purple"}]}}],deepDive:{tradeoffs:[{option:"HTTP/1.1",bestWhen:"Legacy clients, simple internal health checks",pros:"Universal compatibility, human-readable headers",cons:"Head-of-line blocking, 6-connection cap per origin, verbose headers"},{option:"HTTP/2",bestWhen:"Web browsers, internal service-to-service gRPC",pros:"Binary framing, multiplexed streams, HPACK compression",cons:"Single lost TCP packet stalls all multiplexed streams"},{option:"HTTP/3 (QUIC)",bestWhen:"Mobile apps, global edge CDNs, lossy wireless links",pros:"0/1-RTT handshake, independent UDP streams, seamless IP migration",cons:"Higher CPU cost than kernel-offloaded TCP; some corporate firewalls block UDP :443"}],failureModes:[{title:"DNS Propagation Lag During Regional Outage",mitigation:"Keep DNS TTL low (30–60s) for critical APIs and pair with Anycast BGP routing so failover occurs in seconds rather than waiting on stale ISP resolvers.",interviewProbe:"What happens if an enterprise DNS resolver ignores your 30-second TTL?"},{title:"Connection Pool / Ephemeral Port Exhaustion (TIME_WAIT)",mitigation:"Enable HTTP Keep-Alive, persistent gRPC HTTP/2 channels, and bounded upstream connection pools with idle timeouts.",interviewProbe:"Why did our API Gateway suddenly throw EADDRNOTAVAIL under 50k RPS?"}]}},{id:"latency-throughput",title:"Latency & Throughput",subtitle:"Why averages lie, how p99 tail latency explodes across microservices, and Little’s Law.",duration:"8 min",level:"Beginner",companies:["Google","Microsoft","Amazon"],tags:["p99","tail latency","throughput","qps","hedged requests","littles law"],objectives:["Distinguish latency (ms) from throughput (RPS/QPS)","Understand why p99 matters far more than mean latency","Calculate tail-latency amplification in fan-out microservices","Apply hedged requests, timeouts, and async offloading to protect p99"],steps:[{shortLabel:"Latency vs RPS",stage:"SETUP",title:"Speed of one request vs volume per second",body:["**Latency** is the duration a single request takes from client send to client receive (e.g., `45 ms`). **Throughput** is how many requests the system finishes per second (e.g., `25,000 RPS`).","They are related by **Little’s Law** (`Concurrency = Throughput × Latency`), but not identical: a batch pipeline has high throughput and terrible latency; an unqueued server at 95% CPU sees latency shoot toward infinity."],callout:{type:"KEY IDEA",text:"Queueing Theory warning: Above ~70–80% CPU utilization, request queues grow nonlinearly and p99 latency spikes 10x before throughput even hits 100%."},scene:{hud:[{label:"MEDIAN (p50)",value:"18 ms",status:"good"},{label:"THROUGHPUT",value:"12,000 RPS",status:"good"},{label:"CPU LOAD",value:"62%",status:"info"},{label:"QUEUE DEPTH",value:"3 reqs",status:"good"}],nodes:[{id:"c",type:"users",x:130,y:215,label:"Clients",sublabel:"12k req/s",tone:"slate"},{id:"q",type:"queue",x:350,y:215,label:"Accept Queue",sublabel:"Depth: 3",tone:"amber"},{id:"w",type:"hex",x:590,y:215,label:"Worker Pool",sublabel:"18 ms avg",tone:"blue",load:62}],edges:[{from:"c",to:"q",label:"λ = 12k/s",packetColor:"coral",speed:1.8},{from:"q",to:"w",label:"L = λ × W",packetColor:"green",bidirectional:!0,speed:1.8}],legend:[{label:"arrival rate λ",tone:"coral"},{label:"completed work",tone:"green"}]}},{shortLabel:"Tail explosion",stage:"PROBLEM",title:"Fan-out multiplies p99 tail latency",body:["Suppose each backend leaf service has a **99% probability** of replying in < 20 ms, and a 1% chance of a GC pause taking **500 ms**.","If your homepage aggregator fans out to **100 leaf services** in parallel and waits for all of them, the chance that at least one leaf is slow is `1 - 0.99^100 = 63.4%`! Now **more than half** your users suffer the 500 ms tail!"],callout:{type:"WATCH OUT",text:'Google’s famous "The Tail at Scale" paper (Jeff Dean & Luiz Barroso) proved that tail latency becomes the common-case latency in large fan-out architectures.'},scene:{hud:[{label:"SINGLE LEAF p99",value:"1% slow",status:"good"},{label:"FAN-OUT WIDTH",value:"100 leaves",status:"warn"},{label:"USER SLOW PROB",value:"63.4%!",status:"bad"},{label:"PAGE LATENCY",value:"512 ms",status:"bad"}],nodes:[{id:"agg",type:"hex",x:185,y:215,label:"Aggregator",sublabel:"Waits for ALL",tone:"blue",load:74},{id:"l1",type:"hex",x:520,y:95,label:"Leaf 1..33",sublabel:"15 ms",tone:"green",load:42},{id:"l2",type:"hex",x:520,y:215,label:"Leaf 34..66",sublabel:"18 ms",tone:"green",load:45},{id:"l3",type:"hex",x:520,y:335,label:"Leaf 97 (GC!)",sublabel:"500 ms stall",tone:"coral",badge:"GC pause",badgeTone:"rose",load:96}],edges:[{from:"agg",to:"l1",label:"15 ms",packetColor:"green",speed:1.5},{from:"agg",to:"l2",label:"18 ms",packetColor:"green",speed:1.6},{from:"agg",to:"l3",label:"500 ms tail!",packetColor:"coral",dashed:!0,speed:4.5}],legend:[{label:"fast leaf",tone:"green"},{label:"straggler blocking response",tone:"coral"}]}},{shortLabel:"Hedged RPCs",stage:"SOLUTION",title:"Taming p99 with Hedged Requests & Partial Degradation",body:["How does Google Search keep p99 blazing fast across 1,000 shards? Two key techniques: **Hedged Requests** (if a read takes longer than p95, issue a duplicate read to a replica and use whichever finishes first, adding only ~5% extra load) and **Graceful Partial Degradation**.",'For non-critical widgets (like "Recommended for you"), apply strict **deadline propagation** (e.g., 40 ms budget) and omit or serve stale cache if the widget misses its deadline.'],callout:{type:"INTERVIEW SIGNAL",text:"Only hedge idempotent READ operations! Hedging a non-idempotent POST payment could charge a customer twice."},changes:["+Hedged backup read fired after p95 delay (20 ms)","+Strict deadline budget propagated across RPC tree","~p99 drops from 512 ms → 34 ms with only +5% traffic"],scene:{hud:[{label:"HEDGE DELAY",value:"20 ms (p95)",status:"info"},{label:"EXTRA LOAD",value:"+5% reads",status:"good"},{label:"NEW p99",value:"34 ms",status:"good"},{label:"STRAGGLER",value:"Bypassed",status:"good"}],nodes:[{id:"agg",type:"hex",x:170,y:215,label:"Aggregator",sublabel:"Hedge @ 20ms",tone:"blue",load:48},{id:"p1",type:"hex",x:520,y:135,label:"Replica A",sublabel:"Stalled (GC)",tone:"coral",badge:"cancelled",badgeTone:"rose",dim:!0,load:95},{id:"p2",type:"hex",x:520,y:295,label:"Replica B",sublabel:"Wins in 12 ms!",tone:"green",badge:"hedged winner",badgeTone:"green",load:38}],edges:[{from:"agg",to:"p1",label:"t=0ms primary",packetColor:"coral",dashed:!0,speed:4,dim:!0},{from:"agg",to:"p2",label:"t=20ms hedge → 32ms done",packetColor:"green",bidirectional:!0,speed:1.5}],legend:[{label:"slow primary cancelled",tone:"coral"},{label:"fast hedged replica",tone:"green"}]}},{shortLabel:"Recap",stage:"RECAP",title:"Key latency & throughput rules to quote in interviews",body:["1. Never cite average latency alone — always set **SLOs on p95 and p99** (and p99.9 for payments/search).","2. Keep steady-state utilization below **65–70%** so sudden bursts do not trigger queueing collapse.","3. Use **hedged reads**, **request coalescing**, **deadline propagation**, and **asynchronous queues** to protect tail latency."],callout:{type:"GOOD TO KNOW",text:"Memorize Jeff Dean’s latency ladder: L1 cache 0.5 ns · RAM 100 ns · NVMe SSD 100 µs · Same-DC RPC 0.5 ms · Cross-continent RTT 150 ms."},scene:{hud:[{label:"RAM READ",value:"100 ns",status:"good"},{label:"NVME SSD",value:"100 µs",status:"info"},{label:"SAME-DC RPC",value:"0.5 ms",status:"info"},{label:"US ↔ EU RTT",value:"80 – 150 ms",status:"warn"}],nodes:[{id:"ram",type:"cache",x:140,y:215,label:"RAM",sublabel:"100 ns",tone:"green"},{id:"ssd",type:"db",x:320,y:215,label:"NVMe SSD",sublabel:"100 µs (1000x)",tone:"blue"},{id:"dc",type:"hex",x:500,y:215,label:"Same-DC RPC",sublabel:"0.5 ms (5000x)",tone:"purple"},{id:"wan",type:"users",x:665,y:215,label:"Global WAN",sublabel:"150 ms (1.5Mx)",tone:"amber"}],edges:[{from:"ram",to:"ssd",label:"1,000×",packetColor:"blue",speed:2},{from:"ssd",to:"dc",label:"5×",packetColor:"purple",speed:2.2},{from:"dc",to:"wan",label:"300×",packetColor:"amber",speed:2.6}],legend:[{label:"memory speed",tone:"green"},{label:"network speed",tone:"amber"}]}}],deepDive:{capacityMath:[{label:"Little's Law",value:"L = λ × W",formula:"Concurrent Requests = Throughput (req/s) × Avg Latency (sec)"},{label:"Fan-out Tail Formula",value:"P(slow) = 1 − (0.99)^N",formula:"For N = 100 downstream calls, P(slow) = 63.4%"},{label:"Utilization Target",value:"≤ 65–70% CPU",formula:"Leaves headroom for 2x traffic spikes + zone failover"},{label:"4 Nines Availability",value:"99.99% = 52.6 min/yr",formula:"99.9% = 8.76 hr/yr · 99.999% = 5.26 min/yr"}],failureModes:[{title:"Retry Storm Turning a Blip Into a Total Outage",mitigation:"Cap retries at 2–3, use Exponential Backoff + Full Jitter, and enforce a per-client retry budget (max 10% of total traffic).",interviewProbe:"Why can naive immediate retries make a 5-second DB hiccup last 45 minutes?"}]}},{id:"napkin-math",title:"Napkin Math",subtitle:"Convert DAU into QPS, peak traffic, 5-year storage, bandwidth, and cache RAM in 90 seconds.",duration:"8 min",level:"Beginner",companies:["Microsoft","Google","Meta","Amazon"],tags:["back of the envelope","estimation","qps","storage","bandwidth","powers of 2"],objectives:["Use the 10^5 seconds/day shortcut to convert DAU into QPS instantly","Size peak traffic (3x–5x), storage over 5 years, and network bandwidth","Apply the 80/20 rule to estimate Redis cache RAM","Translate numbers into concrete hardware decisions (shards, replicas, CDN)"],steps:[{shortLabel:"QPS shortcut",stage:"SETUP",title:"The 100,000 seconds/day magic shortcut",body:["A day has `86,400` seconds — round it to **`10^5` (100,000) seconds** in interviews! That lets you do mental math instantaneously without fumbling.","Example: **100M DAU** making **10 reads/day** = `10^9` reads/day ÷ `10^5` sec/day = **`10,000 avg QPS`**. Multiply by **3×** for peak hours = **`30,000 peak QPS`**."],callout:{type:"INTERVIEW SIGNAL",text:"Interviewers do not care about 4 decimal places — they care about order-of-magnitude correctness (10 GB vs 10 TB decides single Postgres vs sharded cluster!)."},scene:{hud:[{label:"DAU",value:"100 Million",status:"info"},{label:"AVG READ QPS",value:"10,000 /s",status:"info"},{label:"PEAK (3×)",value:"30,000 /s",status:"warn"},{label:"WRITE (10:1)",value:"1,000 /s",status:"good"}],nodes:[{id:"dau",type:"users",x:145,y:215,label:"100M DAU",sublabel:"10 reads · 1 write",tone:"slate"},{id:"calc",type:"hex",x:400,y:215,label:"÷ 10^5 sec",sublabel:"Daily → QPS",tone:"green",badge:"86,400 ≈ 100k",badgeTone:"green"}],edges:[{from:"dau",to:"calc",label:"1B req/day",packetColor:"blue",speed:1.9}],overlayCard:{x:470,y:120,title:"INSTANT QPS CHEAT SHEET",rows:[{label:"1M req/day",value:"≈ 12 QPS",pct:15,tone:"blue"},{label:"100M req/day",value:"≈ 1.2k QPS",pct:45,tone:"green"},{label:"1B req/day",value:"≈ 12k QPS",pct:80,tone:"amber"},{label:"10B req/day",value:"≈ 120k QPS",pct:100,tone:"coral"}],footer:"Always multiply avg QPS by 3x for Peak!"},legend:[{label:"daily request volume",tone:"blue"}]}},{shortLabel:"Storage & RAM",stage:"TECHNIQUE",title:"5-year storage, replication & 80/20 cache RAM",body:["Suppose each write stores **1 KB** of JSON metadata. `100M writes/day × 1 KB = 100 GB/day`. Over **5 years** (`~1,825 days ≈ 2,000 days`), raw storage is **200 TB** (times 3× replication = **600 TB** → must shard across DB nodes!).","For **Cache RAM**, apply the **80/20 rule**: cache the hottest **20%** of daily read data. `20% × 1B reads × 1 KB` deduplicated across active items typically fits in a **100–256 GB Redis cluster**."],callout:{type:"KEY IDEA",text:"Numbers drive architecture! 50 GB total fits on one NVMe Postgres box; 200 TB requires sharding; 10 Gbps media egress demands a CDN."},scene:{hud:[{label:"DAILY NEW DATA",value:"100 GB/day",status:"info"},{label:"5-YR RAW",value:"182 TB",status:"warn"},{label:"3× REPLICATED",value:"546 TB",status:"bad"},{label:"HOT CACHE (20%)",value:"~128 GB RAM",status:"good"}],nodes:[{id:"app",type:"hex",x:145,y:215,label:"Write Path",sublabel:"1k writes/s × 1KB",tone:"blue"},{id:"cache",type:"cache",x:400,y:120,label:"Redis Cluster",sublabel:"128 GB Hot 20%",tone:"green",badge:"fits in RAM",badgeTone:"green"},{id:"db",type:"db",x:400,y:300,label:"Sharded DB",sublabel:"546 TB (3x repl)",tone:"purple",badge:"needs sharding",badgeTone:"amber"},{id:"cdn",type:"hex",x:635,y:215,label:"Object + CDN",sublabel:"Images / Video",tone:"amber",callout:"S3 / Blob"}],edges:[{from:"app",to:"cache",label:"hot read keys",packetColor:"green",speed:1.7},{from:"app",to:"db",label:"100 GB/day",packetColor:"purple",speed:2.1},{from:"db",to:"cdn",label:"media blobs",packetColor:"amber",dashed:!0,speed:2.4}],legend:[{label:"hot cache",tone:"green"},{label:"durable writes",tone:"purple"},{label:"media offload",tone:"amber"}]}},{shortLabel:"Recap",stage:"RECAP",title:"The 4-line Napkin Math template for interviews",body:["1. **QPS**: `DAU × actions / 10^5` (and Peak = `3× avg`).","2. **Storage**: `writes/day × payload_bytes × 365 × 5 × replication_factor`.","3. **Bandwidth**: `peak_QPS × avg_response_bytes × 8` (bits/sec).","4. **Decision trigger**: Use these numbers immediately to justify your Cache, CDN, Read Replicas, or Sharding — then try the live calculator in **Design Lab**!"],callout:{type:"GOOD TO KNOW",text:"1 Million bytes = 1 MB · 1 Billion bytes = 1 GB · 1 Trillion bytes = 1 TB · 1 Quadrillion bytes = 1 PB."},scene:{hud:[{label:"10^6 BYTES",value:"1 MB",status:"info"},{label:"10^9 BYTES",value:"1 GB",status:"info"},{label:"10^12 BYTES",value:"1 TB",status:"warn"},{label:"10^15 BYTES",value:"1 PB",status:"bad"}],nodes:[{id:"q",type:"hex",x:135,y:215,label:"1. QPS",sublabel:"Peak = 3× Avg",tone:"blue"},{id:"s",type:"db",x:315,y:215,label:"2. Storage",sublabel:"5-Yr × 3× Repl",tone:"purple"},{id:"b",type:"hex",x:495,y:215,label:"3. Bandwidth",sublabel:"Mbps / Gbps",tone:"amber"},{id:"c",type:"cache",x:660,y:215,label:"4. Cache",sublabel:"80/20 Hot Set",tone:"green"}],edges:[{from:"q",to:"s",label:"drives shards",packetColor:"purple",speed:2},{from:"s",to:"b",label:"drives CDN",packetColor:"amber",speed:2},{from:"b",to:"c",label:"drives RAM",packetColor:"green",speed:2}],legend:[{label:"sizing pipeline",tone:"green"}]}}],deepDive:{capacityMath:[{label:"Seconds per Day",value:"86,400 ≈ 10^5",formula:"Seconds/month ≈ 2.5M · Seconds/year ≈ 3×10^7"},{label:"Typical Single Postgres Box",value:"~5k–15k QPS",formula:"Simple indexed reads; writes ~2k–5k TPS on NVMe"},{label:"Typical Single Redis Node",value:"~80k–120k ops/s",formula:"Single-threaded command loop, sub-millisecond p99"},{label:"Typical Kafka Broker",value:"~100k–500k msg/s",formula:"Sequential disk I/O + OS page cache + zero-copy sendfile()"}]}}]},a={id:"mod-02-scaling",number:"02",title:"Scaling",track:"hld",lessons:[{id:"vertical-horizontal",title:"Vertical vs Horizontal",subtitle:"When buying a bigger box beats distributed complexity — and when you must scale out.",duration:"7 min",level:"Beginner",companies:["Amazon","Microsoft","Stack Overflow"],tags:["scale up","scale out","vertical","horizontal","spof","autoscaling"],objectives:["Compare vertical scaling (scale-up) vs horizontal scaling (scale-out)","Identify the hardware ceiling and single-point-of-failure trap","Know when vertical scaling is actually the smarter Staff-level choice"],steps:[{shortLabel:"Scale up",stage:"PROBLEM",title:"Vertical scaling hits a wall — and has zero failover",body:["**Vertical scaling** (scale-up) means upgrading a single server to more CPU cores, RAM, and NVMe SSDs. It requires **zero code changes**, zero network hops between nodes, and keeps transactions trivially ACID.","But hardware has a hard ceiling (cost grows super-linearly past 64–128 cores), and if that single machine loses power or needs a kernel reboot, your **entire product goes offline**."],callout:{type:"WATCH OUT",text:"Vertical scaling alone gives you high capacity up to a ceiling, but 0% redundancy — a single machine is a Single Point of Failure (SPOF)."},scene:{hud:[{label:"NODES",value:"1 Server",status:"warn"},{label:"CPU LOAD",value:"94% (Ceiling)",status:"bad"},{label:"FAILOVER",value:"None (SPOF)",status:"bad"},{label:"CODE CHANGES",value:"Zero",status:"good"}],nodes:[{id:"u",type:"users",x:165,y:215,label:"All Users",sublabel:"15,000 req/s",tone:"slate"},{id:"big",type:"hex",x:525,y:215,label:"Giant Server",sublabel:"128 vCPU · 512GB",tone:"coral",badge:"SPOF · maxed",badgeTone:"rose",load:94}],edges:[{from:"u",to:"big",label:"100% traffic",packetColor:"coral",bidirectional:!0,speed:1.5,packetCount:3}],legend:[{label:"saturated traffic",tone:"coral"}]}},{shortLabel:"Scale out",stage:"SOLUTION",title:"Horizontal scaling adds commodity machines behind an LB",body:["**Horizontal scaling** (scale-out) spreads traffic across a fleet of identical commodity servers behind a **Load Balancer**. Traffic doubles? Add more nodes dynamically via an **Auto-Scaling Group**.","Now a single server crash only affects 1/N of capacity, and the load balancer drains it automatically in seconds."],callout:{type:"KEY IDEA",text:"In real Big Tech systems, you combine BOTH: scale vertically to a cost-efficient sweet spot (e.g., 16–32 vCPU nodes) and scale horizontally across availability zones for resilience and elastic growth."},changes:["+Load Balancer spreads requests across 4 commodity servers","+Survives single-node crash with zero downtime","~Per-node CPU drops from 94% → 32%"],scene:{hud:[{label:"NODES",value:"4 Servers",status:"good"},{label:"AVG CPU",value:"32%",status:"good"},{label:"FAILOVER",value:"Auto-drained",status:"good"},{label:"ELASTICITY",value:"Auto-scaling",status:"good"}],nodes:[{id:"u",type:"users",x:110,y:215,label:"All Users",sublabel:"15,000 req/s",tone:"slate"},{id:"lb",type:"hex",x:315,y:215,label:"Load Balancer",sublabel:"Health Checks",tone:"green",load:24},{id:"s1",type:"hex",x:580,y:95,label:"App 1",sublabel:"AZ-a",tone:"blue",load:32},{id:"s2",type:"hex",x:580,y:215,label:"App 2",sublabel:"AZ-b",tone:"blue",load:31},{id:"s3",type:"hex",x:580,y:335,label:"App 3",sublabel:"AZ-c",tone:"blue",load:33}],edges:[{from:"u",to:"lb",label:"15k req/s",packetColor:"blue",speed:1.6},{from:"lb",to:"s1",label:"5k/s",packetColor:"green",speed:1.9},{from:"lb",to:"s2",label:"5k/s",packetColor:"green",speed:1.9},{from:"lb",to:"s3",label:"5k/s",packetColor:"green",speed:1.9}],legend:[{label:"incoming traffic",tone:"blue"},{label:"balanced traffic",tone:"green"}]}},{shortLabel:"Recap",stage:"RECAP",title:"Know when NOT to over-distribute",body:["1. **Stack Overflow** served 1.3B monthly page views on just 9 beefy web servers and 2 SQL Server clusters — don’t introduce distributed complexity before you need it.","2. Always scale **stateless web/API tiers horizontally** across multiple AZs for availability, and only shard stateful databases once vertical scaling + read replicas + caching are exhausted."],callout:{type:"INTERVIEW SIGNAL",text:'Senior candidates explicitly state: "First we scale the DB vertically and add caching + read replicas; we only shard when write QPS or storage exceeds a single primary."'},scene:{hud:[{label:"STATELESS TIER",value:"Horizontal + AZs",status:"good"},{label:"DB FIRST STEP",value:"Vertical + Cache",status:"good"},{label:"DB NEXT STEP",value:"Read Replicas",status:"info"},{label:"DB LAST STEP",value:"Sharding",status:"warn"}],nodes:[{id:"v",type:"hex",x:170,y:215,label:"1. Vertical",sublabel:"Simple + Cache",tone:"green"},{id:"r",type:"db",x:390,y:215,label:"2. Replicas",sublabel:"Scale Reads",tone:"blue"},{id:"sh",type:"db",x:605,y:215,label:"3. Sharding",sublabel:"Scale Writes/TB",tone:"purple"}],edges:[{from:"v",to:"r",label:"read bottleneck",packetColor:"blue",speed:2},{from:"r",to:"sh",label:"write / TB limit",packetColor:"purple",speed:2.2}],legend:[{label:"scaling ladder",tone:"blue"}]}}],deepDive:{tradeoffs:[{option:"Vertical Scaling",bestWhen:"Early stage, heavy ACID SQL joins, low operational headcount",pros:"No distributed transactions, lowest latency (local RAM/IPC), minimal ops",cons:"Hardware ceiling, downtime during upgrades, single point of failure"},{option:"Horizontal Scaling",bestWhen:"High availability SLAs, spiky workloads, global scale",pros:"Near-infinite scale, zero-downtime rolling upgrades, fault tolerance",cons:"Requires load balancer, stateless design, distributed state & debugging overhead"}]}},{id:"load-balancing",title:"Load Balancing",subtitle:"L4 vs L7 routing, balancing algorithms, active health checks, and avoiding LB SPOF.",duration:"9 min",level:"Beginner",companies:["Microsoft","Amazon","Google","Cloudflare"],tags:["l4","l7","nginx","envoy","haproxy","round robin","least connections","anycast"],objectives:["Compare Layer 4 (TCP/UDP) vs Layer 7 (HTTP/gRPC) load balancers","Pick the right balancing algorithm (Round Robin, Least Connections, Consistent Hash)","Design high-availability load balancers with Anycast BGP / active-passive VIP"],steps:[{shortLabel:"L4 vs L7",stage:"SETUP",title:"Transport-level speed (L4) vs content-aware routing (L7)",body:["A **Layer 4 Load Balancer** (AWS NLB, Azure LB, Maglev) inspects only IP + TCP/UDP port and forwards packets at millions of connections/sec with ultra-low overhead — it never decrypts HTTPS.","A **Layer 7 Load Balancer** (Envoy, NGINX, AWS ALB) terminates TLS and reads HTTP URLs, headers, cookies, and gRPC paths — routing `/api/payments` to the Payment cluster and `/static/*` to Media."],callout:{type:"KEY IDEA",text:"At Big Tech scale (Google Maglev, Meta Katran), requests hit an L4 Anycast load balancer fleet first, which spreads connections across a horizontally scaled L7 Envoy/NGINX tier."},scene:{hud:[{label:"L4 THROUGHPUT",value:"Millions RPS",status:"good"},{label:"L7 ROUTING",value:"Path / Header",status:"good"},{label:"TLS TERM",value:"At L7 Edge",status:"info"},{label:"ARCHITECTURE",value:"L4 → L7 Tiered",status:"good"}],nodes:[{id:"u",type:"users",x:100,y:215,label:"Clients",sublabel:"HTTPS",tone:"slate"},{id:"l4",type:"hex",x:275,y:215,label:"L4 LB",sublabel:"TCP / ECMP",tone:"amber",badge:"ultra-fast",badgeTone:"amber",load:22},{id:"l7",type:"hex",x:465,y:215,label:"L7 Proxy",sublabel:"Envoy / TLS",tone:"green",badge:"path routing",badgeTone:"green",load:40},{id:"pay",type:"hex",x:660,y:125,label:"Payments",sublabel:"/api/pay",tone:"purple",load:36},{id:"feed",type:"hex",x:660,y:300,label:"Feed Svc",sublabel:"/api/feed",tone:"blue",load:44}],edges:[{from:"u",to:"l4",label:"TCP:443",packetColor:"amber",speed:1.6},{from:"l4",to:"l7",label:"L4 forward",packetColor:"green",speed:1.6},{from:"l7",to:"pay",label:"/api/pay",packetColor:"purple",speed:1.8},{from:"l7",to:"feed",label:"/api/feed",packetColor:"blue",speed:1.8}],legend:[{label:"L4 TCP packets",tone:"amber"},{label:"L7 path routes",tone:"blue"}]}},{shortLabel:"Algorithms",stage:"TECHNIQUE",title:"Why Least Connections beats Round Robin under skew",body:["**Round Robin** sends requests 1-2-3-1-2-3 blindly. If one endpoint takes 5 ms and another takes 800 ms (or runs on slower hardware), Round Robin overloads busy servers!","**Least Connections** (or **Power of Two Choices — P2C**, used by Envoy and NGINX) picks two random healthy backends and forwards to whichever has fewer active in-flight requests — achieving near-optimal load balance in O(1) time."],callout:{type:"INTERVIEW SIGNAL",text:'Mentioning "Power of Two Choices (P2C) Least-Requests" in a Microsoft/Google/Meta interview immediately signals real production L7 proxy experience!'},scene:{hud:[{label:"ALGORITHM",value:"P2C Least Conn",status:"good"},{label:"HEAVY SERVER",value:"Avoided",status:"good"},{label:"COMPLEXITY",value:"O(1)",status:"good"},{label:"TAIL LATENCY",value:"-42% p99",status:"good"}],nodes:[{id:"lb",type:"hex",x:185,y:215,label:"Envoy L7",sublabel:"P2C Least Conn",tone:"green",load:28},{id:"s1",type:"hex",x:540,y:100,label:"Node A",sublabel:"140 active",tone:"coral",badge:"busy · skipped",badgeTone:"rose",load:91},{id:"s2",type:"hex",x:540,y:215,label:"Node B",sublabel:"22 active",tone:"blue",badge:"selected",badgeTone:"green",load:34},{id:"s3",type:"hex",x:540,y:330,label:"Node C",sublabel:"19 active",tone:"blue",badge:"selected",badgeTone:"green",load:30}],edges:[{from:"lb",to:"s1",label:"throttled",packetColor:"coral",dashed:!0,dim:!0,speed:3.5},{from:"lb",to:"s2",label:"route here",packetColor:"green",speed:1.6},{from:"lb",to:"s3",label:"route here",packetColor:"green",speed:1.6}],legend:[{label:"fast healthy node",tone:"green"},{label:"congested node skipped",tone:"coral"}]}},{shortLabel:"Health & HA",stage:"SOLUTION",title:"Health checks & eliminating LB as a Single Point of Failure",body:["Load balancers run both **active health checks** (periodic `GET /healthz`) and **passive outlier detection** (ejecting a backend that returns 5 consecutive 5xx errors).","What if the Load Balancer itself dies? Production setups deploy **redundant LB pairs** (Active-Active via DNS/ECMP BGP or Active-Passive via floating Virtual IP / VRRP) across multiple Availability Zones."],callout:{type:"WATCH OUT",text:"Keep `/healthz` shallow (process alive) and `/readyz` mindful of dependencies — never fail `/healthz` just because a downstream analytics DB blinked, or the LB will kill your entire healthy fleet!"},changes:["+Active-Active redundant LB fleet via BGP ECMP","+Unhealthy Node C automatically ejected on 3 failed probes","~Zero user-visible errors during backend crash"],scene:{hud:[{label:"LB REDUNDANCY",value:"Active-Active",status:"good"},{label:"NODE C STATUS",value:"Ejected",status:"warn"},{label:"FAILOVER TIME",value:"< 2 sec",status:"good"},{label:"UPTIME",value:"99.99%",status:"good"}],nodes:[{id:"dns",type:"users",x:110,y:215,label:"Anycast BGP",sublabel:"ECMP Split",tone:"slate"},{id:"lb1",type:"hex",x:320,y:145,label:"LB Primary",sublabel:"AZ-a",tone:"green",load:34},{id:"lb2",type:"hex",x:320,y:285,label:"LB Secondary",sublabel:"AZ-b",tone:"green",load:35},{id:"ok",type:"hex",x:600,y:150,label:"Healthy Pool",sublabel:"200 OK",tone:"blue",badge:"serving",badgeTone:"green",load:48},{id:"bad",type:"hex",x:600,y:300,label:"Crashed Node",sublabel:"503 / Timeout",tone:"coral",badge:"ejected",badgeTone:"rose",dim:!0,load:0}],edges:[{from:"dns",to:"lb1",label:"50%",packetColor:"green",speed:1.8},{from:"dns",to:"lb2",label:"50%",packetColor:"green",speed:1.8},{from:"lb1",to:"ok",label:"active",packetColor:"blue",speed:1.7},{from:"lb2",to:"ok",label:"active",packetColor:"blue",speed:1.7},{from:"lb2",to:"bad",label:"health probe fail",packetColor:"coral",dashed:!0,dim:!0,speed:3}],legend:[{label:"ECMP balanced",tone:"green"},{label:"ejected probe",tone:"coral"}]}}],deepDive:{tradeoffs:[{option:"Round Robin / Weighted RR",bestWhen:"Uniform fast endpoints, identical VM sizes",pros:"Dead simple, zero state",cons:"Ignores slow requests & uneven CPU load"},{option:"Least Connections / P2C",bestWhen:"Mixed fast/slow APIs, WebSockets, variable DB queries",pros:"Naturally avoids overloaded nodes",cons:"Slightly more state tracking on LB"},{option:"Consistent Hash (IP/Key)",bestWhen:"Local in-memory caches, stateful chat rooms, CDN edges",pros:"Maximizes cache hit rate on backend",cons:"Hot keys can skew load onto one server"}]}},{id:"stateless",title:"Stateless Services",subtitle:"Why storing sessions in server RAM breaks autoscaling, and how externalizing state unlocks elasticity.",duration:"7 min",level:"Beginner",companies:["Amazon","Microsoft","Netflix"],tags:["stateless","sticky sessions","redis session","jwt","autoscaling"],objectives:["See why in-memory server sessions break load balancing and deploys","Externalize session state to Redis or signed stateless JWTs","Separate stateless compute tiers from stateful data tiers"],steps:[{shortLabel:"Sticky trap",stage:"PROBLEM",title:"In-memory sessions trap users on one server",body:["If Server A stores Alice’s shopping cart or login session in its local RAM, every future request from Alice **must** land on Server A (**sticky sessions**).","When Server A restarts for a deployment or crashes, Alice is logged out and loses her cart. Worse, autoscaling adds Server D, which gets zero existing sticky users while Server A stays overloaded!"],callout:{type:"WATCH OUT",text:"Sticky sessions couple user availability to a single server instance — turning horizontal scaling into brittle vertical silos."},scene:{hud:[{label:"SESSION STORE",value:"Local RAM",status:"bad"},{label:"ON SERVER CRASH",value:"Cart Lost!",status:"bad"},{label:"AUTOSCALING",value:"Uneven / Broken",status:"bad"},{label:"DEPLOY IMPACT",value:"Forced Logout",status:"warn"}],nodes:[{id:"alice",type:"users",x:120,y:215,label:"Alice",sublabel:"Cookie: SrvA",tone:"slate"},{id:"lb",type:"hex",x:325,y:215,label:"Load Balancer",sublabel:"Sticky Cookie",tone:"amber"},{id:"s1",type:"hex",x:580,y:140,label:"Server A",sublabel:"Alice RAM (Crash!)",tone:"coral",badge:"session lost",badgeTone:"rose",load:90},{id:"s2",type:"hex",x:580,y:295,label:"Server B",sublabel:"No Alice state",tone:"slate",dim:!0,load:12}],edges:[{from:"alice",to:"lb",label:"checkout",packetColor:"coral",speed:1.8},{from:"lb",to:"s1",label:"pinned to A",packetColor:"coral",speed:1.8},{from:"lb",to:"s2",label:"401 Unauthorized",packetColor:"amber",dashed:!0,dim:!0,speed:2.8}],legend:[{label:"pinned sticky route",tone:"coral"},{label:"missing state fallback",tone:"amber"}]}},{shortLabel:"External state",stage:"SOLUTION",title:"Move state out to a shared Redis store (or signed JWT)",body:["By moving session & cart state out of app server RAM into a replicated **Redis Cluster** (or self-contained signed **JWT** for read-only auth claims), every app server becomes **100% stateless and interchangeable**.","Now the Load Balancer can route Alice’s request to ANY server, you can run zero-downtime rolling deploys, and Kubernetes HPA can scale from 5 → 500 pods effortlessly."],callout:{type:"KEY IDEA",text:"Treat stateless compute servers like cattle (disposable, replaceable in seconds), and isolate all durable state inside purpose-built replicated data stores."},changes:["+Shared replicated Redis cluster holds session state (0.5 ms)","+App servers hold zero user state in RAM","~Any server can answer any user — instant autoscaling & zero-downtime deploys"],scene:{hud:[{label:"APP TIER",value:"100% Stateless",status:"good"},{label:"SESSION STORE",value:"Redis Cluster",status:"good"},{label:"ON SERVER CRASH",value:"Zero Impact",status:"good"},{label:"AUTOSCALING",value:"Linear",status:"good"}],nodes:[{id:"alice",type:"users",x:100,y:215,label:"Alice",sublabel:"Session ID",tone:"slate"},{id:"lb",type:"hex",x:260,y:215,label:"LB",sublabel:"Any Node",tone:"green"},{id:"s1",type:"hex",x:450,y:135,label:"App 1",sublabel:"Stateless",tone:"blue",load:38},{id:"s2",type:"hex",x:450,y:295,label:"App 2",sublabel:"Stateless",tone:"blue",load:36},{id:"redis",type:"cache",x:650,y:215,label:"Redis HA",sublabel:"Sessions + Cart",tone:"purple",badge:"replicated",badgeTone:"green"}],edges:[{from:"alice",to:"lb",label:"req",packetColor:"green",speed:1.7},{from:"lb",to:"s1",label:"req 1",packetColor:"blue",speed:1.8},{from:"lb",to:"s2",label:"req 2",packetColor:"blue",speed:1.8},{from:"s1",to:"redis",label:"0.5 ms",packetColor:"purple",bidirectional:!0,speed:1.6},{from:"s2",to:"redis",label:"0.5 ms",packetColor:"purple",bidirectional:!0,speed:1.6}],legend:[{label:"any-node routing",tone:"blue"},{label:"shared state lookup",tone:"purple"}]}},{shortLabel:"Exceptions",stage:"TRADEOFF",title:"When stateful services ARE intentional",body:["Not every tier can be stateless: **WebSocket gateways** (chat servers holding open TCP sockets), **real-time multiplayer game servers**, and **in-memory stream processors (Flink)** hold live state in RAM on purpose.","For those, keep business logic stateless and isolate connection state into a dedicated **Stateful Gateway Tier** with a Redis mapping (`userId → gatewayHost`)."],callout:{type:"INTERVIEW SIGNAL",text:"Calling out the split between stateful WebSocket edge servers and stateless backend microservices is a classic Senior/Staff signal in WhatsApp & Uber designs."},scene:{hud:[{label:"WS GATEWAY",value:"Stateful Socket",status:"warn"},{label:"CORE APIS",value:"Stateless",status:"good"},{label:"ROUTING TABLE",value:"Redis Registry",status:"info"},{label:"BLAST RADIUS",value:"Isolated",status:"good"}],nodes:[{id:"c",type:"users",x:110,y:215,label:"Chat Users",sublabel:"Persistent WS",tone:"slate"},{id:"ws",type:"hex",x:315,y:215,label:"WS Gateway",sublabel:"Holds Sockets",tone:"amber",badge:"stateful edge",badgeTone:"amber"},{id:"svc",type:"hex",x:540,y:140,label:"Chat Logic",sublabel:"Stateless Fleet",tone:"blue",badge:"elastic",badgeTone:"green"},{id:"reg",type:"cache",x:540,y:295,label:"Presence Map",sublabel:"user → gw_id",tone:"purple"}],edges:[{from:"c",to:"ws",label:"TCP WS",packetColor:"amber",bidirectional:!0,speed:1.9},{from:"ws",to:"svc",label:"gRPC",packetColor:"blue",speed:1.7},{from:"svc",to:"reg",label:"lookup gw",packetColor:"purple",speed:1.7}],legend:[{label:"stateful TCP socket",tone:"amber"},{label:"stateless RPC",tone:"blue"}]}}]},{id:"caching",title:"Caching",subtitle:"Cache-Aside, Write-Through, Write-Behind, LRU/LFU eviction, and surviving Stampedes & Hot Keys.",duration:"11 min",level:"Intermediate",companies:["Meta","Amazon","Microsoft","Google"],tags:["redis","memcached","cache-aside","write-through","write-back","stampede","bloom filter","lru","lfu"],objectives:["Compare Cache-Aside, Write-Through, and Write-Behind caching patterns","Pick eviction policies (LRU, LFU, TTL jitter)","Mitigate Cache Stampede (Thundering Herd), Cache Penetration, and Hot Keys"],steps:[{shortLabel:"DB overload",stage:"PROBLEM",title:"Repeated hot reads crush your database",body:["Most internet apps are **90–99% reads** and obey a power-law distribution: **20% of items receive 80%+ of traffic** (trending posts, product pages, user profiles).","Sending every identical read to disk-backed PostgreSQL wastes CPU parsing SQL, acquiring latches, and hitting storage IOPS — collapsing latency at just 10k RPS."],callout:{type:"WATCH OUT",text:"A single Redis node handles ~100,000 ops/sec at < 1 ms latency because it serves directly from RAM with zero query planner overhead."},scene:{hud:[{label:"READ LATENCY",value:"145 ms",status:"bad"},{label:"DB CPU",value:"96%",status:"bad"},{label:"CACHE HIT RATE",value:"0%",status:"bad"},{label:"READ/WRITE",value:"95 : 5",status:"info"}],nodes:[{id:"app",type:"hex",x:185,y:215,label:"App Fleet",sublabel:"50k reads/s",tone:"blue",load:52},{id:"db",type:"db",x:545,y:215,label:"Primary DB",sublabel:"Disk IOPS maxed",tone:"coral",badge:"overloaded",badgeTone:"rose",load:96}],edges:[{from:"app",to:"db",label:"50k identical SELECTs/s",packetColor:"coral",bidirectional:!0,speed:1.4,packetCount:3}],legend:[{label:"uncached DB queries",tone:"coral"}]}},{shortLabel:"Cache-Aside",stage:"SOLUTION",title:"Cache-Aside (Lazy Loading) offloads 95% of reads",body:["In **Cache-Aside**, the app checks **Redis** first. On a **Hit** (95%), it returns in < 1 ms. On a **Miss** (5%), it queries the DB, writes the result into Redis with a **TTL**, and returns.","On writes, the app updates the DB first and **deletes (invalidates)** the cache key — deleting is safer than overwriting the cache because concurrent writes cannot leave an older value stuck in Redis."],callout:{type:"KEY IDEA",text:"Update DB → Delete Cache (never Update Cache before DB, which risks stale data on concurrent updates). Always attach a TTL as a safety net!"},changes:["+Redis Cluster intercepts 95% of reads in 0.6 ms","~Primary DB load plunges from 96% → 18%","~p99 read latency drops from 145 ms → 4 ms"],scene:{hud:[{label:"READ LATENCY",value:"4 ms",status:"good"},{label:"DB CPU",value:"18%",status:"good"},{label:"CACHE HIT RATE",value:"95%",status:"good"},{label:"PATTERN",value:"Cache-Aside",status:"info"}],nodes:[{id:"app",type:"hex",x:165,y:215,label:"App Fleet",sublabel:"Check Cache First",tone:"blue",load:42},{id:"redis",type:"cache",x:440,y:120,label:"Redis Cache",sublabel:"0.6 ms · TTL 5m",tone:"green",badge:"95% hit",badgeTone:"green",load:34},{id:"db",type:"db",x:590,y:295,label:"Primary DB",sublabel:"5% miss + writes",tone:"purple",load:18}],edges:[{from:"app",to:"redis",label:"1. GET (95% hit)",packetColor:"green",bidirectional:!0,speed:1.4,packetCount:3},{from:"app",to:"db",label:"2. miss only (5%)",packetColor:"amber",dashed:!0,speed:2.6},{from:"db",to:"redis",label:"3. populate + TTL",packetColor:"purple",dashed:!0,speed:2.4}],legend:[{label:"fast cache hit",tone:"green"},{label:"5% DB miss",tone:"amber"},{label:"lazy fill",tone:"purple"}]}},{shortLabel:"Stampede fix",stage:"TECHNIQUE",title:"Preventing Cache Stampede, Penetration & Avalanche",body:["1. **Cache Stampede (Thundering Herd)**: A celebrity key expires and 10,000 requests simultaneously miss and slam the DB. Fix: **Single-Flight Mutex / Request Coalescing** (only 1 request queries DB; 9,999 wait for its result) + **Probabilistic Early Expiration**.","2. **Cache Penetration**: Attackers request non-existent IDs (`id=-999`), bypassing the cache every time. Fix: **Bloom Filter** in front of DB + cache negative `NULL` sentinels with short TTL.","3. **Cache Avalanche**: 1M keys expire at the exact same second. Fix: Add **random TTL jitter** (`baseTTL + rand(0, 20%)`)."],callout:{type:"INTERVIEW SIGNAL",text:"Naming all three caching failure modes — Stampede (Single-Flight), Penetration (Bloom Filter), Avalanche (TTL Jitter) — is a guaranteed Strong Hire highlight at Microsoft, Meta, and Amazon."},scene:{hud:[{label:"STAMPEDE",value:"Single-Flight Lock",status:"good"},{label:"PENETRATION",value:"Bloom Filter",status:"good"},{label:"AVALANCHE",value:"TTL + Jitter",status:"good"},{label:"HOT KEYS",value:"L1 Local + Salt",status:"good"}],nodes:[{id:"reqs",type:"users",x:105,y:215,label:"10k Reqs",sublabel:"Same Hot Key",tone:"slate"},{id:"sf",type:"hex",x:320,y:215,label:"Single-Flight",sublabel:"Coalesce + Bloom",tone:"green",badge:"1 DB call only",badgeTone:"green",load:35},{id:"l1",type:"cache",x:540,y:120,label:"L1 + Redis",sublabel:"TTL + Jitter",tone:"blue",badge:"protected",badgeTone:"blue"},{id:"db",type:"db",x:635,y:295,label:"Primary DB",sublabel:"1 query / miss",tone:"purple",load:14}],edges:[{from:"reqs",to:"sf",label:"10k concurrent",packetColor:"coral",speed:1.5,packetCount:3},{from:"sf",to:"l1",label:"shared fill",packetColor:"green",bidirectional:!0,speed:1.7},{from:"sf",to:"db",label:"1 coalesced read",packetColor:"amber",dashed:!0,speed:2.5,packetCount:1}],legend:[{label:"10k waiting callers",tone:"coral"},{label:"1 single-flight DB read",tone:"amber"},{label:"broadcast hit",tone:"green"}]}},{shortLabel:"Write patterns",stage:"TRADEOFF",title:"Write-Through vs Write-Behind (Write-Back) & Eviction",body:["**Write-Through** updates cache and DB synchronously on every write (always fresh reads, higher write latency). **Write-Behind** writes to cache immediately and flushes asynchronously to DB in batches (blazing writes for counters/likes, risks data loss if cache crashes before flush).","When memory fills up, evict with **LRU** (Least Recently Used — O(1) HashMap + Doubly-Linked List) or **LFU / W-TinyLFU** (evicts infrequent items so one-time scans don’t pollute hot cache!)."],callout:{type:"GOOD TO KNOW",text:"Explore LRU/LFU pointer swaps and trigger a live Cache Stampede in the interactive **Design Lab → Caching & Eviction Lab**!"},scene:{hud:[{label:"CACHE-ASIDE",value:"Read-heavy General",status:"good"},{label:"WRITE-THROUGH",value:"Consistent Reads",status:"info"},{label:"WRITE-BEHIND",value:"Ultra-fast Writes",status:"warn"},{label:"EVICTION",value:"LRU / W-TinyLFU",status:"good"}],nodes:[{id:"w",type:"hex",x:140,y:215,label:"Writer",sublabel:"POST /like",tone:"blue"},{id:"c",type:"cache",x:390,y:215,label:"Redis Buffer",sublabel:"ACK in 0.5ms",tone:"green",badge:"Write-Behind",badgeTone:"amber"},{id:"d",type:"db",x:640,y:215,label:"DB Batch",sublabel:"Flush every 5s",tone:"purple"}],edges:[{from:"w",to:"c",label:"instant write",packetColor:"green",bidirectional:!0,speed:1.5},{from:"c",to:"d",label:"async batch flush",packetColor:"amber",dashed:!0,speed:2.8}],legend:[{label:"fast cache ACK",tone:"green"},{label:"async DB flush",tone:"amber"}]}}],deepDive:{tradeoffs:[{option:"Cache-Aside (Lazy)",bestWhen:"General read-heavy apps (profiles, feeds, catalogs)",pros:"Only caches requested data; resilient if Redis restarts",cons:"First request misses; brief staleness window possible"},{option:"Write-Through",bestWhen:"Read-after-write freshness required, moderate writes",pros:"Cache never stale on writes; simple read path",cons:"Higher write latency (2 hops); caches cold write-only data"},{option:"Write-Behind (Write-Back)",bestWhen:"High-volume counters, views, telemetry, gaming leaderboards",pros:"Ultra-fast write latency + DB write coalescing",cons:"Risk of data loss if cache crashes before async DB flush"},{option:"Redis vs Memcached",bestWhen:"Redis for rich structures/HA/persistence; Memcached for simple multi-threaded KV",pros:"Redis: Sorted Sets, Lua, Streams, Cluster; Memcached: pure multi-core slab KV",cons:"Redis single-threaded command loop can block on O(N) KEYS * calls"}],failureModes:[{title:"Hot Key Saturating One Redis Shard (e.g., Justin Bieber Tweet)",mitigation:"Add an in-process L1 micro-cache (e.g., 5-second Caffeine/LRU in app RAM) OR salt hot keys across K shards (`key#0..key#9`) and read randomly.",interviewProbe:"Your Redis cluster has 20 shards at 10% CPU, except Shard 7 is at 100% CPU. Why and how do you fix it?"}]}},{id:"cdn",title:"Content Delivery",subtitle:"Put static files close to users with edge servers — cutting global latency by 90% and shielding your origin.",duration:"10 min",level:"Beginner",companies:["Netflix","Cloudflare","Amazon","Microsoft"],tags:["cdn","edge","cloudfront","cloudflare","akamai","cache invalidation","origin shield","anycast"],objectives:["Why speed-of-light distance makes a single origin slow globally","How edge servers cache static files (90%+ of page bytes)","Cold edge warming vs warm cache hit ratios","Invalidation strategies: content hashing, TTL, and purge APIs","Protecting your origin with Origin Shield and Edge Compute"],steps:[{shortLabel:"Far away",stage:"PROBLEM",title:"Your users are far away",body:["Your servers live in **Virginia (us-east-1)**, where latency to New York is 10 ms. But light in fiber optic cable travels at ~200,000 km/s — physics sets a hard floor of **75 ms RTT from London** and **200+ ms RTT from Sydney**.","Every image, CSS file, JS bundle, and video chunk forces global users to cross oceans repeatedly while hammering your single origin at **9,000 req/s**."],callout:{type:"WATCH OUT",text:"You cannot optimize code to beat the speed of light. TCP + TLS + HTTP across 16,000 km can burn over 600 ms before the first pixel renders!"},scene:{hud:[{label:"LONDON LATENCY",value:"80 ms",status:"warn"},{label:"SYDNEY LATENCY",value:"210 ms",status:"bad"},{label:"ORIGIN LOAD",value:"9,000 req/s",status:"bad"},{label:"CACHE HIT RATE",value:"0%",status:"bad"}],nodes:[{id:"origin",type:"hex",x:380,y:110,label:"Origin",sublabel:"Virginia",tone:"blue",load:88},{id:"lon",type:"users",x:175,y:310,label:"London",sublabel:"EU Users",tone:"slate"},{id:"syd",type:"users",x:585,y:310,label:"Sydney",sublabel:"APAC Users",tone:"slate"}],edges:[{from:"lon",to:"origin",label:"≈ 75 ms RTT",packetColor:"coral",bidirectional:!0,speed:2.3,packetCount:2},{from:"syd",to:"origin",label:"≈ 200 ms RTT",packetColor:"coral",bidirectional:!0,speed:3.4,packetCount:2}],legend:[{label:"long-haul request",tone:"coral"},{label:"response",tone:"green"}]}},{shortLabel:"Same bytes",stage:"INSIGHT",title:"98% of a web page is identical for every user",body:['Inspect a typical 2 MB web page: only **30 KB** is personalized HTML/JSON ("Hello, Alice"). The remaining **1.97 MB** — hero images, product thumbnails, fonts, React JS bundles, CSS — is **byte-for-byte identical** for everyone in London and Sydney.',"Shipping the exact same 1.6 MB image across the Pacific Ocean 50,000 times a minute is pure waste."],callout:{type:"KEY IDEA",text:"Static assets are typically 90–98% of the bytes on a page. Cache them once in every major city and let your Origin focus solely on tiny dynamic API calls."},scene:{hud:[{label:"PERSONAL HTML",value:"30 KB (2%)",status:"info"},{label:"STATIC ASSETS",value:"2.0 MB (98%)",status:"good"},{label:"ORIGIN LOAD",value:"9,000 req/s",status:"warn"},{label:"CACHEABLE",value:"98% bytes",status:"good"}],nodes:[{id:"origin",type:"hex",x:220,y:115,label:"Origin",sublabel:"Virginia",tone:"blue",load:88},{id:"lon",type:"users",x:120,y:315,label:"London",sublabel:"Same JS/Images",tone:"slate"},{id:"syd",type:"users",x:350,y:315,label:"Sydney",sublabel:"Same JS/Images",tone:"slate"}],edges:[{from:"lon",to:"origin",label:"2 MB each time",packetColor:"coral",speed:2.3},{from:"syd",to:"origin",label:"2 MB each time",packetColor:"coral",speed:3.1}],overlayCard:{x:455,y:55,title:"WHAT A PAGE IS MADE OF",rows:[{label:"HTML (per user)",value:"30 KB",pct:4,tone:"blue"},{label:"Images & Video",value:"1.6 MB",pct:78,tone:"green"},{label:"JS + CSS + Fonts",value:"400 KB",pct:20,tone:"purple"}],footer:"98% of bytes are identical for everyone"},legend:[{label:"redundant static bytes",tone:"coral"}]}},{shortLabel:"Edges",stage:"SOLUTION",title:"Place CDN Edge PoPs next to your users",body:["A **Content Delivery Network (CDN)** deploys hundreds of caching **Edge Servers (Points of Presence / PoPs)** inside cities worldwide, routed automatically via **Anycast BGP**.","Now London users fetch images in **12 ms** from Edge London, and Sydney users fetch in **16 ms** from Edge Sydney! Only the 10% uncached or dynamic requests ever touch Virginia."],callout:{type:"GOOD TO KNOW",text:"Major CDNs: Cloudflare, AWS CloudFront, Fastly, Akamai, Azure Front Door, and Netflix’s custom ISP-embedded Open Connect appliances."},changes:["+Edge servers deployed in London and Sydney","~90% of requests answered locally at the edge","~Origin load drops 9,000 → 933 req/s (CPU 88% → 28%)"],scene:{hud:[{label:"LONDON LATENCY",value:"12 ms",status:"good"},{label:"SYDNEY LATENCY",value:"16 ms",status:"good"},{label:"ORIGIN LOAD",value:"933 req/s",status:"good"},{label:"CACHE HIT RATE",value:"90%",status:"good"}],nodes:[{id:"origin",type:"hex",x:380,y:85,label:"Origin",sublabel:"Virginia",tone:"blue",load:28},{id:"edge-lon",type:"hex",x:185,y:205,label:"Edge London",sublabel:"PoP LHR",tone:"green",badge:"warm · 92% hit",badgeTone:"green",load:31},{id:"edge-syd",type:"hex",x:575,y:205,label:"Edge Sydney",sublabel:"PoP SYD",tone:"green",badge:"warm · 89% hit",badgeTone:"green",load:29},{id:"lon",type:"users",x:185,y:345,label:"London",sublabel:"12 ms",tone:"slate"},{id:"syd",type:"users",x:575,y:345,label:"Sydney",sublabel:"16 ms",tone:"slate"}],edges:[{from:"lon",to:"edge-lon",label:"12 ms hit",packetColor:"green",bidirectional:!0,speed:1.4,packetCount:2},{from:"syd",to:"edge-syd",label:"16 ms hit",packetColor:"green",bidirectional:!0,speed:1.5,packetCount:2},{from:"edge-lon",to:"origin",label:"10% miss",packetColor:"amber",dashed:!0,speed:2.8,packetCount:1},{from:"edge-syd",to:"origin",label:"10% miss",packetColor:"amber",dashed:!0,speed:3.1,packetCount:1}],legend:[{label:"edge hit (local)",tone:"green"},{label:"edge miss → origin",tone:"amber"}]}},{shortLabel:"Cold edge",stage:"TECHNIQUE",title:"Pull CDN warming: what happens on a cold edge",body:["Most modern web apps use a **Pull CDN**: you don’t manually upload files to 300 cities. When Sydney’s edge starts **cold** (or after a deploy), the first request for `hero.webp` misses, fetches from Origin, caches it locally, and every subsequent Sydney user gets a 12 ms hit.","During the warming window, Sydney latency temporarily hovers around **88 ms** and Origin load bumps to ~2,300 req/s before settling back down."],callout:{type:"GOOD TO KNOW",text:"Use a Push CDN (pre-warming edges before launch) for massive predictable events like iOS updates, Netflix premieres, or Disney+ Hotstar cricket finals."},scene:{hud:[{label:"LONDON LATENCY",value:"12 ms",status:"good"},{label:"SYDNEY LATENCY",value:"88 ms",status:"warn"},{label:"ORIGIN LOAD",value:"2,340 req/s",status:"warn"},{label:"CACHE HIT RATE",value:"71%",status:"warn"}],nodes:[{id:"origin",type:"hex",x:380,y:85,label:"Origin",sublabel:"Virginia",tone:"blue",load:52},{id:"edge-lon",type:"hex",x:185,y:205,label:"Edge London",sublabel:"≈ 10 ms",tone:"green",badge:"warm",badgeTone:"green",load:30},{id:"edge-syd",type:"hex",x:575,y:205,label:"Edge Sydney",sublabel:"filling cache",tone:"amber",badge:"cold · filling",badgeTone:"amber",load:54},{id:"lon",type:"users",x:185,y:345,label:"London",sublabel:"fast hits",tone:"slate"},{id:"syd",type:"users",x:575,y:345,label:"Sydney",sublabel:"warming up",tone:"slate"}],edges:[{from:"lon",to:"edge-lon",label:"10 ms",packetColor:"green",bidirectional:!0,speed:1.4},{from:"syd",to:"edge-syd",label:"12 ms local",packetColor:"amber",bidirectional:!0,speed:1.7},{from:"edge-syd",to:"origin",label:"only on a miss",packetColor:"amber",dashed:!0,speed:2.2,packetCount:3}],legend:[{label:"warm cache hit",tone:"green"},{label:"cold cache fill → origin",tone:"amber"}]}},{shortLabel:"Invalidation",stage:"TECHNIQUE",title:"Cache invalidation: Content Hashing beats manual purging",body:["How do you deploy a new `app.js` without users stuck on yesterday’s cached bundle? **Never overwrite the same URL** and hope TTLs expire!","Instead, use **Content-Hashed (Fingerprinted) URLs** like `app.8f3a2c.js` with `Cache-Control: public, max-age=31536000, immutable`. Your tiny `index.html` (`max-age=0, must-revalidate`) points to the new hash — instant atomic rollouts AND instant rollbacks!"],callout:{type:"INTERVIEW SIGNAL",text:"Use Content-Hashed Immutable URLs for JS/CSS/images, short `s-maxage` + `stale-while-revalidate` for semi-dynamic pages, and Surrogate Keys / Purge APIs for emergency takedowns."},scene:{hud:[{label:"STATIC ASSETS",value:"immutable · 1 yr",status:"good"},{label:"HTML SHELL",value:"revalidate",status:"info"},{label:"STALE BUG RISK",value:"Zero",status:"good"},{label:"ROLLBACK TIME",value:"< 1 sec",status:"good"}],nodes:[{id:"html",type:"hex",x:160,y:215,label:"index.html",sublabel:"no-cache",tone:"amber",badge:"tiny · 4 KB",badgeTone:"amber"},{id:"old",type:"cache",x:440,y:125,label:"app.v1a2.js",sublabel:"Old build",tone:"slate",dim:!0},{id:"new",type:"cache",x:440,y:295,label:"app.8f3c.js",sublabel:"max-age=1yr",tone:"green",badge:"immutable",badgeTone:"green"},{id:"u",type:"users",x:660,y:215,label:"Users",sublabel:"Atomic v2",tone:"blue"}],edges:[{from:"html",to:"new",label:"points to hash",packetColor:"green",speed:1.7},{from:"new",to:"u",label:"cached 1 year",packetColor:"green",speed:1.6}],legend:[{label:"immutable hashed asset",tone:"green"}]}},{shortLabel:"Origin Shield",stage:"SOLUTION",title:"Origin Shielding collapses 300 edge misses into 1",body:["With 300 global Edge PoPs, a brand-new viral video causes all 300 edges to miss simultaneously and send 300 redundant requests to Origin.","Adding a regional **Origin Shield** (a mid-tier cache layer right in front of Origin) coalesces misses across all edges: Edge London, Edge Paris, and Edge Sydney hit the Origin Shield first, so Origin only serves **1 single copy**!"],callout:{type:"KEY IDEA",text:"Tiered caching (Edge PoP → Regional Origin Shield → Origin) reduces origin egress bills by 80%+ and shields databases from viral launch spikes."},changes:["+Regional Origin Shield added in front of Virginia Origin","+300 edge misses collapsed into 1 single origin fetch","~Origin CPU stays flat at 12% even during viral launches"],scene:{hud:[{label:"EDGE POPS",value:"300 Cities",status:"good"},{label:"SHIELD LAYER",value:"Regional L2",status:"good"},{label:"ORIGIN MISSES",value:"300 → 1",status:"good"},{label:"ORIGIN CPU",value:"12%",status:"good"}],nodes:[{id:"e1",type:"hex",x:130,y:110,label:"Edge London",sublabel:"L1",tone:"green"},{id:"e2",type:"hex",x:130,y:215,label:"Edge Tokyo",sublabel:"L1",tone:"green"},{id:"e3",type:"hex",x:130,y:320,label:"Edge Sydney",sublabel:"L1",tone:"green"},{id:"shield",type:"cache",x:400,y:215,label:"Origin Shield",sublabel:"L2 Coalescer",tone:"purple",badge:"request collapse",badgeTone:"purple",load:24},{id:"origin",type:"hex",x:650,y:215,label:"Origin",sublabel:"Virginia",tone:"blue",load:12}],edges:[{from:"e1",to:"shield",label:"miss",packetColor:"amber",dashed:!0,speed:2},{from:"e2",to:"shield",label:"miss",packetColor:"amber",dashed:!0,speed:2},{from:"e3",to:"shield",label:"miss",packetColor:"amber",dashed:!0,speed:2},{from:"shield",to:"origin",label:"1 fetch only!",packetColor:"purple",bidirectional:!0,speed:2.2,packetCount:1}],legend:[{label:"edge misses",tone:"amber"},{label:"single coalesced origin read",tone:"purple"}]}},{shortLabel:"Recap",stage:"RECAP",title:"CDN architecture checklist for Big Tech interviews",body:["1. Put static images, JS, CSS, HLS/DASH video chunks, and public read-heavy APIs behind a **CDN**.","2. Use **Pull CDN** for general apps and **Push / Pre-warmed CDN** for predictable global media drops.","3. Version static assets with **content hashes (`immutable`)**; use **Origin Shield** to prevent 300-PoP miss storms; never cache private user data with `public` headers!"],callout:{type:"WATCH OUT",text:"Security bug alert: Caching a response containing a `Set-Cookie` or personalized header at a shared CDN edge leaks Alice’s account page to Bob! Always mark private routes `Cache-Control: private, no-store`."},scene:{hud:[{label:"GLOBAL LATENCY",value:"12 – 20 ms",status:"good"},{label:"ORIGIN OFFLOAD",value:"95%+",status:"good"},{label:"INVALIDATION",value:"Content Hash",status:"good"},{label:"PRIVATE DATA",value:"private, no-store",status:"info"}],nodes:[{id:"u",type:"users",x:115,y:215,label:"Global Users",sublabel:"Anycast",tone:"slate"},{id:"edge",type:"hex",x:315,y:215,label:"300+ Edges",sublabel:"TLS + Static",tone:"green",badge:"95% hit",badgeTone:"green"},{id:"sh",type:"cache",x:505,y:215,label:"Origin Shield",sublabel:"L2 Tier",tone:"purple"},{id:"o",type:"hex",x:675,y:215,label:"Origin",sublabel:"Dynamic APIs",tone:"blue",load:14}],edges:[{from:"u",to:"edge",label:"12 ms",packetColor:"green",bidirectional:!0,speed:1.5},{from:"edge",to:"sh",label:"5% miss",packetColor:"amber",dashed:!0,speed:2.3},{from:"sh",to:"o",label:"1x fill",packetColor:"purple",dashed:!0,speed:2.5}],legend:[{label:"edge hit",tone:"green"},{label:"tiered miss",tone:"amber"}]}}],deepDive:{tradeoffs:[{option:"Pull CDN",bestWhen:"Web apps, e-commerce, UGC (Instagram/YouTube long tail)",pros:"Zero sync ops; only caches actually requested assets",cons:"First request per PoP suffers cold-cache latency"},{option:"Push CDN",bestWhen:"Small immutable bundles, major game patches, live broadcast events",pros:"Zero cold-start latency at launch time",cons:"You pay storage & bandwidth even for files nobody downloads"},{option:"Edge Compute (Workers)",bestWhen:"Auth JWT verification, A/B testing, geo-redirects, HTML assembly",pros:"Sub-20ms dynamic personalization without origin RTT",cons:"Strict CPU/memory limits; global DB writes still need origin"}],failureModes:[{title:"Cache Poisoning / Personal Data Leak on CDN Edge",mitigation:"Separate static asset domains (`cdn.example.com`, cookie-less), set `Cache-Control: private, no-store` on authenticated endpoints, and configure strict `Vary` keys.",interviewProbe:"A user reports seeing another customer’s order history right after we turned on CDN caching. What happened?"}]}}]},n=[e,a],d={id:"mod-03-data-storage",number:"03",title:"Data & Storage",track:"hld",lessons:[{id:"sql-nosql",title:"SQL vs NoSQL",subtitle:"Choosing between Relational ACID, Document, Key-Value, Wide-Column, Graph, Time-Series, and Vector DBs.",duration:"10 min",level:"Beginner",companies:["Microsoft","Amazon","Google","Meta"],tags:["postgresql","mysql","dynamodb","cassandra","mongodb","neo4j","acid","nosql"],objectives:["Choose SQL when relational integrity, joins, and ACID transactions dominate","Pick the exact NoSQL family (KV, Document, Wide-Column, Graph, Time-Series, Vector)","Understand Polyglot Persistence in modern Big Tech architectures"],steps:[{shortLabel:"Relational SQL",stage:"SETUP",title:"SQL shines for structured schemas & strict ACID guarantees",body:["**Relational databases** (PostgreSQL, MySQL, Azure SQL) organize data into normalized tables linked by foreign keys and enforce **ACID** transactions (Atomicity, Consistency, Isolation, Durability).","If Alice transfers $100 to Bob, both rows commit together or roll back cleanly — never leaving money created out of thin air."],callout:{type:"KEY IDEA",text:"Default to PostgreSQL unless a concrete access pattern (massive write velocity, flexible nested JSON, graph traversals, or multi-TB KV scale) demands a specialized NoSQL engine."},scene:{hud:[{label:"GUARANTEE",value:"Strict ACID",status:"good"},{label:"JOINS",value:"Native SQL",status:"good"},{label:"SCALE LIMIT",value:"Vertical + Shards",status:"warn"},{label:"BEST FOR",value:"Finance · Orders",status:"info"}],nodes:[{id:"app",type:"hex",x:140,y:215,label:"Order Svc",sublabel:"BEGIN TX",tone:"blue"},{id:"pg",type:"db",x:420,y:215,label:"PostgreSQL",sublabel:"ACID + MVCC",tone:"purple",badge:"strict schema",badgeTone:"purple",callout:"orders + ledger"},{id:"rep",type:"db",x:645,y:215,label:"Read Replica",sublabel:"Analytics",tone:"blue"}],edges:[{from:"app",to:"pg",label:"ACID COMMIT",packetColor:"green",bidirectional:!0,speed:1.8},{from:"pg",to:"rep",label:"WAL stream",packetColor:"purple",dashed:!0,speed:2.3}],legend:[{label:"ACID transaction",tone:"green"},{label:"WAL replication",tone:"purple"}]}},{shortLabel:"NoSQL families",stage:"TECHNIQUE",title:"Not one NoSQL — pick the right data model for the query",body:['**"NoSQL" is 6 distinct engines**: **Key-Value** (DynamoDB, Redis) for sub-10ms key lookups; **Document** (MongoDB, Cosmos DB) for evolving product catalogs; **Wide-Column** (Cassandra, ScyllaDB, Bigtable) for trillions of write-heavy chat/telemetry rows; **Graph** (Neo4j) for social hops; **Time-Series** (InfluxDB/Timescale) for metrics; **Vector** (Pinecone/pgvector) for AI embeddings.',"In NoSQL, you **model around your query access patterns** (denormalize and duplicate data) to avoid expensive distributed joins!"],callout:{type:"INTERVIEW SIGNAL",text:'Never say "I will use NoSQL because it scales better." Name the exact NoSQL family and access pattern (e.g., "Cassandra partitioned by `(channel_id, bucket)` with `message_id` clustering key for sequential chat scans").'},scene:{hud:[{label:"KEY-VALUE",value:"DynamoDB / Redis",status:"good"},{label:"WIDE-COLUMN",value:"Cassandra / Scylla",status:"good"},{label:"DOCUMENT",value:"MongoDB / Cosmos",status:"info"},{label:"SEARCH / VECTOR",value:"Elastic / Milvus",status:"info"}],nodes:[{id:"gw",type:"hex",x:135,y:215,label:"Polyglot API",sublabel:"Right tool/job",tone:"green"},{id:"sql",type:"db",x:430,y:90,label:"PostgreSQL",sublabel:"Billing (ACID)",tone:"purple"},{id:"wc",type:"db",x:430,y:215,label:"ScyllaDB",sublabel:"Chat (1M writes/s)",tone:"blue",badge:"LSM-Tree",badgeTone:"blue"},{id:"es",type:"db",x:430,y:340,label:"Elasticsearch",sublabel:"Full-text Search",tone:"amber"},{id:"vec",type:"cache",x:645,y:215,label:"Vector DB",sublabel:"RAG / HNSW",tone:"green"}],edges:[{from:"gw",to:"sql",label:"payments",packetColor:"purple",speed:1.9},{from:"gw",to:"wc",label:"messages",packetColor:"blue",speed:1.6},{from:"gw",to:"es",label:"search",packetColor:"amber",speed:2},{from:"wc",to:"vec",label:"embeddings",packetColor:"green",dashed:!0,speed:2.4}],legend:[{label:"polyglot persistence",tone:"blue"}]}},{shortLabel:"NewSQL",stage:"SOLUTION",title:"Distributed SQL (Spanner / CockroachDB) bridges both worlds",body:["Modern **Distributed SQL** engines (Google Spanner, CockroachDB, TiDB) give you familiar SQL + global ACID transactions across horizontal shards using **Raft/Paxos consensus** and **TrueTime / HLC clocks**.","The trade-off? Cross-region consensus commits add **30–100 ms write latency** because a quorum across datacenters must agree before returning COMMIT."],callout:{type:"GOOD TO KNOW",text:"Google Spanner uses GPS + atomic clocks (TrueTime) to bound clock uncertainty to < 7 ms, enabling External Consistency (globally ordered serializable transactions)."},scene:{hud:[{label:"SQL + ACID",value:"Yes (Global)",status:"good"},{label:"SHARDING",value:"Automatic",status:"good"},{label:"CONSENSUS",value:"Paxos / Raft",status:"info"},{label:"WRITE LATENCY",value:"Higher (WAN RTT)",status:"warn"}],nodes:[{id:"c",type:"users",x:115,y:215,label:"Global App",sublabel:"SQL Client",tone:"slate"},{id:"r1",type:"db",x:350,y:120,label:"Range 1 (US)",sublabel:"Raft Leader",tone:"green",badge:"quorum",badgeTone:"green"},{id:"r2",type:"db",x:350,y:310,label:"Range 2 (EU)",sublabel:"Raft Leader",tone:"blue"},{id:"r3",type:"db",x:615,y:215,label:"Replica (APAC)",sublabel:"Synced Log",tone:"purple"}],edges:[{from:"c",to:"r1",label:"TX write",packetColor:"green",bidirectional:!0,speed:1.9},{from:"r1",to:"r3",label:"Raft commit",packetColor:"purple",dashed:!0,speed:2.3},{from:"r2",to:"r3",label:"Raft commit",packetColor:"blue",dashed:!0,speed:2.3}],legend:[{label:"distributed ACID write",tone:"green"},{label:"cross-region Raft",tone:"purple"}]}}],deepDive:{tradeoffs:[{option:"Relational (PostgreSQL / MySQL)",bestWhen:"Orders, ledger, IAM, complex joins, < 50k TPS",pros:"ACID, rich SQL, mature ecosystem",cons:"Manual sharding at massive write/TB scale"},{option:"Wide-Column (Cassandra / ScyllaDB)",bestWhen:"Chat messages, IoT, audit logs, massive write QPS",pros:"Linear horizontal writes, masterless high availability",cons:"No ad-hoc joins; must design tables per query"},{option:"Key-Value (DynamoDB)",bestWhen:"Shopping carts, session stores, user preferences",pros:"Predictable single-digit ms latency at any scale",cons:"Limited secondary query flexibility; hot partition limits"},{option:"Distributed SQL (Spanner / Cockroach)",bestWhen:"Global financial metadata, multi-region inventory",pros:"Auto-sharding + SQL + strong ACID",cons:"Higher cross-region write latency & compute cost"}]}},{id:"indexes",title:"Indexes",subtitle:"B+ Trees, Clustered vs Secondary, Composite Leftmost Prefix, Covering, Inverted & Spatial indexes.",duration:"9 min",level:"Beginner",companies:["Microsoft","Google","Amazon"],tags:["b-tree","composite index","covering index","inverted index","geohash","h3","quadtree"],objectives:["Turn O(N) full table scans into O(log N) B+ Tree seeks","Apply Leftmost Prefix and Covering Indexes to eliminate heap lookups","Choose Inverted Indexes (search) and Spatial Indexes (Uber/Yelp)"],steps:[{shortLabel:"Full scan",stage:"PROBLEM",title:"Without an index, every query reads the entire table",body:['Searching `WHERE email = "alice@ms.com"` on a 50-million-row unindexed table forces the database to read **every 8 KB disk page sequentially** (O(N) full table scan — 4+ seconds and 100% disk I/O!).'],callout:{type:"WATCH OUT",text:"An index speeds up READS dramatically, but every index slows down WRITES (INSERT/UPDATE/DELETE must update every B+ Tree) and consumes extra RAM & disk."},scene:{hud:[{label:"ROWS SCANNED",value:"50,000,000",status:"bad"},{label:"QUERY TIME",value:"4,200 ms",status:"bad"},{label:"COMPLEXITY",value:"O(N) Full Scan",status:"bad"},{label:"DISK IOPS",value:"98% Saturated",status:"bad"}],nodes:[{id:"q",type:"hex",x:145,y:215,label:"SQL Query",sublabel:"WHERE email=?",tone:"blue"},{id:"p1",type:"db",x:380,y:120,label:"Pages 1..1M",sublabel:"Scanning...",tone:"coral",load:98},{id:"p2",type:"db",x:380,y:310,label:"Pages 1M..5M",sublabel:"Scanning...",tone:"coral",load:98},{id:"hit",type:"db",x:630,y:215,label:"Page 4,812,001",sublabel:"Row finally found",tone:"amber"}],edges:[{from:"q",to:"p1",label:"scan all",packetColor:"coral",speed:1.6},{from:"q",to:"p2",label:"scan all",packetColor:"coral",speed:1.6},{from:"p2",to:"hit",label:"4.2 sec!",packetColor:"amber",dashed:!0,speed:3}],legend:[{label:"full table disk scan",tone:"coral"}]}},{shortLabel:"B+ Tree",stage:"SOLUTION",title:"A 4-level B+ Tree finds 1 row in 50 million in 4 page reads",body:["A **B+ Tree** packs hundreds of sorted keys into each 8–16 KB node (high branching factor ~500). With 500 keys per node, a tree just **4 levels deep** indexes `500^4 = 62.5 BILLION` rows!","Better yet, all leaf pages are linked sequentially in a doubly-linked list, making **range queries** (`WHERE created_at BETWEEN t1 AND t2`) blazingly fast sequential scans."],callout:{type:"KEY IDEA",text:"Composite Index `(tenant_id, status, created_at)` obeys the **Leftmost Prefix Rule**: it accelerates `(tenant_id)` and `(tenant_id, status)`, but CANNOT be used efficiently for a query filtering only on `(created_at)`."},changes:["+B+ Tree index built on (email) — 4 levels deep","~Rows scanned drops 50,000,000 → 1 leaf entry","~Query time drops 4,200 ms → 1.4 ms"],scene:{hud:[{label:"TREE DEPTH",value:"4 Hops",status:"good"},{label:"QUERY TIME",value:"1.4 ms",status:"good"},{label:"COMPLEXITY",value:"O(log_500 N)",status:"good"},{label:"RANGE SCANS",value:"Linked Leaves",status:"good"}],nodes:[{id:"root",type:"hex",x:380,y:85,label:"Root Node",sublabel:"Pinned in RAM",tone:"green",badge:"hop 1",badgeTone:"green"},{id:"b1",type:"hex",x:205,y:205,label:"Branch A–M",sublabel:"500 keys",tone:"blue",badge:"hop 2",badgeTone:"blue"},{id:"b2",type:"hex",x:555,y:205,label:"Branch N–Z",sublabel:"skipped",tone:"slate",dim:!0},{id:"leaf",type:"db",x:205,y:335,label:"Leaf Page",sublabel:"alice@ms.com → row",tone:"purple",badge:"1.4 ms hit!",badgeTone:"green"},{id:"next",type:"db",x:460,y:335,label:"Next Leaf",sublabel:"Range Scan →",tone:"purple",dim:!0}],edges:[{from:"root",to:"b1",label:"A–M",packetColor:"green",speed:1.5},{from:"b1",to:"leaf",label:"exact match",packetColor:"green",speed:1.5},{from:"leaf",to:"next",label:"linked list",packetColor:"purple",dashed:!0,speed:2.4}],legend:[{label:"O(log N) tree traversal",tone:"green"},{label:"sequential range link",tone:"purple"}]}},{shortLabel:"Specialized",stage:"TECHNIQUE",title:"Covering, Inverted (Search) & Spatial (Geo) Indexes",body:["1. **Covering Index (`INCLUDE`)**: Stores extra selected columns right in the leaf page so the DB performs an **Index-Only Scan** without ever fetching the main heap row!","2. **Inverted Index** (Elasticsearch/Lucene): Maps `token → [doc_id_1, doc_id_9, ...]` for instant full-text search.",'3. **Spatial Index** (**Geohash**, **QuadTree**, **Uber H3 hexagons**): Maps 2D `(lat, lng)` coordinates into 1D prefix strings or hexagonal cells for sub-10ms "find nearby drivers" queries.'],callout:{type:"INTERVIEW SIGNAL",text:"In PostgreSQL/SQL Server, ordering columns in a composite index as **Equality columns first, Range column last** (`WHERE tenant_id = ? AND created_at > ?` → index `(tenant_id, created_at)`) is a classic optimization question."},scene:{hud:[{label:"COVERING",value:"Index-Only Scan",status:"good"},{label:"FULL-TEXT",value:"Inverted Index",status:"good"},{label:"GEO / UBER",value:"H3 / QuadTree",status:"good"},{label:"AI / RAG",value:"HNSW Vector",status:"info"}],nodes:[{id:"cov",type:"db",x:140,y:215,label:"Covering B+",sublabel:"No Heap Fetch",tone:"green"},{id:"inv",type:"db",x:380,y:120,label:"Inverted",sublabel:"word → docIDs",tone:"amber"},{id:"geo",type:"hex",x:380,y:310,label:"Spatial H3",sublabel:"(lat,lng) → Hex",tone:"blue"},{id:"vec",type:"cache",x:630,y:215,label:"HNSW Graph",sublabel:"Cosine Top-K",tone:"purple"}],edges:[{from:"cov",to:"inv",label:"SQL vs Text",packetColor:"amber",dashed:!0,speed:2.3},{from:"cov",to:"geo",label:"2D Radius",packetColor:"blue",dashed:!0,speed:2.3},{from:"inv",to:"vec",label:"Hybrid RAG",packetColor:"purple",speed:2}],legend:[{label:"index specialization",tone:"purple"}]}}]},{id:"storage-engines",title:"Storage Engines",subtitle:"Inside the disk layer: B-Tree in-place updates (Postgres) vs LSM-Tree MemTable + SSTables (Cassandra/RocksDB).",duration:"10 min",level:"Intermediate",companies:["Google","Meta","Amazon","Microsoft"],tags:["lsm-tree","b-tree","sstable","memtable","wal","compaction","bloom filter","rocksdb"],objectives:["Trace how B-Tree engines use WAL + fixed-size pages (read-optimized)","Trace how LSM-Trees convert random writes into sequential append-only I/O","Understand Compaction, Write/Read Amplification, and Bloom Filters"],steps:[{shortLabel:"B-Tree disk",stage:"SETUP",title:"B-Trees update fixed 8–16 KB pages in place",body:["In PostgreSQL and MySQL InnoDB, data lives in fixed-size **pages** on disk. Before mutating a page in RAM, the engine appends the change to a sequential **Write-Ahead Log (WAL)** for crash recovery, then flushes dirty pages asynchronously.","Reads are ultra-predictable (1 key lives in exactly 1 place!), but heavy random writes cause **random disk seeks** and **page splits** (write amplification)."],callout:{type:"KEY IDEA",text:"B-Trees optimize for predictable **READ latency** and strong page-level concurrency locks; LSM-Trees optimize for blistering **WRITE throughput**."},scene:{hud:[{label:"ENGINE",value:"B+ Tree (InnoDB)",status:"info"},{label:"READ SPEED",value:"Fast · 1 Lookup",status:"good"},{label:"RANDOM WRITES",value:"Page Splits",status:"warn"},{label:"CRASH SAFETY",value:"WAL Append",status:"good"}],nodes:[{id:"w",type:"hex",x:130,y:215,label:"Write Tx",sublabel:"UPDATE row",tone:"blue"},{id:"wal",type:"queue",x:365,y:115,label:"WAL Log",sublabel:"Sequential fsync",tone:"green",badge:"durable",badgeTone:"green"},{id:"buf",type:"cache",x:365,y:310,label:"Buffer Pool",sublabel:"Dirty 8KB Page",tone:"amber"},{id:"disk",type:"db",x:630,y:215,label:"B-Tree Disk",sublabel:"In-Place Overwrite",tone:"purple"}],edges:[{from:"w",to:"wal",label:"1. append WAL",packetColor:"green",speed:1.6},{from:"w",to:"buf",label:"2. mutate page",packetColor:"amber",speed:1.8},{from:"buf",to:"disk",label:"3. checkpoint flush",packetColor:"purple",dashed:!0,speed:2.6}],legend:[{label:"crash-safe WAL",tone:"green"},{label:"in-place page flush",tone:"purple"}]}},{shortLabel:"LSM-Tree",stage:"SOLUTION",title:"LSM-Trees turn random writes into sequential appends",body:["**Log-Structured Merge-Trees** (RocksDB, Cassandra, ScyllaDB, Bigtable) never overwrite data in place! Every write appends to a **WAL** and inserts into an in-memory sorted tree (**MemTable** — Red-Black Tree / SkipList).","When the MemTable hits ~64 MB, it flushes sequentially to disk as an immutable sorted file called an **SSTable (Sorted String Table)**. Background **Compaction** merges SSTables and discards tombstones/old versions."],callout:{type:"INTERVIEW SIGNAL",text:'How do LSM-Trees avoid checking 20 SSTables when reading a non-existent key? Each SSTable attaches an in-memory **Bloom Filter** — if the Bloom Filter says "definitely not here," the engine skips that SSTable with zero disk I/O!'},changes:["+Writes hit RAM MemTable + Sequential WAL (10× faster writes!)","+Immutable SSTables merged asynchronously via Compaction","+Bloom Filters skip disk reads for missing keys"],scene:{hud:[{label:"WRITE PATH",value:"RAM + Seq WAL",status:"good"},{label:"WRITE TPS",value:"10× Higher",status:"good"},{label:"READ ASSIST",value:"Bloom Filters",status:"info"},{label:"BACKGROUND",value:"Compaction CPU",status:"warn"}],nodes:[{id:"in",type:"hex",x:105,y:215,label:"1M Writes/s",sublabel:"Random Keys",tone:"blue"},{id:"mem",type:"cache",x:300,y:155,label:"MemTable",sublabel:"Sorted RAM + WAL",tone:"green",badge:"O(log M) RAM",badgeTone:"green"},{id:"l0",type:"db",x:500,y:115,label:"SSTable L0",sublabel:"Immutable + Bloom",tone:"amber"},{id:"l1",type:"db",x:500,y:295,label:"SSTable L1..Ln",sublabel:"Compacted Runs",tone:"purple",badge:"merged",badgeTone:"purple"},{id:"read",type:"users",x:680,y:215,label:"Readers",sublabel:"Mem → L0 → L1",tone:"slate"}],edges:[{from:"in",to:"mem",label:"append only",packetColor:"green",speed:1.4,packetCount:3},{from:"mem",to:"l0",label:"seq flush",packetColor:"amber",speed:2},{from:"l0",to:"l1",label:"compaction",packetColor:"purple",dashed:!0,speed:2.7},{from:"read",to:"l0",label:"Bloom check",packetColor:"blue",dashed:!0,speed:2.1}],legend:[{label:"sequential RAM/WAL write",tone:"green"},{label:"background compaction",tone:"purple"}]}}],deepDive:{tradeoffs:[{option:"B+ Tree (Postgres, MySQL)",bestWhen:"Read-heavy OLTP, point lookups, strong transactional locks",pros:"Predictable p99 reads, key exists in 1 place",cons:"Higher write amplification on random inserts, page fragmentation"},{option:"LSM-Tree (RocksDB, Cassandra, Scylla)",bestWhen:"Write-heavy workloads (chat, metrics, time-series, IoT)",pros:"Blistering sequential writes, superior compression ratio",cons:"Compaction I/O spikes can hurt p99 reads; reads may inspect multiple levels"}]}},{id:"replication",title:"Replication",subtitle:"Single-Leader sync vs async, Multi-Leader conflicts, and Leaderless Dynamo quorums (W + R > N).",duration:"11 min",level:"Intermediate",companies:["Amazon","Meta","Microsoft","Google"],tags:["leader-follower","replication lag","multi-leader","leaderless","quorum","read-your-writes","merkle tree"],objectives:["Compare Sync vs Semi-Sync vs Async Leader-Follower replication","Handle Replication Lag anomalies (Read-Your-Writes, Monotonic Reads)","Understand Leaderless Dynamo quorums (W + R > N), Read Repair, and Hinted Handoff"],steps:[{shortLabel:"Leader-Follower",stage:"SOLUTION",title:"Single-Leader scales reads — but watch Async Replication Lag",body:["All **WRITES** go to the **Leader (Primary)**; it streams WAL/binlog changes to **Read Replicas** which handle 90% of **READS**.","**Synchronous** replication guarantees zero data loss on leader crash, but slows writes if any replica stalls. **Asynchronous** replication is fast, but creates **Replication Lag**: Alice updates her avatar on the Leader, reloads from a lagging Replica 50 ms later, and sees her old avatar!"],callout:{type:"WATCH OUT",text:"Fix Read-Your-Writes anomalies by routing a user’s reads to the Leader for 5–10 seconds after their own edit (or tracking the user’s last-written LSN/timestamp and waiting on the replica)."},scene:{hud:[{label:"WRITES",value:"Leader Only",status:"info"},{label:"READ SCALE",value:"N× Replicas",status:"good"},{label:"ASYNC LAG",value:"50 – 500 ms",status:"warn"},{label:"SEMI-SYNC",value:"1 Sync + K Async",status:"good"}],nodes:[{id:"app",type:"hex",x:120,y:215,label:"App Tier",sublabel:"RW Split",tone:"blue"},{id:"lead",type:"db",x:380,y:120,label:"Leader DB",sublabel:"Writes + RYW",tone:"green",badge:"primary",badgeTone:"green",load:42},{id:"r1",type:"db",x:630,y:120,label:"Replica 1",sublabel:"Semi-Sync (0ms)",tone:"purple",badge:"sync standby",badgeTone:"blue"},{id:"r2",type:"db",x:630,y:310,label:"Replica 2",sublabel:"Async (120ms lag)",tone:"amber",badge:"lag: 120ms",badgeTone:"amber"}],edges:[{from:"app",to:"lead",label:"WRITES",packetColor:"green",speed:1.6},{from:"app",to:"r2",label:"READS (90%)",packetColor:"blue",bidirectional:!0,speed:1.8},{from:"lead",to:"r1",label:"sync WAL",packetColor:"purple",speed:1.7},{from:"lead",to:"r2",label:"async WAL",packetColor:"amber",dashed:!0,speed:2.8}],legend:[{label:"primary write",tone:"green"},{label:"read replica query",tone:"blue"},{label:"async lag stream",tone:"amber"}]}},{shortLabel:"Leaderless W+R>N",stage:"TECHNIQUE",title:"Leaderless Quorums (Dynamo / Cassandra): W + R > N",body:["In **Leaderless** databases (Cassandra, DynamoDB-style), any coordinator writes concurrently to `N = 3` replicas and succeeds once `W = 2` acknowledge. Readers query `R = 2` replicas and pick the freshest version.","Because **`W + R > N`** (`2 + 2 > 3`), the read quorum and write quorum are mathematically guaranteed to overlap by at least 1 up-to-date node! Stale nodes catch up via **Read Repair** and background **Merkle Tree Anti-Entropy**."],callout:{type:"INTERVIEW SIGNAL",text:"Quorum (`W+R>N`) gives strong-ish overlap, NOT strict linearizability (concurrent writes + sloppy quorums/hinted handoff can still cause edge cases — test this live in our **Design Lab → Quorum & Raft Simulator**!)."},scene:{hud:[{label:"REPLICAS (N)",value:"N = 3",status:"info"},{label:"WRITE QUORUM",value:"W = 2",status:"good"},{label:"READ QUORUM",value:"R = 2",status:"good"},{label:"OVERLAP",value:"W + R > N ✓",status:"good"}],nodes:[{id:"coord",type:"hex",x:145,y:215,label:"Coordinator",sublabel:"W=2 · R=2",tone:"green",badge:"quorum met",badgeTone:"green"},{id:"n1",type:"db",x:470,y:85,label:"Replica A",sublabel:"v5 ✓",tone:"green",badge:"W + R overlap",badgeTone:"green"},{id:"n2",type:"db",x:470,y:215,label:"Replica B",sublabel:"v5 ✓",tone:"blue"},{id:"n3",type:"db",x:470,y:345,label:"Replica C",sublabel:"v4 (Down/Stale)",tone:"coral",badge:"read repair",badgeTone:"amber",dim:!0}],edges:[{from:"coord",to:"n1",label:"ACK v5",packetColor:"green",bidirectional:!0,speed:1.6},{from:"coord",to:"n2",label:"ACK v5",packetColor:"green",bidirectional:!0,speed:1.6},{from:"coord",to:"n3",label:"timeout / async repair",packetColor:"amber",dashed:!0,speed:3.1}],legend:[{label:"quorum ACK",tone:"green"},{label:"hinted handoff / repair",tone:"amber"}]}}]},{id:"sharding",title:"Sharding",subtitle:"Horizontal partitioning across databases: shard key selection, hot partitions, and cross-shard joins.",duration:"10 min",level:"Intermediate",companies:["Meta","Instagram","Microsoft","Amazon"],tags:["partitioning","shard key","hot partition","celebrity problem","resharding","vitess","citus"],objectives:["Choose a high-cardinality shard key aligned with dominant queries","Compare Hash, Range, and Directory-based sharding","Solve the Celebrity Hot-Shard problem and Cross-Shard Joins"],steps:[{shortLabel:"Shard keys",stage:"TECHNIQUE",title:"Your shard key makes or breaks the whole database",body:["**Sharding** splits one giant table horizontally across `K` independent database clusters. Every shard holds `1/K` of the rows and writes.","Picking the wrong shard key ruins performance: sharding Tweets by `timestamp` sends 100% of today’s writes to the newest shard (**write hot-spot**)! Sharding by `user_id` spreads writes evenly and keeps a user’s timeline on 1 shard."],callout:{type:"WATCH OUT",text:"Once a table is sharded by `user_id`, querying by `email` becomes a slow **Scatter-Gather** fan-out across ALL shards unless you maintain a secondary lookup table (`email → user_id`)."},scene:{hud:[{label:"SHARD KEY",value:"hash(user_id)",status:"good"},{label:"WRITE SCALE",value:"4× Linear",status:"good"},{label:"CROSS-SHARD JOIN",value:"Avoid!",status:"warn"},{label:"ROUTER",value:"Vitess / Citus",status:"info"}],nodes:[{id:"app",type:"hex",x:110,y:215,label:"App Tier",sublabel:"user_id = 42",tone:"blue"},{id:"rt",type:"hex",x:300,y:215,label:"Shard Router",sublabel:"Hash / Lookup",tone:"green",badge:"O(1) route",badgeTone:"green"},{id:"s0",type:"db",x:585,y:95,label:"Shard 0",sublabel:"Users 0..24%",tone:"purple",load:34},{id:"s1",type:"db",x:585,y:215,label:"Shard 1",sublabel:"Users 25..49%",tone:"purple",load:36},{id:"s2",type:"db",x:585,y:335,label:"Shard 2",sublabel:"Users 50..99%",tone:"purple",load:35}],edges:[{from:"app",to:"rt",label:"key: u42",packetColor:"blue",speed:1.7},{from:"rt",to:"s0",label:"route",packetColor:"green",speed:1.7},{from:"rt",to:"s1",label:"route",packetColor:"green",speed:1.9},{from:"rt",to:"s2",label:"route",packetColor:"green",speed:2.1}],legend:[{label:"targeted single-shard query",tone:"green"}]}},{shortLabel:"Hot shard fix",stage:"SOLUTION",title:"Key Salting defeats the Celebrity Hot Partition",body:["Even with `hash(user_id)`, if a celebrity with 100M followers posts during the World Cup, **1 single shard** gets blasted with 200,000 likes/sec while 99 other shards sit idle!","**Fix — Key Salting**: Append a random suffix `0..9` to hot keys (`post_99#0` .. `post_99#9`) so writes scatter across 10 shards. Readers merge the 10 sub-keys (or read from a cached aggregate)."],callout:{type:"INTERVIEW SIGNAL",text:"Also avoid `hash(key) % N` directly on physical servers — map keys to **4,096 virtual logical shards** (or use Consistent Hashing) so adding new database hardware only moves a tiny slice of logical shards without rehashing everything."},scene:{hud:[{label:"HOT KEY",value:"celebrity_post",status:"warn"},{label:"SALT SUFFIX",value:"#0 .. #9",status:"good"},{label:"SHARD SKEW",value:"100% → 10%",status:"good"},{label:"VIRTUAL SHARDS",value:"4,096 Buckets",status:"info"}],nodes:[{id:"fan",type:"users",x:115,y:215,label:"200k Likes/s",sublabel:"Viral Post",tone:"slate"},{id:"salt",type:"hex",x:325,y:215,label:"Salter",sublabel:"key + rand(0..9)",tone:"amber",badge:"spreads writes",badgeTone:"green"},{id:"d1",type:"db",x:590,y:115,label:"Shard A",sublabel:"post#0..3",tone:"green",load:35},{id:"d2",type:"db",x:590,y:215,label:"Shard B",sublabel:"post#4..6",tone:"green",load:34},{id:"d3",type:"db",x:590,y:315,label:"Shard C",sublabel:"post#7..9",tone:"green",load:36}],edges:[{from:"fan",to:"salt",label:"hot key",packetColor:"coral",speed:1.4,packetCount:3},{from:"salt",to:"d1",label:"33%",packetColor:"green",speed:1.8},{from:"salt",to:"d2",label:"33%",packetColor:"green",speed:1.8},{from:"salt",to:"d3",label:"33%",packetColor:"green",speed:1.8}],legend:[{label:"hot spike",tone:"coral"},{label:"salted balanced writes",tone:"green"}]}}]},{id:"consistent-hashing",title:"Consistent Hashing",subtitle:"Hash rings and Virtual Nodes: scale caches and shards while remapping only 1/N of keys.",duration:"9 min",level:"Intermediate",companies:["Amazon","Discord","Akamai","Microsoft"],tags:["hash ring","virtual nodes","vnodes","dynamo","cassandra","cache sharding"],objectives:["See why `hash(k) % N` triggers a catastrophic cache miss storm on resize","Map servers and keys onto a 0..2^32-1 Consistent Hash Ring","Use Virtual Nodes (100–200 per server) to eliminate load skew"],steps:[{shortLabel:"Modulo disaster",stage:"PROBLEM",title:"Adding 1 server to `hash(k) % N` invalidates ~80% of keys!",body:["Suppose you shard Redis across `N = 4` nodes using `server = hash(key) % 4`. Now traffic grows and you add a 5th node (`N = 5`).","Suddenly almost EVERY key hashes to a different server! **80% of your cache misses simultaneously**, slamming your backend SQL database into an outage."],callout:{type:"WATCH OUT",text:"With naive modulo hashing, adding or losing 1 server out of N remaps approximately `(N-1)/N` of all keys — near 100% churn in large clusters!"},scene:{hud:[{label:"FORMULA",value:"hash(k) % N",status:"bad"},{label:"CLUSTER CHANGE",value:"4 → 5 Nodes",status:"warn"},{label:"KEYS REMAPPED",value:"~80% Misses!",status:"bad"},{label:"DB IMPACT",value:"Meltdown",status:"bad"}],nodes:[{id:"mod",type:"hex",x:165,y:215,label:"hash(k) % 5",sublabel:"Was % 4!",tone:"coral",badge:"80% churn",badgeTone:"rose"},{id:"c1",type:"cache",x:470,y:120,label:"Redis 1..4",sublabel:"Wrong keys!",tone:"amber",load:20},{id:"db",type:"db",x:645,y:270,label:"Origin DB",sublabel:"Cache Storm!",tone:"coral",badge:"99% CPU",badgeTone:"rose",load:99}],edges:[{from:"mod",to:"c1",label:"80% cache miss",packetColor:"amber",dashed:!0,speed:1.7},{from:"c1",to:"db",label:"stampede to DB!",packetColor:"coral",speed:1.3,packetCount:3}],legend:[{label:"massive remapping storm",tone:"coral"}]}},{shortLabel:"Ring + vNodes",stage:"SOLUTION",title:"Consistent Hash Ring + Virtual Nodes moves only 1/N keys",body:["Place both **servers** and **keys** onto a circular ring `0 .. 2^32 − 1`. Each key walks **clockwise** to the first server it encounters.","When Server E joins, it ONLY steals the arc between its predecessor and itself — moving just **`1/N` (~20%) of keys**! Giving each physical machine **150 Virtual Nodes (vNodes)** scattered around the ring ensures even load balance (standard deviation < 5%) AND lets beefier hardware take more vNodes."],callout:{type:"GOOD TO KNOW",text:"Play with a live interactive ring right now in **Design Lab → Consistent Hashing Ring Lab** (add/remove nodes, adjust vNodes, watch exact key movement %!)."},changes:["+Servers & keys placed on circular 2^32 hash ring","+150 Virtual Nodes per machine eliminate uneven arc skew","~Adding 5th server remaps only ~20% keys instead of 80%"],scene:{hud:[{label:"ALGORITHM",value:"Consistent Ring",status:"good"},{label:"VNODES / NODE",value:"150 vNodes",status:"good"},{label:"KEYS MOVED",value:"Only 1/N (20%)",status:"good"},{label:"SKEW STDDEV",value:"< 5%",status:"good"}],nodes:[{id:"nA",type:"hex",x:380,y:78,label:"Node A",sublabel:"vNodes: 150",tone:"blue"},{id:"nB",type:"hex",x:585,y:215,label:"Node B",sublabel:"vNodes: 150",tone:"green",badge:"new · takes 20%",badgeTone:"green"},{id:"nC",type:"hex",x:380,y:350,label:"Node C",sublabel:"vNodes: 150",tone:"purple"},{id:"nD",type:"hex",x:175,y:215,label:"Node D",sublabel:"vNodes: 150",tone:"amber"}],edges:[{from:"nA",to:"nB",label:"clockwise arc",packetColor:"green",curve:-22,speed:2},{from:"nB",to:"nC",label:"clockwise arc",packetColor:"purple",curve:22,speed:2},{from:"nC",to:"nD",label:"clockwise arc",packetColor:"amber",curve:22,speed:2},{from:"nD",to:"nA",label:"clockwise arc",packetColor:"blue",curve:-22,speed:2}],legend:[{label:"minimal 1/N clockwise handoff",tone:"green"}]}}]},{id:"unique-ids",title:"Unique IDs at Scale",subtitle:"Twitter Snowflake 64-bit IDs, UUIDv7, ULID, and why random UUIDv4 hurts B+ Tree index performance.",duration:"8 min",level:"Intermediate",companies:["Twitter/X","Discord","Instagram","Microsoft"],tags:["snowflake","uuidv4","uuidv7","ulid","clock skew","64-bit id"],objectives:["Explain why DB auto-increment fails across shards and UUIDv4 fragments B+ Trees","Dissect the 64-bit Twitter Snowflake bit layout (timestamp + machine + sequence)","Handle NTP clock rollback and compare Snowflake vs UUIDv7"],steps:[{shortLabel:"UUIDv4 trap",stage:"PROBLEM",title:"Why random UUIDv4 destroys B+ Tree write performance",body:["A single DB `AUTO_INCREMENT` is a bottleneck across shards. Switching to random 128-bit **UUIDv4** avoids coordination, BUT random IDs are **unsorted**: every insert lands on a random B+ Tree leaf page, causing constant disk cache misses and 50%-empty page splits!"],callout:{type:"WATCH OUT",text:"Benchmarks consistently show random UUIDv4 primary keys cut PostgreSQL/InnoDB write throughput by 3–5× compared to time-sortable 64-bit IDs or UUIDv7."},scene:{hud:[{label:"UUIDv4 SIZE",value:"128-bit Random",status:"warn"},{label:"TIME SORTABLE",value:"No",status:"bad"},{label:"B+ TREE SPLITS",value:"Heavy Random I/O",status:"bad"},{label:"GOAL",value:"64-bit K-Sorted",status:"good"}],nodes:[{id:"gen",type:"hex",x:150,y:215,label:"Random UUIDv4",sublabel:"a9f1... / 02b8...",tone:"coral"},{id:"p1",type:"db",x:525,y:110,label:"Leaf Page 14",sublabel:"Random Jump!",tone:"coral",load:88},{id:"p2",type:"db",x:525,y:215,label:"Leaf Page 892",sublabel:"Page Split!",tone:"coral",load:91},{id:"p3",type:"db",x:525,y:320,label:"Leaf Page 401",sublabel:"Cache Miss!",tone:"coral",load:85}],edges:[{from:"gen",to:"p1",label:"scatter",packetColor:"coral",speed:1.7},{from:"gen",to:"p2",label:"scatter",packetColor:"coral",speed:1.5},{from:"gen",to:"p3",label:"scatter",packetColor:"coral",speed:1.9}],legend:[{label:"random B+ Tree page thrashing",tone:"coral"}]}},{shortLabel:"Snowflake 64b",stage:"SOLUTION",title:"Snowflake IDs: 4,096 IDs/ms per machine, zero coordination",body:["**Twitter Snowflake** packs a globally unique, roughly **time-sortable 64-bit integer** with zero network round trips: **1 sign bit (`0`) + 41 bits timestamp (69 years in ms) + 10 bits datacenter/machine ID (1,024 nodes) + 12 bits per-ms sequence (4,096 IDs/ms/node)**.","Because timestamps occupy the most significant bits, new rows always append cleanly to the **rightmost B+ Tree leaf**! Modern standard alternative: **UUIDv7** (48-bit Unix ms timestamp + 74-bit randomness in standard 128-bit UUID columns)."],callout:{type:"INTERVIEW SIGNAL",text:"What if NTP moves a machine’s clock backwards by 15 ms? Wait out small drift (`< 5 ms`), refuse generation / alert on large rollback, or use monotonic sequence bits + monotonic clock (`CLOCK_MONOTONIC`)."},scene:{hud:[{label:"SIZE",value:"64-bit BIGINT",status:"good"},{label:"THROUGHPUT",value:"4M IDs/sec/node",status:"good"},{label:"SORT ORDER",value:"Time-Ordered ✓",status:"good"},{label:"LIFESPAN",value:"69 Years (41b)",status:"info"}],nodes:[{id:"w1",type:"hex",x:145,y:140,label:"Worker #12",sublabel:"Local Seq 0..4095",tone:"green",badge:"zero lock",badgeTone:"green"},{id:"w2",type:"hex",x:145,y:295,label:"Worker #13",sublabel:"Local Seq 0..4095",tone:"blue"},{id:"db",type:"db",x:375,y:215,label:"Rightmost Leaf",sublabel:"Sequential Append!",tone:"purple",load:24}],edges:[{from:"w1",to:"db",label:"append",packetColor:"green",speed:1.6},{from:"w2",to:"db",label:"append",packetColor:"blue",speed:1.6}],overlayCard:{x:460,y:95,title:"64-BIT SNOWFLAKE LAYOUT",rows:[{label:"Sign (1 bit)",value:"0 (positive)",pct:5,tone:"slate"},{label:"Timestamp (41 bits)",value:"69 yrs (ms)",pct:64,tone:"green"},{label:"DC + Node (10 bits)",value:"1,024 nodes",pct:18,tone:"blue"},{label:"Sequence (12 bits)",value:"4,096 / ms",pct:20,tone:"purple"}],footer:"4.19 Billion IDs/sec across 1,024 nodes!"},legend:[{label:"sequential B+ Tree append",tone:"green"}]}}]},{id:"cap",title:"CAP & Consistency",subtitle:"CAP Theorem, PACELC (Latency vs Consistency), Linearizability, Causal Consistency, Vector Clocks & CRDTs.",duration:"10 min",level:"Intermediate",companies:["Google","Amazon","Microsoft","Meta"],tags:["cap theorem","pacelc","linearizability","eventual consistency","causal","crdt","vector clocks"],objectives:["Explain CAP cleanly: P is unavoidable, so during a partition choose CP vs AP","Apply PACELC to reason about Latency vs Consistency during normal operation","Compare Linearizable, Causal, and Eventual consistency + CRDTs"],steps:[{shortLabel:"CAP & PACELC",stage:"INSIGHT",title:"Partitions ALWAYS happen — PACELC completes the picture",body:["**CAP Theorem**: In a distributed system, network partitions (**P**) are inevitable (cut fiber, switch failure, GC pause). During a partition, you must choose either **CP** (reject writes/reads on the minority side to guarantee fresh consistent data — e.g., etcd, Spanner, banking ledgers) or **AP** (keep accepting reads/writes on both sides even if temporarily stale — e.g., DNS, DynamoDB, shopping carts).","**PACELC** goes further: *If Partition (P), choose A or C; **Else (E, normal operation)**, choose **Latency (L) or Consistency (C)**!* Replicating synchronously across regions adds latency even with zero outages."],callout:{type:"INTERVIEW SIGNAL",text:'Quoting PACELC shows Staff-level maturity: "Even without network partitions, strong cross-region consistency costs 80 ms of extra write latency (PC/EC vs PA/EL)."'},scene:{hud:[{label:"ON PARTITION",value:"CP vs AP",status:"warn"},{label:"NORMAL OPS",value:"Latency vs Cons.",status:"info"},{label:"CP EXAMPLES",value:"Spanner · etcd",status:"info"},{label:"AP EXAMPLES",value:"Cassandra · DNS",status:"good"}],nodes:[{id:"us",type:"db",x:185,y:155,label:"US-East Cluster",sublabel:"Majority (2/3)",tone:"green",badge:"CP: active",badgeTone:"green"},{id:"eu",type:"db",x:575,y:155,label:"EU-West Node",sublabel:"Isolated (1/3)",tone:"coral",badge:"CP: 503 · AP: stale OK",badgeTone:"rose"},{id:"cut",type:"hex",x:380,y:315,label:"Network Split",sublabel:"Fiber Cut (P)",tone:"amber"}],edges:[{from:"us",to:"eu",label:"✕ PARTITIONED",packetColor:"coral",dashed:!0,speed:3.5},{from:"cut",to:"us",label:"CP serves",packetColor:"green",speed:2},{from:"cut",to:"eu",label:"AP serves stale",packetColor:"amber",dashed:!0,speed:2.4}],legend:[{label:"consistent majority",tone:"green"},{label:"partitioned link",tone:"coral"}]}},{shortLabel:"Spectrum & CRDTs",stage:"TECHNIQUE",title:"Linearizability → Causal Consistency → CRDTs",body:["**Linearizability** (strongest) behaves as if only 1 copy of data exists globally. **Causal Consistency** guarantees cause precedes effect (you never see a reply before the comment it replied to!).","For collaborative apps (Google Docs, Figma, multi-region counters), **CRDTs (Conflict-Free Replicated Data Types)** let replicas accept concurrent offline edits and mathematically **merge to the exact same state** without central locks."],callout:{type:"KEY IDEA",text:"Use Strong Consistency (Linearizability) for money, inventory, and seat locks; use Causal/Eventual + CRDTs for likes, presence, and collaborative editing."},scene:{hud:[{label:"STRONGEST",value:"Linearizable",status:"info"},{label:"SWEET SPOT",value:"Causal",status:"good"},{label:"FASTEST",value:"Eventual",status:"good"},{label:"CONFLICT FREE",value:"CRDT Merge",status:"good"}],nodes:[{id:"lin",type:"hex",x:135,y:215,label:"Linearizable",sublabel:"Money · Locks",tone:"purple"},{id:"cau",type:"hex",x:380,y:215,label:"Causal",sublabel:"Feeds · Comments",tone:"blue"},{id:"crdt",type:"hex",x:625,y:215,label:"Eventual + CRDT",sublabel:"Docs · Counters",tone:"green",badge:"converges!",badgeTone:"green"}],edges:[{from:"lin",to:"cau",label:"lower latency →",packetColor:"blue",speed:2},{from:"cau",to:"crdt",label:"offline-ready →",packetColor:"green",speed:2}],legend:[{label:"consistency vs latency trade-off",tone:"green"}]}}]},{id:"consensus",title:"Consensus & Leaders",subtitle:"Preventing Split-Brain with Raft Leader Election, Log Replication, Quorums, and Fencing Tokens.",duration:"10 min",level:"Advanced",companies:["Google","Microsoft","Amazon","Cloudflare"],tags:["raft","paxos","etcd","zookeeper","split-brain","fencing token","distributed lock"],objectives:["Explain why Split-Brain corrupts data and why odd clusters (3 or 5) are required","Step through Raft Leader Election (Terms, Randomized Timeouts, Majority Votes)","Use monotonic Fencing Tokens to make distributed locks safe across GC pauses"],steps:[{shortLabel:"Raft Election",stage:"SOLUTION",title:"Raft elects 1 unambiguous Leader per Term via majority vote",body:["In a **5-node Raft cluster** (used by Kubernetes **etcd**, CockroachDB, TiKV), one **Leader** sends periodic heartbeats. If heartbeats stop, a follower’s **randomized election timeout** (150–300 ms) expires first, increments `Term`, becomes **Candidate**, and requests votes.","Because a leader needs **`⌊N/2⌋ + 1` (3 of 5) votes**, two split-brain partitions can NEVER simultaneously elect two leaders in the same Term!"],callout:{type:"KEY IDEA",text:"Always deploy **odd numbers of consensus nodes**: 3 nodes tolerate 1 failure; 5 nodes tolerate 2 failures. Deploying 4 nodes gives the SAME fault tolerance (1 failure) as 3 nodes with extra latency!"},scene:{hud:[{label:"CLUSTER SIZE",value:"5 Nodes (Odd)",status:"good"},{label:"QUORUM",value:"3 / 5 Votes",status:"good"},{label:"FAULT TOLERANCE",value:"2 Failures",status:"good"},{label:"TERM",value:"Term #7",status:"info"}],nodes:[{id:"ldr",type:"hex",x:380,y:120,label:"Node 1",sublabel:"Term #7 Leader",tone:"green",badge:"elected (4/5)",badgeTone:"green"},{id:"f2",type:"hex",x:165,y:295,label:"Node 2",sublabel:"Follower",tone:"blue"},{id:"f3",type:"hex",x:380,y:325,label:"Node 3",sublabel:"Follower",tone:"blue"},{id:"f4",type:"hex",x:595,y:295,label:"Node 4",sublabel:"Follower",tone:"blue"},{id:"f5",type:"hex",x:645,y:125,label:"Node 5",sublabel:"Offline",tone:"coral",badge:"down",badgeTone:"rose",dim:!0}],edges:[{from:"ldr",to:"f2",label:"AppendEntries",packetColor:"green",bidirectional:!0,speed:1.7},{from:"ldr",to:"f3",label:"AppendEntries",packetColor:"green",bidirectional:!0,speed:1.7},{from:"ldr",to:"f4",label:"AppendEntries",packetColor:"green",bidirectional:!0,speed:1.7},{from:"ldr",to:"f5",label:"unreachable",packetColor:"coral",dashed:!0,dim:!0,speed:3}],legend:[{label:"Raft heartbeat / log commit",tone:"green"},{label:"tolerated failure",tone:"coral"}]}},{shortLabel:"Fencing Tokens",stage:"TECHNIQUE",title:"Why Redis locks alone fail — and how Fencing Tokens save you",body:["Suppose Worker A grabs a 10-second lock, then freezes for 15 seconds due to a JVM **GC pause**. The lock expires and Worker B acquires it. Then Worker A wakes up and blindly overwrites the storage file!","**Fix — Monotonic Fencing Tokens** (Martin Kleppmann’s rule): etcd/ZooKeeper issues a strictly increasing number (`token = 33` for A, `token = 34` for B). The storage server rejects any write carrying a token `< 34`!"],callout:{type:"INTERVIEW SIGNAL",text:"Explaining GC-pause lock expiry + Monotonic Fencing Tokens when asked about distributed locking is pure Staff/Principal (L63–L65) gold."},scene:{hud:[{label:"WORKER A",value:"Token #33 (Stale)",status:"bad"},{label:"WORKER B",value:"Token #34 (Valid)",status:"good"},{label:"STORAGE MAX",value:"34",status:"info"},{label:"CORRUPTION",value:"Blocked ✓",status:"good"}],nodes:[{id:"etcd",type:"hex",x:140,y:215,label:"etcd Lock",sublabel:"Monotonic Rev",tone:"purple"},{id:"wa",type:"hex",x:385,y:120,label:"Worker A",sublabel:"Woke from GC!",tone:"coral",badge:"token 33",badgeTone:"rose"},{id:"wb",type:"hex",x:385,y:310,label:"Worker B",sublabel:"Current Owner",tone:"green",badge:"token 34",badgeTone:"green"},{id:"st",type:"db",x:635,y:215,label:"Storage",sublabel:"Rejects < 34",tone:"blue",badge:"fenced!",badgeTone:"green"}],edges:[{from:"etcd",to:"wa",label:"#33 (expired)",packetColor:"coral",dashed:!0,speed:2.8},{from:"etcd",to:"wb",label:"#34 (active)",packetColor:"green",speed:1.7},{from:"wb",to:"st",label:"write(#34) ✓",packetColor:"green",speed:1.7},{from:"wa",to:"st",label:"write(#33) ✕ REJECT",packetColor:"coral",dashed:!0,speed:2.3}],legend:[{label:"valid fenced write",tone:"green"},{label:"stale zombie rejected",tone:"coral"}]}}]},{id:"transactions",title:"Transactions & Isolation",subtitle:"ACID, MVCC snapshots, Isolation Levels, Phantom Reads, Write Skew, and Optimistic vs Pessimistic locking.",duration:"10 min",level:"Intermediate",companies:["Microsoft","Amazon","Stripe","Google"],tags:["acid","mvcc","isolation levels","write skew","phantom read","optimistic locking","pessimistic locking"],objectives:["Explain how MVCC lets readers never block writers and writers never block readers","Compare Read Committed, Repeatable Read (Snapshot), and Serializable","Prevent double-booking Write Skew with `SELECT ... FOR UPDATE` or `@Version` optimistic locking"],steps:[{shortLabel:"MVCC & Levels",stage:"TECHNIQUE",title:"MVCC snapshots + the 4 SQL Isolation Levels",body:["Modern databases (PostgreSQL, MySQL InnoDB) use **MVCC (Multi-Version Concurrency Control)**: every update writes a new versioned row tuple (`xmin`, `xmax`) rather than locking readers out!","**Read Committed** stops dirty reads. **Repeatable Read / Snapshot Isolation** stops non-repeatable reads, BUT still permits **Write Skew** (two on-call doctors both see `on_call_count == 2` in their snapshot and both clock out concurrently, leaving 0 doctors!)."],callout:{type:"WATCH OUT",text:"Default PostgreSQL isolation is `READ COMMITTED`, while MySQL InnoDB defaults to `REPEATABLE READ`. Always state your locking/isolation strategy explicitly in booking/payment designs!"},scene:{hud:[{label:"READ COMMITTED",value:"No Dirty Reads",status:"info"},{label:"SNAPSHOT / RR",value:"Write Skew Risk",status:"warn"},{label:"SERIALIZABLE",value:"Zero Anomalies",status:"good"},{label:"ENGINE",value:"MVCC Versions",status:"good"}],nodes:[{id:"t1",type:"hex",x:145,y:135,label:"Doctor A Tx",sublabel:"Reads count=2",tone:"amber"},{id:"t2",type:"hex",x:145,y:295,label:"Doctor B Tx",sublabel:"Reads count=2",tone:"amber"},{id:"db",type:"db",x:465,y:215,label:"Snapshot DB",sublabel:"Both clock out!",tone:"coral",badge:"Write Skew: 0 left!",badgeTone:"rose"}],edges:[{from:"t1",to:"db",label:"UPDATE A=off",packetColor:"coral",speed:1.9},{from:"t2",to:"db",label:"UPDATE B=off",packetColor:"coral",speed:1.9}],legend:[{label:"concurrent write skew",tone:"coral"}]}},{shortLabel:"Opt vs Pess Lock",stage:"SOLUTION",title:"Preventing double-booking: Optimistic (`@Version`) vs Pessimistic (`FOR UPDATE`)",body:['**Optimistic Locking** adds a `version` column: `UPDATE seats SET status="BOOKED", version=version+1 WHERE id=5 AND version=7`. If 0 rows update, a rival won — retry or reject! Zero lock wait under low contention.',"**Pessimistic Locking** (`SELECT ... FOR UPDATE`) acquires an exclusive row lock immediately. Best under **extreme contention** (flash sales / BookMyShow front-row seats) where optimistic retries would waste CPU."],callout:{type:"INTERVIEW SIGNAL",text:"Use **Optimistic Locking** for low-contention updates (profile edits, wikis) and **Pessimistic Locking / Redis Lua lease** for high-contention hot seats or flash-sale inventory!"},scene:{hud:[{label:"OPTIMISTIC",value:"WHERE version=v",status:"good"},{label:"PESSIMISTIC",value:"SELECT FOR UPDATE",status:"good"},{label:"LOW CONTENTION",value:"Use Optimistic",status:"info"},{label:"FLASH SALE",value:"Use Pessimistic",status:"warn"}],nodes:[{id:"u1",type:"users",x:120,y:135,label:"User 1",sublabel:"version=7",tone:"green"},{id:"u2",type:"users",x:120,y:295,label:"User 2",sublabel:"version=7",tone:"coral"},{id:"db",type:"db",x:470,y:215,label:"Seat A5 Row",sublabel:"v7 → v8 Atomic",tone:"purple",badge:"1 winner only",badgeTone:"green"}],edges:[{from:"u1",to:"db",label:"CAS v7→v8 (1 row ✓)",packetColor:"green",bidirectional:!0,speed:1.6},{from:"u2",to:"db",label:"CAS v7 (0 rows ✕)",packetColor:"coral",dashed:!0,speed:2.3}],legend:[{label:"atomic winner",tone:"green"},{label:"conflict rejected safely",tone:"coral"}]}}]},{id:"files",title:"Files & Media Storage",subtitle:"Object Storage (S3/Azure Blob), Direct Pre-Signed Uploads, 4MB Chunking & Content-Hash Deduplication.",duration:"8 min",level:"Beginner",companies:["Dropbox","Microsoft","YouTube","Netflix"],tags:["s3","azure blob","presigned url","multipart upload","deduplication","erasure coding"],objectives:["Never stream large files through application servers — use Pre-Signed URLs","Split large files into content-addressed chunks for resumable delta sync & dedup","Separate durable Object Storage (11 nines) from relational Metadata DB"],steps:[{shortLabel:"Pre-signed URLs",stage:"SOLUTION",title:"Bypass app servers with Direct-to-Object-Storage Pre-Signed URLs",body:["Uploading 2 GB videos through your Node/Java API servers saturates RAM, sockets, and bandwidth. Instead, the client asks your API for a **short-lived Pre-Signed URL** (valid 5 min, scoped to 1 key + max size).","The client uploads chunks **directly to S3 / Azure Blob Storage** (11 nines = `99.999999999%` durability via erasure coding). Object Storage then fires an async event to your **Transcoder / Metadata Worker**!"],callout:{type:"KEY IDEA",text:"Split files into **4 MB chunks** hashed by `SHA-256`: if two users upload the same PDF or you edit 1 paragraph of a 100 MB PowerPoint, only the 1 changed chunk ever uploads (Dropbox & OneDrive delta sync!)."},scene:{hud:[{label:"APP SERVER BW",value:"Near Zero",status:"good"},{label:"DURABILITY",value:"11 Nines (S3/Blob)",status:"good"},{label:"RESUMABLE",value:"4 MB Multipart",status:"good"},{label:"DEDUP",value:"SHA-256 Chunk Hash",status:"good"}],nodes:[{id:"c",type:"users",x:110,y:215,label:"Client",sublabel:"2 GB Video",tone:"slate"},{id:"api",type:"hex",x:350,y:105,label:"API + Meta DB",sublabel:"Signs URL (2 KB)",tone:"blue"},{id:"s3",type:"db",x:400,y:300,label:"Object Storage",sublabel:"S3 / Azure Blob",tone:"green",badge:"direct upload",badgeTone:"green"},{id:"wk",type:"hex",x:645,y:215,label:"Async Pipeline",sublabel:"Virus Scan · HLS",tone:"purple"}],edges:[{from:"c",to:"api",label:"1. get signed URL",packetColor:"blue",bidirectional:!0,speed:1.8},{from:"c",to:"s3",label:"2. PUT 4MB chunks direct",packetColor:"green",speed:1.5,packetCount:3},{from:"s3",to:"wk",label:"3. S3 Event trigger",packetColor:"purple",dashed:!0,speed:2.2}],legend:[{label:"tiny auth control plane",tone:"blue"},{label:"direct high-throughput media",tone:"green"}]}},{shortLabel:"Storage Tiers",stage:"TECHNIQUE",title:"Lifecycle Policies: Hot → Cool → Archive slashes storage bills 85%",body:["Most media follows an extreme age curve: 95% of views happen in the first 30 days. Automated **Lifecycle Rules** move untouched objects from **Hot Standard** → **Infrequent Access** → **Glacier / Cold Archive** (10× cheaper per TB) while keeping metadata instant."],callout:{type:"INTERVIEW SIGNAL",text:"Mentioning Lifecycle Tiering + CDN Origin Cache + SHA-256 Deduplication shows strong FinOps / cost-architecture awareness (a core Microsoft L63 & Amazon L6 rubric item!)."},scene:{hud:[{label:"DAYS 0–30",value:"Hot + CDN",status:"good"},{label:"DAYS 31–180",value:"Cool / IA (-45%)",status:"info"},{label:"DAYS 180+",value:"Archive (-85%)",status:"good"},{label:"METADATA",value:"Always Instant",status:"good"}],nodes:[{id:"h",type:"cache",x:165,y:215,label:"Hot + CDN",sublabel:"0–30 days",tone:"green"},{id:"c",type:"db",x:400,y:215,label:"Cool / IA",sublabel:"31–180 days",tone:"blue"},{id:"a",type:"db",x:635,y:215,label:"Cold Archive",sublabel:"180d+ (Compliance)",tone:"purple"}],edges:[{from:"h",to:"c",label:"auto-tier 30d",packetColor:"blue",speed:2.2},{from:"c",to:"a",label:"auto-tier 180d",packetColor:"purple",speed:2.4}],legend:[{label:"automated cost lifecycle",tone:"purple"}]}}]}]},t={id:"mod-04-communication",number:"04",title:"Communication",track:"hld",lessons:[{id:"apis",title:"REST, gRPC, GraphQL & Webhooks",subtitle:"Choosing API protocols, Protobuf binary contracts, cursor pagination, and idempotency keys.",duration:"10 min",level:"Beginner",companies:["Meta","Google","Microsoft","Stripe"],tags:["rest","grpc","protobuf","graphql","webhooks","pagination","idempotency"],objectives:["Choose between REST, gRPC, GraphQL, and Webhooks based on client & payload needs","Why cursor-based pagination beats OFFSET at scale","Design safe retries with Idempotency Keys and signed Webhooks"],steps:[{shortLabel:"Protocol fit",stage:"TECHNIQUE",title:"REST externally, gRPC internally, GraphQL for complex UI graphs",body:["**REST (HTTP + JSON)** wins for public APIs (cacheable via CDN, universal tooling). **gRPC (HTTP/2 + Protobuf)** wins for internal service-to-service hops (strict typed schema, 5–10× smaller payloads, bidirectional streaming).","**GraphQL** eliminates over-fetching and under-fetching for mobile clients querying deeply nested graphs (Meta, GitHub) — while **Webhooks** invert polling so payment/CI platforms push signed events (`HMAC-SHA256`) to your endpoint."],callout:{type:"INTERVIEW SIGNAL",text:"Always use **Cursor Pagination** (`?after=id_991&limit=20`) instead of `OFFSET 100000` (which forces the DB to scan & discard 100k rows and produces duplicates when new items insert!)."},scene:{hud:[{label:"PUBLIC API",value:"REST + OpenAPI",status:"good"},{label:"INTERNAL RPC",value:"gRPC + Protobuf",status:"good"},{label:"MOBILE AGG",value:"GraphQL / BFF",status:"info"},{label:"ASYNC PUSH",value:"Signed Webhooks",status:"info"}],nodes:[{id:"mob",type:"users",x:115,y:120,label:"Mobile / Web",sublabel:"REST / GraphQL",tone:"slate"},{id:"ext",type:"hex",x:115,y:300,label:"Stripe / Partner",sublabel:"HMAC Webhook",tone:"amber"},{id:"gw",type:"hex",x:375,y:215,label:"API Gateway",sublabel:"Edge BFF",tone:"green",badge:"protocol bridge",badgeTone:"green"},{id:"s1",type:"hex",x:640,y:130,label:"Order Svc",sublabel:"gRPC HTTP/2",tone:"blue"},{id:"s2",type:"hex",x:640,y:300,label:"User Svc",sublabel:"gRPC HTTP/2",tone:"purple"}],edges:[{from:"mob",to:"gw",label:"JSON / GQL",packetColor:"green",bidirectional:!0,speed:1.7},{from:"ext",to:"gw",label:"POST webhook",packetColor:"amber",speed:2.1},{from:"gw",to:"s1",label:"Protobuf",packetColor:"blue",bidirectional:!0,speed:1.5},{from:"gw",to:"s2",label:"Protobuf",packetColor:"purple",bidirectional:!0,speed:1.5}],legend:[{label:"external JSON/GQL",tone:"green"},{label:"internal binary gRPC",tone:"blue"}]}},{shortLabel:"Idempotency",stage:"SOLUTION",title:"Idempotency Keys prevent double-charges on flaky retries",body:['Alice taps "Pay $50", the server charges her card, and the Wi-Fi drops before the `200 OK` arrives. Her app retries `POST /payments`. Without protection, she is charged **$100**!',"With an **`Idempotency-Key: uuid`** header stored in a unique DB/Redis table alongside the cached response, the retry sees the existing key and returns the original `200 OK` receipt without executing the charge twice."],callout:{type:"KEY IDEA",text:"GET, PUT, and DELETE are naturally idempotent; POST is NOT. Make every mutating POST (payments, bookings, orders) idempotent via a client-generated UUID key!"},scene:{hud:[{label:"HEADER",value:"Idempotency-Key",status:"good"},{label:"RETRY #2",value:"Returns Cached 200",status:"good"},{label:"DOUBLE CHARGE",value:"Impossible ✓",status:"good"},{label:"KEY TTL",value:"24–72 Hours",status:"info"}],nodes:[{id:"c",type:"users",x:115,y:215,label:"Client Retry",sublabel:"Key: ik_881a",tone:"amber"},{id:"api",type:"hex",x:365,y:215,label:"Payment API",sublabel:"Atomic Check",tone:"green",badge:"deduped!",badgeTone:"green"},{id:"idem",type:"db",x:635,y:120,label:"Idempotency DB",sublabel:"ik_881a → 200 OK",tone:"purple"},{id:"psp",type:"hex",x:635,y:310,label:"Card PSP",sublabel:"Skipped on retry",tone:"slate",dim:!0}],edges:[{from:"c",to:"api",label:"retry ik_881a",packetColor:"amber",bidirectional:!0,speed:1.8},{from:"api",to:"idem",label:"found → replay 200",packetColor:"green",bidirectional:!0,speed:1.6},{from:"api",to:"psp",label:"NOT called twice",packetColor:"coral",dashed:!0,dim:!0,speed:3}],legend:[{label:"safe idempotent replay",tone:"green"}]}}],deepDive:{tradeoffs:[{option:"REST (HTTP/JSON)",bestWhen:"Public APIs, CRUD, CDN-cacheable GETs",pros:"Universal, human-readable, HTTP cache semantics",cons:"Verbose payloads, over/under-fetching across nested entities"},{option:"gRPC (HTTP/2 + Protobuf)",bestWhen:"Internal microservices, low-latency streaming, polyglot backends",pros:"5–10× smaller payloads, strict contracts, bidirectional streaming",cons:"Poor native browser support (needs gRPC-Web), harder curl debugging"},{option:"GraphQL",bestWhen:"Complex UI screens (web + iOS + Android) needing tailored projections",pros:"Single round trip, zero over-fetching, strongly typed schema",cons:"N+1 DB query risk (fix with DataLoader), harder HTTP CDN caching"}]}},{id:"queues",title:"Message Queues",subtitle:"Peak shaving, decoupling slow workers, visibility timeouts, at-least-once delivery, and Dead-Letter Queues.",duration:"9 min",level:"Beginner",companies:["Amazon","Microsoft","Uber","Shopify"],tags:["sqs","rabbitmq","dlq","peak shaving","backpressure","idempotent consumer","competing consumers"],objectives:["Smooth massive traffic spikes (peak shaving) without crashing downstream DBs","Handle worker crashes safely via Visibility Timeouts + Idempotent Consumers","Route poison-pill messages to a Dead-Letter Queue (DLQ) with alerting"],steps:[{shortLabel:"Peak shaving",stage:"SOLUTION",title:"Buffers absorb 50× traffic spikes without losing a single order",body:["During a flash sale, 100,000 orders/sec hit Checkout, while your email/invoice/inventory worker pipeline can safely process 5,000/sec. Synchronous RPCs would time out and drop orders!","Inserting a durable **Message Queue** (AWS SQS, RabbitMQ, Azure Service Bus) lets Checkout enqueue and ACK in **4 ms**, while **Competing Consumer Workers** drain the queue steadily at their maximum safe throughput (**Peak Shaving**)."],callout:{type:"KEY IDEA",text:"Queues trade immediate synchronous completion for **resilience, backpressure protection, and elastic independent scaling** of producers vs consumers."},scene:{hud:[{label:"INGEST SPIKE",value:"100k msg/s",status:"warn"},{label:"CHECKOUT P99",value:"4 ms ACK",status:"good"},{label:"WORKER DRAIN",value:"5k/s Steady",status:"good"},{label:"DROPPED ORDERS",value:"0",status:"good"}],nodes:[{id:"p",type:"hex",x:115,y:215,label:"Checkout API",sublabel:"100k spike",tone:"blue"},{id:"q",type:"queue",x:350,y:215,label:"Order Queue",sublabel:"SQS / RabbitMQ",tone:"amber",badge:"shock absorber",badgeTone:"amber"},{id:"w1",type:"hex",x:615,y:120,label:"Worker 1..N",sublabel:"Steady Drain",tone:"green",load:58},{id:"dlq",type:"queue",x:615,y:315,label:"Dead-Letter Q",sublabel:"Failed > 3x",tone:"coral",badge:"alert + inspect",badgeTone:"rose"}],edges:[{from:"p",to:"q",label:"burst enqueue",packetColor:"coral",speed:1.3,packetCount:3},{from:"q",to:"w1",label:"pull + ACK",packetColor:"green",speed:2},{from:"q",to:"dlq",label:"poison pill",packetColor:"coral",dashed:!0,speed:3.1,packetCount:1}],legend:[{label:"traffic burst",tone:"coral"},{label:"controlled worker drain",tone:"green"}]}},{shortLabel:"At-least-once",stage:"TECHNIQUE",title:"Visibility Timeout + Idempotent Workers = Effectively-Once",body:["When Worker 1 pulls a message, the queue hides it for a **Visibility Timeout** (e.g., 30s). If Worker 1 crashes before calling `ACK`, the message reappears and Worker 2 processes it (**At-Least-Once delivery**).","Because Worker 1 might have crashed *after* writing to DB but *before* calling `ACK`, every queue consumer **MUST be idempotent** (dedup by `message_id` / `order_id` unique constraint)!"],callout:{type:"WATCH OUT",text:"Poison Pill Bug: A malformed JSON message crashes Worker 1 → retries on Worker 2 → crashes Worker 2 forever in an infinite loop! Always configure `maxReceiveCount = 3` → move to **Dead-Letter Queue (DLQ)**."},scene:{hud:[{label:"DELIVERY",value:"At-Least-Once",status:"info"},{label:"SAFETY RULE",value:"Idempotent Consumer",status:"good"},{label:"RETRY CAP",value:"3× → DLQ",status:"good"},{label:"LOSS RISK",value:"Zero (Durable)",status:"good"}],nodes:[{id:"q",type:"queue",x:150,y:215,label:"Queue",sublabel:"Vis Timeout 30s",tone:"amber"},{id:"w1",type:"hex",x:420,y:120,label:"Worker 1",sublabel:"Crash pre-ACK!",tone:"coral",badge:"died",badgeTone:"rose",dim:!0},{id:"w2",type:"hex",x:420,y:310,label:"Worker 2",sublabel:"Dedup + ACK ✓",tone:"green",badge:"idempotent",badgeTone:"green"},{id:"db",type:"db",x:660,y:215,label:"Orders DB",sublabel:"UNIQUE(msg_id)",tone:"purple"}],edges:[{from:"q",to:"w1",label:"try 1",packetColor:"coral",dashed:!0,speed:2.5},{from:"q",to:"w2",label:"redeliver @ 30s",packetColor:"green",speed:1.8},{from:"w2",to:"db",label:"upsert safely",packetColor:"purple",speed:1.7}],legend:[{label:"crash-safe redelivery",tone:"green"}]}}]},{id:"pubsub",title:"Pub/Sub & Event Streaming (Kafka)",subtitle:"Inside Apache Kafka: append-only partitioned logs, Consumer Groups, Offsets, ISR, and Zero-Copy.",duration:"11 min",level:"Intermediate",companies:["LinkedIn","Uber","Microsoft","Netflix"],tags:["kafka","pubsub","partitions","consumer group","offset","isr","zero copy","event hubs"],objectives:["Contrast traditional destructive queues (SQS/RabbitMQ) vs replayable event logs (Kafka)","Understand how Topics, Partitions, Partition Keys, and Consumer Groups govern ordering and parallelism","Explain why Kafka sustains 1M+ msg/sec (sequential disk I/O + OS page cache + zero-copy sendfile)"],steps:[{shortLabel:"Log & Groups",stage:"SOLUTION",title:"Kafka is a durable replayable commit log — multiple apps read independently",body:["Unlike RabbitMQ (which deletes a message once consumed), **Apache Kafka** (and Azure Event Hubs) appends events to immutable **Partitions** retained for days/weeks. Each **Consumer Group** tracks its own **Offset**!","So a single `OrderPlaced` event can simultaneously feed **Billing**, **Fraud ML**, **Notifications**, and **Data Warehouse** — and a brand-new analytics service can replay the last 7 days from offset `0`!"],callout:{type:"KEY IDEA",text:"Ordering in Kafka is guaranteed **ONLY within a single Partition**, NOT across the whole topic! Always key related events by entity ID (e.g., `key = order_id` or `user_id`) so all state transitions for one order land in the exact same partition in strict order."},scene:{hud:[{label:"ORDERING",value:"Per Partition",status:"info"},{label:"MAX PARALLELISM",value:"1 Consumer / Part.",status:"warn"},{label:"REPLAYABLE",value:"Yes (Offset Seek)",status:"good"},{label:"THROUGHPUT",value:"1M+ msg/s",status:"good"}],nodes:[{id:"prod",type:"hex",x:105,y:215,label:"Producer",sublabel:"hash(order_id)",tone:"blue"},{id:"p0",type:"queue",x:350,y:120,label:"Partition 0",sublabel:"Offsets 0..941",tone:"amber",badge:"ordered",badgeTone:"amber"},{id:"p1",type:"queue",x:350,y:310,label:"Partition 1",sublabel:"Offsets 0..882",tone:"amber",badge:"ordered",badgeTone:"amber"},{id:"g1",type:"hex",x:635,y:120,label:"Billing Grp",sublabel:"Offset: 941",tone:"green"},{id:"g2",type:"hex",x:635,y:310,label:"Fraud ML Grp",sublabel:"Offset: 710",tone:"purple"}],edges:[{from:"prod",to:"p0",label:"ord_101",packetColor:"blue",speed:1.6},{from:"prod",to:"p1",label:"ord_204",packetColor:"blue",speed:1.6},{from:"p0",to:"g1",label:"consume",packetColor:"green",speed:1.8},{from:"p1",to:"g1",label:"consume",packetColor:"green",speed:1.9},{from:"p0",to:"g2",label:"independent copy",packetColor:"purple",dashed:!0,speed:2.3},{from:"p1",to:"g2",label:"independent copy",packetColor:"purple",dashed:!0,speed:2.3}],legend:[{label:"partitioned publish",tone:"blue"},{label:"independent consumer group",tone:"purple"}]}},{shortLabel:"Why so fast?",stage:"TECHNIQUE",title:"Sequential I/O, Zero-Copy `sendfile()`, and ISR Durability (`acks=all`)",body:["Why is Kafka blazing fast despite writing to disk? 1) **Sequential disk appends** rival RAM speed, 2) **OS Page Cache** serves hot consumers straight from kernel RAM, 3) **Zero-Copy (`sendfile()`)** streams bytes directly from Page Cache → NIC without copying into JVM heap!","For durability without data loss, configure **`acks=all`** with **`min.insync.replicas=2`** (replication factor 3) so a message commits only once written to Leader + at least 1 In-Sync Replica (ISR)."],callout:{type:"WATCH OUT",text:"If a topic has 6 partitions and you launch 10 consumers in one Consumer Group, 4 consumers sit 100% idle! Maximum concurrency in a consumer group equals the partition count."},scene:{hud:[{label:"DISK PATTERN",value:"Sequential Log",status:"good"},{label:"NETWORK",value:"Zero-Copy NIC",status:"good"},{label:"DURABILITY",value:"acks=all · ISR≥2",status:"good"},{label:"COMPACTION",value:"Latest Key State",status:"info"}],nodes:[{id:"ldr",type:"queue",x:185,y:215,label:"Leader Broker",sublabel:"Page Cache + WAL",tone:"green",badge:"zero-copy",badgeTone:"green"},{id:"isr1",type:"db",x:455,y:120,label:"ISR Replica 1",sublabel:"Synced ✓",tone:"blue"},{id:"isr2",type:"db",x:455,y:310,label:"ISR Replica 2",sublabel:"Synced ✓",tone:"blue"},{id:"nic",type:"hex",x:665,y:215,label:"DMA → NIC",sublabel:"Bypass JVM Heap",tone:"purple"}],edges:[{from:"ldr",to:"isr1",label:"replicate",packetColor:"blue",bidirectional:!0,speed:1.7},{from:"ldr",to:"isr2",label:"replicate",packetColor:"blue",bidirectional:!0,speed:1.7},{from:"ldr",to:"nic",label:"sendfile()",packetColor:"purple",speed:1.5}],legend:[{label:"ISR durability",tone:"blue"},{label:"zero-copy stream",tone:"purple"}]}}]},{id:"realtime",title:"Real-Time Updates",subtitle:"Short Polling vs Long Polling vs Server-Sent Events (SSE) vs WebSockets vs WebRTC.",duration:"9 min",level:"Beginner",companies:["Meta","Microsoft","Discord","OpenAI"],tags:["websockets","sse","long polling","short polling","webrtc","streaming"],objectives:["Compare all 5 real-time communication mechanisms by direction, overhead, and firewall friendliness","Know why ChatGPT / LLM token streaming uses SSE while WhatsApp / Trading uses WebSockets","Understand WebRTC P2P media (STUN/TURN) for video & voice calls"],steps:[{shortLabel:"Compare 5",stage:"TECHNIQUE",title:"Pick the simplest push mechanism that matches your directionality",body:['**Short Polling** wastes bandwidth asking "any updates?" every 2s. **Long Polling** holds the HTTP request open until data arrives (good fallback).',"**Server-Sent Events (SSE)** is pure one-way HTTP streaming (Server → Client) with automatic reconnects — ideal for **LLM token streaming (ChatGPT/Copilot)**, live sports scores, and stock tickers! **WebSockets** upgrade HTTP to a full-duplex persistent TCP socket for **Chat, Multiplayer Games, and Collaborative Docs**."],callout:{type:"INTERVIEW SIGNAL",text:"Don’t reach for WebSockets blindly! If updates only flow Server → Client (notifications, dashboards, AI streaming), **SSE over HTTP/2** is far simpler to load-balance and firewall-friendly than WebSockets."},scene:{hud:[{label:"SSE",value:"Server → Client",status:"good"},{label:"WEBSOCKETS",value:"Full Duplex TCP",status:"good"},{label:"WEBRTC",value:"P2P Audio/Video",status:"info"},{label:"LONG POLL",value:"Legacy Fallback",status:"warn"}],nodes:[{id:"c",type:"users",x:120,y:215,label:"Browser / App",sublabel:"Real-time UI",tone:"slate"},{id:"sse",type:"hex",x:430,y:100,label:"SSE Stream",sublabel:"AI Tokens / Feed",tone:"green",badge:"HTTP/2 1-way",badgeTone:"green"},{id:"ws",type:"hex",x:430,y:215,label:"WebSocket GW",sublabel:"Chat / Docs",tone:"blue",badge:"full duplex",badgeTone:"blue"},{id:"rtc",type:"hex",x:430,y:335,label:"WebRTC SFU",sublabel:"Teams / Zoom",tone:"purple",badge:"UDP media",badgeTone:"purple"}],edges:[{from:"sse",to:"c",label:"text/event-stream",packetColor:"green",speed:1.6},{from:"c",to:"ws",label:"ws:// bidirectional",packetColor:"blue",bidirectional:!0,speed:1.5},{from:"c",to:"rtc",label:"SRTP / UDP P2P",packetColor:"purple",bidirectional:!0,speed:1.4}],legend:[{label:"SSE 1-way push",tone:"green"},{label:"WebSocket 2-way",tone:"blue"},{label:"WebRTC UDP media",tone:"purple"}]}},{shortLabel:"Scaling WS",stage:"SOLUTION",title:"Scaling 10M WebSockets: Stateful Gateways + Pub/Sub Backplane",body:["A single tuned Linux box holds ~100k–500k idle WebSocket connections (limited by RAM per socket + file descriptors, not CPU). To serve 10M concurrent users, run 100 **WebSocket Gateways**.","When Alice (on Gateway #1) messages Bob (on Gateway #47), Gateway #1 publishes to **Redis Pub/Sub / Kafka** (or looks up Bob’s gateway in a **Session Registry**) so Gateway #47 pushes the frame down Bob’s open socket!"],callout:{type:"WATCH OUT",text:"Deploying a WebSocket gateway disconnects 100k users at once — causing a **Thundering Herd Reconnect Storm**! Mitigate with **draining + randomized client reconnect jitter**."},scene:{hud:[{label:"CONNS / NODE",value:"100k – 500k",status:"good"},{label:"CROSS-GW BUS",value:"Redis Pub/Sub",status:"info"},{label:"HEARTBEAT",value:"Every 30s",status:"info"},{label:"RECONNECT",value:"Jittered Backoff",status:"good"}],nodes:[{id:"a",type:"users",x:95,y:120,label:"Alice",sublabel:"On GW #1",tone:"slate"},{id:"gw1",type:"hex",x:270,y:120,label:"WS GW #1",sublabel:"100k sockets",tone:"blue"},{id:"bus",type:"queue",x:455,y:215,label:"Pub/Sub Bus",sublabel:"Routes to GW #47",tone:"amber"},{id:"gw47",type:"hex",x:270,y:315,label:"WS GW #47",sublabel:"100k sockets",tone:"green"},{id:"b",type:"users",x:95,y:315,label:"Bob",sublabel:"Receives in 25ms",tone:"slate"}],edges:[{from:"a",to:"gw1",label:"send msg",packetColor:"blue",speed:1.7},{from:"gw1",to:"bus",label:"route(Bob)",packetColor:"amber",speed:1.6},{from:"bus",to:"gw47",label:"deliver",packetColor:"green",speed:1.6},{from:"gw47",to:"b",label:"push frame",packetColor:"green",speed:1.5}],legend:[{label:"cross-gateway message relay",tone:"green"}]}}]}]},o={id:"mod-05-reliability",number:"05",title:"Reliability",track:"hld",lessons:[{id:"redundancy",title:"Redundancy, Failover & Cells",subtitle:"Multi-AZ & Multi-Region DR (RPO/RTO), Active-Active vs Active-Passive, and Cell-Based Blast Radius Isolation.",duration:"10 min",level:"Intermediate",companies:["Amazon","Microsoft","Netflix","Google"],tags:["high availability","rpo","rto","active-active","cell architecture","multi-region","blast radius"],objectives:["Define Availability Nines (99.9% vs 99.99%), RPO (data loss), and RTO (downtime)","Compare Active-Passive (Warm Standby / Pilot Light) vs Active-Active Multi-Region","Apply Amazon/Azure Cell-Based Architecture to cap outage blast radius to 1/N of users"],steps:[{shortLabel:"Active-Active",stage:"SOLUTION",title:"Active-Passive vs Active-Active Multi-Region & RPO/RTO",body:["**RPO (Recovery Point Objective)** is the max data loss tolerated (e.g., 5 seconds of async lag). **RTO (Recovery Time Objective)** is how fast service recovers after disaster.","**Active-Passive** runs production in US-East and fails over to US-West on disaster (simpler consistency, minutes of RTO). **Active-Active** serves live traffic in both US and EU simultaneously (lowest latency, near-zero RTO, but requires handling multi-region write conflicts!)."],callout:{type:"INTERVIEW SIGNAL",text:'If you say "Active-Active Multi-Region," immediately address **how writes avoid conflicts** (e.g., Geo-Pinned Home Region per user, CRDTs, or Distributed SQL Spanner)!'},scene:{hud:[{label:"AVAILABILITY",value:"99.99% (52m/yr)",status:"good"},{label:"RPO TARGET",value:"< 5 sec",status:"good"},{label:"RTO TARGET",value:"< 30 sec",status:"good"},{label:"ROUTING",value:"GeoDNS + Health",status:"info"}],nodes:[{id:"dns",type:"hex",x:380,y:80,label:"Global Traffic Mgr",sublabel:"Azure Front Door / R53",tone:"green"},{id:"us",type:"hex",x:185,y:235,label:"US-East Region",sublabel:"3 AZs · Active",tone:"blue",badge:"healthy",badgeTone:"green",load:44},{id:"eu",type:"hex",x:575,y:235,label:"EU-West Region",sublabel:"3 AZs · Active",tone:"purple",badge:"healthy",badgeTone:"green",load:41},{id:"sync",type:"db",x:380,y:340,label:"Cross-Region Rep",sublabel:"Async / Global DB",tone:"amber"}],edges:[{from:"dns",to:"us",label:"Americas",packetColor:"blue",speed:1.7},{from:"dns",to:"eu",label:"EMEA / Failover",packetColor:"purple",speed:1.7},{from:"us",to:"sync",label:"replicate",packetColor:"amber",dashed:!0,speed:2.3},{from:"eu",to:"sync",label:"replicate",packetColor:"amber",dashed:!0,speed:2.3}],legend:[{label:"active-active regional traffic",tone:"blue"}]}},{shortLabel:"Cell Isolation",stage:"TECHNIQUE",title:"Cell-Based Architecture caps blast radius to 1/N of customers",body:["A bad config deploy or noisy tenant in a giant shared cluster can take down **100% of users** at once. **Amazon, Slack, and Microsoft Azure** partition production into independent **Cells** (each cell has its own stateless services, Redis, and DB shard serving 5% of tenants).","A thin **Cell Router** hashes `tenant_id → Cell #k`. Even a catastrophic bug rolled out to Cell 1 leaves 95% of customers completely untouched!"],callout:{type:"KEY IDEA",text:'Cell-based architecture + Shuffle Sharding (assigning each tenant to 2 of N cells) makes multi-tenant "noisy neighbor" outages mathematically near-impossible.'},scene:{hud:[{label:"BLAST RADIUS",value:"Max 1 Cell (25%)",status:"good"},{label:"DEPLOY ROLLOUT",value:"Cell 1 → 2 → All",status:"good"},{label:"NOISY NEIGHBOR",value:"Contained ✓",status:"good"},{label:"PATTERN",value:"Azure / AWS Cells",status:"info"}],nodes:[{id:"rt",type:"hex",x:135,y:215,label:"Cell Router",sublabel:"Stateless Thin",tone:"green"},{id:"c1",type:"hex",x:485,y:95,label:"Cell 1 (Canary)",sublabel:"App + Cache + DB",tone:"coral",badge:"bad deploy isolated",badgeTone:"rose"},{id:"c2",type:"hex",x:485,y:215,label:"Cell 2",sublabel:"App + Cache + DB",tone:"green",badge:"100% healthy",badgeTone:"green"},{id:"c3",type:"hex",x:485,y:335,label:"Cell 3..N",sublabel:"App + Cache + DB",tone:"green",badge:"100% healthy",badgeTone:"green"}],edges:[{from:"rt",to:"c1",label:"5% tenants",packetColor:"coral",dashed:!0,speed:2.5},{from:"rt",to:"c2",label:"healthy",packetColor:"green",speed:1.7},{from:"rt",to:"c3",label:"healthy",packetColor:"green",speed:1.7}],legend:[{label:"isolated healthy cell",tone:"green"},{label:"contained canary fault",tone:"coral"}]}}]},{id:"rate-limiting",title:"Rate Limiting",subtitle:"Token Bucket, Leaky Bucket, Fixed Window, Sliding Window Log/Counter, and atomic Redis Lua scripts.",duration:"10 min",level:"Intermediate",companies:["Stripe","Cloudflare","Microsoft","Amazon"],tags:["token bucket","leaky bucket","sliding window","redis lua","429","ddos"],objectives:["Compare all 5 Rate Limiting algorithms by burst handling, accuracy, and RAM footprint","Prevent distributed race conditions using atomic Redis Lua scripts","Return standard `HTTP 429` + `X-RateLimit-Remaining` + `Retry-After` headers"],steps:[{shortLabel:"5 Algorithms",stage:"TECHNIQUE",title:"Token Bucket vs Leaky Bucket vs Sliding Window Counter",body:["1. **Token Bucket** (AWS/Stripe): Tokens refill at rate `R` up to capacity `B` — **allows controlled short bursts** while capping long-term average.","2. **Leaky Bucket**: Requests queue and drain at a **strictly constant pace** — smooths traffic for fragile downstream APIs.","3. **Fixed Window**: Simple counter per minute, BUT suffers a **2× boundary spike** (`59.9s` + `60.1s`). **Sliding Window Counter** blends previous + current window weights in **O(1) memory** with < 0.1% approximation error!"],callout:{type:"GOOD TO KNOW",text:"Stress-test all 4 algorithms side-by-side with live burst buttons in **Design Lab → Rate Limiter Arena**!"},scene:{hud:[{label:"TOKEN BUCKET",value:"Bursts Allowed",status:"good"},{label:"LEAKY BUCKET",value:"Constant Outflow",status:"info"},{label:"SLIDING COUNTER",value:"O(1) Accurate",status:"good"},{label:"HTTP CODE",value:"429 + Retry-After",status:"warn"}],nodes:[{id:"c",type:"users",x:110,y:215,label:"API Clients",sublabel:"Burst 500 req/s",tone:"slate"},{id:"rl",type:"hex",x:350,y:215,label:"Rate Limiter",sublabel:"Gateway Middleware",tone:"amber",badge:"Token Bucket",badgeTone:"amber"},{id:"rd",type:"cache",x:350,y:355,label:"Redis Lua",sublabel:"Atomic Eval (0.4ms)",tone:"purple"},{id:"ok",type:"hex",x:635,y:130,label:"Backend API",sublabel:"Protected ✓",tone:"green",load:36},{id:"rej",type:"hex",x:635,y:300,label:"429 Rejected",sublabel:"Retry-After: 2s",tone:"coral"}],edges:[{from:"c",to:"rl",label:"API key",packetColor:"blue",speed:1.5,packetCount:3},{from:"rl",to:"rd",label:"Lua script",packetColor:"purple",bidirectional:!0,speed:1.4},{from:"rl",to:"ok",label:"allowed",packetColor:"green",speed:1.7},{from:"rl",to:"rej",label:"over limit",packetColor:"coral",dashed:!0,speed:2}],legend:[{label:"allowed request",tone:"green"},{label:"429 throttled",tone:"coral"}]}},{shortLabel:"Race & Failover",stage:"SOLUTION",title:"Atomic Redis Lua fixes read-then-write races; Fail-Open vs Fail-Closed",body:["If 2 API Gateways run `GET count` → both see `99` → both allow and `SET 100`, you leak extra requests! Running the check-and-decrement inside a single **Redis Lua script** executes atomically on Redis’s single-threaded loop.","What if Redis itself goes unreachable? Decide explicitly: **Fail-Open** (allow traffic so checkout doesn’t break during a Redis blip) vs **Fail-Closed** (block traffic for security-critical login/OTP endpoints)!"],callout:{type:"INTERVIEW SIGNAL",text:'Always ask your interviewer: "If the rate-limiter Redis cluster goes down, should we Fail-Open for availability or Fail-Closed for protection?" That question alone earns Staff points.'},scene:{hud:[{label:"ATOMICITY",value:"Redis Lua Eval",status:"good"},{label:"CHECKOUT RL",value:"Fail-Open",status:"info"},{label:"LOGIN / OTP RL",value:"Fail-Closed",status:"warn"},{label:"MULTI-REGION",value:"Local + Async Sync",status:"good"}],nodes:[{id:"g1",type:"hex",x:145,y:135,label:"Gateway 1",sublabel:"EVALSHA",tone:"blue"},{id:"g2",type:"hex",x:145,y:295,label:"Gateway 2",sublabel:"EVALSHA",tone:"blue"},{id:"lua",type:"cache",x:470,y:215,label:"Redis Single-Thread",sublabel:"Atomic Lua Script",tone:"green",badge:"zero race!",badgeTone:"green"}],edges:[{from:"g1",to:"lua",label:"atomic #1",packetColor:"green",bidirectional:!0,speed:1.6},{from:"g2",to:"lua",label:"atomic #2",packetColor:"green",bidirectional:!0,speed:1.9}],legend:[{label:"serialized atomic Lua execution",tone:"green"}]}}]},{id:"timeouts-retries",title:"Timeouts, Retries & Circuit Breakers",subtitle:"Stopping cascading failures with Exponential Backoff + Full Jitter, Circuit Breakers, and Bulkheads.",duration:"9 min",level:"Intermediate",companies:["Amazon","Netflix","Microsoft","Google"],tags:["circuit breaker","exponential backoff","jitter","bulkhead","cascading failure","load shedding"],objectives:["Prevent thread-pool exhaustion with strict connect + read timeouts","Avoid synchronized thundering-herd retries using Exponential Backoff + Full Jitter","Implement the 3-state Circuit Breaker (Closed → Open → Half-Open) and Bulkhead Isolation"],steps:[{shortLabel:"Cascading crash",stage:"PROBLEM",title:"One slow dependency freezes every caller’s thread pool",body:["Suppose Recommendation Service stalls for 30 seconds instead of failing fast. Frontend API threads wait indefinitely; incoming requests pile up, exhaust all 500 worker threads, and **crash the entire Checkout site** even though Checkout doesn’t even need recommendations!","Then clients blindly retry every 1 second in lockstep, multiplying load 10× on the struggling server (**Retry Storm**)."],callout:{type:"WATCH OUT",text:"A slow dependency is FAR more dangerous than a dead dependency that returns `503` in 2 ms! Always configure explicit timeouts on every outbound HTTP/DB/RPC client."},scene:{hud:[{label:"RECS SERVICE",value:"30s Hang!",status:"bad"},{label:"CALLER THREADS",value:"500 / 500 Blocked",status:"bad"},{label:"CHECKOUT",value:"Collateral Outage",status:"bad"},{label:"RETRY LOAD",value:"10× Storm",status:"bad"}],nodes:[{id:"fe",type:"hex",x:165,y:215,label:"Storefront API",sublabel:"500/500 Blocked",tone:"coral",badge:"thread exhaustion",badgeTone:"rose",load:99},{id:"rec",type:"hex",x:545,y:215,label:"Recs Service",sublabel:"Stalled 30s",tone:"coral",badge:"zombie hang",badgeTone:"rose",load:98}],edges:[{from:"fe",to:"rec",label:"no timeout + retry storm!",packetColor:"coral",speed:1.4,packetCount:3}],legend:[{label:"cascading thread starvation",tone:"coral"}]}},{shortLabel:"Breaker + Jitter",stage:"SOLUTION",title:"Circuit Breaker + Full Jitter + Bulkhead contain the blast",body:["1. **Circuit Breaker**: Normally **CLOSED**. If error/timeout rate crosses 50%, it trips **OPEN** and fails fast locally in `0.1 ms` (serving a cached fallback!) so Recs can breathe. After 30s, **HALF-OPEN** sends 1 probe request to test recovery.","2. **Exponential Backoff + Full Jitter**: `sleep = random(0, min(cap, base * 2^attempt))` spreads retries evenly over time.","3. **Bulkhead Pattern**: Give Recommendations its own 20-thread pool separate from Checkout’s 200-thread pool — like watertight ship compartments!"],callout:{type:"KEY IDEA",text:'AWS’s famous "Exponential Backoff And Jitter" study proved Full Jitter reduces server contention and finishes all work faster than pure exponential backoff.'},changes:["+Circuit Breaker trips OPEN → fails fast in 0.1 ms with fallback","+Bulkhead isolates Recs to max 20 threads; Checkout stays 100% healthy","+Full Jitter eliminates synchronized retry spikes"],scene:{hud:[{label:"BREAKER STATE",value:"OPEN → Fallback",status:"warn"},{label:"CHECKOUT SLA",value:"100% Healthy ✓",status:"good"},{label:"RETRY POLICY",value:"Exp + Full Jitter",status:"good"},{label:"ISOLATION",value:"Bulkhead Pools",status:"good"}],nodes:[{id:"fe",type:"hex",x:135,y:215,label:"Storefront",sublabel:"Bulkhead Isolated",tone:"green",load:34},{id:"cb",type:"hex",x:375,y:120,label:"Circuit Breaker",sublabel:"OPEN → Cached Recs",tone:"amber",badge:"fail-fast 0.1ms",badgeTone:"amber"},{id:"chk",type:"hex",x:625,y:295,label:"Checkout Pool",sublabel:"200 Threads OK",tone:"green",badge:"unharmed",badgeTone:"green",load:40},{id:"rec",type:"hex",x:625,y:120,label:"Recs Service",sublabel:"Recovering safely",tone:"coral",dim:!0,load:22}],edges:[{from:"fe",to:"cb",label:"0.1ms fallback",packetColor:"amber",bidirectional:!0,speed:1.6},{from:"cb",to:"rec",label:"1 half-open probe",packetColor:"coral",dashed:!0,speed:3.4,packetCount:1},{from:"fe",to:"chk",label:"isolated pool",packetColor:"green",bidirectional:!0,speed:1.6}],legend:[{label:"protected checkout traffic",tone:"green"},{label:"circuit-breaker fallback",tone:"amber"}]}}]},{id:"observability",title:"Observability & SLOs",subtitle:"Metrics (RED/USE), Structured Logs, OpenTelemetry Distributed Tracing, and Error Budgets.",duration:"8 min",level:"Beginner",companies:["Google","Microsoft","Datadog","Amazon"],tags:["prometheus","grafana","opentelemetry","jaeger","elk","sli","slo","sla","error budget"],objectives:["Distinguish the Three Pillars: Metrics (what), Traces (where), Logs (why)","Propagate W3C `traceparent` TraceID/SpanID across microservices and Kafka","Manage reliability scientifically using SLIs, SLOs, SLAs, and Error Budgets"],steps:[{shortLabel:"Three Pillars",stage:"SOLUTION",title:"Metrics alert you, Traces pinpoint the slow hop, Logs explain why",body:["1. **Metrics** (Prometheus / Azure Monitor): Cheap numeric time-series tracking **RED** (Rate, Errors, Duration p99) for services and **USE** (Utilization, Saturation, Errors) for hardware.","2. **Distributed Tracing** (OpenTelemetry / Jaeger): Stamps every request with a **`TraceID`** at the gateway and creates child **`SpanID`s** across every gRPC, DB, and Kafka hop so you spot the exact 420 ms bottleneck in a waterfall graph.","3. **Structured Logs** (JSON in ELK / Loki): Attach `trace_id` to error logs for root-cause stack traces."],callout:{type:"KEY IDEA",text:"Don’t trace 100% of 1M RPS requests — use **Tail-Based Sampling**: keep 1% of fast 200 OK traces, and **100% of 5xx errors and slow p99 traces**!"},scene:{hud:[{label:"METRICS",value:"RED · Prometheus",status:"good"},{label:"TRACING",value:"OTel TraceID",status:"good"},{label:"SAMPLING",value:"Tail-Based (100% err)",status:"good"},{label:"ERROR BUDGET",value:"0.1% / 30 days",status:"info"}],nodes:[{id:"svc",type:"hex",x:135,y:215,label:"Microservices",sublabel:"OTel SDK",tone:"blue"},{id:"col",type:"hex",x:360,y:215,label:"OTel Collector",sublabel:"Tail Sampler",tone:"green"},{id:"m",type:"db",x:630,y:95,label:"Metrics TSDB",sublabel:"Prometheus/Alert",tone:"amber"},{id:"t",type:"db",x:630,y:215,label:"Trace Store",sublabel:"Tempo / Jaeger",tone:"purple"},{id:"l",type:"db",x:630,y:335,label:"Log Index",sublabel:"ELK / Loki",tone:"blue"}],edges:[{from:"svc",to:"col",label:"OTLP stream",packetColor:"green",speed:1.6},{from:"col",to:"m",label:"p99 / RPS",packetColor:"amber",speed:1.8},{from:"col",to:"t",label:"slow/err spans",packetColor:"purple",speed:1.9},{from:"col",to:"l",label:"JSON logs",packetColor:"blue",speed:2}],legend:[{label:"telemetry pipeline",tone:"green"}]}},{shortLabel:"SLI / SLO / SLA",stage:"TECHNIQUE",title:"Google SRE: Error Budgets align Velocity vs Reliability",body:["**SLI** = actual measurement (`99.94%` of checkout calls < 300 ms). **SLO** = internal target (`99.9%`). **SLA** = external legal contract with financial credits (`99.5%`, always looser than SLO!).","With a `99.9%` monthly SLO, your **Error Budget** is `0.1%` (~43 minutes/month). Budget left? Ship fast! Budget burned? Freeze new features and pay down reliability debt."],callout:{type:"INTERVIEW SIGNAL",text:"Alert on **SLO Burn Rate** (symptoms hurting users) rather than noisy CPU spikes — e.g., page on-call if 2% of your 30-day error budget burns in 1 hour!"},scene:{hud:[{label:"SLI (MEASURED)",value:"99.94%",status:"good"},{label:"SLO (TARGET)",value:"99.90%",status:"good"},{label:"SLA (CONTRACT)",value:"99.50%",status:"info"},{label:"BUDGET LEFT",value:"60% Remaining",status:"good"}],nodes:[{id:"sli",type:"hex",x:165,y:215,label:"SLI Metric",sublabel:"Real User Latency",tone:"blue"},{id:"slo",type:"hex",x:400,y:215,label:"SLO Budget",sublabel:"43 min / mo",tone:"green",badge:"healthy burn",badgeTone:"green"},{id:"act",type:"hex",x:635,y:215,label:"Release Gate",sublabel:"Ship or Freeze",tone:"purple"}],edges:[{from:"sli",to:"slo",label:"compare",packetColor:"blue",speed:1.8},{from:"slo",to:"act",label:"burn-rate alert",packetColor:"green",speed:1.8}],legend:[{label:"SRE error-budget loop",tone:"green"}]}}]}]},c=[t,o],l={id:"mod-06-architecture",number:"06",title:"Architecture",track:"hld",lessons:[{id:"microservices",title:"Monolith vs Microservices",subtitle:"Modular Monoliths, independent deployability, Strangler Fig migration, and avoiding the Distributed Monolith.",duration:"9 min",level:"Intermediate",companies:["Amazon","Netflix","Uber","Microsoft"],tags:["monolith","microservices","modular monolith","strangler fig","cqrs","conways law"],objectives:["Start with a Modular Monolith and split only when team autonomy or scaling bottlenecks demand it","Enforce Database-per-Service so microservices never share tables directly","Migrate safely from legacy monolith using the Strangler Fig pattern"],steps:[{shortLabel:"Trade-offs",stage:"SETUP",title:"Microservices solve organizational scale, not day-one code",body:["A **Modular Monolith** compiles into one deployable unit with strict internal module boundaries: zero network latency, easy ACID joins, trivial debugging. When **100+ engineers** collide on one CI pipeline or Video Transcoding needs GPUs while Checkout needs CPU, splitting into **Microservices** shines.","Cardinal Rule: **Database-per-Service**. If Service A queries Service B’s SQL tables directly, you built a **Distributed Monolith** — all the latency of microservices with none of the independence!"],callout:{type:"WATCH OUT",text:"Amazon Prime Video cut monitoring infrastructure costs by **90%** by consolidating an over-fragmented serverless microservice pipeline back into a single Modular Monolith."},scene:{hud:[{label:"SMALL TEAM",value:"Modular Monolith",status:"good"},{label:"100+ DEVS",value:"Microservices",status:"info"},{label:"DATA RULE",value:"1 DB per Service",status:"good"},{label:"ANTI-PATTERN",value:"Shared DB Coupling",status:"bad"}],nodes:[{id:"gw",type:"hex",x:120,y:215,label:"API Gateway",sublabel:"Strangler Router",tone:"green"},{id:"s1",type:"hex",x:385,y:115,label:"Order Svc",sublabel:"Team A · Go",tone:"blue"},{id:"d1",type:"db",x:635,y:115,label:"Order DB",sublabel:"Private Schema",tone:"purple"},{id:"s2",type:"hex",x:385,y:315,label:"Catalog Svc",sublabel:"Team B · Java",tone:"blue"},{id:"d2",type:"db",x:635,y:315,label:"Catalog DB",sublabel:"Private Schema",tone:"purple"}],edges:[{from:"gw",to:"s1",label:"/orders",packetColor:"green",speed:1.7},{from:"gw",to:"s2",label:"/catalog",packetColor:"green",speed:1.7},{from:"s1",to:"d1",label:"owned",packetColor:"purple",speed:1.8},{from:"s2",to:"d2",label:"owned",packetColor:"purple",speed:1.8},{from:"s1",to:"s2",label:"API/Event only",packetColor:"amber",dashed:!0,speed:2.4}],legend:[{label:"private owned DB",tone:"purple"},{label:"contract-only IPC",tone:"amber"}]}},{shortLabel:"Strangler Fig",stage:"SOLUTION",title:"Strangler Fig migrates monoliths slice-by-slice without a rewrite",body:['Never do a "Big Bang 18-month rewrite." Put a routing proxy in front of the monolith, peel off one domain (e.g., `/payments`), run **shadow traffic** to verify output parity, shift 1% → 10% → 100% traffic, and retire the old monolith module.'],callout:{type:"INTERVIEW SIGNAL",text:"Recommending **Strangler Fig + Shadow Traffic + Feature Flags** for legacy migrations is a classic Microsoft/Amazon Senior/Principal behavioral + design answer."},scene:{hud:[{label:"STRATEGY",value:"Strangler Fig",status:"good"},{label:"NEW SLICE",value:"/payments (100%)",status:"good"},{label:"LEGACY",value:"Shrinking Safely",status:"info"},{label:"DOWNTIME",value:"Zero",status:"good"}],nodes:[{id:"u",type:"users",x:110,y:215,label:"Traffic",sublabel:"100% Live",tone:"slate"},{id:"px",type:"hex",x:325,y:215,label:"Strangler Proxy",sublabel:"Canary / Shadow",tone:"green"},{id:"new",type:"hex",x:615,y:120,label:"New Payment Svc",sublabel:"Extracted ✓",tone:"green",badge:"live 100%",badgeTone:"green"},{id:"old",type:"hex",x:615,y:310,label:"Legacy Monolith",sublabel:"Rest of routes",tone:"amber",dim:!0}],edges:[{from:"u",to:"px",label:"all reqs",packetColor:"blue",speed:1.7},{from:"px",to:"new",label:"/payments",packetColor:"green",speed:1.6},{from:"px",to:"old",label:"/* remaining",packetColor:"amber",dashed:!0,speed:2.2}],legend:[{label:"incremental cutover",tone:"green"}]}}]},{id:"service-discovery",title:"Service Discovery & Mesh",subtitle:"Dynamic container IPs, Client vs Server Discovery (Consul/K8s DNS), and Envoy Sidecar Service Mesh.",duration:"8 min",level:"Intermediate",companies:["Google","Microsoft","Lyft","Amazon"],tags:["service discovery","consul","kubernetes dns","service mesh","istio","envoy","mtls"],objectives:["Discover ephemeral pod IPs without hardcoded hostnames","Compare Client-Side Discovery (Eureka/gRPC) vs Server-Side (K8s Service/ALB)","Offload mTLS, retries, timeouts, and telemetry to an Envoy Service Mesh sidecar"],steps:[{shortLabel:"Static IP Trap",stage:"PROBLEM",title:"Hardcoded IPs break the instant autoscaling restarts a container",body:["In cloud-native Kubernetes clusters, pods scale up during traffic spikes and get replaced on deploys with **brand-new ephemeral IP addresses** every few minutes.","Hardcoding `10.0.4.12:8080` in config files causes cascading `Connection Refused` failures the moment a single container recycles."],callout:{type:"WATCH OUT",text:"Traditional DNS caching inside JVM/Node clients can keep sending traffic to a dead pod IP for 60+ seconds unless you use active health-checked discovery or Envoy sidecars!"},scene:{hud:[{label:"POD LIFESPAN",value:"Ephemeral IPs",status:"warn"},{label:"STATIC CONFIG",value:"Stale / Broken",status:"bad"},{label:"DNS TTL LAG",value:"30 – 60s Errors",status:"bad"},{label:"FIX",value:"Registry + Mesh",status:"good"}],nodes:[{id:"ord",type:"hex",x:145,y:215,label:"Order Pod",sublabel:"Calls 10.0.4.12",tone:"blue"},{id:"old",type:"hex",x:520,y:120,label:"10.0.4.12",sublabel:"Terminated!",tone:"coral",badge:"dead IP",badgeTone:"rose",dim:!0},{id:"new",type:"hex",x:520,y:310,label:"10.0.9.88",sublabel:"New Healthy Pod",tone:"green",badge:"unreached",badgeTone:"amber"}],edges:[{from:"ord",to:"old",label:"ECONNREFUSED",packetColor:"coral",dashed:!0,speed:2.2}],legend:[{label:"stale hardcoded IP failure",tone:"coral"}]}},{shortLabel:"Registry & Mesh",stage:"SOLUTION",title:"Dynamic Registry + Envoy Sidecars standardize resilience across languages",body:["In Kubernetes and autoscaled clouds, pod IPs change every minute. Every healthy pod registers in a **Service Registry** (CoreDNS/etcd, Consul) with a heartbeat TTL.","A **Service Mesh** (Istio/Linkerd + **Envoy Sidecars**) intercepts all pod-to-pod traffic transparently — giving Go, Python, Java, and C# services uniform **mTLS encryption, retries, circuit breaking, canary splits, and OpenTelemetry tracing** with zero app code!"],callout:{type:"KEY IDEA",text:"Control Plane (Istiod) pushes routing & certs; Data Plane (Envoy sidecar next to each container) handles every packet at sub-millisecond overhead."},changes:["+Control Plane pushes live healthy endpoints via xDS in milliseconds","+Envoy Sidecars enforce mTLS + automatic retries across all languages"],scene:{hud:[{label:"DATA PLANE",value:"Envoy Sidecars",status:"good"},{label:"CONTROL PLANE",value:"Registry / Istio",status:"info"},{label:"SECURITY",value:"Zero-Trust mTLS",status:"good"},{label:"HOP COST",value:"~0.5 ms",status:"good"}],nodes:[{id:"cp",type:"hex",x:380,y:80,label:"Control Plane",sublabel:"Certs + Endpoints",tone:"purple"},{id:"a",type:"hex",x:165,y:265,label:"Order Pod",sublabel:"+ Envoy Sidecar",tone:"blue",badge:"mTLS",badgeTone:"green"},{id:"b",type:"hex",x:595,y:265,label:"Billing Pod",sublabel:"+ Envoy Sidecar",tone:"green",badge:"mTLS",badgeTone:"green"}],edges:[{from:"cp",to:"a",label:"xDS routes",packetColor:"purple",dashed:!0,speed:2.5},{from:"cp",to:"b",label:"xDS routes",packetColor:"purple",dashed:!0,speed:2.5},{from:"a",to:"b",label:"encrypted mTLS + retries",packetColor:"green",bidirectional:!0,speed:1.6}],legend:[{label:"sidecar mTLS data plane",tone:"green"},{label:"xDS config push",tone:"purple"}]}}]},{id:"sagas",title:"Sagas, 2PC & Transactional Outbox",subtitle:"Distributed transactions across microservices without blocking locks: 2PC pitfalls, Saga compensations, and Outbox + CDC.",duration:"11 min",level:"Advanced",companies:["Amazon","Uber","Microsoft","Stripe"],tags:["saga","2pc","two phase commit","outbox pattern","cdc","debezium","compensating transaction"],objectives:["Explain why Two-Phase Commit (2PC) blocks under coordinator failure","Design Choreography vs Orchestration Sagas with Compensating Transactions","Solve the Dual-Write bug atomically with the Transactional Outbox + Debezium CDC"],steps:[{shortLabel:"2PC vs Saga",stage:"SOLUTION",title:"Sagas replace blocking 2PC locks with local ACID steps + compensations",body:["**Two-Phase Commit (2PC)** holds row locks across Order, Payment, and Inventory DBs until a coordinator finishes Prepare + Commit. If the coordinator crashes mid-phase, all participants stay locked indefinitely!","The **Saga Pattern** executes a sequence of local ACID transactions (`ReserveSeat → ChargeCard → IssueTicket`). If `ChargeCard` fails, the **Saga Orchestrator** triggers a **Compensating Transaction** (`ReleaseSeat`) to semantically undo prior steps!"],callout:{type:"KEY IDEA",text:"Use **Choreography** (services react to Kafka events) for 2–3 simple steps; use **Orchestration** (Temporal / Step Functions state machine) for complex 4+ step business workflows like flight+hotel+payment booking!"},scene:{hud:[{label:"PATTERN",value:"Saga Orchestrator",status:"good"},{label:"LOCK HOLDING",value:"Zero Cross-DB Locks",status:"good"},{label:"ON FAILURE",value:"Compensate Undo",status:"warn"},{label:"ENGINE",value:"Temporal / Durable",status:"info"}],nodes:[{id:"orch",type:"hex",x:380,y:95,label:"Saga Orchestrator",sublabel:"Temporal State",tone:"purple",badge:"durable workflow",badgeTone:"purple"},{id:"inv",type:"hex",x:145,y:290,label:"1. Inventory",sublabel:"Reserve / Undo",tone:"green"},{id:"pay",type:"hex",x:380,y:290,label:"2. Payment",sublabel:"Declined!",tone:"coral",badge:"failed → rollback",badgeTone:"rose"},{id:"ship",type:"hex",x:615,y:290,label:"3. Shipping",sublabel:"Skipped",tone:"slate",dim:!0}],edges:[{from:"orch",to:"inv",label:"compensate: release!",packetColor:"amber",dashed:!0,speed:2},{from:"orch",to:"pay",label:"charge → fail",packetColor:"coral",bidirectional:!0,speed:1.8},{from:"orch",to:"ship",label:"not called",packetColor:"slate",dashed:!0,dim:!0,speed:3}],legend:[{label:"failed step",tone:"coral"},{label:"compensating rollback",tone:"amber"}]}},{shortLabel:"Outbox + CDC",stage:"TECHNIQUE",title:"Transactional Outbox + Debezium CDC fixes the Dual-Write Bug",body:['Classic distributed bug: `db.save(order)` succeeds, then the container crashes right before `kafka.publish("OrderCreated")`! Now DB and Kafka are permanently out of sync.',"**Fix — Transactional Outbox**: Insert the `order` row AND an `outbox_events` row in the **SAME local SQL ACID transaction**. **Debezium CDC** tails PostgreSQL’s WAL log and reliably publishes every outbox row to Kafka with zero lost events!"],callout:{type:"INTERVIEW SIGNAL",text:"Naming the **Dual-Write Problem** and solving it with **Transactional Outbox + CDC (Debezium)** is one of the highest-signal Staff architecture answers in big tech interviews."},scene:{hud:[{label:"DUAL-WRITE BUG",value:"Eliminated ✓",status:"good"},{label:"LOCAL TX",value:"orders + outbox",status:"good"},{label:"RELAY",value:"Debezium WAL CDC",status:"info"},{label:"EVENT LOSS",value:"Zero",status:"good"}],nodes:[{id:"svc",type:"hex",x:115,y:215,label:"Order Svc",sublabel:"1 ACID TX",tone:"blue"},{id:"pg",type:"db",x:335,y:215,label:"Postgres",sublabel:"orders + outbox",tone:"purple",badge:"atomic commit",badgeTone:"green"},{id:"cdc",type:"hex",x:525,y:215,label:"Debezium CDC",sublabel:"Tails WAL Log",tone:"green"},{id:"kf",type:"queue",x:690,y:215,label:"Kafka",sublabel:"At-Least-Once",tone:"amber"}],edges:[{from:"svc",to:"pg",label:"BEGIN..COMMIT",packetColor:"purple",speed:1.7},{from:"pg",to:"cdc",label:"WAL stream",packetColor:"green",speed:1.7},{from:"cdc",to:"kf",label:"publish event",packetColor:"amber",speed:1.7}],legend:[{label:"atomic DB → WAL → Kafka",tone:"green"}]}}]},{id:"batch-stream",title:"Batch & Stream Processing",subtitle:"Lambda vs Kappa architectures, Apache Flink Event Time & Watermarks, Spark, and Iceberg/Lakehouse.",duration:"9 min",level:"Intermediate",companies:["Uber","Netflix","Google","Microsoft"],tags:["flink","spark","kafka streams","lambda","kappa","watermarks","iceberg","clickhouse"],objectives:["Contrast Batch (Spark/MapReduce) vs Real-Time Stream Processing (Flink)","Handle late-arriving mobile events with Event Time + Watermarks","Simplify dual Lambda codebases into unified Kappa streaming pipelines"],steps:[{shortLabel:"Flink & Kappa",stage:"SOLUTION",title:"Kappa Architecture + Flink Watermarks process millions of events/sec",body:["**Batch Processing** (Spark) runs hourly/daily over Parquet/Iceberg lakehouses for exact billing & ML training. **Stream Processing** (Apache Flink) computes sub-second sliding windows (Uber surge pricing, fraud alerts, trending hashtags) continuously off Kafka.","Mobile phones go offline in tunnels and deliver events 2 minutes late! Flink tracks **Event Time** (timestamp on phone) plus a **Watermark** tolerance window so late data lands in the exact historical bucket rather than skewing the current minute."],callout:{type:"GOOD TO KNOW",text:"**Lambda** runs two codebases (Batch + Speed) and merges outputs; **Kappa** treats everything as a single Kafka replayable stream into Flink, avoiding duplicated business logic."},scene:{hud:[{label:"STREAM ENGINE",value:"Apache Flink",status:"good"},{label:"WINDOW TIME",value:"Event + Watermark",status:"good"},{label:"OLAP SINK",value:"ClickHouse / Pinot",status:"info"},{label:"LAKEHOUSE",value:"S3 + Iceberg",status:"info"}],nodes:[{id:"kf",type:"queue",x:120,y:215,label:"Kafka Log",sublabel:"Click / Ride Events",tone:"amber"},{id:"fl",type:"hex",x:375,y:130,label:"Apache Flink",sublabel:"1-min Sliding Win",tone:"green",badge:"sub-sec",badgeTone:"green"},{id:"sp",type:"hex",x:375,y:310,label:"Apache Spark",sublabel:"Nightly ML / ETL",tone:"blue"},{id:"olap",type:"db",x:640,y:130,label:"ClickHouse",sublabel:"Live Dashboards",tone:"purple"},{id:"lake",type:"db",x:640,y:310,label:"Iceberg Lake",sublabel:"Parquet on S3",tone:"slate"}],edges:[{from:"kf",to:"fl",label:"stream",packetColor:"green",speed:1.5},{from:"kf",to:"sp",label:"archive",packetColor:"blue",dashed:!0,speed:2.5},{from:"fl",to:"olap",label:"real-time agg",packetColor:"purple",speed:1.6},{from:"sp",to:"lake",label:"batch tables",packetColor:"blue",speed:2.3}],legend:[{label:"real-time Flink stream",tone:"green"},{label:"batch lakehouse ETL",tone:"blue"}]}},{shortLabel:"Checkpoints",stage:"TECHNIQUE",title:"Exactly-Once State Checkpointing survives worker crashes cleanly",body:["If a Flink worker crashes halfway through computing a 1-hour revenue counter, naively restarting loses the in-memory sum or double-counts events!","Flink injects **Chandy-Lamport Checkpoint Barriers** periodically into the Kafka stream and snapshots operator state (RocksDB) to S3 — recovering seamlessly with **Exactly-Once** accuracy!"],callout:{type:"INTERVIEW SIGNAL",text:'Mentioning **Event Time + Watermarks + RocksDB Checkpointing** for stream analytics separates Staff engineers from generic "just use Spark" answers.'},scene:{hud:[{label:"STATE STORE",value:"Local RocksDB",status:"good"},{label:"RECOVERY",value:"S3 Checkpoints",status:"good"},{label:"SEMANTICS",value:"Exactly-Once",status:"good"},{label:"LATE DATA",value:"Side Output Tag",status:"info"}],nodes:[{id:"kf",type:"queue",x:140,y:215,label:"Kafka Offset",sublabel:"Barrier #42",tone:"amber"},{id:"op",type:"hex",x:400,y:215,label:"Flink Operator",sublabel:"RocksDB State",tone:"green",badge:"checkpointed",badgeTone:"green"},{id:"s3",type:"db",x:645,y:215,label:"S3 Snapshot",sublabel:"Durable State",tone:"purple"}],edges:[{from:"kf",to:"op",label:"events + barrier",packetColor:"amber",speed:1.7},{from:"op",to:"s3",label:"async snapshot",packetColor:"purple",dashed:!0,speed:2.2}],legend:[{label:"checkpointed stream state",tone:"purple"}]}}]}]},s={id:"mod-07-security",number:"07",title:"Security & Enterprise",track:"hld",lessons:[{id:"authentication",title:"Authentication (JWT, OAuth 2.0, OIDC)",subtitle:"Stateful Session Cookies vs Stateless JWTs, Refresh Token Rotation, OAuth 2.0 + PKCE, and Enterprise SSO.",duration:"10 min",level:"Intermediate",companies:["Microsoft","Google","Okta","Amazon"],tags:["jwt","oauth2","pkce","oidc","sso","session cookie","refresh token","entra id"],objectives:["Compare Session Cookies vs JWTs (including the JWT instant-revocation trap!)","Trace OAuth 2.0 Authorization Code + PKCE and OpenID Connect (OIDC)","Mitigate XSS/CSRF using HttpOnly, Secure, SameSite cookies and short-lived Access Tokens"],steps:[{shortLabel:"OAuth2 + PKCE",stage:"SOLUTION",title:"Short-lived Access JWT (15m) + Rotating Refresh Token",body:["A **JWT** (`Header.Payload.Signature`) is cryptographically signed (RS256/ES256) so any microservice verifies identity locally with zero DB hits. **Trap**: You cannot easily revoke a stolen stateless JWT before it expires!","**Production Gold Standard**: Issue a **15-minute Access JWT** + a stateful **Refresh Token** stored in an `HttpOnly, Secure, SameSite=Lax` cookie with **Refresh Token Rotation** (if a stolen refresh token is reused, revoke the entire token family immediately!)."],callout:{type:"WATCH OUT",text:"Never store sensitive secrets in a JWT payload — it is Base64-encoded, NOT encrypted! And never put long-lived JWTs in `localStorage` where XSS scripts can exfiltrate them."},scene:{hud:[{label:"ACCESS JWT",value:"15 min (RS256)",status:"good"},{label:"REFRESH TOKEN",value:"HttpOnly + Rotate",status:"good"},{label:"FLOW",value:"Auth Code + PKCE",status:"good"},{label:"IDENTITY",value:"OIDC / Entra ID",status:"info"}],nodes:[{id:"c",type:"users",x:105,y:215,label:"Client App",sublabel:"PKCE Verifier",tone:"slate"},{id:"idp",type:"hex",x:365,y:115,label:"IdP (OIDC)",sublabel:"Entra / Auth0",tone:"purple",badge:"signs RS256",badgeTone:"purple"},{id:"gw",type:"hex",x:365,y:310,label:"API Gateway",sublabel:"Verifies JWKS",tone:"green",badge:"local 0.1ms",badgeTone:"green"},{id:"api",type:"hex",x:635,y:310,label:"Backend Svc",sublabel:"Trusted Claims",tone:"blue"}],edges:[{from:"c",to:"idp",label:"1. login + PKCE → JWT",packetColor:"purple",bidirectional:!0,speed:1.9},{from:"c",to:"gw",label:"2. Bearer Access JWT",packetColor:"green",speed:1.6},{from:"idp",to:"gw",label:"public JWKS keys",packetColor:"amber",dashed:!0,speed:2.8},{from:"gw",to:"api",label:"x-user-id",packetColor:"blue",speed:1.6}],legend:[{label:"OIDC token issuance",tone:"purple"},{label:"verified API request",tone:"green"}]}},{shortLabel:"Revocation",stage:"TECHNIQUE",title:"Refresh Token Rotation & Emergency Session Revocation",body:["When an employee leaves or a laptop is stolen, waiting 15 minutes for a JWT to expire may be too long for high-security admin routes.","Maintain a tiny Redis **Revocation Blocklist** (keyed by `jti` with 15-minute TTL) for emergency logouts, AND rotate the Refresh Token on every refresh so reuse of a stolen token immediately revokes the entire session family!"],callout:{type:"INTERVIEW SIGNAL",text:"Distinguishing **Session Cookies** (instant revoke, stateful Redis lookup) vs **Short Access JWT + Rotating Refresh Cookie** (stateless edge verify + safe revoke) nails every Big Tech security follow-up."},scene:{hud:[{label:"STOLEN REFRESH",value:"Reuse Detected!",status:"bad"},{label:"RESPONSE",value:"Revoke Family ✓",status:"good"},{label:"JTI BLOCKLIST",value:"Redis 15m TTL",status:"info"},{label:"XSS GUARD",value:"HttpOnly Cookie",status:"good"}],nodes:[{id:"atk",type:"users",x:120,y:215,label:"Stolen Token",sublabel:"Replayed rt_v1",tone:"coral"},{id:"auth",type:"hex",x:380,y:215,label:"Auth Server",sublabel:"Detects Reuse!",tone:"amber",badge:"family revoked",badgeTone:"rose"},{id:"rd",type:"cache",x:635,y:215,label:"Revocation Set",sublabel:"Blocks all tokens",tone:"green"}],edges:[{from:"atk",to:"auth",label:"old rt_v1",packetColor:"coral",speed:1.8},{from:"auth",to:"rd",label:"revoke family_id",packetColor:"green",speed:1.6}],legend:[{label:"refresh-reuse defense",tone:"green"}]}}]},{id:"authorization",title:"Authorization (RBAC, ABAC, Zanzibar)",subtitle:"Role-Based (RBAC), Attribute-Based (ABAC), and Relationship-Based (Google Zanzibar / ReBAC) permissions.",duration:"9 min",level:"Intermediate",companies:["Google","Microsoft","GitHub","Notion"],tags:["rbac","abac","rebac","zanzibar","spicedb","acl","iam"],objectives:["Differentiate AuthN (who you are) from AuthZ (what you can do)","Scale from RBAC/ABAC to Google Zanzibar ReBAC for nested Docs/Drive sharing","Avoid stale permission bugs with Zanzibar Zookies (consistency tokens)"],steps:[{shortLabel:"RBAC → Zanzibar",stage:"TECHNIQUE",title:"How Google Drive & Microsoft 365 evaluate billions of permissions in < 10 ms",body:['**RBAC** assigns static roles (`Admin`, `Editor`). **ABAC** adds policy rules (`if user.dept == doc.dept && time < 6pm`). Neither models nested sharing graphs cleanly ("Alice is in Engineering → Engineering can edit Folder Q4 → Doc X is inside Folder Q4").','**Google Zanzibar (ReBAC)** stores relation tuples (`doc:X#parent@folder:Q4`, `folder:Q4#editor@group:eng#member`) and traverses the graph with distributed caching + **Zookies** to prevent the "New Enemy" stale-revocation vulnerability!'],callout:{type:"INTERVIEW SIGNAL",text:"When designing Google Drive, OneDrive, Notion, or GitHub at Microsoft/Google, proposing a dedicated **Zanzibar-style ReBAC tuple graph** immediately elevates your design to Staff level."},scene:{hud:[{label:"SIMPLE APPS",value:"RBAC / ABAC",status:"info"},{label:"DOCS / DRIVE",value:"Zanzibar ReBAC",status:"good"},{label:"CHECK P99",value:"< 10 ms",status:"good"},{label:"STALE GUARD",value:"Zookie Token",status:"good"}],nodes:[{id:"u",type:"users",x:110,y:215,label:"Alice",sublabel:"Can edit Doc X?",tone:"slate"},{id:"z",type:"hex",x:350,y:215,label:"AuthZ Engine",sublabel:"Zanzibar / SpiceDB",tone:"purple",badge:"Check(Alice, edit, X)",badgeTone:"purple"},{id:"g",type:"db",x:625,y:125,label:"Tuple Graph",sublabel:"Alice→Eng→Dir→Doc",tone:"green",badge:"ALLOW ✓",badgeTone:"green"},{id:"c",type:"cache",x:625,y:305,label:"Leopard Cache",sublabel:"Flattened Groups",tone:"blue"}],edges:[{from:"u",to:"z",label:"check()",packetColor:"purple",bidirectional:!0,speed:1.7},{from:"z",to:"g",label:"graph walk",packetColor:"green",speed:1.7},{from:"z",to:"c",label:"cached membership",packetColor:"blue",bidirectional:!0,speed:1.5}],legend:[{label:"ReBAC graph authorization",tone:"green"}]}},{shortLabel:"Zookie Guard",stage:"PROBLEM",title:'Preventing the "New Enemy" Stale-Permission Vulnerability',body:["Suppose Alice removes Bob from `Doc X` at `t=10`, then writes secret salary data into `Doc X` at `t=11`. If Bob reads from a lagging AuthZ replica still at `t=9`, he reads the brand-new secret even though he was ALREADY removed!","Google Zanzibar solves this with a **Zookie** (an opaque timestamp consistency token saved on the Doc): AuthZ refuses to evaluate any check using a snapshot older than the Doc’s Zookie!"],callout:{type:"KEY IDEA",text:"Security > Speed when permissions shrink: a Zookie guarantees causal consistency between a document edit and its latest ACL revocation."},scene:{hud:[{label:"DOC ZOOKIE",value:"t ≥ 11 Required",status:"info"},{label:"STALE REPLICA",value:"t = 9 Bypassed",status:"warn"},{label:"BOB CHECK",value:"DENY (403) ✓",status:"good"},{label:"NEW ENEMY BUG",value:"Prevented ✓",status:"good"}],nodes:[{id:"bob",type:"users",x:115,y:215,label:"Bob (Revoked)",sublabel:"Reads Doc @ t=11",tone:"coral"},{id:"chk",type:"hex",x:380,y:215,label:"Zanzibar Check",sublabel:"Min TS = Zookie(11)",tone:"purple",badge:"causal fence",badgeTone:"purple"},{id:"fresh",type:"db",x:640,y:215,label:"Fresh Snapshot",sublabel:"t = 11 → DENY",tone:"green",badge:"403 Blocked ✓",badgeTone:"green"}],edges:[{from:"bob",to:"chk",label:"GET Doc X",packetColor:"coral",speed:1.8},{from:"chk",to:"fresh",label:"eval @ t≥11",packetColor:"green",bidirectional:!0,speed:1.7}],legend:[{label:"zookie-fenced permission check",tone:"green"}]}}]},{id:"encryption",title:"Encryption, KMS & Multi-Tenancy",subtitle:"TLS + Envelope Encryption (DEK/KEK), Secret Rotation, and Microsoft Azure Multi-Tenant Isolation Tiers.",duration:"10 min",level:"Intermediate",companies:["Microsoft","Amazon","Google","Salesforce"],tags:["kms","envelope encryption","multi-tenancy","silo","pool","gdpr","azure key vault","zero trust"],objectives:["Use Envelope Encryption (fast local DEK encrypted by KMS KEK) for at-rest security","Design Multi-Tenant SaaS isolation: Pool (shared DB + RLS) vs Bridge vs Silo (dedicated DB)","Satisfy Enterprise GDPR/HIPAA compliance, data residency, and Customer-Managed Keys (CMK)"],steps:[{shortLabel:"Envelope KMS",stage:"TECHNIQUE",title:"Envelope Encryption: Encrypt data locally with DEK, wrap DEK with KMS KEK",body:["You cannot send 10 GB files across the network to AWS KMS / Azure Key Vault to encrypt them. Instead, generate a local symmetric **AES-256 Data Encryption Key (DEK)** to encrypt the payload locally in microseconds, then ask KMS to encrypt ONLY the 32-byte DEK using the master **Key Encryption Key (KEK)**.","Store `(ciphertext + encrypted_DEK)` together! Enterprise customers can even supply a **Customer-Managed Key (CMK / BYOK)** to cryptographically shred all their data instantaneously."],callout:{type:"INTERVIEW SIGNAL",text:"Microsoft L62/L63 interviewers LOVE enterprise cloud constraints: **Multi-Tenancy Isolation (Pool vs Silo)**, **Data Residency (EU data stays in EU)**, **Row-Level Security**, and **KMS Envelope Encryption**."},scene:{hud:[{label:"IN TRANSIT",value:"TLS 1.3 + mTLS",status:"good"},{label:"AT REST",value:"AES-256 Envelope",status:"good"},{label:"SMB TENANTS",value:"Pool + RLS",status:"info"},{label:"BANKS / GOV",value:"Silo + CMK",status:"good"}],nodes:[{id:"kms",type:"hex",x:380,y:80,label:"KMS / Key Vault",sublabel:"HSM Master KEK",tone:"purple",badge:"never leaves HSM",badgeTone:"purple"},{id:"pool",type:"db",x:185,y:270,label:"Pool Tier (SMB)",sublabel:"Shared DB + RLS",tone:"blue",badge:"cost optimal",badgeTone:"blue"},{id:"silo",type:"db",x:575,y:270,label:"Silo Tier (Bank)",sublabel:"Dedicated DB + CMK",tone:"green",badge:"strict compliance",badgeTone:"green"}],edges:[{from:"kms",to:"pool",label:"wrap DEK",packetColor:"purple",dashed:!0,speed:2.2},{from:"kms",to:"silo",label:"customer BYOK",packetColor:"green",bidirectional:!0,speed:1.9}],legend:[{label:"HSM-backed envelope key wrap",tone:"purple"},{label:"enterprise BYOK silo",tone:"green"}]}},{shortLabel:"Zero Trust",stage:"SOLUTION",title:"Zero Trust + Automated Secret Rotation + Data Residency",body:["Never trust a request merely because it came from inside your VPC! **Zero Trust** authenticates every service-to-service hop with short-lived **mTLS workload identities (SPIFFE/Managed Identity)** and rotates DB credentials automatically without restarts.","For global SaaS (Microsoft 365 / Azure), pin EU tenants’ storage, backups, and search indexes strictly inside **EU regions (Data Residency)** to satisfy GDPR compliance."],callout:{type:"KEY IDEA",text:"No static long-lived API keys in `.env` files! Use **Cloud Workload Identity (OIDC / Azure Managed Identity)** to mint ephemeral 1-hour credentials on demand."},scene:{hud:[{label:"NETWORK MODEL",value:"Zero Trust mTLS",status:"good"},{label:"SECRETS",value:"Auto-Rotated",status:"good"},{label:"EU TENANTS",value:"Pinned EU-West",status:"good"},{label:"COMPLIANCE",value:"GDPR · SOC2 · HIPAA",status:"info"}],nodes:[{id:"id",type:"hex",x:145,y:215,label:"Managed Identity",sublabel:"1-hr Short Token",tone:"green"},{id:"eu",type:"db",x:425,y:125,label:"EU Tenant Pod",sublabel:"GDPR Pinned",tone:"blue"},{id:"us",type:"db",x:425,y:305,label:"US Tenant Pod",sublabel:"HIPAA Pinned",tone:"purple"},{id:"aud",type:"queue",x:660,y:215,label:"Immutable Audit",sublabel:"WORM Log",tone:"amber"}],edges:[{from:"id",to:"eu",label:"mTLS auth",packetColor:"blue",speed:1.7},{from:"id",to:"us",label:"mTLS auth",packetColor:"purple",speed:1.7},{from:"eu",to:"aud",label:"access trail",packetColor:"amber",dashed:!0,speed:2.3},{from:"us",to:"aud",label:"access trail",packetColor:"amber",dashed:!0,speed:2.3}],legend:[{label:"zero-trust audited isolation",tone:"green"}]}}]}]},r={id:"mod-08-shipping",number:"08",title:"Shipping & DevOps",track:"hld",lessons:[{id:"testing",title:"Testing, Load & Chaos Engineering",subtitle:"Testing pyramid, consumer-driven contracts, shadow traffic, soak/load testing, and Netflix Chaos Monkey.",duration:"7 min",level:"Beginner",companies:["Netflix","Amazon","Microsoft","Google"],tags:["chaos engineering","load testing","contract testing","shadow traffic","game day"],objectives:["Validate production readiness with Load, Spike, and Soak testing (memory leaks)","Test new services safely using Shadow Traffic mirroring","Verify failover actually works via Chaos Engineering & Game Days"],steps:[{shortLabel:"Shadow & Chaos",stage:"TECHNIQUE",title:"If you never test failover in production, failover is broken",body:["Unit and integration tests catch logic bugs, NOT p99 connection-pool exhaustion or broken AZ failover. **Shadow Traffic** asynchronously mirrors real production reads to a new v2 service and compares diffs with zero user risk.","**Chaos Engineering** (Netflix Chaos Monkey / Azure Chaos Studio) intentionally kills pods, injects 300 ms latency, or blacks out an Availability Zone during business hours to prove automated recovery works!"],callout:{type:"KEY IDEA",text:"Run **Soak Tests** (sustained 12-hour traffic) to uncover slow memory leaks and file-descriptor exhaustion that 5-minute load bursts completely miss."},scene:{hud:[{label:"SHADOW MODE",value:"0 User Impact",status:"good"},{label:"CHAOS FAULT",value:"AZ-b Killed",status:"warn"},{label:"AUTO-HEAL",value:"99.99% Held ✓",status:"good"},{label:"SOAK TEST",value:"No Mem Leak",status:"good"}],nodes:[{id:"lb",type:"hex",x:135,y:215,label:"Edge Proxy",sublabel:"Traffic Mirror",tone:"blue"},{id:"v1",type:"hex",x:430,y:120,label:"Prod v1",sublabel:"Serves Users",tone:"green",badge:"live",badgeTone:"green"},{id:"v2",type:"hex",x:430,y:310,label:"Shadow v2",sublabel:"Async Mirror",tone:"purple",badge:"diff checker",badgeTone:"purple"},{id:"ch",type:"hex",x:660,y:215,label:"Chaos Monkey",sublabel:"Fault Injection",tone:"amber"}],edges:[{from:"lb",to:"v1",label:"100% live",packetColor:"green",bidirectional:!0,speed:1.6},{from:"lb",to:"v2",label:"mirrored copy",packetColor:"purple",dashed:!0,speed:2},{from:"ch",to:"v1",label:"kill 1 pod",packetColor:"amber",dashed:!0,speed:2.5}],legend:[{label:"live production",tone:"green"},{label:"shadow diff test",tone:"purple"}]}},{shortLabel:"Testing Pyramid",stage:"SETUP",title:"Unit → Contract → Load/Soak → Production Game Days",body:["1. **Unit & Component Tests** run in milliseconds on every PR. 2. **Consumer-Driven Contract Tests (Pact)** ensure Service B never breaks Service A’s schema.","3. **Load + Spike + 12h Soak Tests** prove throughput, GC health, and zero connection leaks before peak events like Prime Day!"],callout:{type:"GOOD TO KNOW",text:"Amazon runs mandatory **Game Days** every quarter — intentionally pulling plugs on production regions so on-call engineers practice failover calmly."},scene:{hud:[{label:"PR GATE",value:"Unit + Contract",status:"good"},{label:"PRE-LAUNCH",value:"Load + Soak",status:"info"},{label:"IN PROD",value:"Chaos Game Day",status:"good"},{label:"CONFIDENCE",value:"Proven Failover",status:"good"}],nodes:[{id:"u",type:"hex",x:140,y:215,label:"Unit & Pact",sublabel:"Every PR (< 2m)",tone:"green"},{id:"l",type:"hex",x:390,y:215,label:"Load & Soak",sublabel:"3× Peak · 12 hrs",tone:"blue"},{id:"g",type:"hex",x:640,y:215,label:"Game Day",sublabel:"Live AZ Failover",tone:"purple"}],edges:[{from:"u",to:"l",label:"promote",packetColor:"blue",speed:1.9},{from:"l",to:"g",label:"prove HA",packetColor:"purple",speed:1.9}],legend:[{label:"reliability verification ladder",tone:"purple"}]}}]},{id:"cicd",title:"CI/CD, Containers & Deployments",subtitle:"Docker & Kubernetes internals, immutable pipelines, Blue-Green, Canary rollouts, and Feature Flags.",duration:"9 min",level:"Beginner",companies:["Netflix","Microsoft","Google","Amazon"],tags:["cicd","docker","kubernetes","canary","blue-green","feature flags","rollback"],objectives:["Explain Docker isolation (namespaces, cgroups, OverlayFS) and Kubernetes Control Plane","Compare Rolling, Blue-Green, and automated Canary deployments with metric rollback","Decouple code deployment from feature launch using Feature Flags"],steps:[{shortLabel:"Canary CI/CD",stage:"SOLUTION",title:"Automated Canary Deployments catch regressions at 1% traffic",body:["Modern CI/CD builds an immutable container image once (`Git → Test → Security Scan → Registry`), then deploys progressively: **Canary** shifts **1% → 5% → 25% → 100%** of traffic while automatically comparing error rates & p99 against the baseline.","If error rate rises by even 0.2%, the controller rolls back in **< 10 seconds**. Pair with **Expand-and-Contract DB migrations** (never drop a column while old pods still read it!)."],callout:{type:"INTERVIEW SIGNAL",text:"Always mention **Backward-Compatible Schema Migrations (Expand & Contract)** during zero-downtime deployments — dropping or renaming a column in one deploy breaks live v1 pods!"},scene:{hud:[{label:"STRATEGY",value:"Canary 1%→100%",status:"good"},{label:"ROLLBACK",value:"Auto < 10s",status:"good"},{label:"ORCHESTRATOR",value:"Kubernetes HPA",status:"info"},{label:"DB SCHEMA",value:"Expand & Contract",status:"good"}],nodes:[{id:"ci",type:"hex",x:110,y:215,label:"CI Pipeline",sublabel:"Build · Scan · Sign",tone:"purple"},{id:"ing",type:"hex",x:345,y:215,label:"K8s Ingress",sublabel:"95% v1 · 5% v2",tone:"blue"},{id:"v1",type:"hex",x:625,y:125,label:"Stable v1",sublabel:"95% Traffic",tone:"green",load:42},{id:"v2",type:"hex",x:625,y:305,label:"Canary v2",sublabel:"5% · Auto-Judge",tone:"amber",badge:"metrics OK ✓",badgeTone:"green",load:18}],edges:[{from:"ci",to:"ing",label:"immutable image",packetColor:"purple",speed:2},{from:"ing",to:"v1",label:"95%",packetColor:"green",speed:1.6},{from:"ing",to:"v2",label:"5% canary",packetColor:"amber",speed:2}],legend:[{label:"stable fleet",tone:"green"},{label:"canary slice",tone:"amber"}]}},{shortLabel:"Feature Flags",stage:"TECHNIQUE",title:"Decouple Deploy from Release with Feature Flags + Expand-Contract DB",body:["**Deployment** puts dark code into production safely; **Release** flips a **Feature Flag** for 1% of staff → 10% of beta users → 100% globally (instant 100 ms kill-switch without redeploying!).","For DB changes, use **Expand & Contract**: 1) Add new column nullable, 2) Dual-write old + new + backfill, 3) Switch reads to new, 4) Drop old column in a later deploy!"],callout:{type:"WATCH OUT",text:"Running `ALTER TABLE ADD COLUMN ... DEFAULT ... NOT NULL` on a 500M-row legacy MySQL table can lock writes for 20 minutes! Always verify online/non-blocking schema migrations."},scene:{hud:[{label:"KILL SWITCH",value:"< 100 ms Flag Off",status:"good"},{label:"DB MIGRATION",value:"Expand & Contract",status:"good"},{label:"ZERO DOWNTIME",value:"Backward Compat",status:"good"},{label:"ROLLBACK",value:"Safe Anytime",status:"good"}],nodes:[{id:"fl",type:"hex",x:145,y:215,label:"Feature Flag",sublabel:"1% → 100% Rollout",tone:"purple"},{id:"app",type:"hex",x:400,y:215,label:"Dual-Write App",sublabel:"v1 + v2 Safe",tone:"green"},{id:"db",type:"db",x:645,y:215,label:"Zero-Lock DB",sublabel:"old_col + new_col",tone:"blue"}],edges:[{from:"fl",to:"app",label:"instant toggle",packetColor:"purple",speed:1.6},{from:"app",to:"db",label:"dual-write",packetColor:"green",speed:1.7}],legend:[{label:"zero-downtime progressive rollout",tone:"green"}]}}]}]},i={id:"mod-09-fintech-ai-realworld",number:"09",title:"Fintech, AI & Real-World",track:"hld",lessons:[{id:"payments-ledger",title:"Payment Systems, UPI & Double-Entry Ledger",subtitle:"ByteByteGo Fintech deep dive: PSPs, Card Networks, Immutable Double-Entry Ledgers, Idempotency & Reconciliation.",duration:"12 min",level:"Advanced",companies:["Stripe","Amazon","Uber","Microsoft"],tags:["payments","stripe","upi","double-entry ledger","reconciliation","idempotency","psp","fintech"],objectives:["Trace Pay-in / Pay-out flows across Merchant, PSP (Stripe/Adyen), Card Network, and Banks","Design an append-only Double-Entry Accounting Ledger (sum of debits + credits == 0)","Guarantee zero double-charges and catch silent bank drift via T+1 Reconciliation"],steps:[{shortLabel:"Payment Flow",stage:"SETUP",title:"Never mutate a balance column — use an immutable Double-Entry Ledger",body:["When Alice pays $50 to Merchant M, **NEVER** run `UPDATE accounts SET balance = balance - 50` without an audit log! Every financial movement appends **two balanced immutable rows**: `DEBIT Alice -$50` and `CREDIT Merchant +$50` (**Double-Entry Bookkeeping** — the sum across all rows MUST always equal `0.00`).","Use a strict **Payment State Machine** (`CREATED → AUTHORIZED → CAPTURED → SETTLED / FAILED`), client **Idempotency Keys**, and async **PSP Webhooks** because card authorization takes 1–3 seconds."],callout:{type:"WATCH OUT",text:'Store money as **integer minor units** (`5000` cents in `BIGINT` + `currency = "USD"`), NEVER IEEE-754 `float`/`double` (`0.1 + 0.2 = 0.30000000000000004`)!'},scene:{hud:[{label:"LEDGER RULE",value:"∑(DR + CR) = 0",status:"good"},{label:"MONEY TYPE",value:"BIGINT Cents",status:"good"},{label:"EXACTLY-ONCE",value:"Idempotency Key",status:"good"},{label:"SAFETY NET",value:"T+1 Reconcile",status:"info"}],nodes:[{id:"c",type:"users",x:95,y:215,label:"Checkout",sublabel:"Idem-Key UUID",tone:"slate"},{id:"pay",type:"hex",x:280,y:215,label:"Payment Svc",sublabel:"State Machine",tone:"blue",badge:"strict ACID",badgeTone:"green"},{id:"psp",type:"hex",x:495,y:110,label:"PSP / UPI Switch",sublabel:"Stripe · Visa · NPCI",tone:"amber"},{id:"led",type:"db",x:495,y:315,label:"Double-Entry DB",sublabel:"Append-Only Ledger",tone:"purple",badge:"DR + CR = 0",badgeTone:"purple"},{id:"rec",type:"hex",x:675,y:215,label:"Reconciler",sublabel:"Daily Settlement Diff",tone:"green"}],edges:[{from:"c",to:"pay",label:"POST /pay",packetColor:"blue",bidirectional:!0,speed:1.7},{from:"pay",to:"psp",label:"auth + capture",packetColor:"amber",bidirectional:!0,speed:2},{from:"pay",to:"led",label:"DR -$50 / CR +$50",packetColor:"purple",speed:1.6},{from:"psp",to:"rec",label:"settlement file",packetColor:"green",dashed:!0,speed:2.5},{from:"led",to:"rec",label:"internal ledger",packetColor:"green",dashed:!0,speed:2.5}],legend:[{label:"PSP / card clearing",tone:"amber"},{label:"immutable ledger",tone:"purple"},{label:"reconciliation audit",tone:"green"}]}},{shortLabel:"Reconciliation",stage:"TECHNIQUE",title:"Reconciliation catches every silent distributed inconsistency",body:["Even with perfect retries and webhooks, external banks crash, drop webhooks, or settle partial refunds 24 hours later. Every night (or hourly), the **Reconciliation Engine** compares your internal **Double-Entry Ledger** against the PSP’s **Settlement File**.","Any mismatch (`internal = FAILED` while `bank = CAPTURED`) triggers automated refund/adjustment workflows or alerts Finance Ops!"],callout:{type:"INTERVIEW SIGNAL",text:"Bringing up **Double-Entry Ledger + BIGINT Cents + Idempotency Key + T+1 Reconciliation** covers 100% of what Stripe, Amazon Pay, and Uber Payments interviewers grade for!"},scene:{hud:[{label:"MATCH RATE",value:"99.998%",status:"good"},{label:"MISMATCHES",value:"Auto-Queued",status:"warn"},{label:"PCI SCOPE",value:"Tokenized at PSP",status:"good"},{label:"FRAUD CHECK",value:"Pre-Auth ML",status:"info"}],nodes:[{id:"l",type:"db",x:165,y:135,label:"Internal Ledger",sublabel:"Postgres ACID",tone:"purple"},{id:"b",type:"db",x:165,y:295,label:"PSP Settlement",sublabel:"SFTP / API File",tone:"amber"},{id:"diff",type:"hex",x:440,y:215,label:"Reconcile Engine",sublabel:"3-Way Match",tone:"green",badge:"zero drift",badgeTone:"green"},{id:"ops",type:"hex",x:665,y:215,label:"Auto-Heal / Alert",sublabel:"Refund / Ticket",tone:"blue"}],edges:[{from:"l",to:"diff",label:"tx records",packetColor:"purple",speed:1.9},{from:"b",to:"diff",label:"bank rows",packetColor:"amber",speed:1.9},{from:"diff",to:"ops",label:"0.002% exceptions",packetColor:"coral",dashed:!0,speed:2.5}],legend:[{label:"financial audit loop",tone:"green"}]}}]},{id:"ai-llm-rag",title:"AI / LLM Serving & Production RAG",subtitle:"Hybrid Search (BM25 + HNSW Vector), Reranking, Semantic Caching, KV-Cache, vLLM PagedAttention & SSE streaming.",duration:"12 min",level:"Advanced",companies:["Microsoft","Google","OpenAI","Meta"],tags:["rag","llm","vector database","hnsw","vllm","pagedattention","kv cache","ai gateway","semantic cache"],objectives:["Architect an enterprise Hybrid RAG pipeline (Ingestion → Chunking → BM25+Vector → Reranker)","Understand LLM GPU bottlenecks: Compute-bound Prefill vs Memory-Bandwidth-bound Decode","Scale serving with Continuous Batching, PagedAttention (vLLM), Semantic Caching, and SSE token streaming"],steps:[{shortLabel:"Hybrid RAG",stage:"SOLUTION",title:"Enterprise RAG: Hybrid Search (BM25 + Vector) + Cross-Encoder Reranking",body:["Pure vector cosine search misses exact SKUs, error codes (`ERR_5041`), and acronyms; pure keyword search (BM25) misses synonyms. Production RAG runs **Hybrid Retrieval** (BM25 + Dense HNSW Vector DB merged via **Reciprocal Rank Fusion**), then re-scores top-50 candidates down to top-5 with a fast **Cross-Encoder Reranker**.","Crucial Enterprise Security Rule: Pass the caller’s **ACL / Tenant Permissions** directly into the Vector DB pre-filter so users NEVER retrieve chunks from confidential docs they can’t open!"],callout:{type:"INTERVIEW SIGNAL",text:"Mentioning **Document-level ACL filtering before RAG context injection** + **Semantic Caching** (Redis vector similarity hit > 0.96 skips the GPU entirely!) is a massive differentiator in 2026 Microsoft Copilot & Google AI interviews."},scene:{hud:[{label:"RETRIEVAL",value:"BM25 + HNSW RRF",status:"good"},{label:"RERANK",value:"Top 50 → Top 5",status:"good"},{label:"SECURITY",value:"ACL Pre-Filter",status:"good"},{label:"STREAMING",value:"SSE Tokens",status:"good"}],nodes:[{id:"u",type:"users",x:95,y:215,label:"User Prompt",sublabel:"SSE Stream",tone:"slate"},{id:"gw",type:"hex",x:265,y:215,label:"AI Gateway",sublabel:"PII · Token RL · Cache",tone:"green",badge:"guardrails",badgeTone:"green"},{id:"vec",type:"db",x:470,y:110,label:"Hybrid Index",sublabel:"BM25 + HNSW + ACL",tone:"purple"},{id:"rr",type:"hex",x:470,y:315,label:"Reranker",sublabel:"Cross-Encoder Top-5",tone:"amber"},{id:"gpu",type:"hex",x:665,y:215,label:"vLLM GPU Fleet",sublabel:"PagedAttention",tone:"blue",badge:"KV-Cache",badgeTone:"blue",load:72}],edges:[{from:"u",to:"gw",label:"query / SSE",packetColor:"green",bidirectional:!0,speed:1.6},{from:"gw",to:"vec",label:"top-50 + ACL",packetColor:"purple",bidirectional:!0,speed:1.7},{from:"vec",to:"rr",label:"rerank",packetColor:"amber",speed:1.8},{from:"rr",to:"gpu",label:"grounded prompt",packetColor:"blue",speed:1.6}],legend:[{label:"SSE token stream",tone:"green"},{label:"hybrid retrieval",tone:"purple"}]}},{shortLabel:"vLLM GPU Scale",stage:"TECHNIQUE",title:"Prefill vs Decode, KV-Cache & Continuous Batching (vLLM)",body:["LLM inference has two radically different phases: **Prefill** (processing the entire prompt in parallel — **GPU compute-bound**, sets **TTFT** Time-To-First-Token) and **Decode** (generating 1 token at a time using cached attention states — **GPU VRAM bandwidth-bound**, sets **TPOT**).","**vLLM PagedAttention** stores the **KV-Cache** in non-contiguous OS-style virtual memory pages, cutting VRAM waste by 60%+, while **Continuous Batching** swaps finished requests out mid-batch to boost GPU throughput 10–20×!"],callout:{type:"KEY IDEA",text:"Measure LLM serving with **TTFT** (Time to First Token, < 500 ms), **TPOT** (Time Per Output Token, < 30 ms), and **Token-per-Minute (TPM)** rate limits — not just raw RPS!"},scene:{hud:[{label:"TTFT (PREFILL)",value:"320 ms",status:"good"},{label:"TPOT (DECODE)",value:"18 ms/tok",status:"good"},{label:"VRAM EFFICIENCY",value:"PagedAttention",status:"good"},{label:"BATCHING",value:"Continuous",status:"good"}],nodes:[{id:"sc",type:"cache",x:145,y:215,label:"Semantic Cache",sublabel:"Skip GPU on 0.96+",tone:"green"},{id:"pre",type:"hex",x:390,y:125,label:"Prefill Pool",sublabel:"Compute-Bound",tone:"amber",load:78},{id:"dec",type:"hex",x:390,y:305,label:"Decode Pool",sublabel:"VRAM BW-Bound",tone:"blue",load:68},{id:"kv",type:"db",x:645,y:215,label:"Paged KV-Cache",sublabel:"Prefix Sharing",tone:"purple",badge:"zero fragmentation",badgeTone:"purple"}],edges:[{from:"sc",to:"pre",label:"cache miss",packetColor:"amber",speed:1.7},{from:"pre",to:"kv",label:"write KV pages",packetColor:"purple",speed:1.6},{from:"kv",to:"dec",label:"stream tokens",packetColor:"blue",bidirectional:!0,speed:1.4}],legend:[{label:"disaggregated prefill / decode",tone:"blue"}]}}]},{id:"realworld-discord-hotstar",title:"Case Study: Discord & Disney+ Hotstar",subtitle:"ByteByteGo 101 classics: Storing trillions of messages in ScyllaDB & scaling live cricket to 50M+ concurrent users.",duration:"10 min",level:"Advanced",companies:["Discord","Disney+ Hotstar","Meta"],tags:["discord","scylladb","request coalescing","hotstar","50m concurrent","live streaming","bytebytego"],objectives:["Trace Discord’s journey from MongoDB → Cassandra → ScyllaDB + Rust Data Services","Apply Request Coalescing to collapse 100k simultaneous identical channel reads into 1 DB query","Learn Hotstar’s Ladder-Based Pre-Scaling for 50M+ simultaneous World Cup viewers"],steps:[{shortLabel:"Discord Trillions",stage:"SOLUTION",title:"How Discord stores Trillions of messages with sub-20ms p99",body:["Discord outgrew **MongoDB** (RAM index limits), moved to **Cassandra** (177 nodes), and hit massive **JVM Garbage Collection pauses** + hot-partition storms when 100,000 members opened an announcement channel at the exact same second.","Their two legendary wins: 1) Migrated to **ScyllaDB** (C++ Cassandra rewrite, shard-per-core, zero JVM GC pauses — slashing 177 nodes down to **72 nodes** and p99 from 40–125 ms to **15 ms**!), 2) Built **Rust Data Services** with **Request Coalescing** (100k concurrent reads for Channel #1 collapse into **1** DB query!)."],callout:{type:"KEY IDEA",text:"Partition Key lesson from Discord: Partitioning chat purely by `channel_id` creates unbounded giant partitions! Discord uses a composite partition key `(channel_id, 10_day_bucket)` so every partition stays bounded and fast."},scene:{hud:[{label:"MESSAGES",value:"Trillions+",status:"info"},{label:"DB NODES",value:"177 → 72 Scylla",status:"good"},{label:"P99 READS",value:"125ms → 15ms",status:"good"},{label:"HOT CHANNEL",value:"Rust Coalesced",status:"good"}],nodes:[{id:"u",type:"users",x:105,y:215,label:"100k Users",sublabel:"Same Channel!",tone:"slate"},{id:"rs",type:"hex",x:365,y:215,label:"Rust Data Svc",sublabel:"Request Coalescing",tone:"green",badge:"100k → 1 query",badgeTone:"green",load:32},{id:"sc",type:"db",x:635,y:215,label:"ScyllaDB (C++)",sublabel:"(chan_id, bucket)",tone:"purple",badge:"zero GC pause",badgeTone:"purple",load:28}],edges:[{from:"u",to:"rs",label:"100k reads",packetColor:"coral",speed:1.4,packetCount:3},{from:"rs",to:"sc",label:"1 single fetch!",packetColor:"green",bidirectional:!0,speed:1.7,packetCount:1}],legend:[{label:"thundering channel open",tone:"coral"},{label:"coalesced ScyllaDB query",tone:"green"}]}},{shortLabel:"Hotstar 50M",stage:"TECHNIQUE",title:"How Disney+ Hotstar handles 50M+ concurrent live sports viewers",body:["When a wicket falls in an India vs Pakistan cricket match, **10 Million users join within 60 seconds** — far too fast for reactive CPU autoscaling (EC2/K8s nodes take 3–5 minutes to boot!).","Hotstar’s solution: **Ladder-Based Pre-Warming** (pre-provision fleet buffers ahead of predicted match milestones), **Multi-CDN dynamic steering** (Akamai + CloudFront), **Jittered Client Polling**, and **Graceful Shedding** (disable social emojis/feeds automatically if core video playback is threatened)."],callout:{type:"INTERVIEW SIGNAL",text:"Reactive autoscaling FAILS on sudden step-function spikes (Super Bowl, IPL, Taylor Swift tickets). Always combine **Pre-Warming**, **Virtual Waiting Rooms**, and **Feature Degradation Kill-Switches**!"},scene:{hud:[{label:"CONCURRENT",value:"50M+ Viewers",status:"info"},{label:"SCALING",value:"Pre-Warmed Ladders",status:"good"},{label:"VIDEO DELIVERY",value:"Multi-CDN HLS",status:"good"},{label:"OVERLOAD PLAN",value:"Shed Non-Core UI",status:"good"}],nodes:[{id:"v",type:"users",x:105,y:215,label:"50M Viewers",sublabel:"+10M in 60s",tone:"slate"},{id:"cdn",type:"hex",x:350,y:120,label:"Multi-CDN",sublabel:"HLS 4s Chunks",tone:"green",badge:"99.9% edge",badgeTone:"green"},{id:"api",type:"hex",x:350,y:310,label:"Pre-Warmed API",sublabel:"Ladder Pool",tone:"blue",load:55},{id:"deg",type:"hex",x:635,y:310,label:"Kill-Switch",sublabel:"Shed Chat/Emojis",tone:"amber",badge:"protect video",badgeTone:"amber"}],edges:[{from:"v",to:"cdn",label:"ABR video",packetColor:"green",speed:1.5,packetCount:3},{from:"v",to:"api",label:"jittered heartbeat",packetColor:"blue",speed:2},{from:"api",to:"deg",label:"load > 80%",packetColor:"amber",dashed:!0,speed:2.4}],legend:[{label:"multi-CDN live edge",tone:"green"}]}}]},{id:"realworld-prime-netflix-so",title:"Case Study: Prime Video, Netflix & Stack Overflow",subtitle:"ByteByteGo 101 architecture lessons: When Monoliths beat Serverless (-90% cost), Open Connect CDN, and Vertical Mastery.",duration:"9 min",level:"Intermediate",companies:["Amazon","Netflix","Stack Overflow"],tags:["prime video","netflix","open connect","stack overflow","serverless","cost optimization","bytebytego"],objectives:["Explain why Amazon Prime Video moved from Lambda/Step Functions to a Monolith (-90% cost)","Understand Netflix’s Control Plane (AWS) vs Data Plane (ISP Open Connect Appliances)","Recognize when vertical scaling + caching (Stack Overflow) beats distributed sprawl"],steps:[{shortLabel:"Prime -90%",stage:"INSIGHT",title:"Amazon Prime Video: Moving FROM Serverless TO a Monolith cut costs 90%",body:["Prime Video’s audio/video quality monitor originally chained **AWS Step Functions + Lambdas**, writing every decoded video frame to **S3** between stages. At scale, S3 I/O and Step Function state transitions blew past budget and throughput limits!","They packed all stages into **one single ECS container process** passing frames in shared RAM instead of S3 — **cutting costs by 90%** and increasing throughput dramatically! Architecture isn’t dogma; measure data-movement bottlenecks."],callout:{type:"KEY IDEA",text:"Serialization + network/S3 round trips between micro-steps dominate high-bandwidth media workloads. Keep tight inner loops in-process!"},scene:{hud:[{label:"BEFORE",value:"Step Fn + S3 Hops",status:"bad"},{label:"AFTER",value:"Single ECS Process",status:"good"},{label:"COST DROP",value:"-90% Savings!",status:"good"},{label:"FRAME TRANSFER",value:"In-Memory RAM",status:"good"}],nodes:[{id:"old",type:"hex",x:185,y:215,label:"Old Serverless",sublabel:"Lambda → S3 → Lambda",tone:"coral",badge:"high S3 cost",badgeTone:"rose",dim:!0},{id:"new",type:"hex",x:565,y:215,label:"Unified Monolith",sublabel:"Shared RAM Pipeline",tone:"green",badge:"-90% cost ✓",badgeTone:"green",load:45}],edges:[{from:"old",to:"new",label:"consolidate hot loop",packetColor:"green",speed:2}],legend:[{label:"data-locality optimization",tone:"green"}]}},{shortLabel:"Netflix & SO",stage:"SOLUTION",title:"Netflix Open Connect (Control vs Data Plane) & Stack Overflow Simplicity",body:["**Netflix** splits cleanly into two worlds: **AWS Control Plane** (login, recommendations, search, billing) and **Open Connect Data Plane** (custom NVMe cache boxes placed *physically inside local ISPs*, pre-loaded overnight during off-peak hours so 4K streams travel 1 hop!).","**Stack Overflow** proved the flip side: with disciplined C# code, zero ORM bloat, aggressive Redis caching, and 2 beefy SQL Server boxes, **just 9 web servers** handled over 1 billion monthly page views at 10% CPU!"],callout:{type:"INTERVIEW SIGNAL",text:"Separating **Control Plane** (API/metadata/billing) from **Data Plane** (high-throughput video/files/packets) is one of the cleanest architectural abstractions you can draw on any Big Tech whiteboard."},scene:{hud:[{label:"NETFLIX CTRL",value:"AWS Microservices",status:"info"},{label:"NETFLIX DATA",value:"ISP Open Connect",status:"good"},{label:"STACK OVERFLOW",value:"9 Web + 2 SQL",status:"good"},{label:"CORE LESSON",value:"Right-Size Complexity",status:"good"}],nodes:[{id:"tv",type:"users",x:115,y:215,label:"Smart TV",sublabel:"Press Play",tone:"slate"},{id:"aws",type:"hex",x:430,y:115,label:"AWS Control Plane",sublabel:"Auth · Recs · URL",tone:"blue"},{id:"oca",type:"cache",x:430,y:315,label:"Open Connect Box",sublabel:"Inside Your ISP!",tone:"green",badge:"4K in 5 ms",badgeTone:"green"}],edges:[{from:"tv",to:"aws",label:"1. metadata (10 KB)",packetColor:"blue",bidirectional:!0,speed:2},{from:"tv",to:"oca",label:"2. 4K video stream (GBs)",packetColor:"green",speed:1.4,packetCount:3}],legend:[{label:"control plane API",tone:"blue"},{label:"ISP-local video data plane",tone:"green"}]}}]}]},u=[l,s,r,i],b={id:"mod-10-whole-systems",number:"10",title:"Whole Systems (HLD)",track:"hld",lessons:[{id:"hld-lld",title:"HLD & LLD: Two Zoom Levels",subtitle:"The same system at two zoom levels: the macro map of services (HLD), and the micro code inside one service (LLD).",duration:"8 min",level:"Beginner",companies:["Microsoft","Amazon","Google","Meta"],tags:["hld","lld","contracts","api","architecture","interview framework"],objectives:["Know what High-Level Design (HLD) decides vs Low-Level Design (LLD)","Connect HLD service boundaries to LLD classes, interfaces, and schemas via Contracts","Navigate the 45-minute Big Tech interview loop smoothly between both zoom levels"],steps:[{shortLabel:"Two levels",stage:"SETUP",title:"One system, two zoom levels",body:["Picture a food-delivery app. From **far away (HLD)**, it is a map of distributed services — **Orders**, **Couriers**, **Payments** — each owning its database, communicating through an API Gateway and Kafka event stream.",'Up close (**LLD**), each box is a software program of its own, with **SOLID classes, design patterns, state machines, SQL schemas, and thread-safe locks**. Neither is "more real" — they answer different questions and change at different speeds.'],callout:{type:"KEY IDEA",text:"HLD optimizes for **scale, latency, availability, and failure domains** across machines; LLD optimizes for **extensibility, clean OOP contracts, and thread safety** inside a codebase."},scene:{hud:[{label:"ZOOM LEVEL",value:"Whole System (HLD)",status:"info"},{label:"BUILDING BLOCKS",value:"Services · DBs · Queues",status:"info"},{label:"YOU PRODUCE",value:"Architecture Blueprint",status:"good"},{label:"INTERVIEW ROUND",value:"System Design (45m)",status:"info"}],nodes:[{id:"gw",type:"hex",x:130,y:215,label:"API Gateway",sublabel:"Auth · Routing",tone:"green"},{id:"ord",type:"hex",x:350,y:140,label:"Orders",sublabel:"HLD Service",tone:"blue"},{id:"odb",type:"db",x:585,y:105,label:"Orders DB",sublabel:"ACID Postgres",tone:"purple",callout:"orders"},{id:"cou",type:"hex",x:350,y:295,label:"Couriers",sublabel:"Dispatch Svc",tone:"green",dim:!0},{id:"cdb",type:"db",x:585,y:295,label:"Geo Store",sublabel:"Redis H3",tone:"purple",callout:"locations"}],edges:[{from:"gw",to:"ord",label:"POST /order",packetColor:"coral",speed:1.8},{from:"ord",to:"odb",label:"commit",packetColor:"purple",speed:1.7},{from:"ord",to:"cou",label:"OrderPlaced event",packetColor:"amber",dashed:!0,speed:2.1},{from:"cou",to:"cdb",label:"nearest driver",packetColor:"green",speed:1.8}],legend:[{label:"request",tone:"coral"},{label:"event",tone:"amber"},{label:"data access",tone:"purple"}]}},{shortLabel:"Zoom into LLD",stage:"TECHNIQUE",title:"Zooming inside the Orders box reveals LLD classes & patterns",body:["Zoom 10× into the `Orders` hexagon: now we care about **`OrderController`**, **`OrderState`** (`CREATED → PAID → ASSIGNED → DELIVERED`), **`PricingStrategy`** (Normal / Surge / Promo), and **`ReentrantLock` / Optimistic `@Version`** so two couriers cannot claim the same order!","The **Contract** (REST/gRPC Protobuf + Kafka Event Schema) is the seam where HLD and LLD lock together."],callout:{type:"INTERVIEW SIGNAL",text:"At Microsoft (L61–L63) and Amazon (SDE2/SDE3), you face BOTH an **HLD Architecture Round** and an **LLD Object-Oriented / Machine Coding Round**. Master both tracks in this atlas!"},scene:{hud:[{label:"ZOOM LEVEL",value:"Inside 1 Service (LLD)",status:"info"},{label:"BUILDING BLOCKS",value:"Classes · Patterns · Locks",status:"info"},{label:"YOU PRODUCE",value:"UML + Clean Code",status:"good"},{label:"SEAM",value:"API & Event Contracts",status:"good"}],nodes:[{id:"svc",type:"uml",x:205,y:215,label:"OrderService",sublabel:"«Facade»",tone:"blue",umlFields:["- repo: OrderRepo","- pricing: PricingStrategy"],umlMethods:["+ createOrder(cmd)","+ assignCourier(id)"]},{id:"strat",type:"uml",x:545,y:120,label:"«interface» PricingStrategy",tone:"green",umlFields:["Standard | Surge | VIP"],umlMethods:["+ calculate(cart): Money"]},{id:"state",type:"uml",x:545,y:310,label:"«interface» OrderState",tone:"purple",umlFields:["Created → Paid → Done"],umlMethods:["+ next(ctx)","+ cancel(ctx)"]}],edges:[{from:"svc",to:"strat",label:"delegates price",packetColor:"green",speed:1.9},{from:"svc",to:"state",label:"transitions",packetColor:"purple",speed:1.9}],legend:[{label:"strategy dispatch",tone:"green"},{label:"state transition",tone:"purple"}]}}]},{id:"design-url-shortener",title:"Design a URL Shortener (TinyURL)",subtitle:"Base62 encoding, 100:1 read/write ratio, KGS vs Snowflake IDs, 301 vs 302 redirects, and hot-link caching.",duration:"12 min",level:"Beginner",companies:["Microsoft","Amazon","Google","Meta"],tags:["tinyurl","bitly","base62","301 vs 302","kgs","snowflake","shortener"],objectives:["Size 100M writes/day and 10B reads/day (~115k Read QPS) using napkin math","Choose 7-char Base62 keys (3.5 Trillion URLs) via Snowflake or Key Generation Service (KGS)","Decide 301 Permanent (CDN-friendly, no analytics) vs 302 Temporary (click analytics)"],steps:[{shortLabel:"Math & Base62",stage:"SETUP",title:"100:1 Read-Heavy — 7 Base62 characters hold 3.5 Trillion URLs",body:["**Requirements**: `POST /v1/shorten` creates a short alias (`sho.rt/aB9x2K1`); `GET /{code}` redirects in < 20 ms with 99.99% availability. At **100M new URLs/day** (`~1,150 write QPS`) and **100:1 read ratio**, peak reads reach **~350,000 QPS**!","With `[a-z, A-Z, 0-9]` (**62 characters**), a **7-character code** provides `62^7 = 3.52 Trillion` unique URLs — enough for **96+ years** at 100M URLs/day!"],callout:{type:"KEY IDEA",text:"**301 Moved Permanently** lets browsers cache the redirect forever (less server load, ZERO click analytics). **302 Found** hits your server every click (slightly more load, FULL real-time click analytics!)."},scene:{hud:[{label:"WRITE QPS",value:"1.2k /s (3.5k peak)",status:"good"},{label:"READ QPS",value:"115k /s (350k peak)",status:"warn"},{label:"KEY SPACE (62^7)",value:"3.52 Trillion",status:"good"},{label:"5-YR STORAGE",value:"~91 TB (500B/row)",status:"info"}],nodes:[{id:"c",type:"users",x:100,y:215,label:"Global Clicks",sublabel:"350k peak QPS",tone:"slate"},{id:"cdn",type:"hex",x:270,y:215,label:"Edge / LB",sublabel:"Rate Limit · 302",tone:"green"},{id:"svc",type:"hex",x:465,y:215,label:"URL Service",sublabel:"Stateless + KGS",tone:"blue",load:38},{id:"rd",type:"cache",x:660,y:110,label:"Redis Cluster",sublabel:"Hot 20% (95% hit)",tone:"green",badge:"0.5 ms",badgeTone:"green"},{id:"db",type:"db",x:660,y:315,label:"NoSQL / Sharded DB",sublabel:"key → long_url",tone:"purple",callout:"short_code PK"}],edges:[{from:"c",to:"cdn",label:"GET /aB9x2K",packetColor:"coral",bidirectional:!0,speed:1.5},{from:"cdn",to:"svc",label:"route",packetColor:"blue",speed:1.6},{from:"svc",to:"rd",label:"95% hit",packetColor:"green",bidirectional:!0,speed:1.4},{from:"svc",to:"db",label:"5% miss + writes",packetColor:"purple",dashed:!0,speed:2.3}],legend:[{label:"hot Redis redirect",tone:"green"},{label:"durable DB fallback",tone:"purple"}]}},{shortLabel:"KGS & Analytics",stage:"SOLUTION",title:"Zero-Collision Key Generation (KGS / Counter Range) + Async Click Pipeline",body:["How do we generate unique 7-char codes with zero hash collisions and zero DB round trips? Either **Base62-encode a Snowflake ID** (random-ish XOR obfuscated so competitors can’t guess your daily volume!) OR run a **Range Allocator (ZooKeeper/etcd)** leasing blocks of 100,000 numbers to each app server in RAM!","For **Click Analytics**, NEVER run `UPDATE urls SET clicks = clicks + 1` synchronously on the redirect path! Emit a click event to **Kafka → Flink → ClickHouse** asynchronously so redirects stay under 10 ms."],callout:{type:"INTERVIEW SIGNAL",text:"Security & Abuse check: Mention **Safe Browsing Malware URL Scanning** on shorten + **Per-IP Rate Limiting** so spammers cannot turn your domain into a phishing redirector!"},scene:{hud:[{label:"COLLISIONS",value:"Zero (Range Lease)",status:"good"},{label:"REDIRECT P99",value:"< 12 ms",status:"good"},{label:"ANALYTICS",value:"Async Kafka→OLAP",status:"good"},{label:"ABUSE GUARD",value:"Malware Scan + RL",status:"good"}],nodes:[{id:"zk",type:"hex",x:140,y:120,label:"Range Lease (etcd)",sublabel:"Leases 100k IDs",tone:"purple"},{id:"api",type:"hex",x:375,y:215,label:"URL Service",sublabel:"Base62 + Obfuscate",tone:"blue"},{id:"kf",type:"queue",x:560,y:315,label:"Click Kafka",sublabel:"Non-Blocking Emit",tone:"amber"},{id:"olap",type:"db",x:690,y:145,label:"ClickHouse",sublabel:"Geo / Referrer Stats",tone:"green"}],edges:[{from:"zk",to:"api",label:"block [1M..1.1M]",packetColor:"purple",dashed:!0,speed:2.6},{from:"api",to:"kf",label:"async click event",packetColor:"amber",speed:1.7},{from:"kf",to:"olap",label:"batch agg",packetColor:"green",speed:2}],legend:[{label:"non-blocking analytics pipeline",tone:"amber"}]}}],deepDive:{capacityMath:[{label:"Write QPS",value:"1,150 avg · 3,500 peak",formula:"100M URLs/day ÷ 86,400 sec"},{label:"Read QPS (100:1)",value:"115k avg · 350k peak",formula:"10B redirects/day ÷ 86,400 sec"},{label:"5-Year Storage",value:"~91 TB raw",formula:"100M/day × 365 × 5 × 500 bytes/record"},{label:"Hot Cache (20%)",value:"~180 GB RAM",formula:"Unique hot URLs fit easily in a 4-shard Redis cluster"}],failureModes:[{title:"Sequential Predictable Short URLs Leaking Business Metrics",mitigation:"Apply a bijective Feistel cipher / modular prime permutation to the sequential counter before Base62 encoding — still 100% collision-free, completely non-guessable!",interviewProbe:"If ID 1001 is `g9` and ID 1002 is `ga`, can a competitor scrape all private unlisted links?"}]}},{id:"design-news-feed",title:"Design a News Feed (Twitter / X / LinkedIn)",subtitle:"Fan-out on Write (Push) vs Fan-out on Read (Pull), the Hybrid Celebrity Split, Timeline Caches & Ranking.",duration:"12 min",level:"Intermediate",companies:["Meta","Twitter/X","LinkedIn","Microsoft"],tags:["news feed","fanout on write","fanout on read","celebrity problem","redis sorted set","timeline"],objectives:["Compare Push (Fan-out on Write) vs Pull (Fan-out on Read) latency & write amplification","Design the Hybrid Fan-out solution for 100M-follower celebrities","Hydrate cached post IDs via Ranking ML + Media CDN with Cursor Pagination"],steps:[{shortLabel:"Push vs Pull",stage:"PROBLEM",title:"Fan-out on Write breaks for celebrities; Fan-out on Read is slow",body:["**Fan-out on Write (Push)**: When Alice posts, a worker immediately pushes `post_id` into every follower’s precomputed **Redis Home Timeline** (`ZADD`). Reads are an instant `O(1)` 5 ms cache lookup! **Problem**: When Elon Musk (180M followers) tweets, pushing 180M Redis writes creates a massive backlog lag!","**Fan-out on Read (Pull)**: Don’t push on write; instead, when Alice opens the app, query the latest posts of all 500 accounts she follows and merge them on the fly — slow `500-way scatter-gather` every single reload!"],callout:{type:"WATCH OUT",text:"Neither pure Push nor pure Pull works at Twitter/Instagram scale. Always jump straight to the **Hybrid Fan-out Model**!"},scene:{hud:[{label:"NORMAL USER",value:"Push (Fan-out Write)",status:"good"},{label:"CELEBRITY > 50k",value:"Pull at Read Time",status:"good"},{label:"TIMELINE CACHE",value:"Redis ZSET (IDs)",status:"info"},{label:"FEED LOAD P99",value:"< 80 ms",status:"good"}],nodes:[{id:"pub",type:"hex",x:105,y:215,label:"Post Service",sublabel:"Write + Kafka",tone:"blue"},{id:"fw",type:"hex",x:325,y:115,label:"Fanout Workers",sublabel:"< 50k Followers",tone:"green",badge:"Push ZADD",badgeTone:"green"},{id:"cel",type:"cache",x:325,y:315,label:"Celebrity Cache",sublabel:"Top 1% Accounts",tone:"amber",badge:"Pull on Read",badgeTone:"amber"},{id:"tl",type:"cache",x:545,y:115,label:"Home Timelines",sublabel:"Redis [post_id]",tone:"purple"},{id:"agg",type:"hex",x:660,y:265,label:"Feed Aggregator",sublabel:"Merge + ML Rank",tone:"green"}],edges:[{from:"pub",to:"fw",label:"normal user",packetColor:"green",speed:1.6},{from:"pub",to:"cel",label:"celebrity only",packetColor:"amber",speed:1.7},{from:"fw",to:"tl",label:"push IDs",packetColor:"purple",speed:1.6},{from:"tl",to:"agg",label:"precomputed",packetColor:"purple",speed:1.6},{from:"cel",to:"agg",label:"merge live",packetColor:"amber",speed:1.6}],legend:[{label:"push fanout",tone:"green"},{label:"celebrity pull merge",tone:"amber"}]}},{shortLabel:"Hydrate & Rank",stage:"SOLUTION",title:"Store ONLY tiny IDs in Timeline Cache; Hydrate + ML Rank on Read",body:["Never duplicate full 2 KB post JSON inside 100M user timelines! Store only **8-byte `post_id`s** (capped at latest 800 items per active user; skip inactive users who haven’t logged in for 30 days!).","On read: 1) Merge user’s Redis Timeline + followed Celebrities’ recent IDs, 2) Pass top-200 IDs through **ML Ranking Service**, 3) Batch-hydrate top-20 Post + Author objects from Cache, 4) Return with a **Cursor Token** and CDN media URLs!"],callout:{type:"INTERVIEW SIGNAL",text:"Skipping fan-out for inactive users (> 30 days offline) saves 60–75% of Redis RAM and write IOPS immediately!"},scene:{hud:[{label:"CACHE PAYLOAD",value:"8-byte IDs Only",status:"good"},{label:"INACTIVE USERS",value:"Skipped (Backfill)",status:"good"},{label:"RANKING",value:"Top 200 → Top 20",status:"info"},{label:"PAGINATION",value:"Opaque Cursor",status:"good"}],nodes:[{id:"u",type:"users",x:100,y:215,label:"Reader",sublabel:"GET /feed",tone:"slate"},{id:"agg",type:"hex",x:285,y:215,label:"Feed Mixer",sublabel:"Push + Celeb Pull",tone:"blue"},{id:"ml",type:"hex",x:485,y:120,label:"ML Ranker",sublabel:"Relevance Score",tone:"purple"},{id:"hyd",type:"cache",x:485,y:310,label:"Post/User Cache",sublabel:"MGET Top 20",tone:"green"},{id:"cdn",type:"hex",x:675,y:215,label:"Media CDN",sublabel:"Images / Video",tone:"amber"}],edges:[{from:"u",to:"agg",label:"cursor",packetColor:"blue",bidirectional:!0,speed:1.7},{from:"agg",to:"ml",label:"200 IDs",packetColor:"purple",bidirectional:!0,speed:1.6},{from:"agg",to:"hyd",label:"hydrate 20",packetColor:"green",bidirectional:!0,speed:1.5},{from:"hyd",to:"cdn",label:"signed media URLs",packetColor:"amber",dashed:!0,speed:2.2}],legend:[{label:"rank + hydrate read path",tone:"green"}]}}],deepDive:{capacityMath:[{label:"DAU & Reads",value:"300M DAU · 100k Feed QPS",formula:"300M × 30 feed views/day ÷ 86,400"},{label:"Timeline RAM",value:"~1.9 TB (IDs only)",formula:"300M active × 800 IDs × 8 bytes = 1.92 TB across Redis cluster"}]}},{id:"design-chat",title:"Design a Chat System (WhatsApp / Teams)",subtitle:"Stateful WebSocket Gateways, 1:1 & Group Fanout, ScyllaDB storage, E2E Encryption, and Presence Storms.",duration:"12 min",level:"Intermediate",companies:["Meta","Microsoft","Discord","Slack"],tags:["whatsapp","microsoft teams","chat","websockets","presence","e2e encryption","scylladb"],objectives:["Route real-time 1:1 and group messages across distributed stateful WebSocket Gateways","Guarantee message ordering (client sequence / Snowflake IDs) and offline delivery","Prevent Presence Heartbeat Storms in massive groups"],steps:[{shortLabel:"1:1 & Offline",stage:"SOLUTION",title:"Persistent WebSocket Gateways + Session Registry + Push Fallback",body:["Alice sends a message over her persistent **WebSocket** to `GW #1`. The **Chat Service** assigns a monotonic `message_id` (Snowflake/HLC), persists it to **ScyllaDB/Cassandra** partitioned by `(conversation_id, bucket)`, and looks up Bob’s active gateway in the **Redis Session Registry**.","If Bob is online on `GW #42`, relay via Kafka/gRPC and push instantly + send a **Delivered ✓✓** receipt back to Alice! If Bob is offline, save to his **Inbox Sync Queue** and fire **APNs / FCM Push Notification**."],callout:{type:"KEY IDEA",text:"For **WhatsApp E2E Encryption (Signal Protocol)**, servers NEVER hold plaintext keys — they relay opaque encrypted blobs and store only public identity/pre-keys. For **Microsoft Teams Enterprise**, messages are persisted in compliant region-pinned storage for search & eDiscovery!"},scene:{hud:[{label:"CONCURRENT",value:"50M+ Sockets",status:"info"},{label:"DELIVERY P99",value:"< 100 ms",status:"good"},{label:"STORAGE",value:"ScyllaDB LSM",status:"good"},{label:"OFFLINE",value:"Sync + APNs/FCM",status:"good"}],nodes:[{id:"a",type:"users",x:95,y:120,label:"Alice",sublabel:"WS Open",tone:"slate"},{id:"gw1",type:"hex",x:265,y:120,label:"WS GW #1",sublabel:"Stateful",tone:"blue"},{id:"svc",type:"hex",x:465,y:215,label:"Chat Router",sublabel:"Persist + Lookup",tone:"green"},{id:"db",type:"db",x:665,y:120,label:"ScyllaDB",sublabel:"(conv_id, bucket)",tone:"purple"},{id:"gw2",type:"hex",x:265,y:315,label:"WS GW #42",sublabel:"Bob Online",tone:"green"},{id:"b",type:"users",x:95,y:315,label:"Bob",sublabel:"ACK ✓✓",tone:"slate"}],edges:[{from:"a",to:"gw1",label:"msg",packetColor:"blue",bidirectional:!0,speed:1.6},{from:"gw1",to:"svc",label:"gRPC",packetColor:"blue",speed:1.5},{from:"svc",to:"db",label:"write msg",packetColor:"purple",speed:1.6},{from:"svc",to:"gw2",label:"Bob on GW42",packetColor:"green",speed:1.5},{from:"gw2",to:"b",label:"push frame",packetColor:"green",bidirectional:!0,speed:1.5}],legend:[{label:"outbound chat message",tone:"blue"},{label:"real-time push + ACK",tone:"green"}]}},{shortLabel:"Groups & Presence",stage:"TECHNIQUE",title:"Small vs Giant Groups & Taming Presence Heartbeat Storms",body:["**Small Groups (< 500 members)**: Fan-out message IDs to each member’s online gateway / inbox. **Giant Channels (Slack/Discord 50k+ members)**: Do NOT fan-out to 50k inboxes — store once under `channel_id` and push only to users actively viewing that channel!",'**Presence**: Clients send a heartbeat every 30s (`SETEX presence:uid 45 online`). Avoid broadcasting "Alice came online" to 5,000 contacts on every network flap — use **Lazy Presence Pull** (fetch online dots ONLY for the 20 contacts currently visible on screen!) + a 15-second disconnect grace period.'],callout:{type:"INTERVIEW SIGNAL",text:"Switching Presence from global Push broadcast to **Lazy On-Screen Pull + Disconnect Grace Window** eliminates 95% of useless presence fan-out traffic!"},scene:{hud:[{label:"SMALL GROUP",value:"Fanout (< 500)",status:"good"},{label:"GIANT CHANNEL",value:"Single Log + Viewers",status:"good"},{label:"PRESENCE",value:"Lazy On-Screen Pull",status:"good"},{label:"FLAP GUARD",value:"15s Grace TTL",status:"info"}],nodes:[{id:"hb",type:"users",x:120,y:215,label:"Clients",sublabel:"30s Heartbeat",tone:"slate"},{id:"pr",type:"cache",x:380,y:215,label:"Presence Redis",sublabel:"TTL 45s Key",tone:"green",badge:"lazy query",badgeTone:"green"},{id:"pn",type:"hex",x:645,y:215,label:"Push Service",sublabel:"APNs / FCM Offline",tone:"amber"}],edges:[{from:"hb",to:"pr",label:"heartbeat + MGET visible",packetColor:"green",bidirectional:!0,speed:1.8},{from:"pr",to:"pn",label:"offline fallback",packetColor:"amber",dashed:!0,speed:2.3}],legend:[{label:"storm-free presence",tone:"green"}]}}]},{id:"design-video-streaming",title:"Design Video Streaming (YouTube / Netflix)",subtitle:"Resumable chunked uploads, parallel DAG transcoding, HLS/DASH Adaptive Bitrate, CDN & View Counting.",duration:"11 min",level:"Intermediate",companies:["Google","Netflix","Amazon","Meta"],tags:["youtube","netflix","hls","dash","abr","transcoding","dag","cdn"],objectives:["Handle multi-GB uploads reliably with resumable pre-signed multipart chunks","Split raw video into GOP segments and transcode 360p–4K in parallel via a DAG pipeline","Deliver smooth playback on fluctuating mobile networks via HLS/DASH Adaptive Bitrate (ABR)"],steps:[{shortLabel:"Upload & DAG",stage:"SOLUTION",title:"Parallel GOP Transcoding cuts 4K encoding from 2 hours to 4 minutes",body:["Creators upload 4K raw files via **resumable 5 MB chunks directly to S3/GCS**. Instead of encoding a 1-hour video sequentially on 1 CPU, the **Splitter** breaks it into independent **4-second GOP (Group of Pictures) chunks** and fans them out via a **DAG Task Queue** across hundreds of spot GPU/CPU transcoders!","Each chunk outputs **360p, 720p, 1080p, 4K** in **H.264 / VP9 / AV1**, plus a master **`.m3u8` HLS / `.mpd` DASH Manifest** pushed to Object Storage & CDN."],callout:{type:"KEY IDEA",text:"**Adaptive Bitrate Streaming (ABR)**: The player downloads 4-second chunks from the CDN and dynamically switches between 1080p and 480p mid-video whenever your subway Wi-Fi dips — zero buffering wheel!"},scene:{hud:[{label:"UPLOAD",value:"Direct S3 Multipart",status:"good"},{label:"TRANSCODE",value:"Parallel GOP DAG",status:"good"},{label:"PLAYBACK",value:"HLS / DASH ABR",status:"good"},{label:"DELIVERY",value:"Global Edge CDN",status:"good"}],nodes:[{id:"cr",type:"users",x:95,y:120,label:"Creator",sublabel:"4K Resumable",tone:"slate"},{id:"raw",type:"db",x:265,y:120,label:"Raw Blob",sublabel:"4s GOP Chunks",tone:"amber"},{id:"dag",type:"hex",x:465,y:120,label:"DAG Workers",sublabel:"360p..4K + AV1",tone:"purple",badge:"parallel 100×",badgeTone:"purple"},{id:"cdn",type:"hex",x:465,y:310,label:"Edge CDN",sublabel:"HLS .m3u8 + .ts",tone:"green",badge:"ABR 4s chunks",badgeTone:"green"},{id:"vw",type:"users",x:145,y:310,label:"Billion Viewers",sublabel:"Adaptive Player",tone:"blue"}],edges:[{from:"cr",to:"raw",label:"PUT chunks",packetColor:"amber",speed:1.7},{from:"raw",to:"dag",label:"split GOPs",packetColor:"purple",speed:1.6},{from:"dag",to:"cdn",label:"encoded chunks",packetColor:"green",speed:1.8},{from:"cdn",to:"vw",label:"4K / 720p ABR",packetColor:"green",speed:1.4,packetCount:3}],legend:[{label:"parallel DAG transcode",tone:"purple"},{label:"CDN ABR stream",tone:"green"}]}},{shortLabel:"Views & Costs",stage:"TECHNIQUE",title:"Hot vs Cold Encoding Tiers & Deduplicated View Counting",body:["**Cost Optimization (YouTube real world)**: 90% of uploaded videos get < 100 views! Encode only 360p/720p H.264 on upload; trigger expensive **AV1 / 4K transcoding** ONLY once a video crosses a view velocity threshold!","For **View Counts** (anti-bot fraud + write spikes), buffer view heartbeats in **Kafka → Flink** (dedup by `user_id/IP + video_id` window) and batch-flush aggregated counts to DB every few seconds."],callout:{type:"INTERVIEW SIGNAL",text:"Tiered on-demand AV1 transcoding saves tens of millions of dollars per year in compute while keeping viral videos 40% smaller on CDN egress!"},scene:{hud:[{label:"NEW VIDEO",value:"Fast H.264 720p",status:"good"},{label:"VIRAL VIDEO",value:"Trigger AV1 4K",status:"good"},{label:"VIEW COUNTER",value:"Kafka → Flink Agg",status:"good"},{label:"COPYRIGHT",value:"ContentID Audio/Vid",status:"info"}],nodes:[{id:"p",type:"users",x:120,y:215,label:"View Events",sublabel:"30s Watched",tone:"slate"},{id:"k",type:"queue",x:350,y:215,label:"Kafka Views",sublabel:"High Throughput",tone:"amber"},{id:"f",type:"hex",x:590,y:130,label:"Flink Dedup",sublabel:"Anti-Bot + Batch",tone:"green"},{id:"c",type:"hex",x:590,y:300,label:"AV1 Trigger",sublabel:"If Views > 10k",tone:"purple"}],edges:[{from:"p",to:"k",label:"heartbeat",packetColor:"amber",speed:1.6},{from:"k",to:"f",label:"dedup count",packetColor:"green",speed:1.7},{from:"k",to:"c",label:"viral hook",packetColor:"purple",dashed:!0,speed:2.3}],legend:[{label:"buffered streaming analytics",tone:"green"}]}}]},{id:"design-uber",title:"Design Ride-Hailing & Geo Dispatch (Uber)",subtitle:"5-sec Driver GPS Ingestion, Uber H3 Hexagonal Spatial Index, Atomic Dispatch Locking & Real-Time Surge.",duration:"12 min",level:"Advanced",companies:["Uber","Lyft","Google","Amazon"],tags:["uber","h3","geohash","quadtree","spatial index","matching","eta","surge pricing"],objectives:["Ingest 1M+ active drivers updating GPS coordinates every 4–5 seconds (~250k writes/sec)","Compare Geohash, QuadTree, and Uber H3 Hexagons for equidistant nearby-driver search","Prevent double-dispatching the same driver to two riders with atomic distributed locks"],steps:[{shortLabel:"Geo Ingestion",stage:"SOLUTION",title:"250k GPS Updates/sec → In-Memory H3 Spatial Index (Not Disk SQL!)",body:["With **1M active drivers** sending `(lat, lng)` every 4 seconds (`250,000 updates/sec`), writing ephemeral GPS pings to PostgreSQL would melt the disk. Instead, write live driver coordinates into an in-memory **Geo-Sharded Redis / H3 Location Store** (partitioned by City/Region)!","**Why Uber H3 Hexagons beat Square Geohashes?** Every neighbor of a hexagon is at the **exact same center-to-center distance** (no awkward diagonal corner distortion!), and checking `k-ring(hex, 1)` returns the 7 surrounding hexagons in O(1)!"],callout:{type:"KEY IDEA",text:"Historical GPS trails for trips/receipts still stream asynchronously via **Kafka → Cassandra/S3**, keeping the hot dispatch index 100% RAM-resident and sub-5ms!"},scene:{hud:[{label:"LOCATION WRITES",value:"250k GPS / sec",status:"warn"},{label:"SPATIAL INDEX",value:"Uber H3 Hexagons",status:"good"},{label:"RADIUS QUERY",value:"k-ring < 5 ms",status:"good"},{label:"SHARD KEY",value:"City / H3 Cell",status:"info"}],nodes:[{id:"drv",type:"users",x:105,y:215,label:"1M Drivers",sublabel:"GPS every 4s",tone:"slate"},{id:"loc",type:"hex",x:315,y:215,label:"Location Ingest",sublabel:"lat/lng → H3 ID",tone:"blue"},{id:"h3",type:"cache",x:565,y:120,label:"H3 RAM Index",sublabel:"cell → [driver_ids]",tone:"green",badge:"< 5ms query",badgeTone:"green"},{id:"kf",type:"queue",x:565,y:310,label:"Kafka + Flink",sublabel:"Surge & Trip Log",tone:"amber"}],edges:[{from:"drv",to:"loc",label:"250k/s GPS",packetColor:"blue",speed:1.4,packetCount:3},{from:"loc",to:"h3",label:"update cell",packetColor:"green",speed:1.5},{from:"loc",to:"kf",label:"async trail",packetColor:"amber",dashed:!0,speed:2.1}],legend:[{label:"live RAM spatial update",tone:"green"},{label:"async surge / archive",tone:"amber"}]}},{shortLabel:"Atomic Match",stage:"TECHNIQUE",title:"ETA Ranking + Atomic Redis Lock prevents Double-Dispatching a Driver",body:["1) Rider requests pickup → Dispatch fetches ~20 nearby idle drivers from **H3 k-ring**, 2) **Routing / ETA Engine** (road graph Contraction Hierarchies — NOT straight-line bird-flight distance across a river!) ranks true driving ETA, 3) **Atomic Lock (`SET lock:driver_99 ride_7 NX EX 15`)** offers the ride exclusively to Driver #1 for 15 seconds!","If Driver #1 declines or times out, the lock expires and Dispatch automatically offers to Driver #2."],callout:{type:"INTERVIEW SIGNAL",text:"Calling out **Road-Network ETA vs Euclidean Distance** (a driver 200m away across a highway divider takes 12 min to U-turn!) AND **15s Atomic Offer Locks** wins Uber/Google interviews."},scene:{hud:[{label:"CANDIDATES",value:"H3 Top 20 Idle",status:"info"},{label:"RANKING",value:"Road-Graph ETA",status:"good"},{label:"DOUBLE DISPATCH",value:"Blocked (NX Lock)",status:"good"},{label:"OFFER TTL",value:"15 Seconds",status:"warn"}],nodes:[{id:"r",type:"users",x:100,y:215,label:"Rider",sublabel:"Request Pickup",tone:"slate"},{id:"m",type:"hex",x:300,y:215,label:"Match Engine",sublabel:"H3 + Road ETA",tone:"purple"},{id:"lk",type:"cache",x:500,y:120,label:"Redis NX Lock",sublabel:"driver_99 · 15s",tone:"green",badge:"exclusive offer",badgeTone:"green"},{id:"d",type:"hex",x:665,y:265,label:"Driver #99",sublabel:"Accepts via WS ✓",tone:"blue"}],edges:[{from:"r",to:"m",label:"request",packetColor:"purple",speed:1.7},{from:"m",to:"lk",label:"SET NX EX 15",packetColor:"green",bidirectional:!0,speed:1.5},{from:"m",to:"d",label:"push offer",packetColor:"blue",bidirectional:!0,speed:1.7}],legend:[{label:"atomic exclusive ride lock",tone:"green"}]}}]},{id:"design-search-autocomplete",title:"Design Search Autocomplete & Web Crawler",subtitle:"Sharded Top-K Tries (< 30 ms keystroke), Offline Flink/Spark Aggregation, Politeness Queue & Bloom Filter Crawler.",duration:"11 min",level:"Intermediate",companies:["Google","Microsoft","Amazon"],tags:["typeahead","autocomplete","trie","web crawler","bloom filter","robots.txt","politeness"],objectives:["Serve Top-5 autocomplete suggestions in < 30 ms using precomputed Trie node caches","Avoid mutating live Tries on every keystroke via offline aggregation + blue-green snapshots","Design a polite, deduped, trap-resistant distributed Web Crawler"],steps:[{shortLabel:"Top-K Trie",stage:"SOLUTION",title:"Precompute Top-5 queries at every Trie node → O(prefix_len) = 5 ms!",body:['Walking a subtree of 50 million strings under prefix `"sys"` on every keystroke is way too slow! Instead, **cache the Top-5 highest-frequency queries directly inside every Trie node** (prefix max 50 chars). Now lookup is **O(1) memory hops**!',"Shard Tries by prefix frequency range (`aa–am`, `an–az`, ...) and **never update live Tries on writes** — log queries to Kafka, aggregate weekly/hourly with Spark/Flink (with exponential time decay for trending news), build a fresh Trie snapshot, and swap it in!"],callout:{type:"KEY IDEA",text:"Frontend wins too: **Debounce keystrokes (100–150 ms)** + browser `Cache-Control` caching cuts backend QPS by 70% immediately!"},scene:{hud:[{label:"KEYSTROKE P99",value:"< 25 ms",status:"good"},{label:"NODE STORAGE",value:"Cached Top-5",status:"good"},{label:"LIVE UPDATES",value:"Immutable Swap",status:"good"},{label:"DEBOUNCE",value:"150 ms Client",status:"info"}],nodes:[{id:"u",type:"users",x:100,y:215,label:"Search Box",sublabel:'"sys..." (150ms)',tone:"slate"},{id:"tr",type:"cache",x:355,y:135,label:"Sharded Trie RAM",sublabel:'"sys" → Top 5!',tone:"green",badge:"5 ms read",badgeTone:"green"},{id:"kf",type:"queue",x:355,y:315,label:"Query Logs",sublabel:"Kafka Stream",tone:"amber"},{id:"agg",type:"hex",x:635,y:215,label:"Trie Builder",sublabel:"Hourly Snapshot",tone:"purple"}],edges:[{from:"u",to:"tr",label:"GET ?q=sys",packetColor:"green",bidirectional:!0,speed:1.4},{from:"u",to:"kf",label:"log final query",packetColor:"amber",dashed:!0,speed:2.3},{from:"kf",to:"agg",label:"freq + decay",packetColor:"purple",speed:2},{from:"agg",to:"tr",label:"blue-green swap",packetColor:"purple",dashed:!0,speed:2.6}],legend:[{label:"5 ms Trie hit",tone:"green"},{label:"offline Trie rebuild",tone:"purple"}]}},{shortLabel:"Web Crawler",stage:"TECHNIQUE",title:"Polite, Deduplicated Web Crawler: Frontier + Per-Host Queues + Bloom Filter",body:["To crawl 1 Billion pages/month without DDoS-ing websites: the **URL Frontier** separates **Priority Queues** (fresh news crawled hourly) from **Per-Host Politeness Queues** (each worker hits 1 domain at most once per `robots.txt` Crawl-Delay!).","Use a **Bloom Filter** to skip already-visited URLs in O(1) RAM, **SimHash** to skip near-duplicate mirrored pages, a **local DNS cache**, and max URL depth limits to escape infinite calendar **Spider Traps**!"],callout:{type:"INTERVIEW SIGNAL",text:"Naming the 4 classic Crawler challenges — **Politeness (Per-Host Queue + robots.txt)**, **URL Dedup (Bloom Filter)**, **Content Dedup (SimHash)**, and **Spider Traps** — guarantees top marks."},scene:{hud:[{label:"POLITENESS",value:"1 Queue / Domain",status:"good"},{label:"URL DEDUP",value:"Bloom Filter",status:"good"},{label:"CONTENT DEDUP",value:"SimHash Fingerpr.",status:"good"},{label:"DNS BOTTLENECK",value:"Local DNS Cache",status:"info"}],nodes:[{id:"fr",type:"queue",x:120,y:215,label:"URL Frontier",sublabel:"Priority + Host Q",tone:"amber"},{id:"ft",type:"hex",x:350,y:215,label:"HTML Fetcher",sublabel:"DNS Cache + robots",tone:"blue"},{id:"ded",type:"hex",x:590,y:120,label:"SimHash + Parse",sublabel:"Extract New Links",tone:"purple"},{id:"bf",type:"cache",x:590,y:310,label:"Seen Bloom",sublabel:"Skip Visited URLs",tone:"green"}],edges:[{from:"fr",to:"ft",label:"polite pop",packetColor:"amber",speed:1.8},{from:"ft",to:"ded",label:"HTML bytes",packetColor:"blue",speed:1.7},{from:"ded",to:"bf",label:"check seen",packetColor:"green",speed:1.6},{from:"bf",to:"fr",label:"new URLs",packetColor:"purple",dashed:!0,speed:2.2}],legend:[{label:"crawl feedback loop",tone:"green"}]}}]},{id:"design-google-docs",title:"Design Collaborative Editor (Google Docs / Loop)",subtitle:"Operational Transformation (OT) vs CRDTs (Yjs/RGA), Room-Sticky WebSockets, Op-Log & Snapshots.",duration:"11 min",level:"Advanced",companies:["Google","Microsoft","Figma","Notion"],tags:["google docs","microsoft loop","ot","crdt","yjs","websockets","collaboration"],objectives:["Explain why naive full-document saves overwrite concurrent teammates’ edits","Contrast Operational Transformation (OT — Google Docs) vs CRDTs (Figma / Microsoft Loop)","Route all editors of Doc X to the same WebSocket coordinator + persist Append-Only Op Logs + Snapshots"],steps:[{shortLabel:"OT vs CRDT",stage:"SOLUTION",title:"Merge concurrent keystrokes cleanly with OT or CRDTs",body:['Document says `"CAT"`. Simultaneously, Alice inserts `"S"` at index 3 (`"CATS"`) while Bob deletes `"C"` at index 0 (`"AT"`). Naive index replay crashes or outputs garbage!','**OT (Google Docs)** routes all ops through a single central **Doc Authority Server** that transforms Alice’s index `3 → 2` relative to Bob’s delete (`"ATS"`). **CRDTs (Yjs / Automerge / Figma)** assign every character a unique fractional/causal ID so edits are **mathematically commutative** — converging identically even after offline edits on airplanes!'],callout:{type:"INTERVIEW SIGNAL",text:"Use **OT** when you have a single authoritative cloud server and want minimal metadata overhead; use **CRDTs** for **offline-first / P2P / multi-region** apps (Microsoft Loop, Figma, Apple Notes)!"},scene:{hud:[{label:"ROOM STICKY",value:"Consistent Hash(doc)",status:"good"},{label:"CONFLICT RES",value:"OT or CRDT (Yjs)",status:"good"},{label:"PERSISTENCE",value:"Op-Log + Snapshot",status:"good"},{label:"KEYSTROKE P99",value:"< 50 ms Broadcast",status:"good"}],nodes:[{id:"a",type:"users",x:100,y:120,label:"Alice",sublabel:'ins("S", 3)',tone:"blue"},{id:"b",type:"users",x:100,y:310,label:"Bob",sublabel:"del(0)",tone:"purple"},{id:"room",type:"hex",x:375,y:215,label:"Doc Room Server",sublabel:"OT / CRDT Merge",tone:"green",badge:'converged: "ATS"',badgeTone:"green"},{id:"log",type:"db",x:645,y:125,label:"Append Op-Log",sublabel:"Every Delta",tone:"amber"},{id:"snap",type:"db",x:645,y:305,label:"S3 Snapshots",sublabel:"Every 500 Ops",tone:"purple"}],edges:[{from:"a",to:"room",label:"WS op",packetColor:"blue",bidirectional:!0,speed:1.5},{from:"b",to:"room",label:"WS op",packetColor:"purple",bidirectional:!0,speed:1.5},{from:"room",to:"log",label:"append delta",packetColor:"amber",speed:1.8},{from:"log",to:"snap",label:"compact",packetColor:"purple",dashed:!0,speed:2.5}],legend:[{label:"live collaborative sync",tone:"blue"},{label:"delta log + snapshot",tone:"amber"}]}},{shortLabel:"Snapshots",stage:"TECHNIQUE",title:"Avoid replaying 100,000 edits on load with Periodic Snapshots",body:["If a 6-month-old spec doc has 200,000 keystroke deltas, replaying from op #1 takes seconds! Compact the document into an immutable **Snapshot every 500 operations** (stored in S3). Opening the doc loads `Latest Snapshot + last 42 tail ops` in < 80 ms, AND powers full **Version History / Time-Travel Undo**!"],callout:{type:"GOOD TO KNOW",text:"Keep **Ephemeral Presence** (live colored cursors & typing indicators) in RAM / Redis PubSub — NEVER write cursor moves to the durable Op-Log!"},scene:{hud:[{label:"DOC LOAD",value:"Snapshot + Tail Ops",status:"good"},{label:"HISTORY",value:"Time-Travel Undo",status:"good"},{label:"CURSORS",value:"Ephemeral RAM Only",status:"info"},{label:"FAILOVER",value:"Redis / Kafka Replay",status:"good"}],nodes:[{id:"s",type:"db",x:165,y:215,label:"Snapshot #400",sublabel:"Base State (S3)",tone:"purple"},{id:"t",type:"queue",x:400,y:215,label:"Ops #401..442",sublabel:"42 Tiny Deltas",tone:"amber"},{id:"c",type:"users",x:645,y:215,label:"Fast Client",sublabel:"Loaded in 75 ms",tone:"green"}],edges:[{from:"s",to:"t",label:"+ tail replay",packetColor:"amber",speed:1.8},{from:"t",to:"c",label:"hydrate editor",packetColor:"green",speed:1.6}],legend:[{label:"fast snapshot + delta load",tone:"green"}]}}]},{id:"design-ticket-booking",title:"Design Flash-Sale & Ticket Booking (BookMyShow)",subtitle:"Virtual Waiting Room, 10-Min Atomic Seat Holds (Redis TTL + DB Lock), Payment Idempotency & Zero Double-Booking.",duration:"12 min",level:"Intermediate",companies:["Amazon","Ticketmaster","Microsoft","Uber"],tags:["bookmyshow","ticketmaster","flash sale","seat lock","waiting room","pessimistic lock","saga"],objectives:["Absorb 1M simultaneous Taylor Swift ticket fans with a Virtual Waiting Room","Guarantee ZERO double-booking via a 2-phase 10-minute Seat Hold + Payment Saga","Choose Pessimistic (`FOR UPDATE`) vs Redis Distributed Lock + DB Unique Constraint"],steps:[{shortLabel:"Waiting Room",stage:"PROBLEM",title:'1M fans clicking "Buy" at 10:00:00 AM melts any database',body:["During a concert drop or Amazon Prime flash sale, **1,000,000 users** hammer 10,000 seats in the exact same second. Sending all 1M straight to PostgreSQL causes massive lock contention and crashes checkout for everyone.","**Defense 1 — Virtual Waiting Room** (Cloudflare/Edge Queue): Admit users into checkout at a controlled rate (e.g., 5,000/min) with a signed FIFO queue token. Serve static seat maps from **CDN / Redis** refreshed every 2 seconds!"],callout:{type:"KEY IDEA",text:"Separate **Browsing** (eventually consistent 2-sec cached seat map — millions of reads!) from **Booking** (strongly consistent atomic seat reservation — thousands of writes!)."},scene:{hud:[{label:"FAN SPIKE",value:"1M Concurrent",status:"warn"},{label:"EDGE QUEUE",value:"Waiting Room FIFO",status:"good"},{label:"SEAT MAP",value:"Redis / CDN (2s)",status:"good"},{label:"DB LOCKS",value:"Protected ✓",status:"good"}],nodes:[{id:"f",type:"users",x:100,y:215,label:"1M Fans",sublabel:"10:00:00 Drop",tone:"slate"},{id:"wr",type:"queue",x:315,y:215,label:"Waiting Room",sublabel:"5k/min Token Gate",tone:"amber",badge:"throttles spike",badgeTone:"amber"},{id:"map",type:"cache",x:590,y:115,label:"Seat Map Cache",sublabel:"Read-Only 2s TTL",tone:"green"},{id:"bk",type:"hex",x:590,y:310,label:"Booking Engine",sublabel:"ACID Reserve",tone:"blue"}],edges:[{from:"f",to:"wr",label:"1M spike",packetColor:"coral",speed:1.3,packetCount:3},{from:"wr",to:"map",label:"browse seats",packetColor:"green",speed:1.7},{from:"wr",to:"bk",label:"controlled trickle",packetColor:"blue",speed:2}],legend:[{label:"flash-sale burst",tone:"coral"},{label:"controlled admission",tone:"blue"}]}},{shortLabel:"10-Min Hold",stage:"SOLUTION",title:"Two-Phase Seat Hold (10-min TTL) + DB `SELECT FOR UPDATE` = Zero Double-Book",body:["**Phase 1 (Hold)**: User picks Seat A5 → `BEGIN; SELECT * FROM show_seats WHERE id=A5 FOR UPDATE;` Check `status == AVAILABLE` (or `HELD` with `hold_expires_at < NOW()`), update `status = HELD, hold_expires_at = NOW() + 10 min, booking_id = B1`, `COMMIT`. Also mirror lock in Redis for ultra-fast rejection!","**Phase 2 (Confirm)**: User pays via Stripe (with **Idempotency Key = B1**). On webhook confirmation, atomically flip `HELD → BOOKED` ONLY IF `booking_id == B1 AND hold_expires_at > NOW()`. If payment arrives after expiry, trigger an automatic refund!"],callout:{type:"INTERVIEW SIGNAL",text:"Try breaking and fixing this exact race condition live with 2 simultaneous buyers in **Design Lab → LLD Seat Lock Concurrency Simulator**!"},scene:{hud:[{label:"DOUBLE BOOKING",value:"0% (ACID Lock)",status:"good"},{label:"HOLD TTL",value:"10 Minutes",status:"info"},{label:"ABANDONED CART",value:"Auto-Expires ✓",status:"good"},{label:"LATE PAYMENT",value:"Auto-Refund Saga",status:"good"}],nodes:[{id:"b1",type:"hex",x:130,y:215,label:"Booking Svc",sublabel:"Phase 1: Hold",tone:"blue"},{id:"db",type:"db",x:400,y:120,label:"Postgres ACID",sublabel:"FOR UPDATE + TTL",tone:"purple",badge:"single source of truth",badgeTone:"green"},{id:"psp",type:"hex",x:400,y:315,label:"Payment PSP",sublabel:"Idem-Key = B1",tone:"amber"},{id:"tkt",type:"hex",x:655,y:215,label:"Ticket Issued",sublabel:"QR + Email",tone:"green",badge:"BOOKED ✓",badgeTone:"green"}],edges:[{from:"b1",to:"db",label:"1. lock 10m",packetColor:"purple",bidirectional:!0,speed:1.6},{from:"b1",to:"psp",label:"2. charge card",packetColor:"amber",bidirectional:!0,speed:1.9},{from:"psp",to:"tkt",label:"3. confirm webhook",packetColor:"green",speed:1.7},{from:"db",to:"tkt",label:"4. status=BOOKED",packetColor:"green",speed:1.7}],legend:[{label:"2-phase transactional booking",tone:"green"}]}}]},{id:"design-kv-store",title:"Design a Distributed KV Store (DynamoDB)",subtitle:"Consistent Hashing + vNodes, Quorum (W+R>N), Vector Clocks, Gossip Protocol, Hinted Handoff & LSM-Tree.",duration:"12 min",level:"Advanced",companies:["Amazon","Google","Microsoft","Meta"],tags:["dynamodb","cassandra","kv store","gossip protocol","merkle tree","hinted handoff","vector clocks"],objectives:["Assemble all 7 Dynamo paper building blocks into one cohesive planetary-scale KV store","Detect node failures decentrally via Gossip Protocol (no single master SPOF)","Handle temporary outages with Sloppy Quorums + Hinted Handoff and permanent drift with Merkle Trees"],steps:[{shortLabel:"Dynamo Ring",stage:"SOLUTION",title:"The 7 Pillars of Amazon’s Dynamo Paper in One Blueprint",body:["1. **Data Partitioning**: Consistent Hashing Ring + Virtual Nodes.","2. **High Availability**: Replicate every key to the next `N = 3` distinct physical hosts clockwise (across separate racks/AZs!).","3. **Tunable Consistency**: Quorum `W + R > N` (`2 + 2 > 3` for strong overlap, or `W=1, R=1` for ultra-low latency).","4. **Conflict Resolution**: **Vector Clocks** detect concurrent divergent writes; client or CRDT merges siblings (e.g., union of shopping cart items!)."],callout:{type:"KEY IDEA",text:"Dynamo skips virtual nodes belonging to the SAME physical host/AZ when picking the `N=3` replicas so one rack power outage never wipes all 3 copies!"},scene:{hud:[{label:"PARTITIONING",value:"Hash Ring + vNodes",status:"good"},{label:"CONSISTENCY",value:"Tunable W+R>N",status:"good"},{label:"FAILURE DETECT",value:"Gossip Heartbeats",status:"good"},{label:"STORAGE",value:"WAL + MemTable + SST",status:"info"}],nodes:[{id:"c",type:"hex",x:115,y:215,label:"Coordinator",sublabel:"Any Node on Ring",tone:"green"},{id:"n1",type:"db",x:400,y:95,label:"Node A (AZ-1)",sublabel:"LSM + vClock",tone:"blue",badge:"W ACK 1",badgeTone:"green"},{id:"n2",type:"db",x:400,y:215,label:"Node B (AZ-2)",sublabel:"LSM + vClock",tone:"blue",badge:"W ACK 2",badgeTone:"green"},{id:"n3",type:"db",x:400,y:335,label:"Node C (AZ-3)",sublabel:"Temp Down",tone:"coral",dim:!0},{id:"hh",type:"db",x:650,y:275,label:"Node D (Hint)",sublabel:"Hinted Handoff",tone:"amber",badge:"holds for C",badgeTone:"amber"}],edges:[{from:"c",to:"n1",label:"write",packetColor:"green",bidirectional:!0,speed:1.6},{from:"c",to:"n2",label:"write",packetColor:"green",bidirectional:!0,speed:1.6},{from:"c",to:"hh",label:"sloppy hint",packetColor:"amber",dashed:!0,speed:2},{from:"hh",to:"n3",label:"replay on recovery",packetColor:"purple",dashed:!0,speed:2.7}],legend:[{label:"quorum write",tone:"green"},{label:"hinted handoff replay",tone:"amber"}]}},{shortLabel:"Gossip & Merkle",stage:"TECHNIQUE",title:"Gossip Failure Detection + Merkle Tree Anti-Entropy Sync",body:["**5. Failure Detection (Gossip)**: Each node periodically sends its heartbeat membership table to 2–3 random peers. If Node C’s counter hasn’t increased for `T` seconds across multiple peers, it’s marked suspect/down without any central coordinator!","**6. Anti-Entropy (Merkle Trees)**: How do two replicas with 100M keys efficiently find the 3 keys that drifted? Compare their **Merkle Tree root hash** — if identical, stop in O(1); if different, descend ONLY the mismatched hash branch!"],callout:{type:"INTERVIEW SIGNAL",text:"Every single concept in this lesson — Consistent Hashing, LSM-Trees, Quorums, Gossip, Hinted Handoff, Merkle Trees — appears across Amazon, Google, and Microsoft distributed storage interviews!"},scene:{hud:[{label:"MEMBERSHIP",value:"Peer Gossip",status:"good"},{label:"SYNC DIFF",value:"Merkle Tree O(log N)",status:"good"},{label:"SPOF",value:"Zero Masters",status:"good"},{label:"DISK ENGINE",value:"LSM-Tree",status:"good"}],nodes:[{id:"m1",type:"db",x:185,y:215,label:"Replica A",sublabel:"Merkle Root: 8f9a",tone:"blue"},{id:"m2",type:"db",x:575,y:215,label:"Replica B",sublabel:"Merkle Root: 8f1c",tone:"purple"},{id:"g",type:"hex",x:380,y:95,label:"Gossip Mesh",sublabel:"P2P Heartbeats",tone:"green"}],edges:[{from:"m1",to:"m2",label:"sync ONLY mismatched leaf!",packetColor:"purple",bidirectional:!0,speed:1.9},{from:"g",to:"m1",label:"ring state",packetColor:"green",dashed:!0,speed:2.3},{from:"g",to:"m2",label:"ring state",packetColor:"green",dashed:!0,speed:2.3}],legend:[{label:"Merkle anti-entropy sync",tone:"purple"}]}}]},{id:"design-dropbox",title:"Design Cloud File Sync (Dropbox / OneDrive)",subtitle:"4MB Content-Defined Chunks, SHA-256 Deduplication, Delta Sync, ACID Metadata DB & Real-Time Device Sync.",duration:"10 min",level:"Intermediate",companies:["Microsoft","Dropbox","Google","Apple"],tags:["dropbox","onedrive","google drive","delta sync","deduplication","chunking","metadata db"],objectives:["Cut upload bandwidth by 90% via 4MB chunking, compression, and SHA-256 deduplication","Separate high-bandwidth Block Storage (S3/Azure Blob) from strongly consistent Metadata DB","Push real-time file changes to Laptop/Phone devices and resolve offline edit conflicts"],steps:[{shortLabel:"Chunk & Dedup",stage:"SOLUTION",title:"Client Watcher splits into 4 MB SHA-256 chunks → Delta Sync + Dedup",body:["Edit 1 slide in a 200 MB PowerPoint deck on Microsoft OneDrive: the Desktop Client splits the file into **4 MB chunks** (or Rolling Rabin Fingerprint chunks) and hashes each with **SHA-256**.","It asks the **Metadata Service** which chunk hashes already exist globally in Blob Storage. 49 of 50 chunks already exist — so **only 1 single 4 MB chunk uploads**! If a colleague uploads the exact same 1 GB dataset, **0 bytes upload** (cross-user content-addressed dedup)!"],callout:{type:"WATCH OUT",text:"Cross-user dedup requires careful encryption design (Convergent Encryption or per-tenant dedup scope) so an attacker cannot probe whether another company uploaded a confidential file!"},scene:{hud:[{label:"CHUNK SIZE",value:"4 MB (SHA-256)",status:"good"},{label:"DELTA UPLOAD",value:"1 of 50 Chunks",status:"good"},{label:"BLOCK STORE",value:"Azure Blob / S3",status:"good"},{label:"META DB",value:"ACID Postgres/SQL",status:"info"}],nodes:[{id:"pc",type:"users",x:105,y:215,label:"Desktop App",sublabel:"Chunker + SHA-256",tone:"slate"},{id:"meta",type:"hex",x:350,y:115,label:"Metadata Svc",sublabel:"File → [chunk_ids]",tone:"purple",badge:"ACID v14",badgeTone:"purple"},{id:"blob",type:"db",x:350,y:315,label:"Block Storage",sublabel:"Immutable Chunks",tone:"green",badge:"98% deduped",badgeTone:"green"},{id:"sync",type:"hex",x:640,y:215,label:"Notification Svc",sublabel:"Long Poll / WS",tone:"blue"}],edges:[{from:"pc",to:"meta",label:"1. check hashes + commit",packetColor:"purple",bidirectional:!0,speed:1.7},{from:"pc",to:"blob",label:"2. upload ONLY missing 4MB",packetColor:"green",speed:1.6},{from:"meta",to:"sync",label:"3. notify Laptop/Phone",packetColor:"blue",speed:1.7}],legend:[{label:"delta chunk upload",tone:"green"},{label:"metadata + sync broadcast",tone:"purple"}]}},{shortLabel:"Offline Conflicts",stage:"TECHNIQUE",title:"Optimistic Version Checks prevent silent overwrites on offline laptops",body:["Alice edits `budget.xlsx` (v14) offline on a flight; Bob saves v15 in the office. When Alice lands and syncs with `parent_version = 14`, the Metadata DB sees current version is `15` and **NEVER silently overwrites Bob’s work** — it saves `budget (Alice’s conflicted copy).xlsx` so both versions survive safely!"],callout:{type:"INTERVIEW SIGNAL",text:"Calling out `parent_version` optimistic concurrency + conflicted-copy creation + soft-delete trash bin (30-day recovery) is classic Microsoft OneDrive / Dropbox engineering rigor."},scene:{hud:[{label:"CONFLICT GUARD",value:"parent_ver Check",status:"good"},{label:"DATA LOSS",value:"Zero (Branch Copy)",status:"good"},{label:"CLIENT CACHE",value:"Local SQLite Index",status:"info"},{label:"RESTORE",value:"Immutable Chunks",status:"good"}],nodes:[{id:"a",type:"users",x:135,y:135,label:"Alice (Offline)",sublabel:"base=v14 → v15a",tone:"amber"},{id:"b",type:"users",x:135,y:295,label:"Bob (Online)",sublabel:"base=v14 → v15 ✓",tone:"green"},{id:"db",type:"db",x:475,y:215,label:"Metadata DB",sublabel:"Keeps v15 + Conflict Copy",tone:"purple",badge:"zero data loss",badgeTone:"green"}],edges:[{from:"b",to:"db",label:"commit v15 ✓",packetColor:"green",speed:1.6},{from:"a",to:"db",label:"stale v14 → save copy",packetColor:"amber",dashed:!0,speed:2.1}],legend:[{label:"conflict-safe file sync",tone:"green"}]}}]},{id:"design-rate-limiter",title:"Design a Distributed Rate Limiter & API Gateway",subtitle:"Multi-tier quota rules, Envoy/Edge middleware, atomic Redis Cluster Lua, multi-region sync & soft/hard limits.",duration:"10 min",level:"Intermediate",companies:["Stripe","Cloudflare","Microsoft","Amazon"],tags:["rate limiter","api gateway","envoy","redis cluster","lua","quotas"],objectives:["Architect a global low-latency (< 2 ms) distributed Rate Limiter in front of all APIs","Support per-user, per-IP, per-tenant, and per-endpoint dynamic rules reloaded without restarts","Handle multi-region quota enforcement without cross-ocean synchronous Redis hops"],steps:[{shortLabel:"Gateway + Lua",stage:"SOLUTION",title:"Local Config Cache + Redis Cluster Lua adds < 1.5 ms overhead",body:["Place the Rate Limiter inside your **API Gateway (Envoy/Kong)** so abusive traffic is dropped at the edge before burning backend CPU. Gateways poll a **Rules Config Service** (cached in local RAM) mapping `(tier, endpoint) → {limit, window}`.","On every request, Gateway executes a pre-loaded **`EVALSHA` Redis Lua script** implementing **Sliding Window Counter** or **Token Bucket** atomically in 0.5 ms and returns `X-RateLimit-Limit`, `X-RateLimit-Remaining`, and `Retry-After` headers."],callout:{type:"KEY IDEA",text:"For **Multi-Region** apps (US + EU + APAC), NEVER do synchronous cross-ocean Redis calls on every API request! Enforce quotas in **local regional Redis** and asynchronously gossip deltas every 500 ms (or split global quota across regions dynamically)."},scene:{hud:[{label:"ADDED LATENCY",value:"< 1.5 ms",status:"good"},{label:"ATOMICITY",value:"Redis EVALSHA",status:"good"},{label:"RULES RELOAD",value:"Dynamic Push",status:"good"},{label:"MULTI-REGION",value:"Local + Async Sync",status:"info"}],nodes:[{id:"cfg",type:"db",x:380,y:80,label:"Rules Store",sublabel:"YAML / etcd Push",tone:"purple"},{id:"gw",type:"hex",x:185,y:240,label:"Edge Gateway",sublabel:"Local Rule Cache",tone:"green",badge:"< 1.5ms check",badgeTone:"green"},{id:"rd",type:"cache",x:430,y:295,label:"Regional Redis",sublabel:"Lua Token Bucket",tone:"amber"},{id:"api",type:"hex",x:645,y:215,label:"Core Services",sublabel:"Shielded ✓",tone:"blue"}],edges:[{from:"cfg",to:"gw",label:"push rules",packetColor:"purple",dashed:!0,speed:2.5},{from:"gw",to:"rd",label:"EVALSHA",packetColor:"amber",bidirectional:!0,speed:1.4},{from:"gw",to:"api",label:"200 allowed",packetColor:"green",speed:1.6}],legend:[{label:"edge-enforced atomic rate limit",tone:"green"}]}},{shortLabel:"Adaptive RL",stage:"TECHNIQUE",title:"Shadow Mode, Adaptive Concurrency Limits & Graceful Load Shedding",body:["Before turning on a brand-new strict rate limit, deploy it in **Shadow (Dry-Run) Mode** for 48 hours to log false positives without blocking legitimate enterprise customers!","Pair static per-user quotas with **Adaptive Load Shedding** (Netflix Concurrency Limits / Little’s Law): shed low-priority background batch traffic first while preserving 100% of checkout/payment calls during severe incidents."],callout:{type:"INTERVIEW SIGNAL",text:"Distinguishing **Rate Limiting** (fairness per tenant/user) from **Adaptive Load Shedding** (protecting server health by dropping low-priority traffic first) is true Staff-level thinking."},scene:{hud:[{label:"SAFE LAUNCH",value:"Shadow Dry-Run",status:"good"},{label:"P0 CHECKOUT",value:"Always Admitted",status:"good"},{label:"P3 BATCH",value:"Shed First on Spike",status:"warn"},{label:"OUTAGE MODE",value:"Configurable Fail",status:"info"}],nodes:[{id:"in",type:"hex",x:145,y:215,label:"Priority Classifier",sublabel:"P0 Crit · P3 Batch",tone:"blue"},{id:"p0",type:"hex",x:525,y:120,label:"P0 Checkout",sublabel:"100% Protected",tone:"green",badge:"priority pass",badgeTone:"green"},{id:"p3",type:"hex",x:525,y:310,label:"P3 Analytics",sublabel:"503 Load Shed",tone:"coral",badge:"shed under load",badgeTone:"rose",dim:!0}],edges:[{from:"in",to:"p0",label:"admit",packetColor:"green",speed:1.5},{from:"in",to:"p3",label:"shed early",packetColor:"coral",dashed:!0,speed:2.5}],legend:[{label:"priority load shedding",tone:"green"}]}}]},{id:"design-monitoring-notifications",title:"Design Metrics Monitoring & Notification Platform",subtitle:"High-volume TSDB (Gorilla compression & downsampling), Alert Engine, and Multi-Channel Priority Notifications.",duration:"11 min",level:"Intermediate",companies:["Datadog","Microsoft","Amazon","Apple"],tags:["datadog","azure monitor","prometheus","tsdb","gorilla","notifications","apns","fcm"],objectives:["Ingest 10M+ metrics/sec into a Time-Series DB using Gorilla delta-of-delta compression & rollups","Design a reliable Alerting Engine with deduplication and PagerDuty routing","Architect a Multi-Channel Notification System (Push/SMS/Email) with Priority Queues, Templates, and User Fatigue Caps"],steps:[{shortLabel:"Metrics TSDB",stage:"SOLUTION",title:"Time-Series Ingestion: Gorilla Compression (12×) + Multi-Tier Rollups",body:["100,000 servers emitting 100 metrics every 10 seconds = **1,000,000 data points/sec**! Writing to normal SQL fails immediately. A **Time-Series DB** (Prometheus/VictoriaMetrics/M3DB) appends `(metric, tags, ts, val)` into **Gorilla compressed blocks** (delta-of-delta timestamps + XOR float compression = **1.37 bytes/point**!).","Keep raw 10-second granularity for **7 days**, downsample to **1-minute rollups** for 30 days, and **1-hour rollups** for 2 years — slashing storage 90% while keeping 1-year Grafana graphs instant!"],callout:{type:"WATCH OUT",text:"**High-Cardinality Tag Explosion**: Never put unbounded values like `user_id` or `request_id` into Prometheus metric labels — `10M users × 10 endpoints = 100M time series` will OOM your TSDB! Put IDs in Logs/Traces, not Metric tags."},scene:{hud:[{label:"INGESTION",value:"1M+ pts/sec",status:"good"},{label:"COMPRESSION",value:"1.37 B/pt (Gorilla)",status:"good"},{label:"DOWNSAMPLING",value:"10s → 1m → 1h",status:"good"},{label:"TRAP GUARD",value:"Cap Cardinality",status:"warn"}],nodes:[{id:"ag",type:"users",x:100,y:215,label:"100k Hosts",sublabel:"Pull / Push Agent",tone:"slate"},{id:"kf",type:"queue",x:295,y:215,label:"Metrics Kafka",sublabel:"Buffer + Partition",tone:"amber"},{id:"ts",type:"db",x:525,y:120,label:"TSDB Cluster",sublabel:"Gorilla + Rollups",tone:"purple"},{id:"al",type:"hex",x:525,y:315,label:"Alert Engine",sublabel:"Rules + Dedup",tone:"coral",badge:"fires PagerDuty",badgeTone:"rose"}],edges:[{from:"ag",to:"kf",label:"1M pts/s",packetColor:"amber",speed:1.4,packetCount:3},{from:"kf",to:"ts",label:"batch write",packetColor:"purple",speed:1.6},{from:"ts",to:"al",label:"eval SLO burn",packetColor:"coral",dashed:!0,speed:2}],legend:[{label:"high-throughput TSDB pipeline",tone:"purple"}]}},{shortLabel:"Notifications",stage:"TECHNIQUE",title:"Multi-Channel Notification Platform: Priority Queues & Anti-Spam Caps",body:["Never mix **P0 OTP / Fraud Alerts** into the same queue as **10 Million Marketing Promo Emails** — a marketing blast would delay login OTP codes by 30 minutes!","Split into **Isolated Priority Topics (`P0-OTP`, `P1-Transactional`, `P2-Marketing`)**, enforce **User Preferences + Daily Rate Caps** (max 3 promos/day), deduplicate via `notification_id`, render localized templates, and dispatch to **APNs / FCM / Twilio / SendGrid** with retry + DLQ!"],callout:{type:"INTERVIEW SIGNAL",text:"Checking **Opt-Out Preferences + Quiet Hours (Do Not Disturb timezone)** + **Separate OTP vs Marketing Queues** nails the Notification System interview every time!"},scene:{hud:[{label:"P0 OTP SLA",value:"< 2 sec (Isolated)",status:"good"},{label:"P2 PROMO",value:"Separate Queue",status:"info"},{label:"DEDUP & CAPS",value:"Redis Preference",status:"good"},{label:"CHANNELS",value:"APNs · FCM · SMS · Mail",status:"good"}],nodes:[{id:"svc",type:"hex",x:115,y:215,label:"Notify API",sublabel:"Prefs · DND · Dedup",tone:"blue"},{id:"p0",type:"queue",x:350,y:115,label:"P0 Critical Q",sublabel:"OTP / Security",tone:"green",badge:"fast lane",badgeTone:"green"},{id:"p2",type:"queue",x:350,y:315,label:"P2 Bulk Q",sublabel:"Marketing / Digest",tone:"amber"},{id:"w",type:"hex",x:635,y:215,label:"Channel Workers",sublabel:"APNs · SMS · Email",tone:"purple"}],edges:[{from:"svc",to:"p0",label:"OTP < 2s",packetColor:"green",speed:1.4},{from:"svc",to:"p2",label:"bulk campaign",packetColor:"amber",speed:2.3},{from:"p0",to:"w",label:"priority send",packetColor:"green",speed:1.4},{from:"p2",to:"w",label:"throttled send",packetColor:"amber",dashed:!0,speed:2.4}],legend:[{label:"P0 critical fast lane",tone:"green"},{label:"P2 isolated bulk lane",tone:"amber"}]}}]}]},p={id:"mod-14-advanced-hld",number:"14",title:"Advanced HLD Designs (10)",track:"hld",lessons:[{id:"design-ad-click-aggregator",title:"Design an Ad Click Aggregator (Meta / Google Ads)",subtitle:"1M clicks/s ingestion, click-fraud deduplication, Flink 1-min Event-Time Watermarks, ClickHouse OLAP & Lambda exact billing reconciliation.",duration:"13 min",level:"Advanced",companies:["Meta","Google","Amazon","Microsoft"],tags:["ad click aggregator","flink","watermarks","clickhouse","olap","deduplication","billing","hello interview"],objectives:["Ingest 1M ad clicks/sec reliably via Edge Click Redirector + Kafka partitioned by `ad_id`","Prevent double-charging advertisers via signed `impression_id` deduplication + click-fraud filtering","Combine Flink real-time 1-min dashboards (Speed Layer) with Spark nightly exact reconciliation (Billing Layer)"],steps:[{shortLabel:"Ingest & Dedup",stage:"SETUP",title:"Signed Click Tokens stop replay fraud; Kafka absorbs 1M clicks/sec",body:["**Requirements**: Advertisers view real-time clicks per minute (< 60s freshness) AND receive **100% accurate billing invoices** (zero missed or double-counted clicks!). At 1B clicks/day (`~12k avg`, `~100k–1M peak`), direct SQL `UPDATE ads SET clicks = clicks + 1` locks instantly.","When an ad renders, the Ad Server embeds a **cryptographically signed `impression_id`** (HMAC + timestamp). On click, the Edge Redirector validates the signature, immediately sends HTTP `302` to the advertiser landing page, and emits `(ad_id, impression_id, ts)` into **Kafka partitioned by `ad_id`**!"],callout:{type:"KEY IDEA",text:"Partitioning Kafka by `ad_id` sends all clicks for one ad to the same Flink worker — Watch out for Super Bowl **Hot Ads**! Fix by salting hot `ad_id#0..9` during Stage 1 aggregation, then merging in Stage 2!"},scene:{hud:[{label:"PEAK INGEST",value:"500k Clicks/s",status:"warn"},{label:"REDIRECT SLA",value:"< 15 ms (302)",status:"good"},{label:"FRAUD GUARD",value:"Signed imp_id",status:"good"},{label:"HOT AD FIX",value:"2-Stage Salt Agg",status:"good"}],nodes:[{id:"u",type:"users",x:95,y:215,label:"Ad Clickers",sublabel:"Signed Token",tone:"slate"},{id:"ed",type:"hex",x:270,y:215,label:"Click Collector",sublabel:"Verify HMAC + 302",tone:"green",badge:"< 15ms",badgeTone:"green"},{id:"kf",type:"queue",x:470,y:215,label:"Kafka Clicks",sublabel:"Key: ad_id#salt",tone:"amber"},{id:"fl",type:"hex",x:665,y:120,label:"Flink 1m Agg",sublabel:"Dedup + Watermark",tone:"blue"},{id:"s3",type:"db",x:665,y:315,label:"Raw S3 Lake",sublabel:"Exact Billing Replay",tone:"purple"}],edges:[{from:"u",to:"ed",label:"click + HMAC",packetColor:"coral",bidirectional:!0,speed:1.4},{from:"ed",to:"kf",label:"durable log",packetColor:"amber",speed:1.5},{from:"kf",to:"fl",label:"real-time stream",packetColor:"blue",speed:1.6},{from:"kf",to:"s3",label:"immutable archive",packetColor:"purple",dashed:!0,speed:2.3}],legend:[{label:"fast 302 redirect",tone:"coral"},{label:"real-time Flink stream",tone:"blue"},{label:"immutable billing archive",tone:"purple"}]}},{shortLabel:"Flink + Billing",stage:"SOLUTION",title:"Flink Event-Time Watermarks + ClickHouse OLAP + Nightly Exact Reconciliation",body:["**Apache Flink** deduplicates duplicate clicks by `impression_id` inside stateful RocksDB (with TTL), aggregates 1-minute tumbling windows using **Event Time + 2-minute Watermarks** (handling delayed mobile clicks!), and writes compact rollups to **ClickHouse / Apache Druid** for sub-second Advertiser dashboards.","Because late clicks arriving 30 minutes later still matter for money, a **Nightly Spark Reconciliation Job** recomputes exact totals from the raw S3 Kafka archive and overwrites/trues up the billing ledger!"],callout:{type:"INTERVIEW SIGNAL",text:"Distinguishing **Real-Time Approximate Dashboard (Flink → ClickHouse, < 60s)** from **100% Exact Financial Billing Reconciliation (Spark over Raw S3)** is the #1 Staff differentiator on Hello Interview’s Ad Click Aggregator!"},scene:{hud:[{label:"DASHBOARD LAG",value:"< 30 sec (OLAP)",status:"good"},{label:"DEDUP STATE",value:"Flink RocksDB",status:"good"},{label:"LATE CLICKS",value:"Watermarks + Reconcile",status:"good"},{label:"BILLING",value:"100% Exact (Spark)",status:"good"}],nodes:[{id:"fl",type:"hex",x:145,y:125,label:"Flink Speed Layer",sublabel:"1-min Rollups",tone:"blue"},{id:"sp",type:"hex",x:145,y:310,label:"Spark Billing Job",sublabel:"Exact Raw Dedup",tone:"purple"},{id:"ch",type:"db",x:455,y:215,label:"ClickHouse OLAP",sublabel:"Columnar Rollups",tone:"green",badge:"< 50ms queries",badgeTone:"green"},{id:"adv",type:"users",x:675,y:215,label:"Advertisers",sublabel:"Live Dash + Invoice",tone:"slate"}],edges:[{from:"fl",to:"ch",label:"1m increments",packetColor:"blue",speed:1.6},{from:"sp",to:"ch",label:"exact truth overwrite",packetColor:"purple",dashed:!0,speed:2.5},{from:"ch",to:"adv",label:"fast OLAP SQL",packetColor:"green",bidirectional:!0,speed:1.6}],legend:[{label:"speed + exact billing convergence",tone:"green"}]}}],deepDive:{capacityMath:[{label:"Peak Click Volume",value:"100k – 500k clicks/sec",formula:"1B clicks/day ≈ 12k avg; Super Bowl peaks 10–40×"},{label:"Raw Event Storage",value:"~100 GB/day (~180 TB/5yr)",formula:"1B × 100 bytes/event compressed Parquet in S3"}],failureModes:[{title:"Hot Ad Skew Starving One Flink Partition (e.g., Nike Super Bowl Ad)",mitigation:"Append a random shard salt (`ad_id#0..15`) for Stage 1 partial counting across 16 Flink slots, then perform a tiny Stage 2 sum by `ad_id` (only 16 rows/min)!",interviewProbe:"What happens if 40% of all clicks globally hit ONE single ad campaign during the World Cup final?"}]}},{id:"design-leetcode-judge",title:"Design an Online Code Judge (LeetCode)",subtitle:"Secure untrusted code execution with Firecracker microVMs / gVisor, pre-warmed sandbox pools, SSE verdicts & live contest leaderboards.",duration:"12 min",level:"Intermediate",companies:["Google","Microsoft","Amazon","Meta"],tags:["leetcode","code execution","firecracker","sandbox","seccomp","cgroups","contest leaderboard","hello interview"],objectives:["Execute untrusted user C++/Python/Java code safely without container escapes or fork bombs","Keep submission latency < 2s using a Pre-Warmed Firecracker / gVisor Sandbox Pool","Rank 50,000 live contest participants in O(log N) via Redis Sorted Sets"],steps:[{shortLabel:"Safe Sandboxing",stage:"PROBLEM",title:"Untrusted user code WILL try fork bombs, crypto-mining & kernel exploits!",body:["Running user-submitted C++ or Python directly in a standard Docker container on shared host kernels risks **kernel privilege escalation**, `while(1) fork()` fork bombs, 100 GB RAM OOM attacks, and outbound DDoS calls!","**Defense-in-Depth**: Execute every submission inside an ephemeral **Firecracker microVM** (AWS Lambda isolation — dedicated guest kernel booting in ~125 ms!) or **gVisor**, locked down with **`--network=none`**, **cgroups** (1 vCPU, 256 MB RAM, 2-sec wall timeout), **read-only filesystem**, and **seccomp-bpf** syscall allowlists!"],callout:{type:"INTERVIEW SIGNAL",text:"Naming **Firecracker microVMs (dedicated kernel isolation) + `cgroups` CPU/RAM caps + `seccomp-bpf` + `--network=none` + Ephemeral Destroy-After-Run** is the gold-standard security answer!"},scene:{hud:[{label:"ISOLATION",value:"Firecracker microVM",status:"good"},{label:"NETWORK",value:"Disabled (Air-Gap)",status:"good"},{label:"LIMITS",value:"2s · 256MB · 1 vCPU",status:"info"},{label:"CLEANUP",value:"Destroy After Run",status:"good"}],nodes:[{id:"u",type:"users",x:95,y:215,label:"Coder",sublabel:"Submit C++/Py",tone:"slate"},{id:"api",type:"hex",x:265,y:215,label:"Submit API",sublabel:"Returns sub_id",tone:"blue"},{id:"q",type:"queue",x:455,y:215,label:"Lang Queues",sublabel:"C++ · Java · Py",tone:"amber"},{id:"vm",type:"hex",x:655,y:215,label:"Firecracker Pool",sublabel:"Pre-Warmed Sandboxes",tone:"green",badge:"zero escape ✓",badgeTone:"green",load:54}],edges:[{from:"u",to:"api",label:"POST /submit",packetColor:"blue",bidirectional:!0,speed:1.7},{from:"api",to:"q",label:"enqueue job",packetColor:"amber",speed:1.6},{from:"q",to:"vm",label:"run 100 tests",packetColor:"green",speed:1.5}],legend:[{label:"isolated sandbox execution",tone:"green"}]}},{shortLabel:"Pool & Contest",stage:"SOLUTION",title:"Pre-Warmed Language Pools + Compiled Binary Reuse + Live Contest Rank",body:["1) **Speed**: Maintain a **Pre-Warmed Sandbox Pool** per language runtime (Python/Node/JVM already booted!) and compile C++/Java **ONCE** inside the sandbox, streaming all 100 test cases via stdin/stdout in a single execution loop (fail fast on first Wrong Answer / TLE!).","2) **Results & Contests**: Push verdict (`Accepted · 14 ms`) to the user via **SSE / WebSocket** (no wasteful polling!) and update weekly contest scores (`score = solved * 1e9 - penalty_sec`) in a **Redis Sorted Set (`ZADD` / `ZREVRANK`)** in O(log N)!"],callout:{type:"KEY IDEA",text:"During a Sunday Contest (50,000 simultaneous submissions at minute 5!), isolate **Contest Queue** from **Regular Practice Queue** and pre-scale sandbox workers 15 minutes before start!"},scene:{hud:[{label:"COLD START",value:"0 ms (Warm Pool)",status:"good"},{label:"TEST CASES",value:"S3 + Local NVMe",status:"info"},{label:"VERDICT PUSH",value:"SSE Stream",status:"good"},{label:"LEADERBOARD",value:"Redis ZSET O(logN)",status:"good"}],nodes:[{id:"vm",type:"hex",x:140,y:215,label:"Sandbox Worker",sublabel:"AC · 14ms · 42MB",tone:"green"},{id:"db",type:"db",x:430,y:115,label:"Submissions DB",sublabel:"History + Code",tone:"purple"},{id:"lb",type:"cache",x:430,y:315,label:"Redis ZSET",sublabel:"Live Contest Rank",tone:"amber",badge:"ZREVRANK O(logN)",badgeTone:"amber"},{id:"sse",type:"users",x:665,y:215,label:"Browser UI",sublabel:"Instant Verdict!",tone:"blue"}],edges:[{from:"vm",to:"db",label:"save verdict",packetColor:"purple",speed:1.7},{from:"vm",to:"lb",label:"update score",packetColor:"amber",speed:1.6},{from:"db",to:"sse",label:"SSE push",packetColor:"green",speed:1.5}],legend:[{label:"verdict + live leaderboard",tone:"green"}]}}]},{id:"design-top-k-heavy-hitters",title:"Design Top-K Trending / Heavy Hitters",subtitle:"Finding the Top-100 viral videos/hashtags across 1M events/sec using Count-Min Sketch, Min-Heaps & Multi-Window Rollups.",duration:"10 min",level:"Advanced",companies:["YouTube","Twitter/X","TikTok","Google"],tags:["top k","heavy hitters","count-min sketch","min-heap","streaming","trending","hello interview"],objectives:["Explain why an exact HashMap across 500M distinct items OOMs single stream processors","Use Count-Min Sketch (probabilistic O(1) RAM frequency estimator) + Bounded Size-K Min-Heap","Support arbitrary sliding windows (Last 5 min / 1 hr / 24 hr) via time-bucketed merges"],steps:[{shortLabel:"Count-Min Sketch",stage:"SOLUTION",title:"Count-Min Sketch + Size-K Min-Heap tracks Heavy Hitters in just 10 MB RAM!",body:["Counting exact views for 1 Billion distinct video IDs across 100 stream workers takes **tens of gigabytes of RAM** and massive network shuffles. Yet we ONLY care about the **Top 100 Heavy Hitters**!","**Count-Min Sketch** uses a tiny `d × w` 2D integer matrix (`d = 5` hash functions, `w = 100k` columns = **2 MB RAM!**): on each view, increment `grid[i][hash_i(id)]++`; estimate frequency as **`min_i(grid[i][hash_i(id)])`** (never under-counts!). Pair with a **Min-Heap of size K = 100** to emit local Top-K every 10 seconds!"],callout:{type:"KEY IDEA",text:"For **Fast Path (1-min / 1-hr Trending)**, Count-Min Sketch + Heap gives sub-second results in tiny RAM; for **All-Time Exact Charts**, pair with partitioned Flink/MapReduce exact counters!"},scene:{hud:[{label:"SKETCH RAM",value:"~2–10 MB Fixed!",status:"good"},{label:"UPDATE TIME",value:"O(d) = 5 Hashes",status:"good"},{label:"TOP-K HEAP",value:"Size K = 100",status:"good"},{label:"WINDOWS",value:"5m · 1h · 24h",status:"info"}],nodes:[{id:"kf",type:"queue",x:105,y:215,label:"View Stream",sublabel:"1M events/sec",tone:"amber"},{id:"cm1",type:"hex",x:350,y:120,label:"Fast Path (CMS)",sublabel:"Count-Min + Heap",tone:"green",badge:"2 MB RAM!",badgeTone:"green"},{id:"ex",type:"hex",x:350,y:315,label:"Exact MapReduce",sublabel:"24h / 7d Truth",tone:"purple"},{id:"rd",type:"cache",x:635,y:215,label:"Trending Redis",sublabel:"Top-100 Merged",tone:"blue",badge:"1 ms API read",badgeTone:"blue"}],edges:[{from:"kf",to:"cm1",label:"stream",packetColor:"green",speed:1.4,packetCount:3},{from:"kf",to:"ex",label:"partitioned agg",packetColor:"purple",dashed:!0,speed:2.3},{from:"cm1",to:"rd",label:"flush Top-100 / 10s",packetColor:"blue",speed:1.7},{from:"ex",to:"rd",label:"exact 24h chart",packetColor:"purple",dashed:!0,speed:2.4}],legend:[{label:"Count-Min Sketch fast path",tone:"green"}]}},{shortLabel:"Sliding Buckets",stage:"TECHNIQUE",title:"Multi-Window Trending: Merge 1-Minute Buckets Without Re-Scanning Raw Logs",body:['To serve **"Trending in Last 1 Hour"** AND **"Last 24 Hours"**, store each 1-minute Top-K rollup (or CMS sketch — **Count-Min Sketches are linearly additive!** `CMS(1h) = ∑ CMS(1m_1..60)`!). Adding the new minute and subtracting the 61st minute keeps sliding Top-K fresh every second!'],callout:{type:"INTERVIEW SIGNAL",text:"Noting that **Count-Min Sketches are mergeable across shards and time buckets simply by matrix addition** is an instant Google/Meta Staff-level highlight!"},scene:{hud:[{label:"MERGE PROPERTY",value:"Matrix Sum (CMS)",status:"good"},{label:"FRESHNESS",value:"Every 10 sec",status:"good"},{label:"VELOCITY SCORE",value:"Z-Score Spike",status:"info"},{label:"CACHE READ",value:"CDN / Redis 1ms",status:"good"}],nodes:[{id:"b1",type:"cache",x:145,y:120,label:"Bucket t-1m",sublabel:"CMS Matrix",tone:"green"},{id:"b2",type:"cache",x:145,y:310,label:"Bucket t-60m",sublabel:"Expired (Subtract)",tone:"coral",dim:!0},{id:"m",type:"hex",x:455,y:215,label:"Window Merger",sublabel:"Add New · Drop Old",tone:"purple"},{id:"api",type:"users",x:675,y:215,label:"Trending Tab",sublabel:"Top-100 Videos",tone:"blue"}],edges:[{from:"b1",to:"m",label:"+new min",packetColor:"green",speed:1.6},{from:"b2",to:"m",label:"-old min",packetColor:"coral",dashed:!0,speed:2.3},{from:"m",to:"api",label:"instant rank",packetColor:"blue",speed:1.6}],legend:[{label:"sliding additive window",tone:"green"}]}}]},{id:"design-fb-live-comments",title:"Design Live Video Comments (FB Live / Twitch)",subtitle:"Broadcasting comments to 10M simultaneous viewers on ONE live stream via a Hierarchical SSE Fan-Out Tree.",duration:"10 min",level:"Intermediate",companies:["Meta","Twitch","YouTube","Disney+ Hotstar"],tags:["live comments","facebook live","twitch","sse","fanout tree","pub sub","hello interview"],objectives:["Solve Extreme Single-Room Fan-Out: 10,000 comments/sec broadcast to 10M viewers on ONE video","Replace naive 1-tier Pub/Sub with a Hierarchical Regional SSE Fan-Out Tree","Batch comment frames every 200ms and apply Slow-Mode / Sampling when chat explodes"],steps:[{shortLabel:"Fan-Out Tree",stage:"SOLUTION",title:"Hierarchical SSE Fan-Out Tree scales 1 Live Room to 10M+ Viewers",body:["In 1:1 WhatsApp, 1 write fans out to 1 recipient. In **Facebook Live / Twitch**, 1 comment fans out to **10,000,000 live viewers simultaneously**! A single Redis Pub/Sub node collapses past ~500 subscribers.","**Architecture**: 1) Writers POST comments via standard REST (`POST /videos/{id}/comments`) → persisted to Cassandra + published to **Kafka (`key = video_id`)**. 2) **Regional Aggregator Nodes** subscribe to Kafka and fan out to **100 Edge SSE Push Servers** (each holding 100k read-only SSE streams) — forming a **2-tier broadcast tree**!"],callout:{type:"KEY IDEA",text:"Why **REST (POST) for writing + SSE for reading** instead of WebSockets? 99% of viewers only READ comments! SSE over HTTP/2 scales seamlessly behind standard L7 CDNs/load balancers with native reconnect + `Last-Event-ID` cursor catchup!"},scene:{hud:[{label:"LIVE VIEWERS",value:"10M on 1 Stream",status:"warn"},{label:"PROTOCOL",value:"POST + SSE Tree",status:"good"},{label:"BATCH FRAME",value:"Every 200 ms",status:"good"},{label:"CHAT STORM",value:"Sample / Slow-Mode",status:"good"}],nodes:[{id:"w",type:"users",x:95,y:215,label:"Commenters",sublabel:"POST /comment",tone:"slate"},{id:"kf",type:"queue",x:265,y:215,label:"Kafka Room",sublabel:"video_id Partition",tone:"amber"},{id:"reg",type:"hex",x:455,y:215,label:"Regional Fanout",sublabel:"Batch 200ms Frames",tone:"purple",badge:"Tier 1 Hub",badgeTone:"purple"},{id:"e1",type:"hex",x:655,y:115,label:"SSE Edge 1..50",sublabel:"5M US Viewers",tone:"green"},{id:"e2",type:"hex",x:655,y:315,label:"SSE Edge 51..100",sublabel:"5M EU/APAC Viewers",tone:"green"}],edges:[{from:"w",to:"kf",label:"POST + persist",packetColor:"amber",speed:1.5},{from:"kf",to:"reg",label:"1 stream",packetColor:"purple",speed:1.5},{from:"reg",to:"e1",label:"batched SSE",packetColor:"green",speed:1.4,packetCount:3},{from:"reg",to:"e2",label:"batched SSE",packetColor:"green",speed:1.4,packetCount:3}],legend:[{label:"2-tier SSE broadcast fan-out",tone:"green"}]}},{shortLabel:"Chat Storm Guard",stage:"TECHNIQUE",title:"Human Eyes Can Only Read ~10 Comments/Sec — Batch, Sample & Moderate!",body:['When a goal is scored and 50,000 viewers type "GOAL!!" in 1 second, pushing 50,000 DOM updates/sec crashes mobile browsers! **Edge Fanout** batches frames every **200 ms**, caps broadcast at ~20 comments/sec (always showing the commenter’s *own* post optimistically!), and pipes writes through an async ML toxicity filter!'],callout:{type:"INTERVIEW SIGNAL",text:'Connecting **product physics** ("humans cannot read > 15 comments/sec on a phone") to **systems savings** (sampling/batching cuts mobile egress by 99%) is peak Meta Product Architecture!'},scene:{hud:[{label:"INCOMING BURST",value:"50k msgs/sec",status:"warn"},{label:"PUSH CAP",value:"20 msgs/sec / UI",status:"good"},{label:"EGRESS SAVED",value:"99% Bandwidth!",status:"good"},{label:"OWN COMMENT",value:"Optimistic Echo ✓",status:"good"}],nodes:[{id:"b",type:"queue",x:145,y:215,label:"50k/s Burst",sublabel:"Goal Scored!",tone:"coral"},{id:"s",type:"hex",x:400,y:215,label:"Sampler + Batch",sublabel:"Top 20/sec + VIPs",tone:"green",badge:"protects mobile CPU",badgeTone:"green"},{id:"v",type:"users",x:650,y:215,label:"10M Phones",sublabel:"Smooth 60fps Chat",tone:"blue"}],edges:[{from:"b",to:"s",label:"50k/s raw",packetColor:"coral",speed:1.4},{from:"s",to:"v",label:"smooth 20/s SSE",packetColor:"green",speed:1.7}],legend:[{label:"human-paced sampled broadcast",tone:"green"}]}}]},{id:"design-post-search",title:"Design Real-Time Post Search (Facebook / X)",subtitle:"Near-real-time Inverted Indexes, Document-Partitioned Scatter-Gather, Two-Stage BM25 + ML Personalization & Early Termination.",duration:"11 min",level:"Advanced",companies:["Meta","Twitter/X","Google","Microsoft"],tags:["search","inverted index","elasticsearch","scatter gather","bm25","document partitioning","hello interview"],objectives:["Index 500M new posts/day into searchable inverted index segments in < 10 seconds","Justify Document-Partitioned Sharding (scatter-gather) vs Term-Partitioned Sharding (hot-word bottleneck)","Rank billions of matching documents fast via Two-Stage Retrieval (BM25 + ML Personalization) & Early Termination"],steps:[{shortLabel:"Doc Partitioning",stage:"SOLUTION",title:"Why Document-Partitioned Shards Beat Term-Partitioned Shards",body:['If you shard an Inverted Index by **Term** (`"the"`, `"breaking"` on Shard 1), every multi-word query (`"system design interview"`) must ship huge posting lists across the network to intersect them AND hot words crush 1 shard!',"**Document-Partitioned Sharding** (Elasticsearch, Meta Unicorn, X Earlybird) shards posts by `hash(post_id)` across `N` shards. Each shard builds a local inverted index. On query, the **Aggregator** scatters to all shards in parallel, each shard intersects locally and returns ONLY its **Top 50 IDs**, and the Aggregator merges & ranks!"],callout:{type:"KEY IDEA",text:"Sort posting lists **newest-first** (recency-ordered segments in RAM) so the shard stops scanning as soon as it collects 50 fresh high-engagement hits (**Early Termination**) — cutting search p99 to < 80 ms!"},scene:{hud:[{label:"SHARDING",value:"By post_id (Doc)",status:"good"},{label:"INDEX FRESHNESS",value:"< 5 sec NRT",status:"good"},{label:"SEARCH P99",value:"< 100 ms",status:"good"},{label:"OPTIMIZATION",value:"Early Termination",status:"good"}],nodes:[{id:"q",type:"users",x:95,y:215,label:"Search Query",sublabel:'"microsoft l63"',tone:"slate"},{id:"agg",type:"hex",x:275,y:215,label:"Search Aggregator",sublabel:"Scatter → Merge Top50",tone:"blue"},{id:"s1",type:"db",x:525,y:105,label:"Index Shard 1",sublabel:"Local Inverted + RAM",tone:"green"},{id:"s2",type:"db",x:525,y:215,label:"Index Shard 2",sublabel:"Local Inverted + RAM",tone:"green"},{id:"s3",type:"db",x:525,y:325,label:"Index Shard N",sublabel:"Local Inverted + RAM",tone:"green"},{id:"ml",type:"hex",x:690,y:215,label:"ML Ranker",sublabel:"Social Graph Boost",tone:"purple"}],edges:[{from:"q",to:"agg",label:"query",packetColor:"blue",bidirectional:!0,speed:1.7},{from:"agg",to:"s1",label:"Top 50",packetColor:"green",bidirectional:!0,speed:1.6},{from:"agg",to:"s2",label:"Top 50",packetColor:"green",bidirectional:!0,speed:1.6},{from:"agg",to:"s3",label:"Top 50",packetColor:"green",bidirectional:!0,speed:1.6},{from:"agg",to:"ml",label:"rerank Top 20",packetColor:"purple",bidirectional:!0,speed:1.8}],legend:[{label:"parallel document-partitioned search",tone:"green"}]}},{shortLabel:"NRT Indexing",stage:"TECHNIQUE",title:"Near-Real-Time Indexing: Kafka → Tokenizer → Immutable RAM Segments",body:["New posts flow from Kafka into an **Indexer Pipeline** (lowercase, stem, strip stop-words, extract hashtags/mentions, generate vector embeddings for hybrid search) and append into tiny in-memory Lucene segments refreshed every 1–5 seconds before background segment merging!"],callout:{type:"WATCH OUT",text:"In scatter-gather across 50 shards, 1 slow shard delays everyone! Apply **Hedged Reads to shard replicas** and strict **120 ms shard deadlines** (returning 49/50 shards beats failing the search!)."},scene:{hud:[{label:"INGESTION",value:"Kafka → Indexer",status:"good"},{label:"REFRESH",value:"Every 2 sec RAM",status:"good"},{label:"TAIL GUARD",value:"Partial 49/50 OK",status:"good"},{label:"PRIVACY",value:"Friend/ACL Filter",status:"info"}],nodes:[{id:"kf",type:"queue",x:135,y:215,label:"Post Kafka",sublabel:"6k posts/sec",tone:"amber"},{id:"idx",type:"hex",x:390,y:215,label:"Text + Embed Pipeline",sublabel:"Tokenize · Stem",tone:"purple"},{id:"seg",type:"db",x:645,y:215,label:"NRT RAM Segments",sublabel:"Searchable in 2s!",tone:"green"}],edges:[{from:"kf",to:"idx",label:"new posts",packetColor:"amber",speed:1.6},{from:"idx",to:"seg",label:"append segment",packetColor:"green",speed:1.6}],legend:[{label:"near-real-time search indexing",tone:"green"}]}}]},{id:"design-stock-exchange",title:"Design a Stock Exchange (NASDAQ / Coinbase)",subtitle:"Sub-millisecond Single-Threaded Deterministic Matching Engine, LMAX Disruptor Ring Buffer, Limit Order Book & Event Sourcing.",duration:"12 min",level:"Advanced",companies:["Coinbase","Bloomberg","Citadel","Robinhood"],tags:["stock exchange","matching engine","limit order book","lmax disruptor","event sourcing","fix protocol","low latency"],objectives:["Explain why the core Matching Engine runs SINGLE-THREADED in RAM (zero lock contention, deterministic!)","Design the Price-Time Priority Limit Order Book (Sorted Tree of Price Levels + FIFO Doubly-Linked Queue)","Achieve instant crash recovery & auditability via Event Sourcing Sequencer + Deterministic Replay"],steps:[{shortLabel:"Single-Thread Core",stage:"INSIGHT",title:"Counter-Intuitive Truth: Single-Threaded RAM Engine = 1M+ Orders/Sec!",body:["Most candidates try to put a SQL database or multi-threaded mutexes inside a Stock Exchange Matching Engine — that destroys latency (milliseconds instead of microseconds!) and causes lock contention.","**Real Exchanges (NASDAQ, LMAX, Coinbase)**: Shard by **Stock Symbol** (`AAPL` on Core 1, `MSFT` on Core 2). Each symbol’s **Matching Engine** is a **single-threaded, lock-free, pinned CPU loop** reading from a **Sequencer Ring Buffer (LMAX Disruptor)** with ZERO disk I/O and ZERO network calls on the hot path!"],callout:{type:"KEY IDEA",text:"**Order Book Data Structure**: `Bids` (Max-Tree) and `Asks` (Min-Tree) map `price → DoublyLinkedList<Order>` (FIFO time priority) + `HashMap<orderId, Node*>` for **O(1) cancel** and **O(1) best-price match**!"},scene:{hud:[{label:"MATCH LATENCY",value:"< 10 µs (RAM)",status:"good"},{label:"HOT PATH LOCKS",value:"Zero (1 Thread/Sym)",status:"good"},{label:"ORDER BOOK",value:"Tree + FIFO DLL + Map",status:"info"},{label:"DURABILITY",value:"Event-Sourced Log",status:"good"}],nodes:[{id:"gw",type:"hex",x:100,y:215,label:"FIX Gateway",sublabel:"Risk & Balance Check",tone:"blue"},{id:"seq",type:"queue",x:285,y:215,label:"Sequencer",sublabel:"LMAX Ring + Raft Log",tone:"amber",badge:"strict seq #",badgeTone:"amber"},{id:"me",type:"hex",x:495,y:215,label:"Matching Engine",sublabel:"Single-Thread AAPL",tone:"green",badge:"< 10 µs match!",badgeTone:"green",load:42},{id:"md",type:"hex",x:675,y:120,label:"Market Data",sublabel:"UDP Multicast / WS",tone:"purple"},{id:"bk",type:"hex",x:675,y:315,label:"Hot Standby",sublabel:"Deterministic Replica",tone:"blue"}],edges:[{from:"gw",to:"seq",label:"validated order",packetColor:"blue",speed:1.5},{from:"seq",to:"me",label:"ring buffer",packetColor:"green",speed:1.3,packetCount:3},{from:"me",to:"md",label:"L2 book / trades",packetColor:"purple",speed:1.4},{from:"seq",to:"bk",label:"same input stream",packetColor:"amber",dashed:!0,curve:70,speed:1.6}],legend:[{label:"lock-free deterministic matching loop",tone:"green"}]}},{shortLabel:"Event Sourcing",stage:"SOLUTION",title:"Deterministic Event Sourcing Gives Instant Hot-Standby Failover",body:["How does an in-memory Matching Engine survive a server crash without losing a single trade? Every incoming command passes through the replicated **Input Sequencer Log** FIRST. A **Hot Standby Matching Engine** consumes the exact same ordered sequence in parallel — because matching is 100% deterministic, Standby’s RAM Order Book is **bit-for-bit identical** and takes over in milliseconds!"],callout:{type:"INTERVIEW SIGNAL",text:"Pair this with **Pre-Trade Risk Checks** (verify user has sufficient buying power & reserve cash *before* entering the Sequencer) + **Regulatory Immutable Audit Trail** directly from the Event Log!"},scene:{hud:[{label:"FAILOVER",value:"Hot Standby (< 10ms)",status:"good"},{label:"AUDIT TRAIL",value:"100% Replayable",status:"good"},{label:"RISK ENGINE",value:"Pre-Trade Reserve",status:"good"},{label:"SHARD KEY",value:"By Ticker Symbol",status:"info"}],nodes:[{id:"log",type:"queue",x:165,y:215,label:"Replicated Event Log",sublabel:"Order #1..#9,812,004",tone:"amber"},{id:"p",type:"hex",x:475,y:120,label:"Primary Engine",sublabel:"Live Active",tone:"green"},{id:"s",type:"hex",x:475,y:310,label:"Standby Engine",sublabel:"Bit-Identical RAM",tone:"blue",badge:"instant takeover",badgeTone:"blue"}],edges:[{from:"log",to:"p",label:"exact stream",packetColor:"green",speed:1.5},{from:"log",to:"s",label:"exact stream",packetColor:"blue",speed:1.5}],legend:[{label:"deterministic state-machine replication",tone:"green"}]}}]},{id:"design-hotel-airbnb",title:"Design Hotel & Vacation Booking (Airbnb / Booking)",subtitle:"Geo + Date availability search, zero double-booking via room-type inventory counters + pessimistic/optimistic locks, and payment escrow.",duration:"11 min",level:"Intermediate",companies:["Airbnb","Booking.com","Expedia","Amazon"],tags:["airbnb","hotel booking","overbooking","availability","optimistic locking","elasticsearch","escrow"],objectives:["Model room-type inventory per `(hotel_id, room_type, date)` cleanly (NOT individual room numbers!)","Prevent double-booking across multi-night stays atomically (`check_in .. check_out - 1`)","Separate high-QPS Availability Search (Elasticsearch + Cache) from ACID Reservation Commits"],steps:[{shortLabel:"Date Inventory",stage:"SOLUTION",title:"Model `(hotel_id, room_type_id, date)` Rows — Lock All Stay Nights Atomically!",body:['Hotels don’t sell "Room #304" online — they sell **Room Types** ("King Deluxe", 40 total rooms). Store 1 row per `(hotel_id, room_type_id, date)` holding `(total_inventory, total_reserved)`!','Booking a 3-night stay (May 10–13) runs ONE ACID transaction in PostgreSQL: `SELECT * FROM room_inventory WHERE room_type_id = ? AND date IN ("05-10","05-11","05-12") ORDER BY date FOR UPDATE` → verify `total_reserved + 1 <= total_inventory * 1.1` (if 10% overbooking allowed, else `1.0`) → increment all 3 rows + insert `reservation` with **`Idempotency-Key`**!'],callout:{type:"KEY IDEA",text:"Always `ORDER BY date` in `SELECT ... FOR UPDATE` when locking multi-night date ranges so overlapping bookings (`May 10–12` and `May 11–13`) acquire row locks in the exact same order — zero deadlocks!"},scene:{hud:[{label:"SEARCH QPS",value:"50k/s (Elastic)",status:"info"},{label:"BOOKING TPS",value:"500/s (Postgres)",status:"good"},{label:"DOUBLE BOOK",value:"0% (Multi-Night TX)",status:"good"},{label:"DEADLOCK FIX",value:"ORDER BY date",status:"good"}],nodes:[{id:"u",type:"users",x:100,y:215,label:"Travelers",sublabel:"Search & Book",tone:"slate"},{id:"es",type:"db",x:350,y:115,label:"Elasticsearch",sublabel:"Geo + Filters + Dates",tone:"amber",badge:"50k reads/s",badgeTone:"amber"},{id:"bk",type:"hex",x:350,y:315,label:"Booking Svc",sublabel:"Idem-Key + Escrow",tone:"blue"},{id:"pg",type:"db",x:640,y:315,label:"Postgres Inventory",sublabel:"(room_type, date)",tone:"purple",badge:"ACID lock",badgeTone:"green"},{id:"cdc",type:"queue",x:640,y:115,label:"CDC Sync",sublabel:"Update Search Index",tone:"green"}],edges:[{from:"u",to:"es",label:"browse listings",packetColor:"amber",bidirectional:!0,speed:1.6},{from:"u",to:"bk",label:"POST /book",packetColor:"blue",bidirectional:!0,speed:1.8},{from:"bk",to:"pg",label:"lock 3 nights",packetColor:"purple",bidirectional:!0,speed:1.6},{from:"pg",to:"cdc",label:"sold out event",packetColor:"green",dashed:!0,speed:2.1},{from:"cdc",to:"es",label:"refresh availability",packetColor:"green",dashed:!0,speed:2.1}],legend:[{label:"search vs strict ACID booking",tone:"purple"}]}},{shortLabel:"Airbnb Listings",stage:"TECHNIQUE",title:"Airbnb Unique Homes + Dynamic Pricing + Host Payout Escrow",body:["For **Airbnb** (where `total_inventory == 1` unique home), use a PostgreSQL **Exclusion Constraint (`EXCLUDE USING gist (listing_id WITH =, daterange WITH &&)`)** so overlapping date ranges for the same apartment are physically rejected by the database engine itself! Hold funds in an **Escrow Ledger** and release to Host 24h after check-in."],callout:{type:"INTERVIEW SIGNAL",text:"Citing PostgreSQL’s native `daterange` **GiST Exclusion Constraint** for unique-home Airbnb bookings is a jaw-dropping Senior/Staff database modeling win!"},scene:{hud:[{label:"OVERLAP GUARD",value:"GiST daterange!",status:"good"},{label:"PAYOUT MODEL",value:"24h Post-Checkin",status:"info"},{label:"PRICING",value:"Per-Night Calendar",status:"info"},{label:"CANCELS",value:"Saga Refund Rules",status:"good"}],nodes:[{id:"g",type:"db",x:185,y:215,label:"Postgres GiST",sublabel:"No Overlapping Dates",tone:"purple",badge:"engine-enforced ✓",badgeTone:"green"},{id:"esc",type:"hex",x:545,y:215,label:"Escrow Ledger",sublabel:"Hold → Release Host",tone:"green"}],edges:[{from:"g",to:"esc",label:"confirmed stay",packetColor:"green",speed:1.8}],legend:[{label:"overlap-proof booking + escrow",tone:"green"}]}}]},{id:"design-food-delivery",title:"Design Food Delivery Logistics (DoorDash / Swiggy)",subtitle:"3-sided marketplace (Eater, Restaurant, Courier), ML prep-time ETA, Order Saga & multi-order route batching.",duration:"10 min",level:"Intermediate",companies:["DoorDash","Uber","Swiggy","Amazon"],tags:["doordash","uber eats","swiggy","food delivery","dispatch","eta","batching","saga"],objectives:["Coordinate a 3-sided real-time marketplace with asynchronous restaurant acceptance & courier dispatch","Time courier dispatch using Restaurant Prep-Time ML predictions (not instant dispatch!)","Optimize unit economics via Multi-Order Batching (1 courier picking up 2 nearby orders)"],steps:[{shortLabel:"3-Sided Saga",stage:"SOLUTION",title:"Order Saga Orchestrator + Prep-Time Synchronized Courier Dispatch",body:["Unlike Uber rides (2-sided: rider + driver), **Food Delivery is 3-sided**: if a restaurant takes 25 minutes to bake a pizza, dispatching a courier 2 minutes away immediately wastes 23 minutes of courier idle pay! If you dispatch too late, the pizza sits cold!","The **Order Orchestrator (Saga)** moves `PAID → SENT_TO_RESTAURANT → ACCEPTED (prep_eta = 22m) → DELAYED DISPATCH @ T+14m → PICKED_UP → DELIVERED`. Live GPS streams from courier phone → **H3 Geo Index** → SSE/WS map dot on customer’s screen!"],callout:{type:"KEY IDEA",text:"Menu browsing is **99% read-heavy** (cache whole restaurant menus in Redis/CDN per city); Order/Dispatch is **write-critical** (ACID state machine + idempotent webhooks to restaurant POS tablets)!"},scene:{hud:[{label:"MARKETPLACE",value:"3-Sided Sync",status:"info"},{label:"DISPATCH TIME",value:"Prep_ETA − Drive_ETA",status:"good"},{label:"MENU READS",value:"99% Redis / CDN",status:"good"},{label:"TRACKING",value:"GPS → SSE Map",status:"good"}],nodes:[{id:"e",type:"users",x:95,y:215,label:"Customer",sublabel:"Orders Pizza",tone:"slate"},{id:"orch",type:"hex",x:315,y:215,label:"Order Saga",sublabel:"Prep ML + State",tone:"purple",badge:"synced timing",badgeTone:"green"},{id:"rest",type:"hex",x:590,y:115,label:"Restaurant POS",sublabel:"Prep: 22 min",tone:"amber"},{id:"disp",type:"hex",x:590,y:315,label:"Dispatch + H3",sublabel:"Batch Nearby Couriers",tone:"green"}],edges:[{from:"e",to:"orch",label:"place order + track",packetColor:"blue",bidirectional:!0,speed:1.7},{from:"orch",to:"rest",label:"1. accept + prep ETA",packetColor:"amber",bidirectional:!0,speed:1.9},{from:"orch",to:"disp",label:"2. dispatch @ T+14m",packetColor:"green",speed:1.7}],legend:[{label:"just-in-time 3-sided dispatch",tone:"green"}]}},{shortLabel:"Route Batching",stage:"TECHNIQUE",title:"Solving the Vehicle Routing Problem (VRP) Every 15 Seconds",body:["Instead of greedy 1-order-to-1-driver matching, DoorDash/Uber Eats runs a **Global Batch Optimizer** every 15–30 seconds per metro zone — minimizing total wait + cold-food risk while stacking compatible 2-order routes to cut delivery costs 30%!"],callout:{type:"INTERVIEW SIGNAL",text:"Replacing naive greedy nearest-driver assignment with **15-second Batched Global Bipartite / VRP Optimization** is how real Uber & DoorDash dispatch engines work!"},scene:{hud:[{label:"OPTIMIZER",value:"15s Zone Batching",status:"good"},{label:"STACKED ORDERS",value:"-30% Delivery Cost",status:"good"},{label:"FRESHNESS",value:"Max Cold-Time Cap",status:"info"},{label:"OUTAGE SAFE",value:"POS Heartbeat Guard",status:"good"}],nodes:[{id:"o",type:"queue",x:145,y:215,label:"15s Order Window",sublabel:"Zone: Seattle",tone:"amber"},{id:"opt",type:"hex",x:415,y:215,label:"VRP Solver",sublabel:"Min Wait + Batch",tone:"green"},{id:"c",type:"users",x:660,y:215,label:"Couriers",sublabel:"Stacked Routes ✓",tone:"blue"}],edges:[{from:"o",to:"opt",label:"pending orders",packetColor:"amber",speed:1.8},{from:"opt",to:"c",label:"optimal offers",packetColor:"green",speed:1.7}],legend:[{label:"batched route optimization",tone:"green"}]}}]},{id:"design-online-auction",title:"Design Real-Time Online Auction (eBay / IPL)",subtitle:"Surviving last-10-second sniping storms with atomic Redis Lua CAS, strict monotonic bid ordering, soft-close & live SSE broadcast.",duration:"10 min",level:"Intermediate",companies:["eBay","Amazon","Uber","Microsoft"],tags:["auction","bidding","sniping","redis lua","cas","soft close","sse","contention"],objectives:["Handle 100k concurrent bidders firing snipe bids in the final 5 seconds of a hot auction","Enforce strict monotonic bid ordering (`new_bid >= high + min_increment`) atomically via Redis Lua / Kafka partition","Close auctions reliably with Distributed Timer + Soft-Close Extension + Winner Payment Saga"],steps:[{shortLabel:"Sniping Storm",stage:"SOLUTION",title:"Per-Auction Atomic Redis Lua CAS + Async Postgres Durability + Live SSE",body:["During the final 10 seconds of a collectible drop, **50,000 bidders** slam `POST /auctions/99/bid` simultaneously. Classic SQL updates serialize and crash!","**Solution**: Guard the active high bid inside an **atomic Redis Lua script** (`if now < end_ts and amount >= cur_high + step: SET cur_high, cur_winner; return OK`). Append every accepted bid durably to **Kafka (`key = auction_id`) → Postgres Bid Ledger**, and fan out the new high bid to 100k watchers via an **SSE Pub/Sub tree** in < 100 ms!"],callout:{type:"KEY IDEA",text:"**Soft-Close Anti-Sniping**: If a valid bid lands in the final 10 seconds, atomically extend `end_ts += 30s` inside the same Lua script so fair human bidding beats last-millisecond bots!"},scene:{hud:[{label:"FINAL 10s",value:"50k Snipe Bids/s",status:"warn"},{label:"HIGH-BID GUARD",value:"Atomic Redis Lua",status:"good"},{label:"ANTI-SNIPE",value:"Soft-Close +30s",status:"good"},{label:"WATCHER PUSH",value:"SSE < 100 ms",status:"good"}],nodes:[{id:"b",type:"users",x:95,y:215,label:"50k Bidders",sublabel:"Snipe Storm!",tone:"slate"},{id:"api",type:"hex",x:270,y:215,label:"Bid Service",sublabel:"Pre-Auth + RL",tone:"blue"},{id:"lua",type:"cache",x:475,y:120,label:"Redis Lua CAS",sublabel:"high = $1,250 ✓",tone:"green",badge:"strict monotonic",badgeTone:"green"},{id:"kf",type:"queue",x:475,y:315,label:"Kafka → SQL",sublabel:"Durable Audit",tone:"amber"},{id:"sse",type:"hex",x:675,y:215,label:"SSE Broadcast",sublabel:"100k Watchers",tone:"purple"}],edges:[{from:"b",to:"api",label:"POST /bid",packetColor:"coral",speed:1.4,packetCount:3},{from:"api",to:"lua",label:"atomic CAS",packetColor:"green",bidirectional:!0,speed:1.4},{from:"api",to:"kf",label:"accepted bids",packetColor:"amber",speed:1.7},{from:"lua",to:"sse",label:"new high $1,250",packetColor:"purple",speed:1.5}],legend:[{label:"atomic CAS high-bid path",tone:"green"}]}},{shortLabel:"Proxy & Close",stage:"TECHNIQUE",title:"Auto-Proxy Bidding + Deterministic Auction Close & Settlement Saga",body:["Support eBay-style **Proxy Auto-Bidding** (`max_bid = $2,000` kept secret on server; Lua automatically outbids challengers by `$10` up to `$2,000`!). When `now >= end_ts`, the **Closing Worker** locks the auction `CLOSED`, verifies final high bid from the durable Kafka/SQL log, and triggers the **Winner Settlement Payment Saga** (falling back to 2nd highest bidder if payment fails!)."],callout:{type:"INTERVIEW SIGNAL",text:"What if Redis crashes mid-auction? Rebuild `cur_high` deterministically by replaying the auction’s **Kafka partition / Postgres bid log** (always `acks=all` before returning `200 OK` on high-value auctions!)."},scene:{hud:[{label:"PROXY BID",value:"Secret Max Cap",status:"info"},{label:"REDIS CRASH",value:"Replay Kafka Log",status:"good"},{label:"SETTLEMENT",value:"Charge → Escrow",status:"good"},{label:"DEFAULT FALLBACK",value:"Offer #2 Bidder",status:"info"}],nodes:[{id:"clk",type:"hex",x:145,y:215,label:"Close Scheduler",sublabel:"now >= end_ts",tone:"amber"},{id:"ver",type:"db",x:400,y:215,label:"Bid Ledger DB",sublabel:"Final Winner Proof",tone:"purple"},{id:"pay",type:"hex",x:650,y:215,label:"Settlement Saga",sublabel:"Charge + Notify",tone:"green"}],edges:[{from:"clk",to:"ver",label:"freeze auction",packetColor:"purple",speed:1.7},{from:"ver",to:"pay",label:"charge winner",packetColor:"green",speed:1.7}],legend:[{label:"reliable auction close saga",tone:"green"}]}}]},{id:"design-video-conferencing",title:"Design Video Conferencing (Microsoft Teams / Zoom)",subtitle:"Microsoft flagship design: WebSocket Signaling, STUN/TURN NAT traversal, Mesh vs MCU vs SFU, Simulcast & Cloud Recording.",duration:"12 min",level:"Advanced",companies:["Microsoft","Zoom","Google","Meta"],tags:["microsoft teams","zoom","webrtc","sfu","mcu","stun","turn","simulcast","video call"],objectives:["Separate Control Plane Signaling (WebSockets SDP/ICE) from UDP Media Plane (SRTP)","Compare P2P Mesh vs MCU vs SFU (Selective Forwarding Unit) for 2 vs 50 vs 1,000 participants","Deliver smooth video across fiber AND weak 3G laptops simultaneously via Simulcast / SVC"],steps:[{shortLabel:"Signaling & NAT",stage:"SETUP",title:"WebRTC Signaling (SDP/ICE) + STUN/TURN Punch Through Firewalls",body:["Most laptops hide behind corporate NAT firewalls without a public IP! **Step 1 (Signaling)**: Participants connect over WebSockets to a **Signaling Server** to exchange **SDP** (supported codecs: VP9/AV1/Opus) and **ICE candidates**.","**Step 2 (NAT Traversal)**: Clients query a lightweight **STUN** server to learn their public IP:port for direct UDP hole-punching. If a strict enterprise firewall blocks direct UDP (~15% of calls), traffic relays transparently through a **TURN** server over UDP/TCP :443!"],callout:{type:"KEY IDEA",text:"Video calls use **UDP (SRTP)**, NOT TCP! Retransmitting a dropped video frame from 400 ms ago causes horrible stutter — it is far better to drop 1 frame and keep live audio/video synchronized!"},scene:{hud:[{label:"SIGNALING",value:"WebSocket SDP/ICE",status:"info"},{label:"MEDIA PROTO",value:"UDP SRTP (No TCP!)",status:"good"},{label:"NAT PUNCH",value:"STUN (85%) / TURN",status:"good"},{label:"E2E LATENCY",value:"< 150 ms Target",status:"good"}],nodes:[{id:"a",type:"users",x:110,y:215,label:"Alice (NAT)",sublabel:"Teams Client",tone:"blue"},{id:"sig",type:"hex",x:380,y:95,label:"Signaling + STUN",sublabel:"SDP / ICE Setup",tone:"purple"},{id:"turn",type:"hex",x:380,y:325,label:"TURN Relay",sublabel:"Fallback :443",tone:"amber",dim:!0},{id:"b",type:"users",x:650,y:215,label:"Bob (Corp FW)",sublabel:"Teams Client",tone:"green"}],edges:[{from:"a",to:"sig",label:"SDP/ICE",packetColor:"purple",dashed:!0,speed:2},{from:"b",to:"sig",label:"SDP/ICE",packetColor:"purple",dashed:!0,speed:2},{from:"a",to:"b",label:"direct UDP SRTP (< 80ms)",packetColor:"green",bidirectional:!0,speed:1.4},{from:"a",to:"turn",label:"15% firewall relay",packetColor:"amber",dashed:!0,speed:2.3}],legend:[{label:"direct encrypted SRTP",tone:"green"},{label:"signaling control plane",tone:"purple"}]}},{shortLabel:"SFU & Simulcast",stage:"SOLUTION",title:"SFU + Simulcast Scales 50-Person Meetings Without Melting Server CPUs",body:["**P2P Mesh** requires `N-1` uploads per user — explodes past 4 people! **MCU** decodes and re-encodes every stream into 1 mosaic on the server (huge GPU cost + latency). **SFU (Selective Forwarding Unit — Zoom, Teams, Meet)** receives 1 upload per speaker and **forwards encrypted UDP packets directly without decoding** (10× cheaper CPU!).","**Simulcast / SVC**: Alice uploads 3 tiny layered qualities (`1080p`, `480p`, `180p`). The **SFU** forwards `1080p` to fiber viewers on desktop and `180p` to a commuter on 3G — AND only forwards active speakers’ video in 500-person town halls!"],callout:{type:"INTERVIEW SIGNAL",text:"For **Microsoft Teams Global Calls**, cascade **Multi-Region SFUs** over Microsoft’s private fiber backbone (US-SFU ↔ EU-SFU sends 1 single stream across the Atlantic instead of 50 redundant user streams!)."},scene:{hud:[{label:"ARCHITECTURE",value:"Cascaded SFU",status:"good"},{label:"ADAPTIVE VIDEO",value:"Simulcast / SVC",status:"good"},{label:"ACTIVE SPEAKER",value:"Audio-Level Route",status:"good"},{label:"RECORDING",value:"Composite Bot → S3",status:"info"}],nodes:[{id:"sp",type:"users",x:100,y:215,label:"Speaker (US)",sublabel:"1080p+480p+180p",tone:"blue"},{id:"sfu1",type:"hex",x:315,y:215,label:"SFU US-West",sublabel:"Zero Decode Relay",tone:"green",badge:"Simulcast",badgeTone:"green",load:34},{id:"sfu2",type:"hex",x:525,y:215,label:"SFU EU-West",sublabel:"Private Backbone",tone:"purple",load:31},{id:"d1",type:"users",x:690,y:115,label:"Fiber Desktop",sublabel:"Gets 1080p ✓",tone:"green"},{id:"d2",type:"users",x:690,y:315,label:"3G Mobile",sublabel:"Gets 180p ✓",tone:"amber"}],edges:[{from:"sp",to:"sfu1",label:"1 SVC upload",packetColor:"blue",speed:1.5},{from:"sfu1",to:"sfu2",label:"1 trans-ocean hop",packetColor:"purple",speed:1.6},{from:"sfu2",to:"d1",label:"1080p layer",packetColor:"green",speed:1.5},{from:"sfu2",to:"d2",label:"180p layer",packetColor:"amber",speed:1.9}],legend:[{label:"cascaded SFU simulcast routing",tone:"green"}]}}]}]},g={id:"mod-13-in-the-wild",number:"13",title:"In The Wild (Big Tech)",track:"hld",lessons:[{id:"wild-shopify-inventory",title:"Shopify: Inventory Reservations (Redis → MySQL 8)",subtitle:"How Shopify handles $5.1M/min Black Friday flash sales without overselling by moving from Redis to MySQL 8 `SKIP LOCKED`.",duration:"14 min",level:"Advanced",companies:["Shopify","Amazon","Stripe","Microsoft"],tags:["shopify","skip locked","mysql","redis","contention","flash sale","inventory","proxysql","in the wild"],objectives:["Understand the Checkout Seam: why Overselling hurts customers and Underselling loses merchant revenue","Diagnose why splitting state across Redis (reservations) + MySQL (ledger) causes irreversible drift","Eliminate hot-row lock contention by modeling One Row Per Reservable Unit + `SELECT ... FOR UPDATE SKIP LOCKED`","Scale past operational ProxySQL connection-pool limits with bounded unit pools and SQL comment tracing"],steps:[{shortLabel:"Checkout Seam",stage:"SETUP",title:"$5.1M/min Black Friday: The Checkout Seam Dilemma",body:['During a sneaker drop or Black Friday peak (**$5.1M+ sales/minute**), 50,000 buyers race for the last **100 units** of a product. When Alice clicks **"Complete Purchase"**, payment processing with Stripe/banks takes **2–5 seconds**.','Shopify must hold her unit during that window: fail to hold and you **oversell** (two buyers charged for 1 item → canceled orders & angry merchants); hold carelessly and abandoned carts **undersell** (showing "Sold Out" while units sit unbought)!'],callout:{type:"KEY IDEA",text:"Inventory reservation is a textbook **High-Contention Distributed State** problem: every millisecond of lock wait during a flash sale multiplies across tens of thousands of simultaneous checkouts."},scene:{hud:[{label:"PEAK GMV",value:"$5.1M / min",status:"warn"},{label:"HOLD WINDOW",value:"2 – 5 sec Pay",status:"info"},{label:"OVERSELL",value:"0% Tolerated",status:"bad"},{label:"UNDERSELL",value:"Lost Revenue",status:"warn"}],nodes:[{id:"buyers",type:"users",x:115,y:215,label:"50k Buyers",sublabel:"100 Units Left!",tone:"slate"},{id:"chk",type:"hex",x:380,y:215,label:"Checkout Seam",sublabel:"Reserve → Charge",tone:"amber",badge:"extreme contention",badgeTone:"amber",load:84},{id:"psp",type:"hex",x:645,y:120,label:"Payment PSP",sublabel:"2–5s Card Auth",tone:"blue"},{id:"inv",type:"db",x:645,y:310,label:"Inventory Ledger",sublabel:"100 Units Exact",tone:"purple"}],edges:[{from:"buyers",to:"chk",label:"flash spike",packetColor:"coral",speed:1.3,packetCount:3},{from:"chk",to:"psp",label:"charge card (3s)",packetColor:"blue",bidirectional:!0,speed:2.3},{from:"chk",to:"inv",label:"atomic hold",packetColor:"purple",bidirectional:!0,speed:1.7}],legend:[{label:"flash-sale burst",tone:"coral"},{label:"payment & reservation seam",tone:"purple"}]}},{shortLabel:"Redis Split Bug",stage:"PROBLEM",title:"Why the Legacy Architecture (Redis Holds + MySQL Ledger) Drifted",body:["For years, Shopify kept temporary holds in **Redis** (fast atomic Lua counters + cron expiration) and permanent merchant inventory in **MySQL**.","**Fatal Flaw — The Cross-System Seam**: Because Redis and MySQL cannot participate in a single ACID transaction, a pod crash or network timeout *between* committing the MySQL order and releasing the Redis hold left **ghost reservations** (permanent underselling) or missed holds (overselling!)."],callout:{type:"WATCH OUT",text:"Whenever two separate datastores (Redis + SQL) must agree on a strict financial/inventory invariant, network failures between them inevitably create split-brain drift!"},scene:{hud:[{label:"HOLDS STORE",value:"Redis Lua",status:"warn"},{label:"LEDGER STORE",value:"MySQL Primary",status:"info"},{label:"SINGLE ACID TX",value:"Impossible ✕",status:"bad"},{label:"FAILURE MODE",value:"Ghost Drift / Oversell",status:"bad"}],nodes:[{id:"app",type:"hex",x:140,y:215,label:"Checkout Pod",sublabel:"Crash Mid-Step!",tone:"coral",badge:"dual-write seam",badgeTone:"rose"},{id:"rd",type:"cache",x:485,y:115,label:"Redis Holds",sublabel:"Reserved: 100",tone:"amber",badge:"out of sync!",badgeTone:"rose"},{id:"my",type:"db",x:485,y:315,label:"MySQL Ledger",sublabel:"Committed: 94",tone:"purple",badge:"6 ghost units",badgeTone:"amber"}],edges:[{from:"app",to:"rd",label:"1. Lua DECR ✓",packetColor:"amber",speed:1.7},{from:"app",to:"my",label:"2. Crash before COMMIT ✕",packetColor:"coral",dashed:!0,speed:2.5}],legend:[{label:"completed hold",tone:"amber"},{label:"failed cross-DB write",tone:"coral"}]}},{shortLabel:"Hot Counter Lock",stage:"PROBLEM",title:"Moving to MySQL Fixes Atomicity — But 1 Counter Row Creates a Lock Pileup!",body:["Moving reservations into **MySQL** puts reservation + order ledger inside **ONE single ACID transaction** — zero cross-system drift! ","Naive attempt: keep 1 row per SKU (`UPDATE inventory SET available = available - 1 WHERE sku_id = 42 AND available > 0`). Under a flash sale, **10,000 concurrent transactions queue up serially behind ONE single InnoDB row lock**, exhausting DB connections and timing out!"],callout:{type:"INTERVIEW SIGNAL",text:"You cannot fix hot-row lock serialization by adding more CPU cores! Contention on a single counter row must be solved with a **data-modeling shift**."},scene:{hud:[{label:"SINGLE ACID TX",value:"Yes (MySQL)",status:"good"},{label:"DATA MODEL",value:"1 Counter Row",status:"bad"},{label:"LOCK WAITERS",value:"10,000 Serialized",status:"bad"},{label:"THROUGHPUT",value:"Collapsed!",status:"bad"}],nodes:[{id:"t1",type:"hex",x:120,y:110,label:"Checkout #1",sublabel:"Holds Row Lock",tone:"amber"},{id:"t2",type:"hex",x:120,y:215,label:"Checkout #2..5k",sublabel:"BLOCKED waiting",tone:"coral",dim:!0},{id:"t3",type:"hex",x:120,y:320,label:"Checkout #5k..10k",sublabel:"TIMEOUT 504!",tone:"coral",dim:!0},{id:"row",type:"db",x:525,y:215,label:"SKU #42 Row",sublabel:"qty = 100 (1 Lock!)",tone:"coral",badge:"serialized bottleneck",badgeTone:"rose",load:99}],edges:[{from:"t1",to:"row",label:"exclusive X-lock",packetColor:"amber",speed:2},{from:"t2",to:"row",label:"blocked!",packetColor:"coral",dashed:!0,speed:3.1},{from:"t3",to:"row",label:"lock wait timeout",packetColor:"coral",dashed:!0,speed:3.5}],legend:[{label:"single-row lock pileup",tone:"coral"}]}},{shortLabel:"SKIP LOCKED Pool",stage:"SOLUTION",title:"Shopify’s Breakthrough: Bounded Pool of Unit Rows + `FOR UPDATE SKIP LOCKED`",body:["Instead of 1 counter row for 100 sneakers, Shopify stores a **bounded pool of individual reservable unit rows** (like movie seats — 1 row = 1 reservable unit, capped and dynamically replenished as stock drains so a 10M-unit SKU never bloats the table!).",'Each checkout runs MySQL 8’s **`SELECT id FROM reservations WHERE sku_id = 42 AND status = "AVAILABLE" LIMIT 1 FOR UPDATE SKIP LOCKED`**. Checkout #1 locks Unit Row #1; Checkout #2 **instantly skips locked Row #1 and grabs Row #2 with ZERO blocking!**'],callout:{type:"KEY IDEA",text:"`FOR UPDATE SKIP LOCKED` transforms serialized N-way lock contention into lock-free parallel claims inside a single rock-solid ACID relational transaction!"},changes:["+Replaced 1 hot counter row with a bounded pool of reservable unit rows","+MySQL 8 `FOR UPDATE SKIP LOCKED` lets 100 checkouts grab distinct rows simultaneously","+Reservation + Order Ledger commit in ONE atomic MySQL ACID transaction (0% drift!)"],scene:{hud:[{label:"ACID DRIFT",value:"0% (1 Database)",status:"good"},{label:"LOCK CONTENTION",value:"Skipped Instantly!",status:"good"},{label:"PATTERN",value:"Unit Pool + SKIP LOCK",status:"good"},{label:"TABLE SIZE",value:"Bounded + Replenish",status:"good"}],nodes:[{id:"c1",type:"hex",x:115,y:110,label:"Checkout #1",sublabel:"SKIP LOCKED",tone:"green"},{id:"c2",type:"hex",x:115,y:215,label:"Checkout #2",sublabel:"SKIP LOCKED",tone:"blue"},{id:"c3",type:"hex",x:115,y:320,label:"Checkout #3",sublabel:"SKIP LOCKED",tone:"purple"},{id:"u1",type:"db",x:525,y:105,label:"Unit Row #1",sublabel:"Locked by #1 ✓",tone:"green",callout:"zero wait"},{id:"u2",type:"db",x:525,y:220,label:"Unit Row #2",sublabel:"Skipped #1 → #2 ✓",tone:"blue",callout:"parallel!"},{id:"u3",type:"db",x:525,y:335,label:"Unit Row #3",sublabel:"Skipped #1,#2 → #3 ✓",tone:"purple",callout:"parallel!"}],edges:[{from:"c1",to:"u1",label:"claim row 1",packetColor:"green",speed:1.5},{from:"c2",to:"u2",label:"skip → row 2",packetColor:"blue",speed:1.5},{from:"c3",to:"u3",label:"skip → row 3",packetColor:"purple",speed:1.5}],legend:[{label:"parallel zero-wait unit claims",tone:"green"}]}},{shortLabel:"ProxySQL & Ops",stage:"TECHNIQUE",title:"Production Bottleneck Reality: ProxySQL Connections & SQL Tracing",body:["During Black Friday load testing, MySQL CPU wasn’t even the first limit — **connection pool exhaustion at ProxySQL** was! Holding a DB transaction open *while calling Stripe over HTTP* starves DB connections in milliseconds.","**Golden Rule**: Keep DB transactions short (milliseconds!). Reserve the row & **COMMIT** immediately with `expires_at = NOW() + 5m`, call Stripe *outside* the DB transaction, then open a tiny 2nd transaction to flip `RESERVED → SOLD`! Shopify also embeds **SQL comment tags** (`/* checkout_id=.. */`) to trace exact bottleneck queries in production."],callout:{type:"INTERVIEW SIGNAL",text:"Never hold a relational DB transaction open across an external HTTP call (Stripe/shipping API)! Commit the short `HELD` state first, call PSP outside the TX, then finalize atomically."},scene:{hud:[{label:"TX #1 (HOLD)",value:"3 ms → COMMIT",status:"good"},{label:"STRIPE HTTP",value:"Outside DB TX ✓",status:"good"},{label:"TX #2 (CONFIRM)",value:"2 ms → SOLD",status:"good"},{label:"PROXYSQL POOL",value:"Healthy (22% Used)",status:"good"}],nodes:[{id:"app",type:"hex",x:115,y:215,label:"Checkout Svc",sublabel:"Short TX Discipline",tone:"blue"},{id:"px",type:"hex",x:345,y:120,label:"ProxySQL Pool",sublabel:"Multiplexed Conns",tone:"green",load:22},{id:"db",type:"db",x:615,y:120,label:"MySQL 8 Shard",sublabel:"SKIP LOCKED (3ms)",tone:"purple"},{id:"psp",type:"hex",x:485,y:315,label:"Stripe PSP",sublabel:"Called Outside TX!",tone:"amber",badge:"no held DB conn",badgeTone:"green"}],edges:[{from:"app",to:"px",label:"1. 3ms hold + 3. confirm",packetColor:"green",bidirectional:!0,speed:1.5},{from:"px",to:"db",label:"fast SQL",packetColor:"purple",bidirectional:!0,speed:1.5},{from:"app",to:"psp",label:"2. charge (outside TX)",packetColor:"amber",bidirectional:!0,speed:2.2}],legend:[{label:"fast 3ms ACID SQL",tone:"green"},{label:"external PSP outside DB lock",tone:"amber"}]}}],deepDive:{codeTitle:"Shopify Pattern — MySQL 8 / PostgreSQL `FOR UPDATE SKIP LOCKED` SQL",codeSnippets:{sql:`-- Phase 1: Claim N reservable unit rows in parallel with ZERO lock waiting (3ms TX!)
BEGIN;

SELECT id
FROM inventory_reservation_units
WHERE shop_id = :shop_id
  AND sku_id = :sku_id
  AND (status = 'AVAILABLE' OR (status = 'HELD' AND expires_at < NOW()))
LIMIT :requested_qty
FOR UPDATE SKIP LOCKED;

-- Verify returned row count == :requested_qty (else ROLLBACK -> 409 Sold Out!)
UPDATE inventory_reservation_units
SET status = 'HELD',
    checkout_token = :checkout_token,
    expires_at = NOW() + INTERVAL 5 MINUTE
WHERE id IN (:claimed_ids);

COMMIT; -- Release MySQL connection IMMEDIATELY before calling Stripe!

-- Phase 2 (after Stripe PaymentIntent succeeds): Finalize atomically in same MySQL DB
BEGIN;
UPDATE inventory_reservation_units
SET status = 'COMMITTED', order_id = :order_id
WHERE checkout_token = :checkout_token AND status = 'HELD' AND expires_at > NOW();
INSERT INTO inventory_ledger (sku_id, order_id, delta) VALUES (:sku_id, :order_id, -:requested_qty);
COMMIT;`},tradeoffs:[{option:"Redis Lua + MySQL Ledger",bestWhen:"Soft approximate counters where occasional 0.01% drift is tolerable",pros:"Sub-millisecond holds, offloads MySQL",cons:"Two-system seam causes ghost inventory or overselling on crashes"},{option:"MySQL Single Counter Row",bestWhen:"Low-contention normal e-commerce SKUs (< 50 TPS/SKU)",pros:"Simple schema, 1 row per SKU",cons:"Catastrophic lock serialization during flash sales"},{option:"MySQL Bounded Unit Pool + SKIP LOCKED",bestWhen:"High-contention flash sales requiring 100% strict zero-oversell ACID",pros:"Single-DB atomicity + parallel lock-skipping claims",cons:"Requires bounded pool replenishment & strict short-TX connection discipline"}],failureModes:[{title:"Merchant Uploads 10 Million Stock Units for One SKU",mitigation:"Never pre-insert 10M unit rows! Cap the live reservation pool (e.g., max 2,000 rows per hot SKU) and replenish asynchronously from the parent ledger count as units are committed.",interviewProbe:"What happens to your `inventory_reservation_units` table if a merchant sets stock = 1,000,000?"}]}},{id:"wild-slack-kafka-redis",title:"Slack: Kafka in Front of Redis Job Queues",subtitle:"How Slack’s `JQRelay` stopped Redis OOM crashes and dropped background jobs across 1B+ daily async tasks.",duration:"10 min",level:"Advanced",companies:["Slack","Salesforce","Microsoft","Amazon"],tags:["slack","kafka","redis","jqrelay","job queue","backpressure","in the wild"],objectives:["Understand why pure Redis job queues OOM or drop jobs during consumer slowdowns & failovers","Design the Kafka → `JQRelay` → Redis pattern for durable shock absorption + fast worker execution","Handle priority lanes, retries, and regional failover without losing a single notification or webhook"],steps:[{shortLabel:"Redis OOM",stage:"PROBLEM",title:"Why pure Redis job queues crash when downstream workers slow down",body:["Slack originally pushed every async job (push notifications, link unfurls, webhooks, Slackbot triggers — **billions/day**) directly into **Redis lists** because Redis pops in < 1 ms.","**Failure Mode**: When Apple APNs or a database shard slowed down for 10 minutes, jobs piled up in Redis RAM → Redis hit `maxmemory` OOM and crashed! Even worse, Redis async replication drops queued jobs during primary failover."],callout:{type:"WATCH OUT",text:"Redis is an in-memory cache/fast queue — NEVER make RAM your only durable shock absorber for unbounded traffic bursts!"},scene:{hud:[{label:"BACKLOG SPIKE",value:"20M Jobs Queued",status:"bad"},{label:"REDIS MEMORY",value:"99% OOM Crash!",status:"bad"},{label:"FAILOVER",value:"Jobs Lost ✕",status:"bad"},{label:"FIX",value:"Kafka Buffer First",status:"good"}],nodes:[{id:"web",type:"hex",x:120,y:215,label:"Slack Web",sublabel:"100k jobs/s",tone:"blue"},{id:"rd",type:"cache",x:400,y:215,label:"Redis Queue",sublabel:"RAM Exhausted!",tone:"coral",badge:"OOM Crash",badgeTone:"rose",load:99},{id:"wk",type:"hex",x:645,y:215,label:"Slow Workers",sublabel:"APNs Stalled",tone:"amber",dim:!0}],edges:[{from:"web",to:"rd",label:"unbounded push",packetColor:"coral",speed:1.3,packetCount:3},{from:"rd",to:"wk",label:"trickle pop",packetColor:"amber",dashed:!0,speed:3.4}],legend:[{label:"RAM queue overflow",tone:"coral"}]}},{shortLabel:"Kafka + JQRelay",stage:"SOLUTION",title:"Kafka Absorbs Terabytes on Disk; `JQRelay` Meters Jobs Into Redis Safely",body:["Slack kept their fast Redis worker fleet unchanged and put **Apache Kafka** right in front! Producers write every job durably to **Kafka** (`acks=all`, disk-backed terabyte retention).","A lightweight Go service (**`JQRelay`**) reads from Kafka and feeds Redis **ONLY when Redis queue depth is below a safe memory watermark**! If workers stall for 2 hours, backlog sits safely on Kafka disks while Redis stays tiny and healthy at 15% RAM!"],callout:{type:"INTERVIEW SIGNAL",text:"Whenever you need **durable unbounded buffering + fast Redis-style fine-grained worker retries/delayed jobs**, proposing **Kafka → Relay → Redis** is a Staff-level pattern straight from Slack’s engineering blog!"},changes:["+Kafka absorbs unlimited multi-hour backlogs safely on replicated disks","+`JQRelay` pauses pulling when Redis hits memory backpressure threshold","~Zero OOM crashes and zero lost jobs during Redis primary failovers"],scene:{hud:[{label:"DURABILITY",value:"Kafka Disk (RF=3)",status:"good"},{label:"REDIS RAM",value:"Capped ≤ 30% ✓",status:"good"},{label:"BACKPRESSURE",value:"JQRelay Pauses",status:"good"},{label:"RETRIES / DELAY",value:"Fast Redis ZSET",status:"good"}],nodes:[{id:"web",type:"hex",x:95,y:215,label:"Slack Web",sublabel:"Durable Produce",tone:"blue"},{id:"kf",type:"queue",x:265,y:215,label:"Kafka Log",sublabel:"TB Disk Buffer",tone:"amber",badge:"shock absorber",badgeTone:"green"},{id:"rel",type:"hex",x:455,y:215,label:"JQRelay (Go)",sublabel:"Backpressure Gate",tone:"green",badge:"checks Redis RAM",badgeTone:"green"},{id:"rd",type:"cache",x:645,y:120,label:"Redis Workers",sublabel:"Tiny Hot Window",tone:"purple",load:24},{id:"dlq",type:"db",x:645,y:315,label:"Retry / DLQ",sublabel:"Safe Replay",tone:"slate"}],edges:[{from:"web",to:"kf",label:"100k/s durable",packetColor:"amber",speed:1.5},{from:"kf",to:"rel",label:"metered pull",packetColor:"green",speed:1.8},{from:"rel",to:"rd",label:"if RAM < 30%",packetColor:"purple",speed:1.7},{from:"rd",to:"dlq",label:"replay on crash",packetColor:"amber",dashed:!0,speed:2.5}],legend:[{label:"backpressure-controlled relay",tone:"green"}]}}]},{id:"wild-figma-multiplayer",title:"Figma: Multiplayer Editing on Simplified CRDTs",subtitle:"How Figma syncs millions of vector canvas nodes in real time using Fractional Indexing + Property-Level LWW Trees.",duration:"10 min",level:"Advanced",companies:["Figma","Google","Microsoft","Notion"],tags:["figma","crdt","fractional indexing","lww","multiplayer","canvas","in the wild"],objectives:["Understand why Figma skipped complex P2P OT/CRDTs by using a single authoritative room server","Order arbitrary nested canvas layers without renumbering siblings via Fractional Indexing","Support clean per-user Undo/Redo in a multiplayer session without undoing teammates’ work"],steps:[{shortLabel:"Property LWW",stage:"SOLUTION",title:"Central Authority + Property-Level LWW Tree = 10× Simpler than Academic CRDTs",body:["A Figma document is a tree of nodes (`Canvas → Frame → Button → Text`). Instead of locking a whole object, Figma syncs **atomic `(node_id, property_name, value)` mutations**! If Alice moves a rectangle’s `x` while Bob changes its `fillColor`, both merge cleanly with zero conflict!","Because every file connects to **one authoritative Rust WebSocket server**, the server assigns strict arrival order (**Last-Write-Wins per property**) — skipping heavy P2P vector clocks while keeping **instant optimistic local UI updates**!"],callout:{type:"KEY IDEA",text:"**Fractional Indexing** orders sibling layers using strings/rationals between neighbors: moving Layer C between `0.2` and `0.3` assigns `0.25` — updating **1 single field** instead of shifting 500 array indexes!"},scene:{hud:[{label:"CONFLICT UNIT",value:"(Node, Property)",status:"good"},{label:"LAYER ORDER",value:"Fractional Index",status:"good"},{label:"UI FEEL",value:"0ms Optimistic",status:"good"},{label:"UNDO SCOPE",value:"Per-User Inverse",status:"good"}],nodes:[{id:"a",type:"users",x:105,y:120,label:"Alice",sublabel:"btn.x = 240",tone:"blue"},{id:"b",type:"users",x:105,y:310,label:"Bob",sublabel:"btn.color = #0F9",tone:"purple"},{id:"srv",type:"hex",x:400,y:215,label:"Rust Doc Server",sublabel:"Property LWW Merge",tone:"green",badge:"zero conflict!",badgeTone:"green"},{id:"s3",type:"db",x:655,y:215,label:"Checkpoint S3",sublabel:"Every 30–60s",tone:"amber"}],edges:[{from:"a",to:"srv",label:"prop delta",packetColor:"blue",bidirectional:!0,speed:1.5},{from:"b",to:"srv",label:"prop delta",packetColor:"purple",bidirectional:!0,speed:1.5},{from:"srv",to:"s3",label:"periodic snapshot",packetColor:"amber",dashed:!0,speed:2.5}],legend:[{label:"property-level multiplayer sync",tone:"green"}]}},{shortLabel:"Multiplayer Undo",stage:"TECHNIQUE",title:"How Multiplayer Undo Never Erases Your Teammate’s Edits",body:["If Alice changes color `Red → Blue`, Bob changes `x: 10 → 50`, and Alice presses `Ctrl+Z`, naive snapshot undo would revert Bob’s move! Figma maintains a **per-user local inverse property stack** (`undo` only emits `color = Red`), updating the stack cleanly whenever remote edits overwrite the same property."],callout:{type:"INTERVIEW SIGNAL",text:"Naming **Fractional Indexing** (also used by Linear & Jira to drag-reorder Kanban cards in O(1) DB writes!) + **Property-Level LWW** impresses any Staff/Principal interviewer!"},scene:{hud:[{label:"ALICE UNDO",value:"Reverts Color Only",status:"good"},{label:"BOB POSITION",value:"Preserved ✓",status:"good"},{label:"DRAG REORDER",value:"1 Row Update (Frac)",status:"good"},{label:"OFFLINE REJOIN",value:"Reconcile Deltas",status:"info"}],nodes:[{id:"st",type:"queue",x:165,y:215,label:"Alice Undo Stack",sublabel:"color: Blue→Red",tone:"purple"},{id:"doc",type:"hex",x:525,y:215,label:"Live Canvas Node",sublabel:"x=50 (Bob) · Red ✓",tone:"green"}],edges:[{from:"st",to:"doc",label:"apply property inverse",packetColor:"green",speed:1.7}],legend:[{label:"surgical property undo",tone:"green"}]}}]},{id:"wild-meta-zgateway-tao",title:"Meta: Scaling DBs to Millions of Clients (ZGateway & TAO)",subtitle:"How Meta shields ZippyDB & MySQL using `ZGateway` multiplexing proxies, TAO graph caching, and Memcached Leases.",duration:"11 min",level:"Advanced",companies:["Meta","Google","Microsoft","Amazon"],tags:["meta","zgateway","tao","memcached leases","connection pooling","zippydb","in the wild"],objectives:["Solve the N×M connection explosion when 100k app servers connect to 10k DB shards","Design a stateless Database Proxy Tier (`ZGateway`) for multiplexing, routing, caching & shedding","Prevent Cache Stampedes and Stale-Set race bugs using Meta’s Memcached Leases"],steps:[{shortLabel:"ZGateway Proxy",stage:"SOLUTION",title:"Decoupling 100k Clients from 10k Shards via `ZGateway` Proxy Layer",body:["If 100,000 stateless web servers each open 10 TCP connections to every database shard, the database spends 100% of its RAM managing **1,000,000 sockets** and shard topology updates become a nightmare!","Meta inserts a dedicated **`ZGateway` stateless proxy tier** between clients and ZippyDB shards. Clients talk to any local ZGateway; ZGateway **multiplexes connections**, caches shard routing maps, batches hot requests, enforces per-tenant rate limits, and sheds load cleanly!"],callout:{type:"KEY IDEA",text:"Same pattern everywhere at scale: **ProxySQL / PgBouncer** (SQL), **Envoy** (RPC), **ZGateway** (Meta KV), and **Twemproxy / Redis Proxy**!"},scene:{hud:[{label:"APP SERVERS",value:"100,000+ Clients",status:"info"},{label:"DB SOCKETS",value:"Cut by 98% ✓",status:"good"},{label:"ROUTING",value:"Cached at ZGateway",status:"good"},{label:"OVERLOAD",value:"Adaptive Shedding",status:"good"}],nodes:[{id:"app",type:"users",x:105,y:215,label:"100k Web Pods",sublabel:"Thin Clients",tone:"slate"},{id:"zg",type:"hex",x:365,y:215,label:"ZGateway Tier",sublabel:"Mux · Route · RL · Cache",tone:"green",badge:"98% fewer sockets",badgeTone:"green",load:36},{id:"s1",type:"db",x:645,y:120,label:"ZippyDB Shard 1",sublabel:"RocksDB + Paxos",tone:"purple",load:34},{id:"s2",type:"db",x:645,y:310,label:"ZippyDB Shard N",sublabel:"RocksDB + Paxos",tone:"purple",load:32}],edges:[{from:"app",to:"zg",label:"any gateway",packetColor:"blue",speed:1.5,packetCount:3},{from:"zg",to:"s1",label:"pooled mux",packetColor:"green",speed:1.6},{from:"zg",to:"s2",label:"pooled mux",packetColor:"green",speed:1.6}],legend:[{label:"multiplexed proxy pool",tone:"green"}]}},{shortLabel:"Memcached Leases",stage:"TECHNIQUE",title:"Meta’s Memcached Leases solve BOTH Thundering Herd & Stale Sets in 64 bits",body:['In Meta’s famous NSDI paper ("Scaling Memcache at Facebook"), two subtle bugs broke caching at billion-QPS scale: **Thundering Herds** (10k misses hitting MySQL) and **Stale Sets** (slow Reader A writes an outdated DB value into cache *after* Writer B already invalidated the key!).',"**Fix — 64-bit Lease Token**: On a cache miss, Memcached hands a **Lease Token** ONLY to the 1st caller (telling the other 9,999 to retry in 10 ms). If a write deletes the key before Caller 1 finishes, Memcached **invalidates the lease token**, rejecting Caller 1’s stale `SET` automatically!"],callout:{type:"INTERVIEW SIGNAL",text:"Explaining **Memcached Leases** (64-bit invalidatable token fixing BOTH Thundering Herd and Stale-Set race conditions!) is peak Meta E5/E6 Staff-level mastery!"},scene:{hud:[{label:"CALLER #1",value:"Gets Lease #881",status:"good"},{label:"CALLERS #2..999",value:"Wait 10ms (No DB!)",status:"good"},{label:"IF KEY DELETED",value:"Lease #881 Revoked",status:"warn"},{label:"STALE WRITE",value:"Rejected ✓",status:"good"}],nodes:[{id:"r1",type:"hex",x:130,y:120,label:"Reader 1 (Slow)",sublabel:"Lease #881",tone:"amber"},{id:"w",type:"hex",x:130,y:310,label:"Writer (New)",sublabel:"DELETE key!",tone:"green"},{id:"mc",type:"cache",x:475,y:215,label:"Memcached",sublabel:"Lease #881 Invalidated",tone:"purple",badge:"blocks stale SET ✓",badgeTone:"green"}],edges:[{from:"w",to:"mc",label:"invalidate lease",packetColor:"green",speed:1.6},{from:"r1",to:"mc",label:"stale SET(#881) ✕",packetColor:"coral",dashed:!0,speed:2.3}],legend:[{label:"lease-protected cache consistency",tone:"green"}]}}]},{id:"wild-spotify-exabyte-lake",title:"Spotify: Sub-Second Queries on an Exabyte Data Lake",subtitle:"How Spotify’s Random Access Parquet (RAP) serves low-latency point lookups straight from GCS/S3 without duplicating data into Bigtable.",duration:"9 min",level:"Advanced",companies:["Spotify","Google","Databricks","Microsoft"],tags:["spotify","parquet","rap","data lake","exabyte","point lookup","bloom filter","in the wild"],objectives:["Understand the Lakehouse Serving Paradox: cheap Petabyte/Exabyte storage vs costly NoSQL serving copies","See how sorted Parquet Row Groups + Byte-Range Reads + Bloom/Offset Indexes unlock sub-50ms lookups","Know when to keep read-only ML features in Object Storage vs moving to DynamoDB/Bigtable"],steps:[{shortLabel:"The Copy Tax",stage:"PROBLEM",title:"Copying 500 TB of ML features from Parquet into Bigtable costs millions/year",body:["Every night, Spark/Dataflow computes billions of ML recommendation features and writes cheap **Parquet files** to GCS/S3 ($0.02/GB). Historically, serving those features online meant bulk-loading all 500 TB into **Bigtable / Cassandra** — paying 10× more for storage, compaction, and dual-pipeline maintenance!"],callout:{type:"WATCH OUT",text:"For read-only, nightly-refreshed datasets (ML embeddings, wrapped stats, historical archives), paying for 24/7 hot mutable NoSQL clusters is huge FinOps waste."},scene:{hud:[{label:"LAKE COST",value:"$0.02 / GB (GCS)",status:"good"},{label:"HOT NOSQL COPY",value:"10× More Cost!",status:"bad"},{label:"WORKLOAD",value:"Read-Only Batch",status:"info"},{label:"GOAL",value:"Query Lake Direct",status:"good"}],nodes:[{id:"sp",type:"hex",x:135,y:215,label:"Spark ML Job",sublabel:"Nightly Features",tone:"blue"},{id:"gcs",type:"db",x:390,y:120,label:"GCS Parquet",sublabel:"Cheap Exabyte",tone:"green"},{id:"bt",type:"db",x:390,y:315,label:"Hot Bigtable",sublabel:"10× Duplicate Cost",tone:"coral",badge:"expensive copy",badgeTone:"rose"},{id:"api",type:"hex",x:645,y:215,label:"Serving API",sublabel:"Needs 1 User Key",tone:"purple"}],edges:[{from:"sp",to:"gcs",label:"write parquet",packetColor:"green",speed:1.8},{from:"gcs",to:"bt",label:"costly ETL copy",packetColor:"coral",dashed:!0,speed:2.3},{from:"bt",to:"api",label:"point lookup",packetColor:"purple",speed:1.8}],legend:[{label:"avoidable duplicate storage cost",tone:"coral"}]}},{shortLabel:"RAP Indexing",stage:"SOLUTION",title:"Random Access Parquet (RAP): Hash-Bucketed + Sorted + HTTP Range Reads",body:["Spotify’s **RAP** writes Parquet files **bucketed & sorted by `entity_id`** alongside a tiny **Offset/Key Index**. To look up `user_42`, the serving layer hashes to the exact file, binary-searches the cached tiny index in RAM, and issues **1 single HTTP `Range: bytes=40960-45056` read** straight to GCS/S3 (cached on local NVMe)!","Result: **~20–40 ms point lookups** directly off an Exabyte object-store lake at **1/10th the cost**!"],callout:{type:"INTERVIEW SIGNAL",text:"For **immutable batch-generated datasets** (recommendations, analytics lookups, ML feature snapshots), **Sorted Object-Store + HTTP Byte-Range Index + Local NVMe Cache** eliminates entire NoSQL clusters!"},scene:{hud:[{label:"QUERY TIME",value:"20 – 40 ms Direct",status:"good"},{label:"FETCH METHOD",value:"HTTP Byte-Range",status:"good"},{label:"COST SAVINGS",value:"~85% Cheaper ✓",status:"good"},{label:"MUTABLE WRITES",value:"No (Batch Swap)",status:"info"}],nodes:[{id:"api",type:"hex",x:120,y:215,label:"RAP Reader",sublabel:"hash(user_42)",tone:"blue"},{id:"idx",type:"cache",x:375,y:120,label:"RAM Offset Index",sublabel:"file + byte_offset",tone:"green",badge:"0.1 ms lookup",badgeTone:"green"},{id:"gcs",type:"db",x:640,y:215,label:"GCS/S3 Parquet",sublabel:"Range: 40KB..44KB",tone:"purple",badge:"1 range read",badgeTone:"purple"}],edges:[{from:"api",to:"idx",label:"find exact bytes",packetColor:"green",bidirectional:!0,speed:1.5},{from:"api",to:"gcs",label:"HTTP Range GET (4KB)",packetColor:"purple",bidirectional:!0,speed:1.8}],legend:[{label:"direct byte-range lake lookup",tone:"purple"}]}}]},{id:"wild-stripe-uber-netflix-ops",title:"Stripe Idempotency, Uber Docstore & Netflix Adaptive Limits",subtitle:"Three iconic Staff-level production patterns: Stripe atomic recovery points, Uber append-only sharded MySQL, and Netflix Little’s Law load shedding.",duration:"11 min",level:"Advanced",companies:["Stripe","Uber","Netflix","Microsoft"],tags:["stripe","idempotency","recovery points","uber docstore","netflix","adaptive concurrency","in the wild"],objectives:["Build Stripe-grade Idempotency Keys with parameter-mismatch rejection and atomic recovery points","Understand Uber’s Docstore/Schemaless (MySQL shards + append-only versioning + Flux CDC)","Replace brittle static thread limits with Netflix Adaptive Concurrency Limits (AIMD / Vegas)"],steps:[{shortLabel:"Stripe Idem",stage:"TECHNIQUE",title:"Stripe’s Rocket-Grade Idempotency: Recovery Points + Param Hash Guard",body:["Basic idempotency caches the final response. **Stripe goes 3 levels deeper**: 1) Hash the request body (`amount, currency, card`) — if a client reuses the same `Idempotency-Key` with a *different* amount, reject immediately with `422 Parameter Mismatch`! 2) Lock the key row (`IN_PROGRESS`) so concurrent duplicate retries wait/409 instead of double-executing!","3) Save **Atomic Recovery Points** inside Postgres after every external side effect (e.g., `CREATED → CHARGED_CARD → LEDGER_POSTED`) so a crash mid-request resumes cleanly from the exact last safe checkpoint!"],callout:{type:"INTERVIEW SIGNAL",text:'Mentioning **Request Parameter Hash Verification + `IN_PROGRESS` Concurrent Lock + Atomic Recovery Points** turns a standard "add an idempotency key" comment into a Stripe Principal-level answer!'},scene:{hud:[{label:"PARAM GUARD",value:"SHA-256 Body Hash",status:"good"},{label:"CONCURRENT DUP",value:"IN_PROGRESS Lock",status:"good"},{label:"CRASH RESUME",value:"Recovery Points",status:"good"},{label:"DOUBLE CHARGE",value:"0% Guaranteed ✓",status:"good"}],nodes:[{id:"c",type:"users",x:105,y:215,label:"API Retry",sublabel:"Key + Body Hash",tone:"slate"},{id:"id",type:"db",x:350,y:215,label:"Idempotency Row",sublabel:"State: CHARGED",tone:"purple",badge:"recovery point",badgeTone:"purple"},{id:"rec",type:"hex",x:635,y:120,label:"Resume Step 3",sublabel:"Post Ledger Only!",tone:"green"},{id:"err",type:"hex",x:635,y:310,label:"422 Mismatch",sublabel:"If Amount Changed",tone:"coral",dim:!0}],edges:[{from:"c",to:"id",label:"check key + hash",packetColor:"purple",speed:1.6},{from:"id",to:"rec",label:"resume safely",packetColor:"green",speed:1.6},{from:"id",to:"err",label:"hash mismatch",packetColor:"coral",dashed:!0,speed:2.3}],legend:[{label:"checkpointed idempotent recovery",tone:"green"}]}},{shortLabel:"Netflix Vegas",stage:"SOLUTION",title:"Netflix Adaptive Concurrency Limits & Uber Docstore Sharding",body:["**Netflix Concurrency Limits**: Static rate limits break whenever a DB slows down or CPU scales up! Inspired by **TCP Vegas congestion control**, each service continuously compares **current latency vs baseline min latency (`RTT_min`)**: when queueing latency creeps up, it automatically shrinks max in-flight concurrency (`AIMD`) and sheds excess requests early — keeping p99 flat even under 5× overload!","**Uber Docstore**: Wraps battle-tested sharded **MySQL InnoDB** nodes with a stateless Query Engine, Raft-managed consensus failover, and **Flux CDC** streaming every change into Kafka/Elasticsearch!"],callout:{type:"KEY IDEA",text:"Static limits guess capacity; **Adaptive Concurrency Limits** measure real-time queueing delay via Little’s Law (`L = λW`) and self-tune automatically!"},scene:{hud:[{label:"CONTROL LOOP",value:"TCP Vegas / AIMD",status:"good"},{label:"SIGNAL",value:"Queue Latency Drift",status:"info"},{label:"UBER STORAGE",value:"Sharded MySQL + CDC",status:"good"},{label:"OVERLOAD P99",value:"Protected Flat ✓",status:"good"}],nodes:[{id:"in",type:"users",x:105,y:215,label:"5× Traffic",sublabel:"Overload Spike",tone:"coral"},{id:"lim",type:"hex",x:375,y:215,label:"Adaptive Limiter",sublabel:"RTT > Base → Shrink L",tone:"amber",badge:"self-tuning",badgeTone:"green"},{id:"svc",type:"hex",x:645,y:215,label:"Backend Pool",sublabel:"p99 Flat @ 22 ms!",tone:"green",load:64}],edges:[{from:"in",to:"lim",label:"5× burst",packetColor:"coral",speed:1.4,packetCount:3},{from:"lim",to:"svc",label:"safe concurrency L",packetColor:"green",bidirectional:!0,speed:1.6}],legend:[{label:"self-tuning overload defense",tone:"green"}]}}]}]},h=[{id:"osi-ip-tcp-udp",title:"OSI Model, IP, TCP vs UDP",subtitle:"All 7 OSI layers, IPv4/CIDR/IPv6/NAT, TCP reliability & congestion control vs low-latency UDP.",duration:"10 min",level:"Beginner",companies:["Microsoft","Google","Cloudflare","Amazon"],tags:["osi model","tcp","udp","ipv4","ipv6","nat","cidr","flow control","congestion control"],objectives:["Map real systems components (BGP, L4 NLB, L7 Envoy, TLS, HTTP/gRPC) onto the 7 OSI layers","Explain IPv4/CIDR, Private RFC-1918 subnets, NAT traversal, and IPv6","Compare TCP (3-way handshake, flow/congestion control, ordered delivery) vs UDP (gaming, VoIP, DNS, QUIC)"],steps:[{shortLabel:"OSI & IP/NAT",stage:"SETUP",title:"Where System Design Lives on the 7-Layer OSI & TCP/IP Stack",body:["Every network hop encapsulates data down the **OSI Stack**: **L7 Application** (HTTP/3, gRPC, DNS), **L6 Presentation** (TLS encryption, Protobuf), **L5 Session**, **L4 Transport** (TCP/UDP ports + L4 Load Balancers), **L3 Network** (IPv4/IPv6 routing & BGP Anycast), **L2 Data Link** (Ethernet MAC / Switches), **L1 Physical** (Fiber optics).","Because IPv4 only has `2^32 ≈ 4.3 Billion` addresses, **NAT (Network Address Translation)** lets thousands of private `10.0.x.x` VPC servers or home devices share one public IP via port mapping — while **IPv6** provides `2^128` unique addresses!"],callout:{type:"KEY IDEA",text:"In interviews, you operate primarily at **L3 (IP/BGP Anycast)**, **L4 (TCP/UDP NLB)**, and **L7 (HTTP/gRPC/WebSocket ALB & API Gateway)**."},scene:{hud:[{label:"L7 (APP)",value:"HTTP · gRPC · WS",status:"good"},{label:"L4 (TRANSPORT)",value:"TCP / UDP Ports",status:"info"},{label:"L3 (NETWORK)",value:"IPv4/IPv6 · Anycast",status:"info"},{label:"NAT ROLE",value:"Private ↔ Public IP",status:"good"}],nodes:[{id:"l7",type:"hex",x:135,y:215,label:"L7 App/TLS",sublabel:"Envoy / HTTP / gRPC",tone:"green"},{id:"l4",type:"hex",x:350,y:215,label:"L4 TCP/UDP",sublabel:"NLB / Port :443",tone:"blue"},{id:"l3",type:"hex",x:545,y:120,label:"L3 IP + NAT",sublabel:"10.0.1.5 ↔ Pub IP",tone:"purple"},{id:"l1",type:"hex",x:545,y:315,label:"L1–L2 Fiber",sublabel:"Ethernet / BGP",tone:"amber"}],edges:[{from:"l7",to:"l4",label:"segment",packetColor:"blue",speed:1.7},{from:"l4",to:"l3",label:"IP packet",packetColor:"purple",speed:1.7},{from:"l3",to:"l1",label:"wire frames",packetColor:"amber",speed:1.7}],legend:[{label:"packet encapsulation down OSI",tone:"blue"}]}},{shortLabel:"TCP vs UDP",stage:"TRADEOFF",title:"TCP Guarantees Order & Reliability; UDP Trades Guarantees for Raw Speed",body:["**TCP** enforces **3-Way Handshake**, **ACK + Retransmission**, **Flow Control** (receiver window prevents overflowing slow clients), and **Congestion Control** (Slow Start + AIMD/BBR prevents melting routers) — ideal for payments, APIs, SQL, and files.","**UDP** is connectionless fire-and-forget with an 8-byte header and ZERO retransmit stalls — mandatory for **WebRTC video calls (Zoom/Teams)**, **FPS multiplayer gaming**, **DNS**, and as the foundation of **HTTP/3 QUIC**!"],callout:{type:"INTERVIEW SIGNAL",text:"Never design live audio/video calls over TCP! One lost packet forces TCP to stall all subsequent frames waiting for retransmit — causing robotic voice freeze!"},scene:{hud:[{label:"TCP HEADER",value:"20B · Ordered + ACK",status:"info"},{label:"UDP HEADER",value:"8B · Zero Stall",status:"good"},{label:"USE TCP FOR",value:"REST · DB · Banking",status:"good"},{label:"USE UDP FOR",value:"VoIP · Games · QUIC",status:"good"}],nodes:[{id:"src",type:"users",x:115,y:215,label:"Sender",sublabel:"App Stream",tone:"slate"},{id:"tcp",type:"hex",x:430,y:120,label:"TCP Channel",sublabel:"ACK · Retransmit · BBR",tone:"blue",callout:"100% lossless"},{id:"udp",type:"hex",x:430,y:315,label:"UDP Datagrams",sublabel:"Drop Late Frames OK",tone:"green",callout:"lowest latency"}],edges:[{from:"src",to:"tcp",label:"ordered ACKs",packetColor:"blue",bidirectional:!0,speed:2},{from:"src",to:"udp",label:"fast stream",packetColor:"green",speed:1.3,packetCount:3}],legend:[{label:"reliable ordered TCP",tone:"blue"},{label:"low-latency UDP",tone:"green"}]}}],deepDive:{tradeoffs:[{option:"TCP (BBR / Cubic)",bestWhen:"HTTP/1.1, HTTP/2, gRPC, Databases, Kafka, Payments",pros:"Guaranteed ordered delivery, built-in congestion & flow control",cons:"1-RTT handshake, Head-of-Line blocking on lost packets"},{option:"UDP",bestWhen:"WebRTC calls, Online FPS games, DNS lookups, Telemetry, QUIC",pros:"Zero handshake, 8-byte header, no retransmission stalls",cons:"Packets can drop or arrive out of order (app must handle if needed)"}]}}],y=[{id:"proxies-forward-reverse",title:"Forward vs Reverse Proxy & API Gateway",subtitle:"Client-side shielding (Forward Proxy/VPN) vs Server-side routing, TLS termination, caching & API Gateways.",duration:"8 min",level:"Beginner",companies:["Cloudflare","Microsoft","Amazon","Google"],tags:["forward proxy","reverse proxy","api gateway","nginx","envoy","vpn","bff"],objectives:["Distinguish Forward Proxy (acts for clients) from Reverse Proxy (acts for origin servers)","Clarify how Reverse Proxy, Load Balancer, and API Gateway overlap and differ","Apply the Backend-for-Frontend (BFF) gateway pattern cleanly for Web vs Mobile clients"],steps:[{shortLabel:"Forward vs Reverse",stage:"SETUP",title:"Forward Proxy hides the Client; Reverse Proxy hides the Servers",body:["A **Forward Proxy** sits in front of **clients** (corporate firewall, school filter, VPN, egress NAT gateway): the destination website sees the Proxy’s IP, NEVER the individual user’s internal IP. Used for egress compliance, caching outbound downloads, and bypassing geo-blocks.","A **Reverse Proxy** (NGINX, Envoy, Cloudflare) sits in front of **backend servers**: clients think they are talking directly to `api.company.com`, while the Reverse Proxy handles **TLS termination, gzip/Brotli compression, static caching, DDoS WAF, and hiding internal IPs**!"],callout:{type:"KEY IDEA",text:"Mental shortcut: **Forward Proxy protects/controls Clients** going OUT to the internet; **Reverse Proxy protects/accelerates Servers** receiving traffic coming IN!"},scene:{hud:[{label:"FORWARD PROXY",value:"Client-Side Shield",status:"info"},{label:"REVERSE PROXY",value:"Server-Side Shield",status:"good"},{label:"API GATEWAY",value:"L7 Auth + RL + BFF",status:"good"},{label:"LOAD BALANCER",value:"Health + Spread",status:"good"}],nodes:[{id:"c",type:"users",x:95,y:215,label:"Corp Users",sublabel:"Private LAN",tone:"slate"},{id:"fp",type:"hex",x:265,y:215,label:"Forward Proxy",sublabel:"Hides Client IP",tone:"amber",callout:"egress"},{id:"rp",type:"hex",x:475,y:215,label:"Reverse Proxy",sublabel:"TLS · WAF · Cache",tone:"green",callout:"ingress"},{id:"s1",type:"hex",x:665,y:125,label:"Origin 1",sublabel:"Hidden IP",tone:"blue"},{id:"s2",type:"hex",x:665,y:305,label:"Origin 2",sublabel:"Hidden IP",tone:"blue"}],edges:[{from:"c",to:"fp",label:"outbound",packetColor:"amber",speed:1.8},{from:"fp",to:"rp",label:"public internet",packetColor:"green",bidirectional:!0,speed:1.9},{from:"rp",to:"s1",label:"internal",packetColor:"blue",speed:1.6},{from:"rp",to:"s2",label:"internal",packetColor:"blue",speed:1.6}],legend:[{label:"forward egress proxy",tone:"amber"},{label:"reverse ingress proxy",tone:"green"}]}},{shortLabel:"API Gateway / BFF",stage:"TECHNIQUE",title:"API Gateway & Backend-for-Frontend (BFF) without Building a Bottleneck",body:["An **API Gateway** (Kong, AWS API GW, Azure APIM, Envoy) is a specialized L7 Reverse Proxy tailored for microservices: **JWT Auth verification, Rate Limiting, Protocol Translation (REST → gRPC), Canary Routing, and Request Aggregation**.","With **BFF (Backend-for-Frontend)**, Mobile gets a tiny compact JSON gateway while Web gets a rich dashboard gateway — **Watch Out**: never put complex business logic inside your API Gateway, or it turns into a giant single-point-of-failure monolith!"],callout:{type:"WATCH OUT",text:"Keep API Gateways **thin and stateless** — cross-cutting concerns only (Auth, Rate Limit, Routing, Tracing), NEVER core domain business rules!"},scene:{hud:[{label:"MOBILE BFF",value:"Compact Payloads",status:"good"},{label:"WEB BFF",value:"Rich Aggregation",status:"good"},{label:"ANTI-PATTERN",value:"Fat Business GW",status:"bad"},{label:"UPSTREAM",value:"Internal gRPC",status:"info"}],nodes:[{id:"m",type:"users",x:110,y:125,label:"iOS / Android",sublabel:"Low Bandwidth",tone:"slate"},{id:"w",type:"users",x:110,y:305,label:"Web Browser",sublabel:"Rich UI",tone:"slate"},{id:"bm",type:"hex",x:375,y:125,label:"Mobile BFF",sublabel:"Trimmed JSON",tone:"green"},{id:"bw",type:"hex",x:375,y:305,label:"Web BFF",sublabel:"Full GraphQL",tone:"purple"},{id:"core",type:"hex",x:645,y:215,label:"Core gRPC Svcs",sublabel:"Shared Domain",tone:"blue"}],edges:[{from:"m",to:"bm",label:"HTTPS",packetColor:"green",speed:1.6},{from:"w",to:"bw",label:"HTTPS",packetColor:"purple",speed:1.6},{from:"bm",to:"core",label:"gRPC",packetColor:"blue",speed:1.6},{from:"bw",to:"core",label:"gRPC",packetColor:"blue",speed:1.6}],legend:[{label:"tailored BFF edge gateways",tone:"green"}]}}]},{id:"clustering-ha",title:"Clustering, Heartbeats & Fencing",subtitle:"Shared-Nothing vs Shared-Disk clusters, Active-Active vs Active-Passive failover, Split-Brain & STONITH fencing.",duration:"8 min",level:"Intermediate",companies:["Microsoft","Amazon","Oracle","Google"],tags:["clustering","heartbeat","split-brain","stonith","shared-nothing","active-passive","quorum"],objectives:["Compare Shared-Nothing (Cassandra/Postgres shards) vs Shared-Disk (Aurora/SAN) cluster architectures","Detect node deaths accurately with Heartbeats & Phi Accrual Failure Detectors","Eliminate dual-primary Split-Brain corruption using Quorum + STONITH hardware/API fencing"],steps:[{shortLabel:"Cluster Types",stage:"SETUP",title:"Shared-Nothing Scales Linearly; Shared-Storage Simplifies Failover",body:["A **Cluster** links multiple servers to act as one resilient system. In **Shared-Nothing** clusters (Cassandra, Kafka, sharded MySQL), every node owns its own CPU, RAM, and local NVMe disk — zero central storage lock, linear horizontal scale!","In **Shared-Storage** cloud clusters (AWS Aurora, Azure SQL Hyperscale, Neon), stateless compute nodes share a distributed quorum storage layer — failing over to a new primary takes seconds with ZERO data copying!"],callout:{type:"KEY IDEA",text:"Modern cloud-native databases decouple **Stateless Compute** from **Distributed Quorum Storage** (Aurora / AlloyDB / Neon) to get fast failover AND effortless read-replica scaling!"},scene:{hud:[{label:"SHARED-NOTHING",value:"Kafka · Cassandra",status:"good"},{label:"SHARED-STORAGE",value:"Aurora · Neon · SQL",status:"good"},{label:"FAILURE DETECT",value:"Phi Accrual Beat",status:"info"},{label:"SPLIT-BRAIN FIX",value:"Quorum + STONITH",status:"good"}],nodes:[{id:"c1",type:"hex",x:185,y:120,label:"Compute Primary",sublabel:"Stateless SQL",tone:"green",callout:"writes"},{id:"c2",type:"hex",x:565,y:120,label:"Compute Standby",sublabel:"Instant Promote",tone:"blue",callout:"reads"},{id:"st",type:"db",x:375,y:310,label:"Distributed Storage",sublabel:"6-Way Replicated Log",tone:"purple",badge:"decoupled layer",badgeTone:"purple"}],edges:[{from:"c1",to:"st",label:"WAL write",packetColor:"green",speed:1.6},{from:"c2",to:"st",label:"read pages",packetColor:"blue",bidirectional:!0,speed:1.8},{from:"c1",to:"c2",label:"heartbeat",packetColor:"amber",dashed:!0,speed:2.2}],legend:[{label:"decoupled compute-storage cluster",tone:"green"}]}},{shortLabel:"STONITH Fence",stage:"SOLUTION",title:"Preventing Two Active Primaries (Split-Brain) with Quorum & STONITH",body:["In a 2-node Active-Passive cluster, if the heartbeat cable snaps, Standby assumes Primary died and promotes itself — now **BOTH nodes accept writes** and corrupt data permanently (**Split-Brain**)!",'**Fix**: 1) Require an **odd-node Quorum (3+ witnesses / etcd)** to hold leadership, and 2) **STONITH ("Shoot The Other Node In The Head")** — power-fence or revoke the old primary’s storage/cloud API lease BEFORE the new primary accepts a single write!'],callout:{type:"INTERVIEW SIGNAL",text:'Never design a 2-node HA cluster without a **3rd Tie-Breaker / Witness Node (Quorum)** + **Fencing Token / STONITH** — 2 nodes alone cannot distinguish "peer died" from "heartbeat link dropped"!'},scene:{hud:[{label:"WITNESS NODE",value:"3rd Quorum Vote",status:"good"},{label:"OLD PRIMARY",value:"Fenced / Revoked",status:"warn"},{label:"NEW PRIMARY",value:"Epoch #8 Safe ✓",status:"good"},{label:"DATA CORRUPTION",value:"Zero",status:"good"}],nodes:[{id:"w",type:"hex",x:380,y:90,label:"etcd Witness",sublabel:"Breaks 2-Node Tie",tone:"purple"},{id:"old",type:"hex",x:165,y:290,label:"Old Primary",sublabel:"Lease Revoked!",tone:"coral",dim:!0,callout:"fenced"},{id:"new",type:"hex",x:595,y:290,label:"New Primary",sublabel:"2/3 Votes Won ✓",tone:"green",callout:"active"}],edges:[{from:"w",to:"new",label:"grant epoch #8",packetColor:"green",speed:1.6},{from:"w",to:"old",label:"STONITH revoke",packetColor:"coral",dashed:!0,speed:2.4}],legend:[{label:"quorum-fenced failover",tone:"green"}]}}]}],m=[{id:"storage-block-file-object-raid",title:"Block, File, Object Storage & RAID",subtitle:"EBS/NVMe Block vs NFS/EFS File vs S3 Object Storage, plus RAID 0/1/5/6/10 vs Cloud Erasure Coding.",duration:"9 min",level:"Beginner",companies:["Amazon","Microsoft","Google","Dropbox"],tags:["block storage","file storage","object storage","raid","erasure coding","ebs","nfs","san","nas"],objectives:["Choose correctly between Block (EBS/NVMe), File (NFS/EFS/SMB), and Object Storage (S3/Azure Blob)","Contrast RAID 0, 1, 5, 6, and 10 performance vs redundancy overhead","Explain why cloud Object Stores replace 3× replication with Reed-Solomon Erasure Coding (1.3×–1.5× overhead!)"],steps:[{shortLabel:"3 Storage Types",stage:"SETUP",title:"Block for Databases, File for Shared POSIX Apps, Object for Massive Blobs",body:["1. **Block Storage** (AWS EBS, Azure Managed Disk, Local NVMe): Splits disk into raw fixed-size blocks with ultra-low sub-ms random I/O — required for **Databases (Postgres, Kafka, OS boot disks)** (typically mounted by 1 VM at a time).","2. **File Storage** (NFS, AWS EFS, Azure Files): Shared hierarchical folder tree mounted by hundreds of servers simultaneously — great for shared configs, ML datasets, and legacy enterprise apps.","3. **Object Storage** (S3, Azure Blob, GCS): Flat HTTP key-value blobs + metadata, infinitely scalable, 11 nines durability, cheapest per TB — mandatory for **images, videos, backups, and Iceberg data lakes**!"],callout:{type:"KEY IDEA",text:"Never mount S3/Blob as a live SQL database disk (no fast in-place byte overwrites!), and never store 50 TB of user videos on expensive EBS Block Storage!"},scene:{hud:[{label:"BLOCK (EBS/NVME)",value:"< 1ms · Databases",status:"good"},{label:"FILE (NFS/EFS)",value:"Shared POSIX Tree",status:"info"},{label:"OBJECT (S3/BLOB)",value:"HTTP · Exabyte Cheap",status:"good"},{label:"DURABILITY",value:"99.999999999%",status:"good"}],nodes:[{id:"blk",type:"db",x:145,y:215,label:"Block (EBS)",sublabel:"Postgres / Kafka",tone:"purple",callout:"sub-ms IOPS"},{id:"fil",type:"db",x:390,y:215,label:"File (EFS/NFS)",sublabel:"Shared Folders",tone:"blue",callout:"POSIX mount"},{id:"obj",type:"db",x:635,y:215,label:"Object (S3)",sublabel:"Videos / Lakehouse",tone:"green",callout:"$0.02 / GB"}],edges:[{from:"blk",to:"fil",label:"shared access →",packetColor:"blue",dashed:!0,speed:2.3},{from:"fil",to:"obj",label:"infinite scale →",packetColor:"green",dashed:!0,speed:2.3}],legend:[{label:"storage tier selection",tone:"green"}]}},{shortLabel:"RAID & Erasure",stage:"TECHNIQUE",title:"RAID 10 for Fast Local DBs; Erasure Coding Saves 50% Storage in Cloud Blobs",body:["**RAID 0** (Striping): 2× speed, **0 redundancy** (1 dead disk loses all!). **RAID 1** (Mirroring): 50% usable space, survives 1 dead disk. **RAID 10** (Striped Mirrors): Fast random writes + high fault tolerance — standard for hot databases!","**Erasure Coding (Reed-Solomon 10+4)** (used by S3, Azure Storage, HDFS): Splits an object into **10 data chunks + 4 parity chunks** across 14 racks — tolerates **4 simultaneous failures** with only **1.4× storage overhead** instead of 3× (300%) replication!"],callout:{type:"INTERVIEW SIGNAL",text:"Citing **Reed-Solomon Erasure Coding (e.g., 10 data + 4 parity = 1.4× cost vs 3× replication)** when designing Dropbox/YouTube/Object Storage is pure Storage-Team Staff mastery!"},scene:{hud:[{label:"3× REPLICATION",value:"300% Cost · 2 Fails",status:"warn"},{label:"ERASURE (10+4)",value:"140% Cost · 4 Fails!",status:"good"},{label:"HOT DB RAID",value:"RAID 10 (Fast I/O)",status:"good"},{label:"TRADE-OFF",value:"Parity CPU on Rebuild",status:"info"}],nodes:[{id:"f",type:"hex",x:135,y:215,label:"100 MB Blob",sublabel:"Reed-Solomon Encode",tone:"blue"},{id:"d",type:"db",x:430,y:120,label:"10 Data Shards",sublabel:"10 Racks (100 MB)",tone:"green"},{id:"p",type:"db",x:430,y:315,label:"4 Parity Shards",sublabel:"4 Racks (+40 MB)",tone:"purple"},{id:"ok",type:"hex",x:665,y:215,label:"Any 10 of 14",sublabel:"100% Reconstructible!",tone:"green"}],edges:[{from:"f",to:"d",label:"split 10",packetColor:"green",speed:1.7},{from:"f",to:"p",label:"compute 4 parity",packetColor:"purple",speed:1.9},{from:"d",to:"ok",label:"read fast",packetColor:"green",speed:1.6},{from:"p",to:"ok",label:"heal up to 4 dead",packetColor:"purple",dashed:!0,speed:2.3}],legend:[{label:"1.4× cost erasure coding durability",tone:"purple"}]}}]},{id:"normalization-federation",title:"Normalization, Denormalization & Federation",subtitle:"1NF / 2NF / 3NF / BCNF vs strategic Denormalization for read speed, plus Database Federation (functional partitioning).",duration:"9 min",level:"Beginner",companies:["Microsoft","Amazon","Meta","Uber"],tags:["normalization","denormalization","3nf","bcnf","database federation","functional partitioning","schema design"],objectives:["Apply 1NF → 2NF → 3NF normalization to eliminate insert, update, and delete anomalies","Know when to intentionally Denormalize (caching counts/author names) to avoid expensive multi-table JOINs","Scale monolithic databases BEFORE sharding using Database Federation (splitting by domain)"],steps:[{shortLabel:"Norm vs Denorm",stage:"TRADEOFF",title:"Normalize for Write Integrity (3NF); Denormalize Selectively for Read Speed",body:['**Normalization (1NF → 2NF → 3NF)**: Every non-key attribute depends on *"the key, the whole key, and nothing but the key."* Storing `author_name` once in `users` instead of duplicating it across 10,000 `posts` prevents update anomalies and shrinks write size!',"**Denormalization**: In read-heavy apps (100:1 reads), joining 6 normalized tables on every page load crushes CPU! Strategically duplicating `like_count` or `author_username` onto the `posts` row trades tiny extra write/sync work for blazing **0-JOIN single-row reads**!"],callout:{type:"KEY IDEA",text:"Rule of thumb: Start **Normalized (3NF)** in OLTP SQL for clean truth, then **Denormalize ONLY proven hot read paths** (or materialize read views via CQRS/NoSQL)!"},scene:{hud:[{label:"3NF NORMALIZED",value:"Zero Update Drift",status:"good"},{label:"DENORMALIZED",value:"0-JOIN Fast Reads",status:"good"},{label:"WRITE COST",value:"Higher on Denorm",status:"warn"},{label:"NOSQL RULE",value:"Model by Query",status:"info"}],nodes:[{id:"n",type:"db",x:185,y:215,label:"3NF SQL Truth",sublabel:"users + posts + likes",tone:"purple",callout:"clean writes"},{id:"d",type:"db",x:565,y:215,label:"Denormalized View",sublabel:"post + author + count",tone:"green",callout:"1-hop read"}],edges:[{from:"n",to:"d",label:"sync / materialize",packetColor:"green",speed:1.8}],legend:[{label:"write truth → fast read projection",tone:"green"}]}},{shortLabel:"DB Federation",stage:"SOLUTION",title:"Database Federation (Functional Partitioning): Split by Domain Before Sharding!",body:["Before jumping into complex horizontal row sharding, apply **Database Federation**: split one overloaded giant database into separate **domain databases** (`Users DB`, `Products DB`, `Orders DB`)!","Each federated DB gets dedicated CPU/RAM/buffer-pool cache (higher cache hit ratio!) and scales independently — Trade-off: you can no longer run SQL JOINs or single-DB ACID transactions across `Users` and `Orders`!"],callout:{type:"INTERVIEW SIGNAL",text:"The cleanest DB scaling progression to quote in interviews: **1) Indexes + Caching → 2) Read Replicas → 3) Database Federation (split by domain) → 4) Horizontal Row Sharding**!"},scene:{hud:[{label:"FEDERATION",value:"Split by Domain",status:"good"},{label:"BUFFER POOL",value:"Higher Cache Hits",status:"good"},{label:"CROSS-DB JOINS",value:"Done in App / API",status:"warn"},{label:"NEXT STEP",value:"Shard Hot Domain Only",status:"info"}],nodes:[{id:"app",type:"hex",x:135,y:215,label:"App / Services",sublabel:"Domain Routing",tone:"blue"},{id:"u",type:"db",x:525,y:105,label:"Users DB",sublabel:"Auth & Profiles",tone:"green"},{id:"p",type:"db",x:525,y:215,label:"Catalog DB",sublabel:"Products & Media",tone:"purple"},{id:"o",type:"db",x:525,y:325,label:"Orders DB",sublabel:"Billing & Ledger",tone:"amber"}],edges:[{from:"app",to:"u",label:"users",packetColor:"green",speed:1.7},{from:"app",to:"p",label:"catalog",packetColor:"purple",speed:1.7},{from:"app",to:"o",label:"orders",packetColor:"amber",speed:1.7}],legend:[{label:"functional database federation",tone:"green"}]}}]},{id:"acid-vs-base",title:"ACID vs BASE Consistency Models",subtitle:"Strict transactional safety (ACID) vs Basically Available, Soft State, Eventual Consistency (BASE) at planetary scale.",duration:"7 min",level:"Beginner",companies:["Amazon","Microsoft","Google","Meta"],tags:["acid","base","eventual consistency","soft state","transactions","nosql"],objectives:["Recite ACID (Atomicity, Consistency, Isolation, Durability) and what breaks if any letter is missing","Explain BASE (Basically Available, Soft State, Eventual Consistency) clearly","Select ACID vs BASE per bounded context inside the SAME product (e.g., Amazon Cart vs Checkout!)"],steps:[{shortLabel:"ACID vs BASE",stage:"TRADEOFF",title:"Strict Pessimistic Safety (ACID) vs Optimistic Availability (BASE)",body:["**ACID** (PostgreSQL, MySQL, Spanner) guarantees every transaction is **Atomic** (all-or-nothing), **Consistent** (invariants hold), **Isolated** (concurrent TXs don’t corrupt each other), and **Durable** (survives power loss via WAL) — prioritizing correctness even if writes wait.","**BASE** (DynamoDB, Cassandra, DNS, Social Likes) prioritizes ultra-low latency and 99.999% availability: **Basically Available** (always responds), **Soft State** (state may change over time without input as gossip/replication converges), and **Eventual Consistency** (all replicas converge once writes stop)!"],callout:{type:"KEY IDEA",text:"Real Big Tech apps mix BOTH! On **Amazon.com**, View Counts, Recommendations, and Reviews use **BASE** (fast, always up); Inventory Deduction and Credit Card Charging use strict **ACID**!"},scene:{hud:[{label:"ACID PRIORITY",value:"Strict Correctness",status:"info"},{label:"BASE PRIORITY",value:"High Avail + Speed",status:"good"},{label:"USE ACID",value:"Money · Seats · Auth",status:"good"},{label:"USE BASE",value:"Likes · Views · Feeds",status:"good"}],nodes:[{id:"app",type:"hex",x:135,y:215,label:"E-Commerce App",sublabel:"Hybrid Consistency",tone:"blue"},{id:"acid",type:"db",x:525,y:120,label:"ACID Store",sublabel:"Payments & Stock",tone:"purple",callout:"strict CP"},{id:"base",type:"db",x:525,y:315,label:"BASE Store",sublabel:"Views · Likes · Cart",tone:"green",callout:"fast AP"}],edges:[{from:"app",to:"acid",label:"strict commit",packetColor:"purple",bidirectional:!0,speed:1.9},{from:"app",to:"base",label:"sub-5ms AP",packetColor:"green",bidirectional:!0,speed:1.5}],legend:[{label:"strict ACID boundary",tone:"purple"},{label:"high-availability BASE",tone:"green"}]}},{shortLabel:"Hybrid Choice",stage:"TECHNIQUE",title:"How to Justify ACID vs BASE Clearly in 20 Seconds During an Interview",body:['Ask one razor-sharp question: **"What is the dollar or trust cost of reading 500 ms stale data?"** If stale data causes double-charging a credit card or overselling a concert seat → **ACID**. If stale data shows `1,402` likes instead of `1,405` for half a second → **BASE**!'],callout:{type:"INTERVIEW SIGNAL",text:'Framing consistency around **business cost of staleness** instead of dogma ("SQL is old, NoSQL is modern") immediately distinguishes Senior/Staff architects.'},scene:{hud:[{label:"STALE LIKES",value:"$0 Cost → BASE",status:"good"},{label:"STALE BALANCE",value:"High Cost → ACID",status:"warn"},{label:"CONVERGENCE",value:"Gossip / Read Repair",status:"info"},{label:"WAL SAFETY",value:"fsync Durability",status:"good"}],nodes:[{id:"q",type:"hex",x:165,y:215,label:"Staleness Cost?",sublabel:"Evaluate Per Entity",tone:"amber"},{id:"hi",type:"db",x:545,y:120,label:"High → ACID",sublabel:"Ledger · Bookings",tone:"purple"},{id:"lo",type:"db",x:545,y:310,label:"Low → BASE",sublabel:"Feed · Metrics · DNS",tone:"green"}],edges:[{from:"q",to:"hi",label:"zero drift allowed",packetColor:"purple",speed:1.8},{from:"q",to:"lo",label:"500ms lag fine",packetColor:"green",speed:1.6}],legend:[{label:"business-driven consistency choice",tone:"green"}]}}]},{id:"geohashing-quadtrees-h3",title:"Geohashing, Quadtrees & Spatial Indexes",subtitle:"How Yelp, Uber & Google Maps query 2D `(lat, lng)` in milliseconds: Geohash edge bugs, Quadtrees, S2 & Uber H3.",duration:"10 min",level:"Intermediate",companies:["Uber","Google","Yelp","DoorDash"],tags:["geohash","quadtree","h3","s2","spatial index","nearby","redis geo","postgis"],objectives:["Explain why naive SQL `WHERE lat BETWEEN ... AND lng BETWEEN ...` scans millions of rows slowly","Understand Geohash Base32 prefix trees AND solve the Geohash Boundary Edge Bug (query 8 neighbors!)","Compare Static Geohash vs Dynamic Density Quadtrees vs Equidistant Uber H3 Hexagons"],steps:[{shortLabel:"Geohash & Edge Bug",stage:"PROBLEM",title:"Geohash Encodes 2D Coordinates Into 1D Strings — Watch the Boundary Trap!",body:['**Geohash** recursively bisects latitude and longitude into alternating bits encoded in Base32 (`9q8yy`). Longer shared prefix = physically closer! Now a standard B-Tree / Redis index finds nearby points with `LIKE "9q8yy%"`!',"**The Classic Boundary Bug**: Two coffee shops **10 meters apart** across a prime grid line can have **completely different Geohash prefixes** (`9q8yy` vs `9q8zn`)! **Mandatory Fix**: Always query your target cell PLUS its **8 surrounding neighbor cells** (9 cells total)!"],callout:{type:"WATCH OUT",text:"Forgetting to query the **8 neighboring Geohash cells** around the target cell is the #1 bug interviewers catch in Yelp / Nearby Friends / Uber designs!"},scene:{hud:[{label:"ENCODING",value:"Base32 Prefix (1D)",status:"info"},{label:"PRECISION 6",value:"~1.2 km × 0.6 km",status:"info"},{label:"BOUNDARY FIX",value:"Center + 8 Neighbors",status:"good"},{label:"REDIS GEO",value:"52-bit ZSET Geohash",status:"good"}],nodes:[{id:"u",type:"users",x:120,y:215,label:"User (lat,lng)",sublabel:"Cell: 9q8yy",tone:"slate"},{id:"c",type:"hex",x:390,y:125,label:"Center 9q8yy",sublabel:"10m from border!",tone:"green"},{id:"n",type:"hex",x:390,y:310,label:"8 Neighbors",sublabel:"9q8zn · 9q8yv ...",tone:"amber",callout:"must include!"},{id:"res",type:"cache",x:650,y:215,label:"Top-K Radius",sublabel:"Exact Haversine Filter",tone:"purple"}],edges:[{from:"u",to:"c",label:"prefix query",packetColor:"green",speed:1.6},{from:"u",to:"n",label:"+ 8 adjacent cells",packetColor:"amber",speed:1.7},{from:"c",to:"res",label:"merge",packetColor:"purple",speed:1.7},{from:"n",to:"res",label:"merge",packetColor:"purple",speed:1.7}],legend:[{label:"9-cell boundary-safe geohash search",tone:"amber"}]}},{shortLabel:"Quadtree vs H3",stage:"SOLUTION",title:"Dynamic Quadtrees (Yelp Static Places) vs H3 Hexagons (Uber Moving Cabs)",body:["Manhattan has 10,000 restaurants per km² while the Sahara has 0! A **Quadtree** starts as 1 world rectangle and recursively splits any square into 4 quadrants ONLY when it exceeds `500` businesses — tiny deep grids in cities, huge coarse boxes in deserts! Great for **static places (Yelp)**, expensive to rebalance on 250k moving drivers/sec.","For **rapidly moving vehicles (Uber/DoorDash)**, **Uber H3 Hexagons** (or Redis Geo / Google S2) give O(1) coordinate-to-cell hashing with **6 equidistant neighbors** and zero tree-rebalancing locks!"],callout:{type:"INTERVIEW SIGNAL",text:"Rule to quote: **Quadtree** for dense/skewed *static* POIs (Yelp/Google Maps places); **Geohash / Redis Geo / H3 Hexagons** for *high-write moving* entities (Uber drivers / Nearby Friends)!"},scene:{hud:[{label:"STATIC POIS",value:"Quadtree (Yelp)",status:"good"},{label:"MOVING CABS",value:"H3 / Redis Geo",status:"good"},{label:"H3 GEOMETRY",value:"6 Equidistant Sides",status:"good"},{label:"UPDATE COST",value:"O(1) Hash Map",status:"good"}],nodes:[{id:"qt",type:"hex",x:185,y:215,label:"Quadtree",sublabel:"Adaptive Density",tone:"purple",callout:"static POIs"},{id:"h3",type:"hex",x:545,y:215,label:"Uber H3 Hex",sublabel:"O(1) Moving GPS",tone:"green",callout:"250k updates/s"}],edges:[{from:"qt",to:"h3",label:"static vs real-time motion",packetColor:"green",dashed:!0,speed:2.2}],legend:[{label:"spatial engine comparison",tone:"green"}]}}]},{id:"probabilistic-structures",title:"Probabilistic Data Structures at Scale",subtitle:"Bloom Filters, HyperLogLog (1B uniques in 12 KB RAM!), Count-Min Sketch & SkipLists in Redis/RocksDB.",duration:"9 min",level:"Advanced",companies:["Google","Meta","Amazon","Redis"],tags:["bloom filter","hyperloglog","count-min sketch","skiplist","probabilistic","unique visitors","redis"],objectives:["Explain Bloom Filter guarantees: 0% False Negatives, tunable ~1% False Positives, O(k) RAM check","Count 1 Billion unique daily visitors in just 12 KB RAM using HyperLogLog (`PFADD` / `PFCOUNT`)","Know where SkipLists power Redis Sorted Sets and LSM-Tree MemTables"],steps:[{shortLabel:"Bloom & HLL",stage:"SOLUTION",title:"Count 1 Billion Unique Visitors in 12 KB RAM (HyperLogLog) & Skip Disk Reads (Bloom)",body:['Storing 1 Billion 8-byte `user_id`s in a `HashSet` to count "Unique Daily Visitors" eats **8 GB RAM PER PAGE**! **HyperLogLog (Redis `PFADD` / `PFCOUNT`)** tracks the maximum leading zero bits across hashed registers and estimates cardinalities up to `10^9+` with **0.81% error in just 12 KB of RAM** — and merges across servers via element-wise `MAX`!',"**Bloom Filters** use a compact bit array + `k` hashes: if ANY bit is `0`, the key is **100% DEFINITELY ABSENT** (skipbing SSTable disk seeks in Cassandra/RocksDB or blocking Cache Penetration!). Standard Bloom Filters don’t support deletes (use **Counting Bloom** or **Cuckoo Filters** for deletes)."],callout:{type:"INTERVIEW SIGNAL",text:'Saying *"Exact unique counts need 8 GB per URL; Redis HyperLogLog gives 99.2% accurate unique counts for 1B users in 12 KB RAM and merges across regions!"* will make any Google/Meta interviewer smile.'},scene:{hud:[{label:"EXACT HASHSET",value:"8 GB / 1B Users",status:"bad"},{label:"HYPERLOGLOG",value:"12 KB (0.81% err!)",status:"good"},{label:"BLOOM FILTER",value:"0% False Negatives",status:"good"},{label:"REDIS ZSET",value:"SkipList O(log N)",status:"info"}],nodes:[{id:"bf",type:"cache",x:145,y:215,label:"Bloom Filter",sublabel:"Membership · 10b/key",tone:"green",callout:"SSTable / URL"},{id:"hll",type:"cache",x:390,y:120,label:"HyperLogLog",sublabel:"1B Uniques in 12 KB!",tone:"purple",callout:"PFCOUNT"},{id:"cms",type:"cache",x:390,y:315,label:"Count-Min Sketch",sublabel:"Top-K Heavy Hitters",tone:"amber",callout:"frequency"},{id:"sl",type:"hex",x:645,y:215,label:"SkipList",sublabel:"Redis ZSET / MemTbl",tone:"blue"}],edges:[{from:"bf",to:"hll",label:"exists?",packetColor:"purple",dashed:!0,speed:2.2},{from:"bf",to:"cms",label:"how often?",packetColor:"amber",dashed:!0,speed:2.2},{from:"hll",to:"sl",label:"rank leaderboards",packetColor:"blue",dashed:!0,speed:2.2}],legend:[{label:"sub-linear Big Tech data structures",tone:"purple"}]}},{shortLabel:"When Exact Wins",stage:"TRADEOFF",title:"Never Use Probabilistic Structures for Money, Auth or Strict Uniqueness",body:['Use **HyperLogLog** for analytics dashboards ("1.2M unique viewers"), **Bloom Filters** as a fast *pre-filter* in front of exact DB storage, and **Count-Min Sketch** for trending charts. NEVER use approximate sketches for **billing invoices, bank balances, or exact seat counts**!'],callout:{type:"WATCH OUT",text:'Bloom Filters can return a **False Positive** (~1%): when a Bloom Filter says "maybe present," you STILL check the authoritative database/SSTable to verify!'},scene:{hud:[{label:"ANALYTICS",value:"HLL / CMS ✓",status:"good"},{label:"CACHE GUARD",value:"Bloom Pre-Filter ✓",status:"good"},{label:"BILLING / AUTH",value:"Exact ACID Only!",status:"warn"},{label:"DELETES",value:"Cuckoo / Counting",status:"info"}],nodes:[{id:"req",type:"hex",x:145,y:215,label:"Lookup Key",sublabel:"Check Bloom First",tone:"blue"},{id:"no",type:"hex",x:485,y:120,label:"Bit = 0 → Absent!",sublabel:"0 Disk I/O (100% Sure)",tone:"green"},{id:"yes",type:"db",x:485,y:310,label:"All 1s → Verify DB",sublabel:"Handles 1% False Pos",tone:"amber"}],edges:[{from:"req",to:"no",label:"fast reject",packetColor:"green",speed:1.5},{from:"req",to:"yes",label:"confirm truth",packetColor:"amber",dashed:!0,speed:2.1}],legend:[{label:"zero-false-negative pre-filter",tone:"green"}]}}]}],v=[{id:"ntier-esb-eda",title:"N-Tier, ESB vs Event-Driven Architecture",subtitle:'Classic 3-Tier systems, why Enterprise Service Bus (ESB) becomes a bottleneck, and modern "Dumb Pipe, Smart Endpoints" EDA.',duration:"8 min",level:"Beginner",companies:["Microsoft","Amazon","Uber","Salesforce"],tags:["n-tier","3-tier","esb","enterprise service bus","eda","event-driven","choreography"],objectives:["Understand classic 3-Tier Architecture (Presentation → Business Logic → Data Tier)",'Explain why legacy SOA Enterprise Service Buses (ESB) fail at cloud scale ("Smart Pipe" bottleneck)','Design decoupled Event-Driven Architectures (EDA) using "Dumb Pipes, Smart Endpoints" (Kafka/EventBridge)'],steps:[{shortLabel:"3-Tier & ESB",stage:"PROBLEM",title:"N-Tier Starts Simple — Legacy ESB Centralizes Too Much Logic in the Pipe",body:["Classic **3-Tier Architecture** separates **Presentation (Web/Mobile)** → **Application Tier (Stateless API)** → **Data Tier (SQL/Cache)** so each layer scales and deploys independently.",'In legacy enterprise SOA, teams plugged every service into a centralized **Enterprise Service Bus (ESB)** that performed XML transformations, business routing, and orchestration inside the bus itself (**"Smart Pipe, Dumb Endpoints"**). Result: the ESB became a brittle, slow, single-team bottleneck!'],callout:{type:"WATCH OUT",text:'Martin Fowler’s microservices golden rule: **"Smart Endpoints and Dumb Pipes!"** Keep message brokers (Kafka/SQS) purely focused on fast reliable delivery, NOT business transformations!'},scene:{hud:[{label:"3-TIER",value:"UI → App → Data",status:"good"},{label:"LEGACY ESB",value:"Smart Pipe (Bottleneck)",status:"bad"},{label:"MODERN EDA",value:"Dumb Pipe (Kafka)",status:"good"},{label:"COUPLING",value:"Loose Async Events",status:"good"}],nodes:[{id:"esb",type:"hex",x:185,y:215,label:"Legacy ESB ✕",sublabel:"Fat Business Logic Pipe",tone:"coral",load:91},{id:"eda",type:"queue",x:545,y:215,label:"Modern Kafka EDA ✓",sublabel:"Dumb Pipe · Smart Svcs",tone:"green",load:26}],edges:[{from:"esb",to:"eda",label:"evolve to cloud-native EDA →",packetColor:"green",speed:1.9}],legend:[{label:"decoupled event-driven evolution",tone:"green"}]}},{shortLabel:"Modern EDA",stage:"SOLUTION",title:"Event-Driven Architecture (EDA): Producers Emit Facts; Consumers React Independently",body:["In **EDA**, `OrderService` publishes an immutable domain fact (`OrderPlaced`) to Kafka/EventBridge without knowing who listens! **Inventory**, **Email**, **Loyalty Points**, and **Fraud ML** subscribe independently — adding a 5th consumer requires **ZERO changes to `OrderService`**!",'Guard against "Event Spaghetti" with a **Schema Registry (Protobuf/Avro)**, correlation `trace_id` headers, and idempotent consumers.'],callout:{type:"INTERVIEW SIGNAL",text:"Always pair EDA with **Schema Registry (Backward-Compatible Protobuf/Avro Evolution)** so a producer adding a new field never crashes downstream consumers!"},scene:{hud:[{label:"PRODUCER",value:"Zero Consumer Coupling",status:"good"},{label:"CONTRACTS",value:"Avro/Proto Registry",status:"good"},{label:"NEW FEATURE",value:"Plug In New Consumer",status:"good"},{label:"DEBUGGING",value:"OTel TraceID Required",status:"warn"}],nodes:[{id:"ord",type:"hex",x:115,y:215,label:"Order Svc",sublabel:"Emits OrderPlaced",tone:"blue"},{id:"bus",type:"queue",x:350,y:215,label:"Event Bus",sublabel:"Kafka + Schema Reg",tone:"amber"},{id:"s1",type:"hex",x:635,y:105,label:"Inventory",sublabel:"Independent Sub",tone:"green"},{id:"s2",type:"hex",x:635,y:215,label:"Notifications",sublabel:"Independent Sub",tone:"purple"},{id:"s3",type:"hex",x:635,y:325,label:"Fraud / BI",sublabel:"Added Later (0 edits!)",tone:"blue"}],edges:[{from:"ord",to:"bus",label:"publish fact",packetColor:"amber",speed:1.6},{from:"bus",to:"s1",label:"react",packetColor:"green",speed:1.7},{from:"bus",to:"s2",label:"react",packetColor:"purple",speed:1.7},{from:"bus",to:"s3",label:"react",packetColor:"blue",speed:1.7}],legend:[{label:"dumb pipe, smart endpoints",tone:"green"}]}}]},{id:"cqrs-event-sourcing",title:"CQRS & Event Sourcing Internals",subtitle:"Separating Write Commands from Read Projections (CQRS) and storing immutable state transitions (Event Sourcing + Snapshots).",duration:"11 min",level:"Advanced",companies:["Microsoft","Amazon","Stripe","Coinbase"],tags:["cqrs","event sourcing","projections","event store","snapshots","upcasting","audit log"],objectives:["Separate Write Models (normalized ACID commands) from Read Models (denormalized Elasticsearch/Redis projections) via CQRS","Model state as an immutable Append-Only Event Store with Snapshots for fast replay & time-travel auditing","Anticipate CQRS pitfalls: eventual read-projection lag and Event Schema Versioning (Upcasting)"],steps:[{shortLabel:"CQRS Split",stage:"SOLUTION",title:"CQRS: Optimize the Write DB for Integrity and Read DBs for Specialized Queries",body:["In complex domains (E-Commerce, Banking, Analytics), **Writes** need normalized ACID consistency (`PostgreSQL`), while **Reads** need full-text faceted search (`Elasticsearch`), user timelines (`Redis`), and dashboards (`ClickHouse`). One single table cannot optimize all four!","**CQRS (Command Query Responsibility Segregation)** sends **Commands** (`POST /orders`) to the Write Store, streams committed changes via **Outbox/CDC Kafka**, and builds tailored **Read Projections** asynchronously — letting reads and writes scale completely independently!"],callout:{type:"WATCH OUT",text:"CQRS introduces **Eventual Consistency Lag** (50–500 ms) between a Command succeeding and the Read Projection updating! Handle UI UX cleanly via Optimistic UI updates or returning the created entity directly in the Command response."},scene:{hud:[{label:"WRITE PATH",value:"Commands → Postgres",status:"info"},{label:"READ PATH",value:"Queries → Projections",status:"good"},{label:"SYNC LAG",value:"50 – 300 ms Async",status:"warn"},{label:"SCALING",value:"Independent R/W",status:"good"}],nodes:[{id:"cmd",type:"hex",x:110,y:120,label:"Write Command",sublabel:"Create / Mutate",tone:"purple"},{id:"qry",type:"hex",x:110,y:315,label:"Read Query",sublabel:"Search / Dash",tone:"green"},{id:"wdb",type:"db",x:375,y:120,label:"Write DB (3NF)",sublabel:"ACID + Outbox",tone:"purple"},{id:"kf",type:"queue",x:615,y:215,label:"CDC Event Bus",sublabel:"Projector Workers",tone:"amber"},{id:"rdb",type:"db",x:375,y:315,label:"Read Projections",sublabel:"Redis / Elastic / OLAP",tone:"green",callout:"0-JOIN reads"}],edges:[{from:"cmd",to:"wdb",label:"ACID write",packetColor:"purple",speed:1.7},{from:"wdb",to:"kf",label:"CDC stream",packetColor:"amber",speed:1.7},{from:"kf",to:"rdb",label:"update views",packetColor:"green",speed:1.7},{from:"qry",to:"rdb",label:"instant read",packetColor:"green",bidirectional:!0,speed:1.5}],legend:[{label:"write command side",tone:"purple"},{label:"materialized read side",tone:"green"}]}},{shortLabel:"Event Sourcing",stage:"TECHNIQUE",title:"Event Sourcing: The Append-Only Event Log IS Your Source of Truth",body:["Standard DBs overwrite `balance = 150` and destroy history. **Event Sourcing** stores ONLY immutable facts: `[AccountOpened($0), Deposited($200), Withdrew($50)]`! Current state is derived by folding events — giving you **100% regulatory auditability, time-travel debugging, and zero-loss replay** into brand-new analytics views!","**Two Production Must-Haves**: 1) **Periodic Snapshots** (every 200 events) so hydrating a 5-year-old account takes 2 ms instead of replaying 50,000 events, and 2) **Event Upcasters** to translate `v1` historical events cleanly into `v2` code!"],callout:{type:"INTERVIEW SIGNAL",text:"Use Event Sourcing where **history and audit trail are core business requirements** (Fintech Ledgers, Stock Exchanges, Healthcare, Collaborative Docs) — NOT simple CRUD profile apps!"},scene:{hud:[{label:"AUDIT TRAIL",value:"100% Immutable ✓",status:"good"},{label:"FAST REHYDRATE",value:"Snapshots + Tail",status:"good"},{label:"EVOLUTION",value:"Schema Upcasters",status:"info"},{label:"GDPR DELETE",value:"Crypto-Shred Key!",status:"good"}],nodes:[{id:"es",type:"queue",x:145,y:215,label:"Event Store",sublabel:"e1 → e2 → e3 → e4",tone:"amber"},{id:"sn",type:"db",x:415,y:120,label:"Snapshot #200",sublabel:"Fast State Load",tone:"purple"},{id:"vw",type:"cache",x:415,y:315,label:"Replayable Views",sublabel:"Rebuild Anytime!",tone:"green"}],edges:[{from:"es",to:"sn",label:"every N events",packetColor:"purple",dashed:!0,speed:2.2},{from:"es",to:"vw",label:"fold / replay",packetColor:"green",speed:1.7}],legend:[{label:"immutable event-sourced state",tone:"amber"}]}}]}],f=[{id:"tls-mtls-pki",title:"SSL/TLS 1.3, PKI Certificates & mTLS",subtitle:"How HTTPS actually works under the hood: Asymmetric ECDHE key exchange, Symmetric AES-GCM encryption, CA chains & Mutual TLS.",duration:"9 min",level:"Intermediate",companies:["Microsoft","Cloudflare","Google","Amazon"],tags:["ssl","tls 1.3","mtls","https","pki","ecdhe","aes","certificates","x509"],objectives:["Explain why TLS uses Asymmetric cryptography ONLY for the handshake and Symmetric AES-GCM for bulk data","Verify server identity via X.509 Certificate Authority (CA) trust chains and Forward Secrecy (ECDHE)","Upgrade one-way HTTPS to Mutual TLS (mTLS) for Zero-Trust microservice authentication"],steps:[{shortLabel:"TLS 1.3 Flow",stage:"TECHNIQUE",title:"Hybrid Crypto: Asymmetric ECDHE Handshake → Fast Symmetric AES-GCM Tunnel",body:["Asymmetric crypto (RSA/ECDSA) solves key exchange over an untrusted internet, but is **1,000× slower** than symmetric AES! So **TLS 1.3** runs a **1-RTT Hybrid Handshake**:","1) Client sends `ClientHello` + ephemeral **ECDHE Key Share**. 2) Server replies with its **X.509 Certificate** (signed by a trusted Root CA like DigiCert/Let’s Encrypt), its ECDHE Key Share, and signature. 3) Both sides derive the exact same temporary **Symmetric AES-256-GCM Session Key** — giving **Perfect Forward Secrecy** (even if the server’s private key leaks next year, past recorded traffic CANNOT be decrypted!)."],callout:{type:"KEY IDEA",text:"**TLS 1.3** removed legacy weak ciphers and cut the handshake to **1 RTT** (plus optional **0-RTT session resumption** — only use 0-RTT for idempotent GETs to prevent replay attacks!)."},scene:{hud:[{label:"HANDSHAKE",value:"1 RTT (ECDHE)",status:"good"},{label:"BULK CRYPTO",value:"AES-256-GCM Fast",status:"good"},{label:"FORWARD SECRECY",value:"Ephemeral Keys ✓",status:"good"},{label:"IDENTITY",value:"X.509 CA Chain",status:"info"}],nodes:[{id:"c",type:"users",x:120,y:215,label:"Browser",sublabel:"Trusts Root CAs",tone:"slate"},{id:"s",type:"hex",x:455,y:215,label:"HTTPS Server",sublabel:"Cert + ECDHE Share",tone:"green",callout:"TLS 1.3"},{id:"ca",type:"db",x:665,y:120,label:"Root CA Chain",sublabel:"Signs Server Cert",tone:"purple"}],edges:[{from:"c",to:"s",label:"1. ECDHE + Cert Verify (1 RTT)",packetColor:"purple",bidirectional:!0,curve:-32,speed:2},{from:"c",to:"s",label:"2. Fast AES-256-GCM Data",packetColor:"green",bidirectional:!0,curve:32,speed:1.5},{from:"ca",to:"s",label:"signed cert",packetColor:"amber",dashed:!0,speed:2.6}],legend:[{label:"1-RTT asymmetric key exchange",tone:"purple"},{label:"fast symmetric encrypted stream",tone:"green"}]}},{shortLabel:"Mutual TLS (mTLS)",stage:"SOLUTION",title:"Mutual TLS (mTLS): Both Client AND Server Prove Cryptographic Identity",body:["In regular browser HTTPS, only the **server** presents a certificate. Inside a Zero-Trust microservice mesh (Istio/Envoy/Azure), **BOTH services present short-lived X.509 workload certificates (SPIFFE IDs)** rotated automatically every 24 hours!","Now even if an attacker compromises a pod on the internal VPC network, they CANNOT impersonate `PaymentService` without its cryptographic identity cert!"],callout:{type:"INTERVIEW SIGNAL",text:"Always specify **mTLS between internal microservices** + **automated short-lived cert rotation (SPIFFE/cert-manager)** when answering Microsoft/Google security deep dives!"},scene:{hud:[{label:"SERVER VERIFY",value:"X.509 Cert ✓",status:"good"},{label:"CLIENT VERIFY",value:"X.509 Cert ✓",status:"good"},{label:"CERT ROTATION",value:"Auto Every 24h",status:"good"},{label:"ZERO TRUST",value:"Spoofing Blocked",status:"good"}],nodes:[{id:"a",type:"hex",x:165,y:215,label:"Order Envoy",sublabel:"Cert: spiffe://order",tone:"blue"},{id:"b",type:"hex",x:565,y:215,label:"Payment Envoy",sublabel:"Cert: spiffe://pay",tone:"green"},{id:"ca",type:"hex",x:365,y:95,label:"Internal Mesh CA",sublabel:"Auto-Issues 24h Certs",tone:"purple"}],edges:[{from:"ca",to:"a",label:"cert",packetColor:"purple",dashed:!0,speed:2.4},{from:"ca",to:"b",label:"cert",packetColor:"purple",dashed:!0,speed:2.4},{from:"a",to:"b",label:"Mutual 2-Way Cert Verify + AES",packetColor:"green",bidirectional:!0,speed:1.6}],legend:[{label:"zero-trust mutual TLS",tone:"green"}]}}]}],S=[{id:"vms-containers-serverless",title:"VMs vs Containers vs MicroVMs vs Serverless",subtitle:"Hypervisors & Guest OS vs Docker Linux namespaces/cgroups vs Firecracker MicroVMs vs FaaS cold-start trade-offs.",duration:"8 min",level:"Beginner",companies:["Amazon","Microsoft","Google","Cloudflare"],tags:["vm","virtual machine","docker","container","namespaces","cgroups","firecracker","serverless","lambda"],objectives:["Compare Hardware Virtualization (VMs) vs OS-Level Isolation (Docker Containers)","Understand Linux `namespaces` (isolation), `cgroups` (CPU/RAM caps), and `OverlayFS` layers","Pick cleanly between Containers (K8s), MicroVMs (Firecracker), and Serverless FaaS (Lambda/Azure Functions)"],steps:[{shortLabel:"VM vs Container",stage:"SETUP",title:"VMs Boot a Full Guest OS (Minutes, Strong Isolation); Containers Share Host Kernel (ms)",body:["A **Virtual Machine (EC2 / Azure VM)** runs a **Hypervisor (KVM/Hyper-V)** emulating hardware with a full **Guest OS kernel** per VM — gigabytes of RAM overhead and 30–90s boot, but bulletproof hardware-level isolation!","A **Container (Docker)** shares the host’s single Linux kernel using **`namespaces`** (isolated PIDs, network, filesystem) + **`cgroups`** (strict CPU/memory ceilings) + **`OverlayFS`** (layered copy-on-write images) — megabytes in size and **sub-second startup**!"],callout:{type:"KEY IDEA",text:"Need BOTH container startup speed AND VM kernel security (for untrusted user code like LeetCode or AWS Lambda)? Use **Firecracker MicroVMs** (~125 ms boot, dedicated minimal guest kernel, ~5 MB RAM overhead)!"},scene:{hud:[{label:"VM BOOT",value:"30–90s · Full OS",status:"warn"},{label:"CONTAINER",value:"< 1s · Shared Kernel",status:"good"},{label:"FIRECRACKER",value:"125ms · Own Kernel",status:"good"},{label:"SERVERLESS",value:"Scale-to-Zero FaaS",status:"info"}],nodes:[{id:"vm",type:"hex",x:140,y:215,label:"VM (Hypervisor)",sublabel:"Full Guest OS · GBs",tone:"purple"},{id:"dk",type:"hex",x:380,y:215,label:"Docker Container",sublabel:"Shared Kernel · MBs",tone:"green",callout:"K8s pods"},{id:"fc",type:"hex",x:635,y:215,label:"MicroVM / FaaS",sublabel:"125ms · Scale to 0",tone:"blue"}],edges:[{from:"vm",to:"dk",label:"10× density",packetColor:"green",speed:1.9},{from:"dk",to:"fc",label:"untrusted / spiky",packetColor:"blue",speed:1.9}],legend:[{label:"compute isolation spectrum",tone:"green"}]}},{shortLabel:"When Serverless?",stage:"TRADEOFF",title:"Serverless (Lambda / Functions) Wins on Spiky Glue; Containers Win on Steady High-QPS",body:["**Serverless FaaS** scales to zero (`$0` when idle) and auto-handles sudden event triggers (S3 thumbnail resize, Stripe webhook handler, nightly cron). **Trade-offs**: Cold-start latency spikes, 15-min execution limits, and **high per-invocation cost under 24/7 steady traffic** (remember Amazon Prime Video saving 90% moving back to ECS containers!)."],callout:{type:"INTERVIEW SIGNAL",text:"Rule of thumb: Use **Serverless FaaS** for spiky/low-duty event handlers and glue code; use **Kubernetes / ECS Containers** for steady high-QPS APIs, WebSockets, and long-running workers!"},scene:{hud:[{label:"SPIKY / IDLE",value:"Serverless ($0 Idle)",status:"good"},{label:"STEADY 24/7 API",value:"K8s Containers",status:"good"},{label:"WEBSOCKETS",value:"Containers Only",status:"warn"},{label:"COLD START FIX",value:"Provisioned Conc.",status:"info"}],nodes:[{id:"sp",type:"hex",x:185,y:215,label:"Spiky Events",sublabel:"S3 Resize · Webhooks",tone:"amber"},{id:"faas",type:"hex",x:545,y:120,label:"Serverless FaaS",sublabel:"Pay Per ms ($0 Idle)",tone:"green"},{id:"k8s",type:"hex",x:545,y:310,label:"K8s Container Fleet",sublabel:"Steady High-QPS / WS",tone:"blue"}],edges:[{from:"sp",to:"faas",label:"bursty glue",packetColor:"green",speed:1.7},{from:"sp",to:"k8s",label:"always-on core",packetColor:"blue",dashed:!0,speed:2.1}],legend:[{label:"cost-optimal compute choice",tone:"green"}]}}]}];export{S as E,n as M,d as a,c as b,u as c,b as d,p as e,g as f,f as g,v as h,m as i,y as j,h as k};
